    /// Record a newly created thread for happens-before `spawn_ordinal`
    /// resolution. A no-op unless a happens-before program is active.
    pub fn hb_note_spawn(&mut self, dettid: DetTid) {
        if let Some(hb) = self.happens_before.as_mut() {
            hb.note_spawn(dettid);
        }
    }

    pub(crate) fn register_physical_thread(
        &mut self,
        dettid: DetTid,
        mm: MmId,
        physical_pid: i32,
        physical_tid: i32,
    ) -> std::io::Result<()> {
        if physical_pid <= 0 || physical_tid <= 0 {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidInput,
                "host process and thread IDs must be positive",
            ));
        }
        if let Some(control) = &self.reserved_input_control {
            let task = self
                .reserved_input_native_tasks
                .get(&physical_tid)
                .copied()
                .ok_or_else(|| {
                    std::io::Error::other("reserved-input native registration missing")
                })?;
            let registration = control
                .registration(task)
                .ok_or_else(|| std::io::Error::other("reserved-input native generation missing"))?;
            if registration.native_tid != physical_tid || registration.native_pid != physical_pid {
                return Err(std::io::Error::other(
                    "reserved-input native registration identity mismatch",
                ));
            }
            if registration.tool_tid != Some(dettid.as_raw()) {
                return Err(std::io::Error::other(
                    "reserved-input Tool/native registration identity mismatch",
                ));
            }
            // Logical birth/reconnect binds this generation separately. In
            // particular this physical registration can precede completion
            // of the old exec image's logical teardown.
        }
        if let Some((known_mm, known_pid, known_tid, _)) = self.physical_thread_pidfds.get(&dettid)
        {
            if *known_mm == mm && *known_pid == physical_pid && *known_tid == physical_tid {
                return Ok(());
            }
            if *known_mm == mm {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::AlreadyExists,
                    format!(
                        "scheduler identity {dettid} already names host process {known_pid} thread {known_tid}"
                    ),
                ));
            }
        }
        let raw_fd = unsafe {
            libc::syscall(
                libc::SYS_pidfd_open,
                physical_tid,
                libc::O_EXCL as libc::c_uint,
            )
        };
        if raw_fd < 0 {
            return Err(std::io::Error::last_os_error());
        }
        // SAFETY: pidfd_open returned a new descriptor owned by this process.
        let pidfd = unsafe { OwnedFd::from_raw_fd(raw_fd as libc::c_int) };
        self.physical_thread_pidfds
            .insert(dettid, (mm, physical_pid, physical_tid, pidfd));
        self.procfs_kernel_ids
            .insert(dettid, (physical_pid, physical_tid));
        Ok(())
    }

    /// Arm `process`'s exit watch on `pidfd`, a process pidfd for its host
    /// process `physical_pid`, bound to address space `mm`; an earlier watch of
    /// the process stops being current. Nothing calls this in production yet:
    /// arming from unauthenticated numbers was the defect that got
    /// 2ee7190125 reverted, and the authenticated registration of
    /// <https://github.com/rrnewton/hermit/issues/4362> part 2 will be its caller.
    #[cfg_attr(not(test), allow(dead_code))]
    pub(crate) fn arm_process_exit_watch(
        &mut self,
        process: DetPid,
        mm: MmId,
        physical_pid: i32,
        pidfd: OwnedFd,
    ) -> Arc<ProcessExitWatch> {
        let watch = Arc::new(ProcessExitWatch {
            process,
            mm,
            physical_pid,
            pidfd,
        });
        self.process_exit_watches.insert(process, watch.clone());
        watch
    }

    /// Called under the same mutex as registration, exec and deregistration.
    /// Normal leader exit leaves this process watch alive for its siblings.
    pub(crate) fn process_exit_watch_is_current(&self, watch: &Arc<ProcessExitWatch>) -> bool {
        self.process_exit_watches
            .get(&watch.process)
            .is_some_and(|current| Arc::ptr_eq(current, watch))
            && self.thread_tree.contains(&watch.process)
            && self
                .thread_tree
                .my_thread_group(&watch.process)
                .iter()
                .any(|tid| self.thread_mm(*tid) == Some(watch.mm))
    }

    pub(crate) fn finish_process_exit_watch(&mut self, watch: &Arc<ProcessExitWatch>) {
        assert!(self.process_exit_watch_is_current(watch));
        self.process_exit_watches.remove(&watch.process);
    }

    /// The host process ID registered for `dettid`'s host thread, if any.
    pub(crate) fn physical_process_of(&self, dettid: DetTid) -> Option<i32> {
        self.physical_thread_pidfds
            .get(&dettid)
            .map(|(_, physical_pid, ..)| *physical_pid)
    }

    /// Whether the host thread registered for `dettid` has exited, by a
    /// zero-timeout poll of the `PIDFD_THREAD` pidfd opened when it
    /// registered; `None` when it has no registration or the poll fails.
    pub(crate) fn registered_thread_has_exited(&self, dettid: DetTid) -> Option<bool> {
        let (.., pidfd) = self.physical_thread_pidfds.get(&dettid)?;
        let mut poll = libc::pollfd {
            fd: pidfd.as_raw_fd(),
            events: libc::POLLIN,
            revents: 0,
        };
        // SAFETY: one valid pollfd, and a zero timeout never blocks.
        let ready = unsafe { libc::poll(&mut poll, 1, 0) };
        (ready >= 0).then_some(ready > 0)
    }

    /// Whether the scheduler granted the exit of process `detpid` and its
    /// parent has not reaped it: a zombie whose death the schedule fixed.
    pub(crate) fn process_exit_granted(&self, detpid: DetPid) -> bool {
        self.thread_tree.granted_exits.contains(&detpid)
    }

    /// Record that the scheduler granted `detpid`'s exit, as its final Exit
    /// grant does.
    #[cfg(test)]
    pub(crate) fn grant_exit_for_test(&mut self, detpid: DetPid) {
        self.thread_tree.granted_exits.insert(detpid);
    }

    /// The registered thread through which a SIGKILL's victim `detpid` is
    /// known on the host: `named`, the thread the kill named, when it is
    /// registered, or else, for a kill that named the process
    /// (`process_directed`: kill or a pidfd), the victim's lowest registered
    /// thread. A pidfd names the victim's leader, which may have exited while
    /// its siblings run on (https://github.com/rrnewton/hermit/issues/4411).
    /// A thread-directed SIGKILL (tkill, tgkill, rt_tgsigqueueinfo) to an
    /// exited thread gets no fallback: Linux does not end the group for it
    /// (Claude review of https://github.com/rrnewton/hermit/pull/4439, R1).
    pub(crate) fn sigkill_victim_registered_thread(
        &self,
        named: DetTid,
        detpid: DetPid,
        process_directed: bool,
    ) -> Option<DetTid> {
        if self.physical_thread_pidfds.contains_key(&named) {
            return Some(named);
        }
        if !process_directed {
            return None;
        }
        self.live_group_members(detpid)
            .into_iter()
            .find(|tid| self.physical_thread_pidfds.contains_key(tid))
    }

    /// The threads of `detpid`'s process (`process_threads`), in DetTid
    /// order. The tree never drops an edge, so after a thread id is reused it
    /// can also be listed under its old group (Claude review of
    /// https://github.com/rrnewton/hermit/pull/4439, R3), and the tree's walk
    /// can miss a thread of the process (`process_threads` lists the ways).
    fn live_group_members(&self, detpid: DetPid) -> Vec<DetTid> {
        if !self.thread_tree.contains(&detpid) {
            return Vec::new();
        }
        let mut group = self.process_threads(detpid);
        group.sort();
        group
    }

    fn remove_physical_thread(&mut self, dettid: &DetTid, mm: MmId) {
        if self
            .physical_thread_pidfds
            .get(dettid)
            .is_some_and(|(registered_mm, ..)| *registered_mm == mm)
        {
            self.physical_thread_pidfds.remove(dettid);
        }
    }

    /// The kernel's process ID of the host thread `dettid` registered as
    /// ([`Self::register_physical_thread`]), if it registered one.
    pub(crate) fn physical_process_id(&self, dettid: DetTid) -> Option<i32> {
        self.physical_thread_pidfds
            .get(&dettid)
            .map(|(_, pid, _, _)| *pid)
    }

    #[cfg(test)]
    pub(crate) fn physical_thread_identity(&self, dettid: DetTid) -> Option<(MmId, i32, i32)> {
        self.physical_thread_pidfds
            .get(&dettid)
            .map(|(mm, pid, tid, _)| (*mm, *pid, *tid))
    }

    /// Record, in the sender's committed turn, that a SIGKILL to `dettid` (or
    /// to process `target_process`) succeeded. The process will die even
    /// while one of its threads is held at a happens-before gate, so
    /// [`Scheduler::child_waits_wait_only_on_stuck_children`] never counts a
    /// wait for it as part of a deadlock. On ptrace its retirement comes later,
    /// at its host-timed deregistration
    /// (https://github.com/rrnewton/hermit/issues/3994); this record is
    /// decided by the sender's syscall, so it is deterministic.
    pub(crate) fn record_committed_sigkill(
        &mut self,
        dettid: DetTid,
        target_process: Option<DetPid>,
    ) {
        let process = target_process.or_else(|| {
            self.thread_tree
                .thread_to_leader
                .get(&dettid)
                .map(|leader| DetPid::from_raw(leader.as_raw()))
        });
        match process {
            Some(process) => {
                self.sigkilled_processes.insert(process);
                self.pi_doomed_processes.insert(process);
                self.release_pi_futexes_of_killed(process);
            }
            None => self.unresolved_sigkill = true,
        }
    }

    /// A committed SIGKILL doomed `process` (`record_committed_sigkill`,
    /// never a process group's notice before its send): the PI futexes its threads
    /// own go to their waiters now, in the sender's turn, as each thread will
    /// release them in its own exit (`futex_exit_release`) before anything
    /// later can see it. Their retirement comes at a host-timed moment that no
    /// turn waits for (https://github.com/rrnewton/hermit/issues/3994), so
    /// releasing there would admit the waiters at a host-timed drain. A doomed
    /// thread runs no more guest code, so it cannot unlock meanwhile.
    // TODO-HUMAN-REVIEW(#4616): Review handing a SIGKILLed process's PI
    // futexes over at the kill's commit.
    fn release_pi_futexes_of_killed(&mut self, process: DetPid) {
        let threads: Vec<DetTid> = self
            .next_turns
            .keys()
            .copied()
            .filter(|thread| self.thread_tree.process_of(*thread) == Some(process))
            .collect();
        for thread in threads {
            self.release_pi_futexes_of(thread);
        }
    }

    /// Record a successful SIGKILL the scheduler is not told about one victim
    /// at a time: every process now in process group `group`, or, for `None`
    /// (a pidfd whose process Detcore did not record), an unknown process.
    /// An unknown victim makes every child wait count as input that may still
    /// arrive for the rest of the run.
    pub(crate) fn record_unresolved_sigkill(&mut self, group: Option<DetPid>) {
        match group {
            Some(group) => {
                let members: Vec<DetPid> = self
                    .thread_tree
                    .process_wait
                    .iter()
                    .filter(|(_, metadata)| metadata.process_group == group)
                    .map(|(process, _)| *process)
                    .collect();
                self.sigkilled_processes.extend(members);
            }
            None => self.unresolved_sigkill = true,
        }
    }

    /// Whether an empty run queue waits for `process`'s deaths after one of
    /// its threads died of a fatal signal (test observation).
    #[cfg(test)]
    pub(crate) fn signal_death_victim(&self, process: DetPid) -> bool {
        self.signal_death_victims.contains(&process)
    }

    /// Retire `leader` at its own exit as `retire_exited_leader` does on
    /// ptrace, with its exit granted (test setup).
    #[cfg(test)]
    pub(crate) fn retire_test_exited_leader(&mut self, leader: DetTid, mm: MmId) -> bool {
        self.models_signal_targets = true;
        self.committed_exits.insert(leader);
        self.retire_exited_leader(leader, mm)
    }

    /// `sender`, in its delivery turn, is about to take a signal whose action
    /// is the default and whose default action ends the process. Linux ends
    /// the whole thread group at that delivery: `get_signal` carries out the
    /// default action with `do_group_exit` (or `do_coredump` first), which
    /// queues SIGKILL to every other thread before any of them runs another
    /// user instruction. Two exceptions decide nothing here: a PID
    /// namespace's init, for which `get_signal` skips the default action
    /// (`SIGNAL_UNKILLABLE`), and a process with an exec in flight, whose
    /// `de_thread` kills the other threads instead (`do_group_exit` and
    /// `zap_threads` defer to `group_exec_task`).
    ///
    /// The process is recorded doomed (`record_committed_fatal_signal`). When
    /// `retire_others` (the caller read that the kernel carries the default
    /// action out when it resumes `sender`), on a backend that retires a
    /// kill's victims at the kill turn (ptrace), its other threads are
    /// retired here, as committed victims (`retire_fatal_delivery_victims`). Before, each left at its own
    /// host-timed exit report, and a report that came after the sender's let
    /// the empty run queue read as a deadlock of the threads still parked in
    /// futex waits. Returns whether any thread was retired: the sender then
    /// files nothing more, since turn selection now waits for the victims'
    /// deaths, which only its delivery causes.
    pub(crate) fn commit_fatal_delivery(&mut self, sender: DetTid, retire_others: bool) -> bool {
        let Some(process) = self.registered_process(sender) else {
            return false;
        };
        if self.thread_tree.is_pid_namespace_init(process)
            || self.exec_teardowns.contains_key(&process)
        {
            return false;
        }
        self.record_committed_fatal_signal(process);
        if !retire_others {
            return false;
        }
        if !self.holds_serial_grant(sender) {
            tracing::warn!(
                "[scheduler] dettid {sender} reported a fatal delivery without holding the serial grant; its process's other threads stay"
            );
            return false;
        }
        !self.retire_fatal_delivery_victims(sender).is_empty()
    }

    /// Whether a committed SIGKILL doomed `process`, and whether one with an
    /// unnamed victim was seen (test observation of the record above).
    #[cfg(test)]
    pub(crate) fn sigkill_recorded(&self, process: DetPid) -> (bool, bool) {
        (
            self.sigkilled_processes.contains(&process),
            self.unresolved_sigkill,
        )
    }

    /// `dettid`'s own `Exit` (an `exit` or `exit_group`) is granted, in its
    /// committed turn. Its priority-inheritance futexes go to their waiters
    /// here, at the grant, rather than when it deregisters at a host-timed
    /// moment: Linux releases them in the exiting thread's own context
    /// (`futex_exit_release` from `exit_mm`), before anything a later turn can
    /// see, and no locker may attach to it any more
    /// (`Self::pi_futex_live_owner_named`). The waiters it hands a futex are
    /// admitted at the next drain, as at a deregistration.
    // TODO-HUMAN-REVIEW(#4616): Review releasing an exiting owner's PI futexes
    // at its committed Exit grant.
    fn commit_own_exit(&mut self, dettid: DetTid) {
        self.committed_exits.insert(dettid);
        self.release_pi_futexes_of(dettid);
    }

    /// A thread is being registered on `dettid`: any committed exit recorded
    /// for an earlier thread with that tid no longer applies.
    pub(crate) fn forget_committed_exit(&mut self, dettid: DetTid) {
        self.forget_sigkill_receipt(dettid);
        self.committed_exits.remove(&dettid);
        // A leader registering on a pid names a new process.
        self.pi_doomed_processes
            .remove(&DetPid::from_raw(dettid.as_raw()));
        self.retired_exited_leaders.remove(&dettid);
        // A reused pid names a new process, not one a namespace's end or a
        // fatal signal doomed.
        self.namespace_zap_victims.remove(&dettid);
        self.signal_death_victims.remove(&dettid);
        self.fatal_signal_doomed.remove(&dettid);
    }

    pub(crate) fn note_process_sigkill(
        &mut self,
        dettid: DetTid,
        detpid: DetPid,
        process_directed: bool,
    ) {
        if !self.backend.requires_thread_directed_process_signals {
            return;
        }
        let threads: Vec<DetTid> = self
            .live_group_members(detpid)
            .into_iter()
            .filter(|tid| self.next_turns.contains_key(tid))
            .collect();
        // A zombie whose exit the schedule granted has nothing left to retire:
        // Linux sends the signal and nothing changes
        // (https://github.com/rrnewton/hermit/issues/4411).
        if process_directed && threads.is_empty() && self.process_exit_granted(detpid) {
            return;
        }
        let named_mm = self.physical_thread_pidfds.get(&dettid).map(|(mm, ..)| *mm);
        // The named thread may be an exited leader, as a pidfd names it: for a
        // kill that named the process, any registered live thread of the
        // victim is enough to know it (https://github.com/rrnewton/hermit/issues/4411).
        // A thread-directed SIGKILL to an exited thread gets no such fallback
        // (Claude review of https://github.com/rrnewton/hermit/pull/4439, R1).
        if named_mm.is_none() && !process_directed {
            self.terminal_deadlock.get_or_insert_with(|| {
                format!(
                    "HERMIT_DEADLOCK: scheduler cannot complete SIGKILL for dettid {} without its host thread pidfd",
                    dettid,
                )
            });
            return;
        }
        if named_mm.is_none()
            && !threads
                .iter()
                .any(|tid| self.physical_thread_pidfds.contains_key(tid))
        {
            self.terminal_deadlock.get_or_insert_with(|| {
                format!(
                    "HERMIT_DEADLOCK: scheduler cannot complete SIGKILL for dettid {} without its host thread pidfd",
                    dettid,
                )
            });
            return;
        }
        // SIGKILL ends the whole thread group, whichever thread it names.
        // Retire every live thread of the group, the named one first, then in
        // DetTid order, at this same committed point: none of them runs guest
        // code again, and on this backend a killed thread's pending request is
        // answered (`needs_killed_thread_rpc_cancellation`)
        // (https://github.com/rrnewton/hermit/issues/4362).
        if let Some(mm) = named_mm {
            self.logically_kill_thread(&dettid, &detpid, mm);
        }
        for tid in threads
            .into_iter()
            .filter(|tid| *tid != dettid || named_mm.is_none())
        {
            let mm = self
                .physical_thread_pidfds
                .get(&tid)
                .map(|(mm, ..)| *mm)
                .or_else(|| self.thread_mm(tid))
                .unwrap_or(MmId::initial(tid));
            self.logically_kill_thread(&tid, &detpid, mm);
        }
    }

    fn should_synthesize_child_exit_signal(&self, parent: DetTid) -> bool {
        !self.physical_thread_pidfds.contains_key(&parent)
    }

    /// Refuse the run (`HERMIT_HB_POSTHOOK_INTERRUPTED`, exit 122) for a
    /// syscall entry of `dettid` that reached posthook `anchors` and returned
    /// the internal restart `code`: whether that entry returns `EINTR` or is
    /// restarted and never returns is decided by the kernel after this point
    /// (<https://github.com/rrnewton/hermit/issues/3929>).
    ///
    /// The guest names every spawn-ordinal anchor at its nth matching call on
    /// any thread, as for a completed call, so only the anchors that resolve
    /// to `dettid` count ([`HbRuntime::occurrence_anchors_on`]); with none,
    /// the turn proceeds. Otherwise nothing fires, the verdict is recorded (an
    /// earlier pending verdict and its classification are kept), and the turn
    /// grants nothing, so no guest code runs alongside the policy exit.
    fn hb_posthook_interrupted(
        &mut self,
        dettid: DetTid,
        count: u64,
        anchors: &[String],
        code: &str,
    ) -> Result<(), SkipTurn> {
        let anchors = self
            .happens_before
            .as_ref()
            .expect("posthook refusal issued without a happens-before program")
            .occurrence_anchors_on(dettid, anchors);
        if anchors.is_empty() {
            return Ok(());
        }
        if self.terminal_deadlock.is_none() {
            self.terminal_deadlock = Some(format!(
                "HERMIT_HB_POSTHOOK_INTERRUPTED: dtid {} reached posthook happens-before \
                 anchor(s) {:?} at syscall count {}, and the call was interrupted ({}); whether \
                 it returns EINTR or is restarted is decided by the kernel after Hermit's \
                 checkpoint, so the anchor cannot be enforced. Anchor the edge at the prehook \
                 or on a call that is not interrupted.",
                dettid, anchors, count, code
            ));
            self.terminal_kind = TerminalKind::Refusal;
        }
        self.skip_turn_blocked(dettid)
    }

    /// Handle a happens-before checkpoint issued by `dettid` after its `count`th
    /// intercepted syscall (see `Detcore::handle_syscall_event`).
    ///
    /// Grants passage (firing every anchor at `SyscallCount(count)` on this
    /// thread and re-admitting any parked threads whose gate may now be open)
    /// unless a reached anchor is the AFTER endpoint of a Hard edge whose BEFORE
    /// anchor has not fired, in which case the thread is parked out of the run
    /// queue until a later firing wakes it. Mirrors the `SleepUntil` park/skip
    /// protocol: the request/response ivars are left intact so the re-admitted
    /// thread re-evaluates this same checkpoint on its next turn.
    fn hb_checkpoint(
        &mut self,
        dettid: DetTid,
        count: u64,
        occurrence_anchors: &[String],
    ) -> Result<(), SkipTurn> {
        let (reached, blocked) = {
            let hb = self
                .happens_before
                .as_ref()
                .expect("hb checkpoint issued without a happens-before program");
            let mut reached = hb.anchors_at_syscall(dettid, count);
            reached.extend(hb.occurrence_anchors_on(dettid, occurrence_anchors));
            let blocked = reached.iter().any(|name| hb.anchor_blocked(name));
            (reached, blocked)
        };

        if reached.is_empty() {
            // No anchor addresses this (thread, count); nothing to gate or fire.
            return Ok(());
        }

        if blocked {
            info!(
                "[scheduler] >>>>>>>\n\n NONCOMMIT turn {}, SKIP dettid {} held at happens-before \
                 anchor(s) {:?} (syscall count {}) awaiting a BEFORE anchor",
                self.turn, dettid, reached, count
            );
            if self
                .vfork_barriers
                .values()
                .any(|child| *child == Some(dettid))
            {
                // While a vfork child runs, no other thread can be selected
                // (`step3_peek`), so a BEFORE anchor could never fire and the run
                // would spin with no report
                // (https://github.com/rrnewton/hermit/issues/3930). Refuse instead.
                // Keep an earlier verdict, and its classification, if one is
                // already pending.
                if self.terminal_deadlock.is_none() {
                    self.terminal_deadlock = Some(format!(
                        "HERMIT_HB_HOLD_IN_VFORK_CHILD: happens-before anchor(s) {:?} would hold \
                         dtid {}, a vfork child that has not exec'd yet; while it runs no other \
                         thread can, so its gate could never open. Anchor the edge on a point \
                         before the vfork or after the child's exec.",
                        reached, dettid
                    ));
                    self.terminal_kind = TerminalKind::Refusal;
                }
            }
            let now_ns = self.committed_time.as_nanos();
            let hb = self.happens_before.as_mut().unwrap();
            hb.parked.insert(dettid);
            hb.held_at.insert(dettid, reached.clone());
            hb.holds.entry(dettid).or_insert_with(|| HbHold {
                since_ns: now_ns,
                anchors: reached.clone(),
            });
            return self.skip_turn_blocked(dettid);
        }

        // Grant passage: fire the reached anchors. Only wake parked threads when a
        // new anchor actually fired, so an idempotent re-grant causes no churn.
        let mut newly_fired = false;
        {
            let hb = self.happens_before.as_mut().unwrap();
            // Passage granted: any hold of this thread is over.
            hb.holds.remove(&dettid);
            for name in &reached {
                if hb.fired.insert(name.clone()) {
                    newly_fired = true;
                }
            }
        }
        if newly_fired {
            debug!(
                "[happens-before] dettid {} fired anchor(s) {:?} at syscall count {}",
                dettid, reached, count
            );
            // Defer the actual re-admission: we are inside `block_for_one_resource`
            // with a `tentative_pop` selection live, and pushing to the run queue
            // now would trip the queue's transaction assertion. The next
            // `step2_drain_prefix` flushes (`step3_peek` as a backstop).
            self.happens_before.as_mut().unwrap().wake_pending = true;
        }
        Ok(())
    }

    /// If a happens-before anchor fired since the last check, re-admit every
    /// parked thread to the run queue so it re-evaluates its gate on its next
    /// turn. Threads still blocked re-park; the request/response ivars are
    /// untouched, so no request needs re-filling. Deterministic: parked threads
    /// are iterated in `DetTid` order.
    ///
    /// Called from `step2_drain_prefix`, with the other deferred run-queue
    /// admissions and before step2c and step2d look at the queue, and from
    /// `step3_peek` *before* the turn's `tentative_pop`. Both are points with no
    /// live selection transaction: anchors fire deep inside
    /// `block_for_one_resource` while a selection is live, so the actual
    /// re-admission must be deferred to one of them.
    fn hb_flush_wakes(&mut self) {
        match self.happens_before.as_mut() {
            Some(hb) if hb.wake_pending => hb.wake_pending = false,
            _ => return,
        }
        let parked: Vec<DetTid> = self
            .happens_before
            .as_ref()
            .map(|hb| hb.parked.iter().copied().collect())
            .unwrap_or_default();
        for dettid in parked {
            let hb = self.happens_before.as_mut().unwrap();
            hb.parked.remove(&dettid);
            hb.held_at.remove(&dettid);
            if !self.run_queue.contains_tid(dettid) {
                let pos = self.runqueue_push_back(dettid);
                trace!(
                    "[happens-before] re-admitting parked dettid {} at queue position {}",
                    dettid, pos
                );
            }
        }
    }

    /// Refuse the run when a held thread has outlasted a version-2 program's
    /// hold budget (`max_hold_ns`), charged in committed virtual time.
    ///
    /// Called from `step2_drain_prefix`, so at every step2 pass of both turn
    /// loops, before selection. It reads only `committed_time` and the
    /// scheduler's own hold records, and it ends the run rather than releasing
    /// the thread, so it never decides which thread runs. A run with no
    /// version-2 program, or no hold, returns at once.
    fn hb_check_hold_budget(&mut self) -> Result<(), SkipTurn> {
        let now_ns = self.committed_time.as_nanos();
        let Some(refusal) = self
            .happens_before
            .as_ref()
            .and_then(|hb| hb.hold_budget_refusal(now_ns))
        else {
            return Ok(());
        };
        if self.terminal_deadlock.is_none() {
            self.terminal_deadlock = Some(refusal);
            self.terminal_kind = TerminalKind::Refusal;
        }
        Err(SkipTurn)
    }

    /// Fill in a resource request, which is exactly what might make the next logical
    /// step become unblocked.
    pub fn request_put(
        &mut self,
        req: &Ivar<SchedRequest>,
        rs: Resources,
        _global_time: &Arc<Mutex<GlobalTime>>,
    ) {
        // AUTONOMOUS-BOT-IMPLEMENTED
        // TODO-HUMAN-REVIEW(PR-1041): A guest resource-request RPC can race an
        // asynchronous signal delivery. `force_unblock_thread` replaces
        // `next_turns[tid].req` with an already-full Ivar carrying an
        // `InboundSignal` request (see the `Ivar::full` at the bottom of this
        // file). If the guest's own resource-request then lands on that same
        // turn, the previous unconditional `req.put()` panicked with "Ivar
        // multiple put" (observed intermittently on `timeout 5 echo hi` under
        // `--strict --verify`, where a 5s SIGALRM races the child's `wait4`).
        // Tolerate exactly that case: drop the late guest request and let the
        // signal turn win — the interrupted syscall (e.g. `rt_sigsuspend`)
        // restarts and re-issues a fresh request on the next turn. Any other
        // double-put still panics, preserving the write-once Ivar invariant.
        // Mirrors the `try_put` guard in `logically_kill_thread` (PR-845).
        if rs.passes_descriptors_out {
            self.revoke_guest_held_marks(rs.tid);
        }
        let continuation =
            (rs.continues_sigreturn && Self::is_inbound_signal_turn(&rs)).then_some(rs.tid);
        // A `nanosleep` filing its request starts with no interruption noted
        // (`BlockedPool::sleep_interruptions`): one an earlier sleep's wake
        // left behind can never reach it.
        if rs.fyi.as_str() == crate::resources::NANOSLEEP_FYI {
            self.blocked.sleep_interruptions.remove(&rs.tid);
        }
        if let Some(dropped) = req.try_put(Ok(rs)) {
            let tolerated = matches!(
                req.try_read(),
                Some(Ok(existing))
                    if existing
                        .resources
                        .keys()
                        .any(|r| {
                            matches!(
                                r,
                                ResourceID::InboundSignal(_) | ResourceID::WaitidSignals(_)
                            )
                        })
            );
            if tolerated {
                trace!(
                    "[request_put] dropping late guest request {:?}; an async inbound signal already filled the request for this turn (req {})",
                    dropped, req
                );
            } else {
                panic!(
                    "Ivar multiple put exception in request_put! Attempted to write {:?} to {}; existing content is not an inbound-signal request.",
                    dropped, req
                );
            }
        } else if let Some(thread) = continuation {
            self.sigreturn_continuations.insert(thread);
        }
    }

    /// Poll the resource request and *if* it is not currently observed to be full, return
    /// the IVar that *will* contain it in the future.
    fn check_request(&self, det_tid: &DetTid) -> Option<Ivar<SchedRequest>> {
        let nextturn = self.next_turns.get(det_tid).unwrap_or_else(|| {
            panic!(
                "[check_request] internal error: dettid {} queued but missing entry in next_turns",
                det_tid
            )
        });
        if nextturn.req.is_empty() {
            Some(nextturn.req.clone())
        } else {
            None
        }
    }

    /// Returns None if all are parked, otherwise the unfilled request of the next we're waiting on.
    fn are_all_quiesced(&self) -> Option<Ivar<SchedRequest>> {
        // Skip raw TIDs whose old run-queue incarnation is pending removal.
        // `Retire` targets have no `next_turns` entry, while
        // `ReplaceThenAdmit` targets have a fresh registration that must not be
        // waited on until the drain removes the old physical slot and admits
        // that replacement.
        self.run_queue
            .tids()
            .filter(|dt| !self.pending_run_queue_removals.contains_key(dt))
            .find_map(|dt| self.check_request(dt))
    }

    /// Try to pop the next event from the sorted list of stacktrace_events, if it matches the given
    /// index.  This is idempotent, because subsequent attempts will just fizzle.
    ///
    /// The index is the traced (observed) event count, when recording and
    /// under `--replay-schedule-from` alike: it is the counting
    /// `hermit analyze` names critical events by, including a pair a flipped
    /// schedule cannot consume in flipped order at a thread's exit.
    ///
    /// A run can pass a requested index without printing it: the list can be
    /// installed after events were already consumed. Every requested index
    /// below `current_ix` is then reported as missed and discarded, so it
    /// neither disappears silently nor stays at the head of the list and
    /// blocks every later index.
    fn try_pop_stacktrace_event(
        &mut self,
        current_ix: u64,
        observed: &SchedEvent,
    ) -> MaybePrintStack {
        let mut result = None;
        if let Some(iter) = &mut self.stacktrace_events {
            while let Some((missed, _, m_path)) = iter.next_if(|(ix, _, _)| *ix < current_ix) {
                let destination = m_path
                    .as_ref()
                    .map_or_else(|| "stderr".to_string(), |p| p.display().to_string());
                tracing::warn!(
                    "No stack trace for scheduled event #{} (requested for {}): the run passed that position without running it, and reached #{} = {}",
                    missed,
                    destination,
                    current_ix,
                    observed,
                );
                crate::util::capped_eprintln!(
                    "\nMissed stack trace for scheduled event #{} (requested for {}): the run passed that position without running it, and reached #{} = {}",
                    missed,
                    destination,
                    current_ix,
                    observed,
                );
            }
        }
        if let Some(iter) = &mut self.stacktrace_events
            && let Some((next_ix, _, m_path)) = iter.peek()
            && *next_ix == current_ix
        {
            info!(
                "Now output stack trace for scheduled event #{} = {}:",
                current_ix, observed,
            );
            if m_path.is_none() {
                crate::util::capped_eprintln!(
                    "\nPrinting stack trace for scheduled event #{} = {}:",
                    current_ix,
                    observed,
                );
            }
            result = Some(m_path.clone());
            let _ = iter.next();
        }
        result
    }

    /// Report as missed, and discard, every requested stack trace index still
    /// pending, with `reason` saying why each cannot print. As for an index the
    /// run passed (`try_pop_stacktrace_event`), an index that will never print
    /// is reported rather than dropped silently.
    fn report_unprintable_stacktrace_events(
        &mut self,
        reason: impl Fn(u64) -> String,
    ) -> Vec<(u64, String)> {
        let mut reported = Vec::new();
        let Some(iter) = &mut self.stacktrace_events else {
            return reported;
        };
        for (index, _, m_path) in iter.by_ref() {
            let destination = m_path
                .as_ref()
                .map_or_else(|| "stderr".to_string(), |p| p.display().to_string());
            let reason = reason(index);
            tracing::warn!(
                "No stack trace for scheduled event #{} (requested for {}): {}",
                index,
                destination,
                reason,
            );
            crate::util::capped_eprintln!(
                "\nMissed stack trace for scheduled event #{} (requested for {}): {}",
                index,
                destination,
                reason,
            );
            reported.push((index, reason));
        }
        reported
    }

    /// Before a replay stops the run (`--replay-exhausted-panic`,
    /// `--die-on-desync`), report every requested stack trace index still
    /// pending: no later event will reach one, and the stop skips the run's
    /// end, where they would be reported. The stopping event's own index,
    /// `stopping_ix`, is reported too rather than printed, since the stop
    /// comes before the thread could print its stack.
    fn report_stacktrace_events_at_stop(
        &mut self,
        stopping_ix: Option<u64>,
        flag: &str,
    ) -> Vec<(u64, String)> {
        self.report_unprintable_stacktrace_events(|index| {
            stacktrace_stop_reason(index, stopping_ix, flag)
        })
    }

    /// Report every schedule position still requested where a replay is
    /// about to stop away from event consumption (a fatal time-skip desync,
    /// a fatal departure from the record's readmissions, or a fatal
    /// unrecorded background start). Only the opt-in schedule-position
    /// selector is affected: with it off, those stops report nothing here,
    /// exactly as they did before it existed.
    fn report_stacktrace_positions_at_replay_stop(&mut self, flag: &str) -> Vec<(u64, String)> {
        if self.stacktrace_at_schedule_positions {
            self.report_stacktrace_events_at_stop(None, flag)
        } else {
            Vec::new()
        }
    }

    /// At the end of a run that records or replays a schedule, report every
    /// requested stack trace index it never reached. Idempotent: the indices
    /// are discarded as they are reported. Called at the run summary; a run
    /// that ends without one (a non-ptrace backend's `--timeout`, a backend
    /// failure, another immediate exit) does not report them.
    fn report_stacktrace_events_the_run_did_not_reach(&mut self) -> Vec<(u64, String)> {
        if !self.stacktrace_events_counted {
            // `--stacktrace-event` without a recorded or replayed schedule,
            // which counts nothing, as the configuration warned.
            return Vec::new();
        }
        if self.stacktrace_at_schedule_positions {
            // A requested schedule position the replay never reached (its
            // recorded event was never consumed, as for an exit pair a
            // flipped schedule cannot run in flipped order) is reported by
            // position, never dropped silently.
            return self.report_unprintable_stacktrace_events(
                stacktrace_schedule_position_not_reached_reason,
            );
        }
        self.report_unprintable_stacktrace_events(|_| {
            "the run ended before reaching it".to_string()
        })
    }

    /// Under `--stacktrace-at-schedule-positions`, a released schedule
    /// (`Replayer::release_schedule`) consumes no further position: report
    /// every requested position still pending as missed, at the release,
    /// rather than drop it silently.
    fn report_schedule_positions_a_release_drops(&mut self) -> Vec<(u64, String)> {
        self.report_unprintable_stacktrace_events(|_| {
            "the replay released its schedule before consuming that position".to_string()
        })
    }

    /// Under `--replay-schedule-from`, wake the thread the trace switches to
    /// now if it is still in a timed wait whose deadline has passed, so it is
    /// runnable when the next turn is chosen.
    ///
    /// A scheduler pass wakes at most one due timed waiter
    /// (`step2b_process_timed`), so how many due waiters are runnable when a
    /// turn is chosen depends on how many passes ran since their deadlines
    /// passed. The recording's passes include its chaos change points and
    /// slice ends, which the replay does not repeat, so a timed waiter the
    /// recording had woken in an extra pass could still be waiting when the
    /// replay switched to it. The switch then fell through to another
    /// runnable thread, a desync ("expected to be running thread 5, but
    /// running 7"). This is rare while every turn charges half a millisecond
    /// and deadlines pass several passes early. Where a run of expired timed
    /// waits is charged one turn (`expired_wait_runs_charged_once`), deadlines
    /// pass as committed time creeps forward between the turns of that run,
    /// often at the last turn before the switch. Waking the target at its
    /// passed deadline is what the next pass would do anyway, just ahead of
    /// the other due waiters, which the following passes wake as before.
    ///
    /// A target owed a deferred SIGCHLD (`sigchld_deferred`) is left alone:
    /// the recording may have resumed it down that signal's path
    /// (`step2e_process_signal_deferred`), and a wake here would end its wait
    /// by the timeout instead, a replay that differs from its recording
    /// without a desync to say so.
    fn wake_due_replay_target(&mut self, target: DetTid) {
        if self.run_queue.contains_tid(target) || self.blocked.sigchld_deferred.contains(&target) {
            return;
        }
        let Some(deadline) = self.blocked.timed_waiters.thread_deadline(target) else {
            return;
        };
        if deadline > self.committed_time || deadline.is_indefinite() {
            return;
        }
        self.blocked.timed_waiters.remove(target);
        trace!(
            "[replay] dtid {} woken at its passed deadline {} (committed {}) for the trace's switch",
            target, deadline, self.committed_time
        );
        self.wake_timed_event(deadline, target);
    }

    /// Verify that the event we're replaying matches what just happened.  Set up the next
    /// (replayed) event to run.  Return true if the current thread will keep running and false if
    /// it needs to be descheduled.
    ///
    /// PreReq: we're running under --replay-schedule-from
    pub fn consume_schedevent(&mut self, observed: &SchedEvent) -> ConsumeResult {
        if self.boundary_replayer.is_some() {
            return self
                .consume_boundary_record(&detcore_model::schedule::boundary::Record::Event(
                    observed.clone(),
                ))
                .unwrap_or_else(|error| exit_on_scheduler_refusal(&error));
        }
        debug_assert!(self.replayer.is_some());
        let mytid = observed.dettid;

        if let Some(ReplayStep {
            traced_ix: ix,
            action,
            position,
            released_now,
        }) = self.replayer.as_mut().map(|r| {
            let traced_ix = r.traced_event_count;
            let was_released = r.released();
            let action = r.observe_event(observed);
            ReplayStep {
                traced_ix,
                action,
                position: r.stacktrace_position(traced_ix),
                released_now: !was_released && r.released(),
            }
        }) {
            let stop_flag = match action {
                replayer::ReplayAction::Stop(StopReason::FatalDesync) => Some("--die-on-desync"),
                replayer::ReplayAction::Stop(StopReason::ReplayExausted) => {
                    Some("--replay-exhausted-panic")
                }
                _ => None,
            };
            let print_stack = if let Some(flag) = stop_flag {
                // Under `--stacktrace-at-schedule-positions` the stopping
                // event's own index is its schedule position, if it has one.
                let stopping = if self.stacktrace_at_schedule_positions {
                    position
                } else {
                    Some(ix)
                };
                self.report_stacktrace_events_at_stop(stopping, flag);
                None
            } else if self.stacktrace_at_schedule_positions {
                if released_now {
                    self.report_schedule_positions_a_release_drops();
                }
                position.and_then(|position| self.try_pop_stacktrace_event(position, observed))
            } else {
                self.try_pop_stacktrace_event(ix, observed)
            };
            debug!("Next ReplayAction = {:?}", action);
            self.release_replay_priorities_if_exhausted(true);

            match action {
                replayer::ReplayAction::Continue(timeslice_remaining) => {
                    return ConsumeResult {
                        keep_running: true,
                        print_stack,
                        event_ix: ix,
                        timeslice_remaining,
                    };
                }
                replayer::ReplayAction::Stop(StopReason::FatalDesync) => immediate_fatal_exit(),
                replayer::ReplayAction::Stop(StopReason::ReplayExausted) => immediate_fatal_exit(),
                replayer::ReplayAction::ContextSwitch(is_now, new_tid, timeslice_remaining) => {
                    self.requeue_with_new_priority(mytid, REPLAY_DEFERRED_PRIORITY);
                    self.requeue_with_new_priority(new_tid, REPLAY_FOREGROUND_PRIORITY);
                    self.wake_due_replay_target(new_tid);
                    self.note_replay_switch(mytid, new_tid, observed_is_syscall_prehook(observed));
                    if !self.run_queue.contains_tid(new_tid) {
                        // If it is not yet in next_turns, that is because it was JUST spawned and
                        // hasn't showed up yet, but it will by the next scheduler turn.
                        if self.next_turns.contains_key(&new_tid) {
                            tracing::warn!(
                                "Attempted to context switch to tid {}, but it is not runnable atm. This could be legitimate if it is awoken by another thread exiting (futex wake).",
                                new_tid
                            );
                            // TODO(T138906107): make this a fatal error when RESYNC capability is robust enough.
                            // immediate_fatal_exit();
                        }
                    }
                    // The recorded slice length is the next thread's, handed to
                    // it with its grant (`timeslices`). The thread that
                    // switches takes it too. At a prehook it runs on into its
                    // call, and in the recording its yield there ended its
                    // slice, so it resumed with a fresh one; the replay sets
                    // its next timer-ended deadline just before that segment
                    // (`Continue`), so until then it needs a deadline that
                    // does not end the segment early. Its earlier deadline,
                    // set before the yield, can: a static guest's yielding
                    // thread then ended slices its recording did not have,
                    // and its clock moved (`a_schedule_replay_keeps_the_clock_of_a_thread_that_yields_beside_a_computing_one`).
                    // In a recording without `--chaos` a timer-ended slice is
                    // the full `--max-timeslice`, the same length as the fresh
                    // slice the switching thread resumed with. Under `--chaos`
                    // the two lengths differ; replays of such recordings leave
                    // them for other reasons too, and which deadline is right
                    // there is not established.
                    // A thread the replay switches to takes its first
                    // timeslice end with a stop: the grant that resumes it
                    // carries only the length.
                    self.timeslices
                        .insert(new_tid, timeslice_remaining.map(|end| end.length));
                    return ConsumeResult {
                        keep_running: !is_now,
                        print_stack,
                        event_ix: ix,
                        timeslice_remaining,
                    };
                }
            };
        }

        ConsumeResult {
            keep_running: true,
            print_stack: None,
            event_ix: 0,
            timeslice_remaining: None,
        }
    }

    /// Updates the address Linux clears and wakes when this thread exits.
    ///
    /// `set_tid_address(2)` replaces the value supplied by clone. A zero
    /// address disables the exit-time store and wake.
    pub fn set_child_tid_address(&mut self, dettid: DetTid, address: usize) -> bool {
        let Some(next_turn) = self.next_turns.get_mut(&dettid) else {
            return false;
        };
        next_turn.child_tid_addr = address;
        true
    }

    /// Freeze the live sibling set at the caller's deterministic exec boundary.
    /// A failed exec must not kill these threads; only successful exec, or an
    /// actual exit receipt for a sibling, authorizes its eventual retirement.
    pub(crate) fn prepare_exec_teardown(
        &mut self,
        caller: DetTid,
        process: DetPid,
        mm: MmId,
    ) -> bool {
        if self.registered_process(caller) != Some(process)
            || !self.next_turns.contains_key(&caller)
            || !self.rpc_incarnation_matches(caller, mm)
            || self.exec_teardowns.contains_key(&process)
        {
            return false;
        }
        let siblings = self
            .live_process_threads(process)
            .filter(|tid| *tid != caller)
            .collect();
        self.exec_teardowns.insert(
            process,
            ExecTeardown {
                caller,
                mm,
                siblings,
                observed: BTreeSet::new(),
            },
        );
        true
    }

    /// Account a physical exit without letting host callback order mutate the
    /// scheduler. The hook must return promptly: ptrace awaits the displaced
    /// leader's hook before invoking the survivor's successful exec callback.
    pub(crate) fn defer_exec_sibling_retirement(
        &mut self,
        tid: DetTid,
        process: DetPid,
        mm: MmId,
    ) -> bool {
        let Some(teardown) = self.exec_teardowns.get_mut(&process) else {
            return false;
        };
        if teardown.mm != mm || !teardown.siblings.contains(&tid) {
            return false;
        }
        teardown.observed.insert(tid);
        true
    }

    /// The exact old-image receipt replaces absence of a scheduler registration
    /// as proof that a transferred exec's displaced leader was consumed.
    pub(crate) fn exec_sibling_retirement_observed(
        &self,
        tid: DetTid,
        process: DetPid,
        mm: MmId,
    ) -> bool {
        self.exec_teardowns
            .get(&process)
            .is_some_and(|teardown| teardown.mm == mm && teardown.observed.contains(&tid))
    }

    /// Apply retirement in sorted order at the successful exec edge, or retire
    /// just physically consumed owners when an exec attempt fails. The caller
    /// remains registered with its empty request, so no turn can overtake the
    /// complete replacement registration. The ordinary removal path retains
    /// its INFO event, futex wakes and tentative-safe run-queue buffering.
    pub(crate) fn finish_exec_teardown(
        &mut self,
        caller: DetTid,
        process: DetPid,
        mm: MmId,
        succeeded: bool,
    ) -> Vec<DetTid> {
        if !self
            .exec_teardowns
            .get(&process)
            .is_some_and(|teardown| teardown.caller == caller && teardown.mm == mm)
        {
            return Vec::new();
        }
        let teardown = self.exec_teardowns.remove(&process).unwrap();
        let retired: Vec<_> = if succeeded {
            teardown.siblings
        } else {
            teardown.observed
        }
        .into_iter()
        .collect();
        // Only a successful exec's edge retires the others at a committed
        // point; a failed attempt retires the siblings that died meanwhile,
        // at moments host timing set.
        if succeeded {
            self.parent_death_exec_survivor = Some((process, caller));
        }
        for tid in &retired {
            self.logically_kill_thread(tid, &process, mm);
            self.timeslices.remove(tid);
        }
        self.parent_death_exec_survivor = None;
        if succeeded {
            // The existing successful exec edge has accounted this exact old
            // sibling set. The backend additionally authenticates their native
            // effects; the replacement image is a different retained owner.
            self.settle_reserved_input_fence(&retired);
        }
        self.remove_exec_vfork_barriers(&retired);
        self.finish_exec_alarm(process);
        retired
    }

    fn freeze_reserved_input_thread(&mut self, tid: DetTid) {
        let Some(control) = &self.reserved_input_control else {
            return;
        };
        let task = *self.reserved_input_tasks.get(&tid).unwrap_or_else(|| {
            panic!("reserved-input logical retirement lacks native binding for {tid}")
        });
        if self.reserved_input_settled_tasks.contains(&task) {
            // Logical kill is idempotent. A duplicate callback for this
            // already fenced exact generation must not install a new freeze.
            return;
        }
        if let Some((bound, _)) = self.reserved_input_freezes.get(&tid) {
            assert_eq!(
                *bound, task,
                "reserved-input retired incarnation was replaced before settlement"
            );
            return;
        }
        let cohort = control
            .freeze_tasks(&[task])
            .unwrap_or_else(|error| panic!("reserved-input retirement freeze failed: {error}"));
        self.reserved_input_freezes.insert(tid, (task, cohort));
    }

    /// Called only by an already completed scheduler cohort fence. Native
    /// receipts are an additional requirement, never a replacement fence.
    fn settle_reserved_input_fence(&mut self, tids: &[DetTid]) {
        if self.reserved_input_control.is_none() {
            return;
        }
        let tasks: Vec<_> = tids
            .iter()
            .map(|tid| {
                if let Some((frozen, _)) = self.reserved_input_freezes.get(tid) {
                    // Exec may already have published a new image under this
                    // logical/native number. The fence still owns the exact
                    // displaced incarnation captured at logical retirement.
                    *frozen
                } else {
                    *self.reserved_input_tasks.get(tid).unwrap_or_else(|| {
                        panic!("reserved-input completed fence lacks native binding for {tid}")
                    })
                }
            })
            .collect();
        self.settle_reserved_input_tasks(&tasks);
    }

    fn settle_reserved_input_tasks(&mut self, tasks: &[reverie::reserved_input::InputTaskId]) {
        let Some(control) = &self.reserved_input_control else {
            return;
        };
        for task in tasks {
            assert!(
                control.observe_exit_effects(*task).unwrap_or_else(|error| {
                    panic!("reserved-input completed fence has no native effects proof: {error}")
                }),
                "reserved-input completed fence precedes native exit effects"
            );
        }
        self.reserved_input_settled_tasks
            .extend(tasks.iter().copied());
        let all_settled: Vec<_> = self.reserved_input_settled_tasks.iter().copied().collect();
        let operations = self
            .reserved_input_operations
            .as_ref()
            .expect("installed input control requires native operation ownership");
        operations
            .terminal_fenced(&all_settled)
            .unwrap_or_else(|error| {
                panic!("reserved-input terminal operation lacks effects/publication proof: {error}")
            });
        control
            .settle_fenced_tasks(&all_settled)
            .unwrap_or_else(|error| {
                panic!("reserved-input completed fence lacks native settlement: {error}")
            });
        operations.fence_settled(&all_settled);
        self.reserved_input_freezes
            .retain(|_, (task, _)| !tasks.contains(task));
    }

    fn queue_reserved_input_exit_fence(&mut self, tid: DetTid) {
        if self.reserved_input_control.is_none() {
            return;
        }
        let task = self
            .reserved_input_freezes
            .get(&tid)
            .map(|(task, _)| *task)
            .or_else(|| self.reserved_input_tasks.get(&tid).copied())
            .unwrap_or_else(|| panic!("reserved-input Exit fence lacks native binding for {tid}"));
        self.reserved_input_exit_waiters.insert(task);
    }

    /// Consume the actual backend-to-Tool identity report at an existing
    /// logical birth or completed exec replacement, without a new RPC field.
    fn bind_reserved_input_task(&mut self, tid: DetTid) {
        if self.reserved_input_control.is_none() {
            return;
        }
        let task = *self.reserved_input_tool_tasks.get(&tid).unwrap_or_else(|| {
            panic!("reserved-input logical registration lacks Tool identity for {tid}")
        });
        if self
            .reserved_input_tasks
            .insert(tid, task)
            .is_some_and(|old| old != task)
        {
            // Any *unfenced* old incarnation stays retained in the native
            // registry. Dropping this local lookup handle never thaws it.
            // Already queued Exit fences carry their exact task, not `tid`.
            self.reserved_input_freezes.remove(&tid);
        }
    }

    /// Publish the turn the replacement image already owns, after its old
    /// image's fences and logical identity handoff. A successful exec callback
    /// or registered task alone is not execution authority. This changes no
    /// request, turn, clock, mask or current-owner selection.
    pub(crate) fn publish_reserved_input_exec_authority(
        &self,
        tid: DetTid,
        process: DetPid,
        mm: MmId,
    ) -> anyhow::Result<()> {
        let Some(control) = &self.reserved_input_control else {
            return Ok(());
        };
        anyhow::ensure!(
            tid == process
                && self.registered_process(tid) == Some(process)
                && self.thread_mm(tid) == Some(mm)
                && self.rpc_incarnation_matches(tid, mm)
                && self.holds_serial_grant(tid),
            "exec input authority has no matching current serial owner"
        );
        let task = *self
            .reserved_input_tasks
            .get(&tid)
            .ok_or_else(|| anyhow::anyhow!("exec input authority has no logical task binding"))?;
        let registration = control.registration(task).ok_or_else(|| {
            anyhow::anyhow!("exec input authority has no retained native generation")
        })?;
        anyhow::ensure!(
            self.reserved_input_tool_tasks.get(&tid) == Some(&task)
                && self
                    .reserved_input_native_tasks
                    .get(&registration.native_tid)
                    == Some(&task)
                && registration.tool_tid == Some(tid.as_raw())
                && registration.tool_pid == Some(process.as_raw())
                && !self.reserved_input_settled_tasks.contains(&task)
                && !self.reserved_input_freezes.contains_key(&tid),
            "exec input authority differs from the completed image binding"
        );
        if control.current_grant(task).is_some() {
            // An idempotent notification must not renew a grant consumed by a
            // live input operation. Still reject a frozen or retired identity.
            control.native_request_grant(task)?;
        } else {
            control.grant(task, reverie::reserved_input::InputGrantKind::Ordinary)?;
        }
        Ok(())
    }

    /// Remove a thread from the deterministic scheduler.  In order to call this, the precondition
    /// is that this thread will execute no further (visible) instructions.
    ///
    /// This is called while the guest is running, not in the middle of a scheduler turn.
    ///
    /// This is IDEMPOTENT, and it may indeed be called twice, both to proactively remove a thread,
    /// and then reactively in response to an exit hook.
    pub fn logically_kill_thread(&mut self, dtid: &DetTid, detpid: &DetPid, mm: MmId) {
        // Before removing blocking ownership, pending-vfork state, a turn or
        // its receiver: callback cancellation is not native access retirement.
        self.freeze_reserved_input_thread(*dtid);
        self.replay_prehook_callers.remove(dtid);
        if let Some(owners) = &mut self.boundary_owners {
            owners.retire(*dtid, mm);
        }
        self.boundary_budgets.retire(*dtid, mm);
        if self.backend.needs_killed_thread_rpc_cancellation {
            self.logically_killed_threads.insert(*dtid);
        }
        // Remove from the runnable queue at the next deterministic drain. This
        // is safe even if an asynchronous exec reconnect races a live
        // tentative_pop: the handler never reaches the run queue's mutation
        // guard and cannot poison the scheduler mutex.
        self.deschedule_or_defer(*dtid);
        // Remove from all non-runnable pools:
        self.remove_blocking_entries(dtid);
        self.chaos_turns_in_slice.remove(dtid);
        self.chaos_had_turn.remove(dtid);
        self.chaos_first_turn_waits.remove(dtid);
        self.retire_sigalrm_thread(*dtid, *detpid);
        // A logically killed thread is at its terminal edge now, not at its
        // later deregistration: a committed kill's receipt and an early
        // leader exit (which comes through here) both retire it here, so an
        // armed crash of its dies with it and no descendant's later exec
        // takes a switch for a handler that has ended. A successful exec
        // keeps its thread and never comes through here.
        self.post_crash.forget(*dtid);
        // A thread that leaves may close the last descriptor of a pipe end a
        // poller waits on (`retired_at`).
        self.progress_epoch += 1;
        self.retired_at = self.progress_epoch;
        // The process's last thread: its shared queue goes with it.
        let last_of_process = self
            .process_signal_targets(*detpid)
            .iter()
            .all(|thread| thread == dtid);
        self.work_span_retire_thread(*dtid, *detpid);
        if last_of_process {
            self.shared_queue_scheduler_signals.remove(detpid);
            self.signal_curr_targets.remove(detpid);
            self.parked.published_parent_death_signals.remove(detpid);
            // The generation stays, so that no publication older than one
            // already taken can bring dispositions back.
            if let Some(published) = self.published_dispositions.get_mut(detpid) {
                published.dispositions = None;
            }
        }
        // Its own queue goes with it; a later thread with its tid starts empty.
        self.thread_timer_copies
            .retain(|(thread, _), _| thread != dtid);
        self.process_signal_takers.remove(dtid);
        self.remove_physical_thread(dtid, mm);
        // A killed vfork parent must not leave its barrier behind: step2a
        // drops a barrier only when it can read the parent's pending request,
        // which `next_turns.remove` below discards, and while a barrier exists
        // `step3_peek` selects its child first, so a barrier left behind would
        // change the schedule after that child is gone
        // (https://github.com/rrnewton/hermit/issues/3984).
        self.retire_vfork_parent(*dtid);
        // A killed vfork child is its own barrier's release edge; it does not
        // readmit the parent early (`vfork_rejoin_edges`).
        self.release_vfork_child(*dtid, false);
        self.vfork_registration_origins.remove(dtid);
        self.saved_guest_sigmasks.remove(dtid);
        if self.in_guest_signal_delivery {
            self.unknown_guest_sigmasks.remove(dtid);
            self.temporary_mask_publications.remove(dtid);
            self.temporary_guest_sigmasks.remove(dtid);
            self.own_mask_publishers.remove(dtid);
        }
        self.kernel_run_requests.remove(dtid);
        self.published_masks.remove(dtid);
        self.instruction_offsets.remove(dtid);
        let retired = self
            .discarded_at_send
            .retire(discarded_at_send::QueueId::Thread(*dtid));
        self.note_private_entries_retired(retired);
        self.forget_pending_dequeue(*dtid);
        // Its private queue dies with it, and so does a raw-exit status its
        // grant never settled (a thread killed between its report and its
        // grant).
        self.child_exit_sigchld.private_sent.remove(dtid);
        self.child_exit_sigchld.raw_exit_status.remove(dtid);
        self.blocked.sigchld_takers.remove(dtid);
        if dtid.as_raw() == detpid.as_raw() {
            self.child_exit_publications_completed.remove(detpid);
        }
        self.real_timers.retire_task(*detpid, *dtid);
        self.retire_parked_requests(*dtid);
        self.parked.observed_timer_dequeues.remove(dtid);
        self.blocked.sleep_interruptions.remove(dtid);

        let _ = self.priorities.remove(dtid);
        self.turn_clocks.remove(dtid);
        let first_removal = self.next_turns.contains_key(dtid);
        match self.next_turns.remove(dtid) {
            None => {
                trace!(
                    "logically_kill_thread: thread already removed from scheduler: {}",
                    &dtid
                );
            }
            Some(nextturn) => {
                info!(
                    "logically_kill: Scheduler removing all knowledge of [det]tid {} in pid {}..",
                    dtid, detpid
                );
                // Put in a dummy request to unblock the scheduler that might be
                // waiting for the thread to park.
                //
                // WARNING: this try_put should potentially turn back into a put(), if we can narrow
                // down the exit scenarios and ensure that they happen when the guest is running and
                // has NOT filled its request to the scheduler yet.
                let request_was_pending = nextturn.req.try_put(Err(ThreadExited)).is_some();
                if request_was_pending
                    && self.backend.needs_killed_thread_rpc_cancellation
                    && !self.backend_failed()
                {
                    // AUTONOMOUS-BOT-IMPLEMENTED
                    // TODO-HUMAN-REVIEW(PR-845): Review killed-thread RPC cancellation.
                    nextturn.resp.try_put(SchedResponse::Signaled(None));
                }
                // Linux's `futex_cleanup` releases the PI futexes the thread
                // owns before `mm_release` clears its child TID and wakes it.
                self.release_pi_futexes_of(*dtid);
                if nextturn.child_tid_addr != 0 {
                    self.wake_futex_child_cleartid(
                        FutexID::private(mm, nextturn.child_tid_addr),
                        *dtid,
                    );
                }
            }
        }
        // The access trace forgets the thread once its exit wakes are noted,
        // so a later task that reuses its id ends none of its edges.
        if let Some(writer) = self.access_trace.as_mut() {
            writer.note_thread_gone(*dtid);
        }

        if first_removal {
            let process = self.registered_process(*dtid).unwrap_or(*detpid);
            self.hand_off_thread_children(*dtid, process);
            self.deliver_parent_death_signals(*dtid, process);
        }

        // AUTONOMOUS-BOT-IMPLEMENTED
        // TODO-HUMAN-REVIEW(#663)
        let live_process_thread = self.live_process_threads(*detpid).next().is_some();
        // A raw clone child with a non-SIGCHLD exit signal is its own process
        // in the thread tree, although the backend reports its creator's pid
        // (`ResourceID::Exit` below makes the same distinction). Its exit
        // still decides its orphans, when its last thread leaves.
        if let Some(registered) = self.registered_process(*dtid)
            && registered != *detpid
            && self.live_process_threads(registered).next().is_none()
        {
            self.namespace_zap_victims.remove(&registered);
            self.signal_death_victims.remove(&registered);
            self.reparent_orphans(registered);
            self.work_span_parent_gone(registered);
        }
        if !live_process_thread {
            let _ = self.begin_physical_process_exit(*detpid);
            self.reparent_orphans(*detpid);
            self.work_span_parent_gone(*detpid);
            self.logically_exited_processes.insert(*detpid);
            // The kill a namespace's end or a fatal signal owed it has arrived.
            self.namespace_zap_victims.remove(detpid);
            self.signal_death_victims.remove(detpid);
            // Linux decides at exit whether the parent reaps this child
            // automatically (do_notify_parent), and only for a child whose
            // exit signal is SIGCHLD; a later change of the parent's
            // disposition does not bring the child back.
            if self.thread_tree.notification_signal(*detpid) == Some(libc::SIGCHLD)
                && self
                    .thread_tree
                    .parent_process(detpid)
                    .is_some_and(|parent| self.thread_tree.reaps_children_automatically(parent))
            {
                self.autoreaped_exits.insert(*detpid);
            } else {
                self.autoreaped_exits.remove(detpid);
            }
            if let Some(parent) = self.thread_tree.parent_process(detpid) {
                self.wake_child_waiters(parent, *detpid);
            }
            self.blocked.timed_waiters.remove_process_timers(*detpid);
            self.real_timers.retire_process(*detpid);
            self.parked.forget_timer_publications(*detpid);
            // A dying process discards its pending signals.
            self.pending_real_time_expirations.remove(detpid);
            self.child_exit_sigchld.forget_process(*detpid);
            if self.child_exit_publication().is_err() {
                self.child_exit_sigchld.forget_parent(*detpid);
            }
            self.discarded_at_send
                .retire(discarded_at_send::QueueId::Process(*detpid));
            self.posix_timer_arm_generations
                .retain(|(owner, _), _| owner != detpid);
            self.posix_timer_values
                .retain(|(owner, _), _| owner != detpid);
            self.posix_timer_overruns
                .retain(|(owner, _), _| owner != detpid);
            self.signal_unobservable
                .retain(|(owner, _)| owner != detpid);
            self.handler_masks.retain(|(owner, _), _| owner != detpid);
        }
    }

    /// Record that task `tid` armed parent-death signal `signal` with
    /// `prctl(PR_SET_PDEATHSIG)`, in its turn, for Detcore to send itself; 0
    /// disarms (<https://github.com/rrnewton/hermit/issues/4440>).
    pub fn set_parent_death_signal(&mut self, tid: DetTid, signal: i32) {
        if signal == 0 {
            self.thread_tree.parent_death_signals.remove(&tid);
        } else {
            self.thread_tree.parent_death_signals.insert(tid, signal);
        }
    }

    /// The parent-death signal Detcore holds for task `tid`, or 0.
    pub fn parent_death_signal(&self, tid: DetTid) -> i32 {
        self.thread_tree
            .parent_death_signals
            .get(&tid)
            .copied()
            .unwrap_or(0)
    }

    /// Send the parent-death signals of the children whose parent-death
    /// parent is `exited`, a thread of `process` that has just left, and give
    /// those children a new one, as Linux's `forget_original_parent` does
    /// when any thread exits (https://github.com/rrnewton/hermit/issues/4440):
    /// for each such child, in pid order, each of its live tasks that armed a
    /// parent-death signal (leader first, then by tid) has it sent to the
    /// whole child process at the next drain (`flush_parent_death_signals`),
    /// with `process` as its sender, through the scheduler's own send
    /// (`fire_alarm`), which wakes a wait that admits it, or, on a backend that
    /// publishes the signals Detcore decides (a nonempty
    /// `publishable_parent_death_signals`, KVM), through that publication.
    /// Detcore holds only the signals such a backend declares
    /// (`detcore_sends_parent_death_signal`). This is where Detcore decides which
    /// signals a thread's exit sends, to whom and in what order; the backend
    /// only queues them.
    ///
    /// This runs where `logically_kill_thread` first removes `exited`. For an
    /// `exit` or `exit_group` with sequentialized threads that follows the
    /// scheduler-ordered `ResourceID::Exit` grant and precedes the next
    /// committed turn, as re-parenting does (`reparent_orphans`), so the send
    /// is as deterministic as that turn; so are the threads an exit_group or a
    /// committed SIGKILL retires (their process's exit is granted), those an
    /// exec's edge retires (`parent_death_exec_survivor`), and those a fatal
    /// signal ends at a delivery boundary Detcore permitted
    /// (`signal_boundary_deaths`). A thread that died otherwise (a fatal
    /// signal the host reports) leaves at a moment host timing sets: its
    /// children's signals are posted then, as the kernel posted them before,
    /// and recorded as host-timed for their processes, so no gated wait ends
    /// for them (https://github.com/rrnewton/hermit/issues/3146); that is a
    /// determinism loss, named here. A publishing backend has no host task to
    /// post to, and reports every death at a permitted boundary, so its
    /// signals are always published at the drain.
    fn deliver_parent_death_signals(&mut self, exited: DetTid, process: DetPid) {
        if let Some(refusal) = self.parent_death_firing_refusal(exited, process) {
            exit_on_scheduler_refusal(&refusal);
        }
        let children = self.parent_death_children(exited);
        if children.is_empty() {
            return;
        }
        let heir = self.parent_death_heir(exited, process);
        for child in children {
            let signals = self.held_parent_death_signals(child);
            let committed = self.parent_death_exit_is_committed(exited, process);
            for signal in signals {
                let Ok(signal) = Signal::try_from(signal) else {
                    warn!(
                        "[scheduler] parent-death signal {} of process {} is not one Detcore sends",
                        signal, child
                    );
                    continue;
                };
                if committed || self.backend.publishable_parent_death_signals != 0 {
                    if !committed {
                        // Not reached by a death Detcore ordered; say so
                        // rather than let verification compare it.
                        self.note_determinism_loss(format!(
                            "parent-death signal {signal} of process {child} was decided when thread {exited}, which died without an Exit grant, left (https://github.com/rrnewton/hermit/issues/4440)"
                        ));
                    }
                    info!(
                        "[scheduler] thread {} left: parent-death signal {} to process {}",
                        exited, signal, child
                    );
                    self.pending_parent_death_signals
                        .push(PendingParentDeathSignal {
                            child,
                            signal,
                            sender: process,
                        });
                } else {
                    // A thread that left at a host-timed moment (a fatal
                    // signal) sends at that moment, as the kernel did before:
                    // the signal is recorded as host-timed for the child's
                    // process, so that no gated wait of it ends for this copy,
                    // and posted without the scheduler's wake. Where the
                    // record lands is host-timed too, so say so.
                    self.note_determinism_loss(format!(
                        "parent-death signal {signal} of process {child} was posted when thread {exited}, which died without an Exit grant, left at a host-timed moment (https://github.com/rrnewton/hermit/issues/4440)"
                    ));
                    info!(
                        "[scheduler] thread {} left at a host-timed moment: parent-death signal {} posted to process {} as host-timed",
                        exited, signal, child
                    );
                    self.record_host_timed_signals(
                        DetTid::from_raw(child.as_raw()),
                        HostTimedSignalScope::Caller,
                        kernel_signal_bit(signal as libc::c_int),
                    );
                    let _ = signal::kill(Pid::from_raw(child.as_raw()), signal);
                }
            }
            match heir {
                Some(heir) => {
                    self.thread_tree.parent_death_parents.insert(child, heir);
                }
                None => {
                    self.thread_tree.parent_death_parents.remove(&child);
                }
            }
        }
    }

    /// The children whose parent-death parent is `exited`, in pid order.
    fn parent_death_children(&self, exited: DetTid) -> Vec<DetPid> {
        self.thread_tree
            .parent_death_parents
            .iter()
            .filter(|(_, parent)| **parent == exited)
            .map(|(child, _)| *child)
            .collect()
    }

    /// The parent-death signals Detcore holds for the tasks on `child`'s
    /// thread list, leader first, then by tid: its live tasks and, while any
    /// of those lives, its leader even after the leader has left. Linux keeps
    /// a leader that exits before its group's last thread as a zombie on the
    /// thread list, with its `pdeath_signal` (`exit_notify` reaps only an
    /// untraced non-leader at once, kernel/exit.c:757-763, unlinking it in
    /// `__unhash_process`, kernel/exit.c:153), so `forget_original_parent`'s
    /// `for_each_thread` still sends the zombie leader's signal
    /// (kernel/exit.c:713-721, v6.17). A process with no live task holds
    /// nothing.
    fn held_parent_death_signals(&self, child: DetPid) -> Vec<i32> {
        let mut tasks: Vec<DetTid> = self.live_process_threads(child).collect();
        let leader = DetTid::from_raw(child.as_raw());
        if !tasks.is_empty() && !tasks.contains(&leader) {
            tasks.push(leader);
        }
        tasks.sort_by_key(|tid| (tid.as_raw() != child.as_raw(), *tid));
        tasks
            .iter()
            .filter_map(|tid| self.thread_tree.parent_death_signals.get(tid).copied())
            .collect()
    }

    /// Whether `exited`, a thread of `process`, left at a committed point:
    /// its exit, its process's `exit_group`, or an exec's edge was granted.
    fn parent_death_exit_is_committed(&self, exited: DetTid, process: DetPid) -> bool {
        self.committed_exits.contains(&exited)
            || self.thread_tree.granted_exits.contains(&process)
            || self.signal_boundary_deaths.contains(&process)
            || self
                .parent_death_exec_survivor
                .map(|(survivor_process, _)| survivor_process)
                == Some(process)
    }

    /// On an in-guest run's default route (`refuses_parent_death_firing`),
    /// the refusal for the first parent-death signal that would fire as
    /// `exited`, a thread of `process`, leaves: one Detcore holds for a live
    /// task of a child whose parent-death parent `exited` is, in the order
    /// `deliver_parent_death_signals` would send them. Detcore holds such a
    /// signal there, with the kernel armed with 0, but cannot send it yet, so
    /// the run ends by name rather than lose the signal (D28a of A5 step 3c,
    /// https://github.com/rrnewton/hermit/issues/4485). `None` anywhere else,
    /// and where nothing would fire. A SIGKILL parent-death signal is never
    /// held (the kernel keeps it), so never refused here.
    ///
    /// At a committed exit (an `Exit` grant) the refusal is decided at that
    /// grant, in the schedule's order. At an unscheduled death of the parent
    /// (one the backend reports without a grant, such as a process killed by
    /// another's SIGKILL on the in-guest backends) the removal comes at a
    /// moment host timing decides; that death is already a named determinism
    /// loss which refuses verification. The refusal fires there whenever an
    /// armed child is still alive at that moment, which is host-timed too:
    /// a child that has ended by then holds nothing to fire.
    fn parent_death_firing_refusal(
        &self,
        exited: DetTid,
        process: DetPid,
    ) -> Option<ParentDeathFiringRefusal> {
        if !self.refuses_parent_death_firing {
            return None;
        }
        self.parent_death_children(exited)
            .into_iter()
            .find_map(|child| {
                let signal = *self.held_parent_death_signals(child).first()?;
                Some(ParentDeathFiringRefusal {
                    exited,
                    child,
                    signal,
                    committed: self.parent_death_exit_is_committed(exited, process),
                })
            })
    }

    /// Send the parent-death signals decided since the last drain
    /// (`deliver_parent_death_signals`), in the order they were decided, at
    /// this drain, where the run queue may change: through the scheduler's
    /// own send (`fire_alarm`), or on a backend that publishes the signals
    /// Detcore decides (a nonempty `publishable_parent_death_signals`)
    /// through its process signal control (`publish_parent_death_signal`).
    fn flush_parent_death_signals(&mut self) {
        for pending in std::mem::take(&mut self.pending_parent_death_signals) {
            if self.backend.publishable_parent_death_signals != 0 {
                self.publish_parent_death_signal(pending);
                continue;
            }
            let PendingParentDeathSignal { child, signal, .. } = pending;
            self.sending_parent_death = true;
            self.fire_alarm(child, DetTid::from_raw(child.as_raw()), signal);
            self.sending_parent_death = false;
        }
    }

    /// Linux's `forget_original_parent` for a thread that leaves while its
    /// process lives on: the children whose real parent thread is `exited`
    /// (their `wait_owner`) move to the live thread `find_alive_thread` finds,
    /// the heir `parent_death_heir` names, so that thread's `__WNOTHREAD` waits
    /// find them and their exit notification prefers it (`complete_signal`
    /// tries the parent thread first). A move within the thread group keeps
    /// each child's process parent and exit signal, as Linux calls
    /// `reparent_leader` only for a new parent in another thread group. When
    /// the process's last thread leaves (or its exit is granted), the heir is
    /// another process's thread and `reparent_orphans` moves the children
    /// instead. This runs where the thread's parent-death children move,
    /// at its first removal, so it is as ordered as that removal.
    fn hand_off_thread_children(&mut self, exited: DetTid, process: DetPid) {
        let Some(heir) = self.parent_death_heir(exited, process) else {
            return;
        };
        if self.registered_process(heir) == Some(process) {
            self.thread_tree.transfer_wait_owner(process, exited, heir);
        }
    }

    /// The thread that becomes the parent-death parent of `exited`'s
    /// children: the first live thread of `process` that is not exiting
    /// (Linux's `find_alive_thread`, leader first, then by tid), or, when the
    /// whole process is going (its last thread, or an `exit_group` grant),
    /// the thread of the subreaper that adopts them (`find_child_reaper`).
    /// `None`: the container's init, which does not exit during the run.
    fn parent_death_heir(&self, exited: DetTid, process: DetPid) -> Option<DetTid> {
        // An exec's edge retires every other thread; the exec'ing one stays.
        if let Some((survivor_process, survivor)) = self.parent_death_exec_survivor
            && survivor_process == process
            && survivor != exited
        {
            return Some(survivor);
        }
        if !self.thread_tree.granted_exits.contains(&process) {
            let mut live: Vec<DetTid> = self
                .live_process_threads(process)
                .filter(|tid| *tid != exited && !self.committed_exits.contains(tid))
                .collect();
            live.sort_by_key(|tid| (tid.as_raw() != process.as_raw(), *tid));
            if let Some(heir) = live.first() {
                return Some(*heir);
            }
        }
        self.find_child_reaper(process).map(|(_, owner)| owner)
    }

    // TODO-HUMAN-REVIEW(PR-4000): orphan re-parenting to a child subreaper.
    /// Re-parent the children of `exited`, whose last thread just left the run
    /// set, as Linux's `forget_original_parent` does in `exit_notify`.
    ///
    /// The new parent is the nearest process on `exited`'s parent chain that
    /// is a child subreaper and still has a live thread (`find_new_reaper`).
    /// A child that has already exited becomes waitable by its new parent
    /// here. Without such a subreaper the child goes to the container's init,
    /// which no guest can wait for; its record is left as it was before
    /// subreapers were modeled, naming the dead parent, so a program that
    /// never sets the flag sees no change.
    ///
    /// This runs in the same scheduler critical section that makes `exited`
    /// itself waitable, so it is exactly as deterministic as that moment and
    /// never opens a window of its own. For an `exit` or `exit_group` with
    /// sequentialized threads (strict mode), that moment follows the
    /// scheduler-ordered `ResourceID::Exit` grant and precedes the next
    /// committed turn: the exiting thread goes back into the run queue with an
    /// empty request, and the quiesce wait (`are_all_quiesced`) selects no
    /// turn until its deregistration fills it. For a process killed by a
    /// signal it is the host-timed
    /// deregistration (https://github.com/rrnewton/hermit/issues/3994), and the
    /// re-parent moves with it. On ptrace the kernel has already re-parented by
    /// then: the deregistration carries the final exit status, which the tracer
    /// sees only after `exit_notify`.
    ///
    /// The decision is made once per exit. `logically_kill_thread` can run
    /// again for the same dead process, from a thread's late exit hook at a
    /// moment the host chooses; by then every child has either moved to its
    /// subreaper or is an init orphan, and neither is collected again. A
    /// process that died without an Exit grant records a determinism loss
    /// when a subreaper adopts its orphans.
    ///
    /// Children are visited in pid order, so the waiters they wake join the
    /// run queue in an order that does not depend on hashing.
    ///
    /// This is where Detcore decides every orphan's new parent, for every
    /// backend. On ptrace the kernel has already moved its own records the
    /// same way (`exit_notify`). A backend that emulates waits keeps records
    /// of its own instead, and if it places orphans where Detcore names
    /// (`places_orphans`, KVM), the decision is carried out there in this
    /// critical section (`place_orphans_in_backend`): until then the backend
    /// holds the exit's children for the placement, so no other parent can
    /// see them. Where Detcore decides no orphan, such a backend is asked to
    /// place none (`place_no_orphans_in_backend`), which ends the run if it
    /// holds a child all the same.
    fn reparent_orphans(&mut self, exited: DetPid) {
        let orphans = self.thread_tree.undecided_orphans_of(exited);
        if orphans.is_empty() {
            self.place_no_orphans_in_backend(exited);
            return;
        }
        let reaper = self.find_child_reaper(exited);
        if let Some((reaper, _)) = reaper
            && !self.thread_tree.granted_exits.contains(&exited)
            && !self.signal_boundary_deaths.contains(&exited)
        {
            // Without an Exit grant (SIGKILL, another fatal signal, a fault)
            // the parent's exit is recorded at its host-timed deregistration,
            // and so is this adoption
            // (https://github.com/rrnewton/hermit/issues/3994). Say so rather
            // than let verification compare a schedule that host timing chose.
            // A fatal signal taken at a delivery boundary Detcore permitted is
            // not such a death: its receipt is ordered by the schedule
            // (`signal_boundary_deaths`).
            self.note_determinism_loss(format!(
                "subreaper {reaper} adopted the orphans of process {exited}, which died without an Exit grant, at its host-timed deregistration (https://github.com/rrnewton/hermit/issues/3994)"
            ));
        }
        let mut decided = Vec::with_capacity(orphans.len());
        for child in orphans {
            decided.push((child, self.logically_exited_processes.contains(&child)));
            let Some((reaper, owner)) = reaper else {
                debug!(
                    "[scheduler] orphan {} of exited process {} goes to the container init",
                    child, exited
                );
                self.thread_tree.orphan_to_init(child);
                continue;
            };
            self.thread_tree.reparent_child(child, reaper, owner);
            self.work_span_adopt(exited, reaper, child);
            #[cfg(test)]
            self.reparentings.push((child, reaper));
            info!(
                "[scheduler] re-parenting orphan {} of exited process {} to subreaper {}",
                child, exited, reaper
            );
            if self.logically_exited_processes.contains(&child) {
                // Linux's reparent_leader makes the zombie's exit signal
                // SIGCHLD and notifies its new parent, which reaps it at once
                // if it reaps children automatically
                // (https://github.com/rrnewton/hermit/issues/4091).
                if self.thread_tree.reaps_children_automatically(reaper) {
                    self.autoreaped_exits.insert(child);
                }
                self.wake_child_waiters(reaper, child);
            }
        }
        // A backend that keeps its own records of children and places each
        // orphan where Detcore names (`places_orphans`, KVM) moves them now,
        // in this critical section, before any thread can wait for an orphan
        // or ask for its parent (`Scheduler::place_orphans_in_backend`).
        if self.backend.places_orphans && self.signal_control_installed() {
            let reaper = reaper.map(|(reaper, _)| reaper);
            self.place_orphans_in_backend(exited, reaper, &decided);
        }
    }

