    /// A thread registering after the replayed schedule ran out takes the
    /// default priority like every other thread, not the deferred one; one
    /// registering earlier with no context switch to it takes its starting
    /// priority (https://github.com/rrnewton/hermit/issues/4472).
    #[test]
    fn a_thread_registering_after_the_replay_ran_out_takes_the_default_priority() {
        let mut sched = Scheduler::new(&Config::default());
        let parent = DetTid::from_raw(3);
        let early = DetTid::from_raw(5);
        let late = DetTid::from_raw(7);
        let last = SchedEvent::syscall(parent, Sysno::getpid, SyscallPhase::Prehook)
            .with_time(LogicalTime::from_nanos(10_000));
        sched.replayer = Some(Replayer::new(vec![last.clone()]));
        sched.priorities.insert(parent, REPLAY_FOREGROUND_PRIORITY);

        assert!(sched.replay_registration_priority(early, REPLAY_DEFERRED_PRIORITY));
        assert_eq!(
            sched.priorities.get(&early),
            Some(&REPLAY_DEFERRED_PRIORITY)
        );

        let _ = sched.consume_schedevent(&last);
        assert!(!sched.replay_registration_priority(late, REPLAY_DEFERRED_PRIORITY));
        assert_eq!(sched.priorities.get(&late), Some(&DEFAULT_PRIORITY));
        assert_eq!(sched.priorities.get(&early), Some(&DEFAULT_PRIORITY));
    }

    /// Under `--replay-continue-fairly`, once the last recorded event is
    /// consumed, each selection takes the queued thread that has run the
    /// least virtual time since then: a writer that ran half a millisecond
    /// goes ahead of a spinner that ran a 200 ms slice, though the spinner was
    /// queued first. Before the schedule runs out, or without the option,
    /// queue order decides.
    #[test]
    fn a_fair_continuation_runs_the_thread_that_ran_least() {
        for (fair, exhausted, first) in [
            (true, true, "writer"),
            (true, false, "spinner"),
            (false, true, "spinner"),
        ] {
            let cfg = Config {
                replay_continue_fairly: fair,
                ..Default::default()
            };
            let mut sched = Scheduler::new(&cfg);
            let (writer, spinner) = (DetTid::from_raw(3), DetTid::from_raw(5));
            for tid in [writer, spinner] {
                sched.register_thread_for_test(tid);
            }
            let last = SchedEvent::syscall(writer, Sysno::getpid, SyscallPhase::Prehook)
                .with_time(LogicalTime::from_nanos(10_000));
            sched.replayer = Some(Replayer::new(vec![last.clone()]));
            if exhausted {
                let _ = sched.consume_schedevent(&last);
            }
            let mut gtime = GlobalTime::new(&Config::default());
            let epoch = gtime.as_nanos();
            let at = |ns: u64| epoch + LogicalTime::from_nanos(ns);
            let none = LogicalTime::from_nanos(0);
            gtime.update_global_time(writer, at(1_000), none);
            gtime.update_global_time(spinner, at(1_000), none);
            let time = Mutex::new(gtime);
            sched.bump_global_time(&time, &Err(SkipTurn));
            sched.order_continuation_fairly();
            // The spinner ran a 200 ms slice and is queued first, then the
            // writer, which ran half a millisecond.
            time.lock()
                .unwrap()
                .update_global_time(spinner, at(200_001_000), none);
            time.lock()
                .unwrap()
                .update_global_time(writer, at(501_000), none);
            sched.run_queue.push_back(spinner, DEFAULT_PRIORITY);
            sched.run_queue.push_back(writer, DEFAULT_PRIORITY);
            sched.bump_global_time(&time, &Err(SkipTurn));
            let selected = sched.select_test_turn().map(|(tid, _, _)| tid);
            let expected = if first == "writer" { writer } else { spinner };
            assert_eq!(
                selected,
                Some(expected),
                "fair {fair}, schedule exhausted {exhausted}"
            );
        }
    }

    /// The child's startup RPC can report its inherited clock on either side
    /// of step 1, or after step 3 has selected its first turn. Registration
    /// and that first turn must charge the same work in every arrival order.
    #[test]
    fn a_fair_continuation_charges_a_child_whichever_side_its_clock_arrives() {
        let (parent, child) = (DetTid::from_raw(3), DetTid::from_raw(5));
        let mut selected = Vec::new();
        for (front, registration_before_snapshot, arrival) in
            [false, true].into_iter().flat_map(|front| {
                [false, true].into_iter().flat_map(move |registered| {
                    (0..3).map(move |arrival| (front, registered, arrival))
                })
            })
        {
            let cfg = Config {
                replay_continue_fairly: true,
                ..Default::default()
            };
            let mut sched = Scheduler::new(&cfg);
            sched.replay_priorities_released = true;
            sched.register_thread_for_test(parent);
            sched.run_queue.push_back(parent, DEFAULT_PRIORITY);
            let mut gtime = GlobalTime::new(&cfg);
            let epoch = gtime.as_nanos();
            let inherited = LogicalTime::from_nanos(1_000_000);
            gtime.update_global_time(parent, epoch + inherited, LogicalTime::ZERO);
            let time = Mutex::new(gtime);
            sched.bump_global_time(&time, &Err(SkipTurn));
            sched.order_continuation_fairly();

            // The parent has cloned the child; registration and the child's
            // StartNewThread clock update can each precede or follow step 1.
            if registration_before_snapshot {
                sched.register_thread_for_test(child);
            }
            let report_start = || {
                time.lock()
                    .unwrap()
                    .update_global_time(child, epoch + inherited, inherited);
            };
            if arrival == 0 {
                report_start();
            }
            sched.bump_global_time(&time, &Ok(Resources::new(parent)));
            if !registration_before_snapshot {
                sched.register_thread_for_test(child);
            }
            if arrival == 1 {
                report_start();
            }
            // Child-first admission is at the front; parent-first admission
            // is in ordinary turn order. With no own-clock advance the latter
            // isolates selection history from the run-time charge.
            if front {
                sched.run_queue.push_front(child, DEFAULT_PRIORITY);
            } else {
                sched.run_queue.push_back(child, DEFAULT_PRIORITY);
            }
            assert_eq!(sched.select_test_turn().map(|(tid, _, _)| tid), Some(child));
            if arrival == 2 {
                // Selection may precede StartNewThread, but granting its turn
                // waits for the request that the RPC fills.
                report_start();
            }
            assert_eq!(sched.run_queue.commit_tentative_pop_completed_turn(), child);
            let ran = if front { 20_000_000 } else { 0 };
            time.lock().unwrap().update_global_time(
                child,
                epoch + inherited + LogicalTime::from_nanos(ran),
                inherited,
            );
            sched.run_queue.push_back(child, DEFAULT_PRIORITY);
            sched.bump_global_time(&time, &Ok(Resources::new(child)));
            selected.push(sched.select_test_turn().map(|(tid, _, _)| tid));
        }
        assert_eq!(selected, vec![Some(parent); 12]);
    }

    /// Only a leader retired at its own exit while its group lives on counts
    /// as a retired exited leader; one that merely left `next_turns`, as at a
    /// host-timed deregistration on DBT, does not
    /// (https://github.com/rrnewton/hermit/issues/4445).
    #[test]
    fn only_a_leader_retired_at_its_exit_names_a_retired_exited_leader() {
        let mut sched = Scheduler::new(&Config::default());
        let retired = DetTid::from_raw(5);
        let deregistered = DetTid::from_raw(7);
        sched.retired_exited_leaders.insert(retired);
        assert!(sched.names_a_retired_exited_leader(retired));
        assert!(!sched.names_a_retired_exited_leader(deregistered));
        // Registered again under the same tid: live, so no longer retired.
        register_known_thread(&mut sched, retired);
        assert!(!sched.names_a_retired_exited_leader(retired));
    }

    fn exec_replay(
        caller: DetTid,
        next: DetTid,
        following: DetTid,
        branches: Option<u32>,
    ) -> (Replayer, SchedEvent) {
        let prehook = SchedEvent::syscall(caller, Sysno::execve, SyscallPhase::Prehook)
            .with_time(LogicalTime::from_nanos(10_000));
        let mut events = vec![prehook.clone()];
        if let Some(count) = branches {
            // A timer preemption, as recordings write it: branches with no
            // OtherInstructions after them, then the next thread's event.
            events.push(
                SchedEvent::branches(next, count).with_time(
                    LogicalTime::from_nanos(10_000) + LogicalTime::from_rcbs(count.into()),
                ),
            );
        } else {
            events.push(SchedEvent::syscall(
                next,
                Sysno::getpid,
                SyscallPhase::Prehook,
            ));
        }
        events.push(SchedEvent::syscall(
            following,
            Sysno::getpid,
            SyscallPhase::Prehook,
        ));
        (Replayer::new(events), prehook)
    }

    /// A schedule replay's context switch at a prehook stages the next
    /// thread's recorded slice length for that thread (`timeslices`) and
    /// hands the same length to the switching thread, which runs on into its
    /// call with a deadline past it. Keeping the switching thread's earlier
    /// deadline instead ended slices its recording did not have
    /// (`a_schedule_replay_keeps_the_clock_of_a_thread_that_yields_beside_a_computing_one`).
    #[test]
    fn a_prehook_context_switch_hands_the_switching_thread_the_recorded_slice() {
        let mut sched = Scheduler::new(&Config::default());
        let (caller, next, following) = (
            DetTid::from_raw(3),
            DetTid::from_raw(7),
            DetTid::from_raw(9),
        );
        for tid in [caller, next, following] {
            register_known_thread(&mut sched, tid);
        }
        let (replayer, prehook) = exec_replay(caller, next, following, Some(123));
        sched.replayer = Some(replayer);
        let consumed = sched.consume_schedevent(&prehook);
        assert!(consumed.keep_running);
        assert_eq!(
            consumed.timeslice_remaining.map(|end| end.length),
            Some(LogicalTime::from_rcbs(123))
        );
        assert_eq!(
            sched.timeslices.get(&next),
            Some(&Some(LogicalTime::from_rcbs(123)))
        );
    }

    #[tokio::test]
    async fn transferred_exec_reconnect_restores_replay_pre_hook_continuation_grant() {
        for branches in [Some(123), None] {
            let config = Config::default();
            let mut sched = Scheduler::new(&config);
            let leader = DetTid::from_raw(17);
            let caller = DetTid::from_raw(18);
            let unrelated = DetTid::from_raw(31);
            let (detpid, pre_exec_mm, old_leader_request) =
                install_runnable_exec_group(&mut sched, leader, caller);
            register_known_thread(&mut sched, unrelated);
            sched.runqueue_push_back(unrelated);
            let (replayer, prehook) = exec_replay(caller, leader, unrelated, branches);
            sched.replayer = Some(replayer);
            let duration = branches.map(|count| LogicalTime::from_rcbs(count.into()));

            // Exercise the actual prehook ContextSwitch(false, leader, ..),
            // including the priority and pending duration it stages.
            let consumed = sched.consume_schedevent(&prehook);
            assert!(consumed.keep_running);
            assert_eq!(consumed.event_ix, 0);
            assert_eq!(consumed.timeslice_remaining.map(|end| end.length), duration);
            assert_eq!(sched.priorities[&caller], REPLAY_DEFERRED_PRIORITY);
            assert_eq!(sched.priorities[&leader], REPLAY_FOREGROUND_PRIORITY);
            assert_eq!(sched.timeslices.get(&leader), Some(&duration));

            // The backend consumes the displaced leader before post-exec.
            // That removes its priority, but not its pending timeslice.
            sched.logically_kill_thread(&leader, &detpid, pre_exec_mm);
            let caller_request = sched.next_turns[&caller].req.clone();
            sched.turn = 41;
            sched.committed_time = GlobalTime::new(&config).as_nanos();
            let before = (sched.turn, sched.committed_time);
            let next_event = sched.replayer.as_ref().unwrap().cursor.peek().cloned();
            reconnect_transferred_exec(&mut sched, leader, caller, detpid, pre_exec_mm);

            assert_eq!((sched.turn, sched.committed_time), before);
            assert_eq!(sched.priorities[&leader], REPLAY_FOREGROUND_PRIORITY);
            assert_eq!(sched.timeslices.get(&leader), Some(&duration));
            assert!(!sched.timeslices.contains_key(&caller));
            assert!(matches!(caller_request.try_read(), Some(Err(_))));
            assert!(matches!(old_leader_request.try_read(), Some(Err(_))));
            assert_ne!(sched.next_turns[&leader].req, old_leader_request);
            let replayer = sched.replayer.as_ref().unwrap();
            assert_eq!(replayer.traced_event_count, 1);
            assert_eq!(replayer.events_popped, 1);
            assert_eq!(replayer.cursor.peek(), next_event.as_ref());
            assert_eq!(
                replayer.desync_counts,
                BTreeMap::from([(caller, replayer::DesyncStats::default())])
            );

            for tid in [leader, unrelated] {
                let mut resources = Resources::new(tid);
                resources.insert(ResourceID::MemAddrSpace(tid), Permission::RW);
                sched.next_turns[&tid].req.put(Ok(resources));
            }
            let continuation = sched.next_turns[&leader].resp.clone();
            let unrelated_response = sched.next_turns[&unrelated].resp.clone();
            assert!(continuation.try_read().is_none());
            let sched = Arc::new(Mutex::new(sched));
            let global_time = Arc::new(Mutex::new(GlobalTime::new(&config)));
            let granted = tokio::time::timeout(
                Duration::from_secs(5),
                do_a_turn_blocking(sched.clone(), global_time, &Err(SkipTurn)),
            )
            .await
            .expect("the continuation grant must not stall")
            .expect("the replay continuation must be runnable");
            assert_eq!(granted.tid, leader);
            let Some(SchedResponse::Go(granted_duration)) = continuation.try_read() else {
                panic!("replacement did not receive an ordinary continuation grant");
            };
            assert_eq!(
                granted_duration,
                duration.map(|time| SchedValue::Value(time.as_nanos()))
            );
            assert!(unrelated_response.try_read().is_none());
            let sched = sched.lock().unwrap();
            assert_eq!(sched.turn, before.0 + 1);
            assert!(!sched.timeslices.contains_key(&leader));
            assert!(!sched.run_queue.contains_tid(caller));
            assert_eq!(
                sched.run_queue.tids().filter(|tid| **tid == leader).count(),
                1
            );
        }
    }

    #[tokio::test]
    async fn transferred_exec_reconnect_discards_stale_leader_duration_for_other_replay_task() {
        let config = Config::default();
        let mut sched = Scheduler::new(&config);
        let leader = DetTid::from_raw(17);
        let caller = DetTid::from_raw(18);
        let unrelated = DetTid::from_raw(31);
        let (detpid, pre_exec_mm, _) = install_runnable_exec_group(&mut sched, leader, caller);
        register_known_thread(&mut sched, unrelated);
        sched.runqueue_push_back(unrelated);
        sched
            .timeslices
            .insert(leader, Some(LogicalTime::from_nanos(99)));
        let (replayer, prehook) = exec_replay(caller, unrelated, leader, Some(123));
        sched.replayer = Some(replayer);
        let consumed = sched.consume_schedevent(&prehook);
        assert!(consumed.keep_running);
        sched.logically_kill_thread(&leader, &detpid, pre_exec_mm);

        reconnect_transferred_exec(&mut sched, leader, caller, detpid, pre_exec_mm);

        assert_eq!(sched.priorities[&leader], REPLAY_DEFERRED_PRIORITY);
        assert!(!sched.timeslices.contains_key(&leader));
        assert_eq!(sched.priorities[&unrelated], REPLAY_FOREGROUND_PRIORITY);
        assert_eq!(
            sched.timeslices.get(&unrelated),
            Some(&Some(LogicalTime::from_rcbs(123)))
        );
        for tid in [leader, unrelated] {
            sched.next_turns[&tid].req.put(Ok(Resources::new(tid)));
        }
        let continuation = sched.next_turns[&leader].resp.clone();
        let unrelated_response = sched.next_turns[&unrelated].resp.clone();
        let sched = Arc::new(Mutex::new(sched));
        let global_time = Arc::new(Mutex::new(GlobalTime::new(&config)));
        let granted = tokio::time::timeout(
            Duration::from_secs(5),
            do_a_turn_blocking(sched.clone(), global_time, &Err(SkipTurn)),
        )
        .await
        .expect("the unrelated task's grant must not stall")
        .expect("the other replay task must retain its grant");
        assert_eq!(granted.tid, unrelated);
        assert!(continuation.try_read().is_none());
        let Some(SchedResponse::Go(Some(SchedValue::Value(duration)))) =
            unrelated_response.try_read()
        else {
            panic!("the other replay task lost its pending duration");
        };
        assert_eq!(duration, LogicalTime::from_rcbs(123).as_nanos());
    }

    #[test]
    fn transferred_exec_reconnect_preserves_survivor_priority_without_replay() {
        for exhausted_replay in [false, true] {
            let mut sched = Scheduler::new(&Config::default());
            let leader = DetTid::from_raw(17);
            let caller = DetTid::from_raw(18);
            let (detpid, pre_exec_mm, _) = install_runnable_exec_group(&mut sched, leader, caller);
            sched.priorities.insert(leader, runqueue::FIRST_PRIORITY);
            let survivor_priority = DEFAULT_PRIORITY + 7;
            sched.priorities.insert(caller, survivor_priority);
            sched
                .timeslices
                .insert(leader, Some(LogicalTime::from_nanos(99)));
            if exhausted_replay {
                sched.replayer = Some(Replayer::new([]));
            }

            reconnect_transferred_exec(&mut sched, leader, caller, detpid, pre_exec_mm);

            assert_eq!(sched.priorities[&leader], survivor_priority);
            assert!(!sched.timeslices.contains_key(&leader));
            assert_eq!(sched.turn, 0);
        }
    }

    #[test]
    fn transferred_exec_reconnect_retires_former_rpc_identity_without_cancellation() {
        for transfer in [true, false] {
            let config = Config::default().with_backend(|backend| {
                backend.needs_killed_thread_rpc_cancellation = false;
            });
            let mut sched = Scheduler::new(&config);
            let leader = DetTid::from_raw(17);
            let caller = DetTid::from_raw(18);
            let unrelated = DetTid::from_raw(31);
            let (detpid, pre_exec_mm, _) = install_runnable_exec_group(&mut sched, leader, caller);
            let post_exec_mm = pre_exec_mm.for_exec(detpid);
            register_known_thread(&mut sched, unrelated);
            let unrelated_mm = MmId::initial(unrelated);
            assert!(sched.rpc_incarnation_matches(caller, pre_exec_mm));

            if transfer {
                reconnect_transferred_exec(&mut sched, leader, caller, detpid, pre_exec_mm);
            } else {
                reconnect_nonleader_exec(&mut sched, leader, caller, detpid, pre_exec_mm);
            }

            // A transferred caller must not regain a clock component or merge
            // final statistics through a late ordinary RPC, in any address
            // space. The legacy reload mode's admission policy is unchanged.
            for mm in [pre_exec_mm, post_exec_mm, unrelated_mm] {
                assert_eq!(sched.rpc_incarnation_matches(caller, mm), !transfer);
            }
            assert!(!sched.thread_is_logically_killed(caller));
            assert!(sched.rpc_incarnation_matches(leader, post_exec_mm));
            assert!(!sched.rpc_incarnation_matches(leader, pre_exec_mm));
            assert!(sched.rpc_incarnation_matches(unrelated, unrelated_mm));
            assert!(sched.next_turns.contains_key(&unrelated));
        }
    }

    /// A histogram of `n` getpid entries, as a thread with `syscall_count` n
    /// reports it.
    fn entries(n: u64) -> SparseSyscallHistogram {
        let mut histogram = SyscallHistogram::default();
        for _ in 0..n {
            histogram.enter(reverie::syscalls::Sysno::getpid);
        }
        (&histogram).into()
    }

    #[test]
    fn transferred_exec_reconnect_accumulates_consumed_leader_syscalls_once() {
        let config = Config::default().with_backend(|backend| {
            backend.needs_killed_thread_rpc_cancellation = false;
        });
        let mut sched = Scheduler::new(&config);
        let leader = DetTid::from_raw(17);
        let caller = DetTid::from_raw(18);
        let second_caller = DetTid::from_raw(19);
        let (detpid, pre_exec_mm, _) = install_runnable_exec_group(&mut sched, leader, caller);
        assert!(sched.note_deregistration_accounted(leader));
        sched.record_syscall_count(leader, 3, entries(3));
        sched.logically_kill_thread(&leader, &detpid, pre_exec_mm);

        reconnect_transferred_exec(&mut sched, leader, caller, detpid, pre_exec_mm);
        sched.drain_pending_run_queue_removals();
        sched.drain_pending_run_queue_admissions();
        assert!(sched.note_deregistration_accounted(leader));
        sched.record_syscall_count(leader, 7, entries(7));
        assert_eq!(sched.per_thread_syscalls[&leader], 10);
        assert_eq!(sched.per_thread_syscall_histograms[&leader], entries(10));
        assert!(!sched.note_deregistration_accounted(leader));
        // The count itself is idempotent too; do not add the previous aggregate
        // each time the current incarnation reports its final count.
        sched.record_syscall_count(leader, 7, entries(7));
        assert_eq!(sched.per_thread_syscalls[&leader], 10);
        assert_eq!(sched.per_thread_syscall_histograms[&leader], entries(10));

        sched.thread_tree.add_child(leader, second_caller, false);
        register_known_thread(&mut sched, second_caller);
        sched.runqueue_push_back(second_caller);
        let second_mm = pre_exec_mm.for_exec(detpid);
        sched.logically_kill_thread(&leader, &detpid, second_mm);
        reconnect_transferred_exec(&mut sched, leader, second_caller, detpid, second_mm);
        assert!(sched.note_deregistration_accounted(leader));
        sched.record_syscall_count(leader, 11, entries(11));
        assert_eq!(sched.per_thread_syscalls[&leader], 21);
        assert_eq!(sched.per_thread_syscall_histograms[&leader], entries(21));
        assert!(!sched.note_deregistration_accounted(leader));
        assert!(!sched.per_thread_syscalls.contains_key(&caller));
        assert!(!sched.per_thread_syscalls.contains_key(&second_caller));
        assert!(!sched.per_thread_syscall_histograms.contains_key(&caller));
    }

