    #[test]
    fn futex_wake_bitset_only_selects_intersecting_waiters() {
        let mut waiters = vec![
            futex_waiter(1, 0b0001),
            futex_waiter(2, 0b0010),
            futex_waiter(3, 0b0011),
        ];

        let matching = take_matching_futex_waiters(&mut waiters, 0b0010);
        assert_eq!(
            matching
                .iter()
                .map(|waiter| waiter.dettid)
                .collect::<Vec<_>>(),
            [DetTid::from_raw(2), DetTid::from_raw(3)]
        );
        assert_eq!(
            waiters
                .iter()
                .map(|waiter| waiter.dettid)
                .collect::<Vec<_>>(),
            [DetTid::from_raw(1)]
        );

        let matching = take_matching_futex_waiters(&mut waiters, 0);
        assert!(
            matching.is_empty(),
            "a zero wake bitset must match no waiter"
        );
        assert_eq!(waiters.len(), 1, "nonmatching waiters must remain queued");
    }

    #[test]
    fn test_my_thread_group1() {
        let mut tree: ThreadTree = Default::default();
        let p1 = DetPid::from_raw(100);
        let p2 = DetPid::from_raw(200);
        let p3 = DetPid::from_raw(300);
        tree.add_child(p1, p1, true);
        tree.add_child(p1, p2, false);
        tree.add_child(p1, p3, false);
        let mut v = tree.my_thread_group(&p2);
        v.sort();
        assert_eq!(&v, &[p1, p2, p3]);
        let s = format!("{}", tree);
        assert!(!s.is_empty());
    }

    #[test]
    fn test_my_thread_group2() {
        let mut tree: ThreadTree = Default::default();
        let p1 = DetPid::from_raw(100);
        let p2 = DetPid::from_raw(200);
        let p3 = DetPid::from_raw(300);
        let p4 = DetPid::from_raw(400);
        let p5 = DetPid::from_raw(500);
        tree.add_child(p1, p1, true);
        tree.add_child(p1, p2, false);
        tree.add_child(p1, p3, true); // second group leader
        tree.add_child(p3, p4, false);
        tree.add_child(p4, p5, false);
        let mut v = tree.my_thread_group(&p2);
        v.sort();
        assert_eq!(&v, &[p1, p2]);

        let mut v = tree.my_thread_group(&p5);
        v.sort();
        assert_eq!(&v, &[p3, p4, p5]);
        let s = tree.pretty_print();
        assert!(!s.is_empty());
    }

    /// A process whose threads come and go: its live threads are those with
    /// turn state, from any depth of the creation tree and whichever thread
    /// created them, and never a thread of a child process.
    #[test]
    fn the_live_thread_group_is_the_tree_walk_less_exited_threads() {
        let mut scheduler = Scheduler::new(&Config::default());
        let tid = DetTid::from_raw;
        let (leader, first, second, third, child) =
            (tid(100), tid(101), tid(102), tid(103), tid(104));
        scheduler.thread_tree.add_child(leader, leader, true);
        scheduler.thread_tree.add_child(leader, first, false);
        scheduler.thread_tree.add_child(first, second, false);
        scheduler.thread_tree.add_child(second, third, false);
        scheduler.thread_tree.add_child(third, child, true);
        for thread in [leader, second, third, child] {
            register_known_thread(&mut scheduler, thread);
        }
        // `first` exited; `third` hangs below it in the tree.
        let walked: Vec<DetTid> = {
            let mut group = scheduler.thread_tree.my_thread_group(&leader);
            group.retain(|thread| scheduler.next_turns.contains_key(thread));
            group.sort();
            group
        };
        assert_eq!(walked, [leader, second, third]);
        for member in [leader, first, third] {
            assert_eq!(
                scheduler.live_thread_group(&member).collect::<Vec<_>>(),
                walked
            );
        }
        assert_eq!(scheduler.process_signal_targets(leader), walked);
        assert_eq!(
            scheduler.live_thread_group(&child).collect::<Vec<_>>(),
            [child]
        );
    }

    /// The tree keeps the edge to an exited thread, so after Linux gives its
    /// ID to a thread of another process the tree lists that thread under
    /// both. Its live group is only the one it belongs to now.
    #[test]
    fn a_reused_thread_id_is_live_only_in_its_current_group() {
        let mut scheduler = Scheduler::new(&Config::default());
        let tid = DetTid::from_raw;
        let (parent, old_leader, reused, new_leader) = (tid(37), tid(38), tid(39), tid(50));
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, old_leader, true);
        scheduler.thread_tree.add_child(old_leader, reused, false);
        scheduler.thread_tree.add_child(parent, new_leader, true);
        scheduler.thread_tree.add_child(new_leader, reused, false);
        for thread in [old_leader, new_leader, reused] {
            register_known_thread(&mut scheduler, thread);
        }
        assert!(
            scheduler
                .thread_tree
                .my_thread_group(&old_leader)
                .contains(&reused),
            "the stale edge this test is about must exist"
        );
        assert_eq!(scheduler.process_signal_targets(old_leader), [old_leader]);
        assert_eq!(
            scheduler.process_signal_targets(new_leader),
            [reused, new_leader]
        );
    }

    /// An ID that once led a process, given later to a thread of another
    /// process, belongs to that process: its live group is that process's.
    #[test]
    fn a_former_leaders_id_reused_as_a_thread_joins_its_new_group() {
        let mut scheduler = Scheduler::new(&Config::default());
        let tid = DetTid::from_raw;
        let (parent, former_leader, new_leader) = (tid(37), tid(38), tid(50));
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, former_leader, true);
        // Process 38 has exited; Linux gives 38 to a thread of process 50.
        scheduler.thread_tree.add_child(parent, new_leader, true);
        scheduler
            .thread_tree
            .add_child(new_leader, former_leader, false);
        for thread in [parent, new_leader, former_leader] {
            register_known_thread(&mut scheduler, thread);
        }
        let group = [former_leader, new_leader];
        for member in [former_leader, new_leader] {
            assert_eq!(
                scheduler.live_thread_group(&member).collect::<Vec<_>>(),
                group
            );
        }
        // A signal to 38 goes to the process it is a thread of, as Linux's
        // kill(2) of a thread ID reaches that thread's group.
        assert_eq!(scheduler.process_signal_targets(former_leader), group);
    }

    /// Process 38 has exited and been reaped, Linux has given 38 to a thread
    /// of process 50, and that thread has exited too. No task 38 exists, so
    /// Linux's kill(38, sig) answers ESRCH (kill_pid_info finds no task). 38
    /// names neither the process it once led nor process 50: a kill gets no
    /// target. Detcore holds no zombie record for 38 here, so kill(38, 0) is
    /// passed to the host kernel, which finds no task 38 either.
    #[test]
    fn a_dead_former_leaders_id_names_no_process() {
        let mut scheduler = Scheduler::new(&Config::default());
        let tid = DetTid::from_raw;
        let (parent, former_leader, new_leader) = (tid(37), tid(38), tid(50));
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, former_leader, true);
        scheduler.thread_tree.add_child(parent, new_leader, true);
        scheduler
            .thread_tree
            .add_child(new_leader, former_leader, false);
        for thread in [parent, new_leader] {
            register_known_thread(&mut scheduler, thread);
        }
        assert_eq!(scheduler.signal_target_process(former_leader), None);
        assert_eq!(
            scheduler.process_signal_targets(former_leader),
            Vec::<DetTid>::new()
        );
        assert_eq!(scheduler.exited_process_is_zombie(former_leader), None);
        // While the thread 38 lived, 38 named its process, 50.
        register_known_thread(&mut scheduler, former_leader);
        assert_eq!(
            scheduler.signal_target_process(former_leader),
            Some(new_leader)
        );
    }

    /// Grants `thread` a raw `exit` (not `exit_group`) naming `process`.
    fn grant_raw_exit(scheduler: &mut Scheduler, thread: DetTid, process: DetPid) {
        assert!(
            scheduler
                .block_for_one_resource(
                    thread,
                    &ResourceID::Exit {
                        group: false,
                        process,
                        mm: MmId::initial(process),
                    },
                    &Permission::RW,
                    Option::None,
                    Option::None,
                    &Ivar::new(),
                )
                .is_ok()
        );
    }

    /// A raw `exit` grant ends its process, and fixes the process's exit
    /// (`granted_exits`), only for the process's last live thread: not while
    /// a sibling still lives, and not because an exited one is in the tree.
    #[test]
    fn a_raw_exit_grant_ends_its_process_only_at_its_last_live_thread() {
        let tid = DetTid::from_raw;
        let (root, process, sibling) = (tid(1), tid(2), tid(3));
        let setup = |live: &[DetTid]| {
            let mut scheduler = Scheduler::new(&Config::default());
            scheduler.thread_tree.add_child(root, root, true);
            scheduler.thread_tree.add_child(root, process, true);
            scheduler.thread_tree.add_child(process, sibling, false);
            for thread in live {
                register_known_thread(&mut scheduler, *thread);
            }
            scheduler
        };
        let mut scheduler = setup(&[root, process, sibling]);
        grant_raw_exit(&mut scheduler, sibling, process);
        assert!(!scheduler.thread_tree.granted_exits.contains(&process));

        // The sibling has exited: the leader is the last live thread.
        let mut scheduler = setup(&[root, process]);
        grant_raw_exit(&mut scheduler, process, process);
        assert!(scheduler.thread_tree.granted_exits.contains(&process));
    }

    /// Process 38's thread 39 exited and Linux gave 39 to a thread of process
    /// 50. The tree keeps the edge from 38 to 39, but the exit paths that
    /// take a process's live threads (exec teardown, the consumption of an
    /// unreported exit, the SIGKILL reservation) take only 38's own.
    #[test]
    fn exit_paths_do_not_take_a_reused_thread_for_its_old_process() {
        let tid = DetTid::from_raw;
        let (parent, process, reused, other) = (tid(37), tid(38), tid(39), tid(50));
        let setup = || {
            let mut scheduler = Scheduler::new(&Config::default());
            scheduler.thread_tree.add_child(parent, parent, true);
            scheduler.thread_tree.add_child(parent, process, true);
            scheduler.thread_tree.add_child(process, reused, false);
            scheduler.thread_tree.add_child(parent, other, true);
            scheduler.thread_tree.add_child(other, reused, false);
            for thread in [parent, process, reused, other] {
                register_known_thread(&mut scheduler, thread);
                scheduler.record_thread_mm(thread, MmId::initial(thread));
            }
            assert!(
                scheduler
                    .thread_tree
                    .my_thread_group(&process)
                    .contains(&reused),
                "the stale edge this test is about must exist"
            );
            scheduler
        };

        let mut scheduler = setup();
        let mm = MmId::initial(process);
        assert!(scheduler.prepare_exec_teardown(process, process, mm));
        assert!(!scheduler.defer_exec_sibling_retirement(reused, process, mm));

        let mut scheduler = setup();
        assert!(scheduler.has_unreported_exit(process));
        assert!(scheduler.consume_unreported_exit(process));
        assert!(scheduler.deregistration_accounted.contains(&process));
        assert!(!scheduler.deregistration_accounted.contains(&reused));

        let mut scheduler = setup();
        let reserved = scheduler.reserve_sigkill(parent, process, 0).unwrap();
        let victims = scheduler.commit_sigkill(reserved.token, true);
        assert_eq!(
            victims.iter().map(|victim| victim.tid).collect::<Vec<_>>(),
            [process]
        );
    }

    /// Process 38 has gone and Linux has given 38 to a live thread of
    /// process 50. The exit paths that name process 38 find no live thread
    /// of it, and none of process 50's.
    #[test]
    fn exit_paths_find_no_threads_for_a_former_leaders_reused_id() {
        let tid = DetTid::from_raw;
        let (parent, former_leader, new_leader) = (tid(37), tid(38), tid(50));
        let mut scheduler = Scheduler::new(&Config::default());
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, former_leader, true);
        scheduler.thread_tree.add_child(parent, new_leader, true);
        scheduler
            .thread_tree
            .add_child(new_leader, former_leader, false);
        for thread in [parent, new_leader, former_leader] {
            register_known_thread(&mut scheduler, thread);
            scheduler.record_thread_mm(thread, MmId::initial(thread));
        }
        assert!(!scheduler.has_unreported_exit(former_leader));
        assert_eq!(
            scheduler.reserve_sigkill(parent, former_leader, 0),
            Err(sigkill_retirement::SigkillRefusal::NoTarget)
        );
        assert!(!scheduler.consume_unreported_exit(former_leader));
        assert!(scheduler.deregistration_accounted.is_empty());
        // A process reaped automatically keeps its wait metadata, process
        // group included. A SIGKILL to that group reaches process 50, whose
        // thread 38 is, and not a process 38.
        let group = DetPid::from_raw(77);
        assert!(
            scheduler
                .thread_tree
                .set_process_group(former_leader, group)
        );
        assert!(scheduler.thread_tree.set_process_group(new_leader, group));
        let reserved = scheduler.reserve_sigkill_group(parent, group, 0).unwrap();
        let victims = scheduler.commit_sigkill(reserved.token, true);
        assert_eq!(
            victims.iter().map(|victim| victim.tid).collect::<Vec<_>>(),
            [former_leader, new_leader]
        );
    }

    /// Process 38 (created by 37) had thread 39, which exited, and Linux gave
    /// 39 to a thread of process 50, which lives. The tree keeps the edge
    /// from 38 to 39, so the tree's walk of 38's group lists 50's thread.
    /// Every thread has turn state and its process's address space.
    fn reused_thread_family() -> (Scheduler, DetPid, DetTid, DetPid) {
        let tid = DetTid::from_raw;
        let (parent, process, reused, other) = (tid(37), tid(38), tid(39), tid(50));
        let mut scheduler = Scheduler::new(&Config::default());
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, process, true);
        scheduler.thread_tree.add_child(process, reused, false);
        scheduler.thread_tree.add_child(parent, other, true);
        scheduler.thread_tree.add_child(other, reused, false);
        for (thread, leader) in [
            (parent, parent),
            (process, process),
            (reused, other),
            (other, other),
        ] {
            register_known_thread(&mut scheduler, thread);
            scheduler.record_thread_mm(thread, MmId::initial(leader));
        }
        assert!(
            scheduler
                .thread_tree
                .my_thread_group(&process)
                .contains(&reused),
            "the stale edge these tests are about must exist"
        );
        (scheduler, process, reused, other)
    }

    /// Process 38's thread 39 created thread 40 and exited, and Linux gave 39
    /// to a new process, created by 37. The tree's walk of 38's group stops
    /// at 39, now a leader, and misses 38's live thread 40; the walk of
    /// process 39's group descends into 40.
    fn reused_creator_family() -> (Scheduler, DetPid, DetTid, DetPid) {
        let tid = DetTid::from_raw;
        let (parent, process, creator, orphan) = (tid(37), tid(38), tid(39), tid(40));
        let mut scheduler = Scheduler::new(&Config::default());
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, process, true);
        scheduler.thread_tree.add_child(process, creator, false);
        scheduler.thread_tree.add_child(creator, orphan, false);
        scheduler.thread_tree.add_child(parent, creator, true);
        for (thread, leader) in [
            (parent, parent),
            (process, process),
            (orphan, process),
            (creator, creator),
        ] {
            register_known_thread(&mut scheduler, thread);
            scheduler.record_thread_mm(thread, MmId::initial(leader));
        }
        assert_eq!(scheduler.thread_tree.my_thread_group(&process), [process]);
        assert!(
            scheduler
                .thread_tree
                .my_thread_group(&creator)
                .contains(&orphan),
            "the stale edge these tests are about must exist"
        );
        (scheduler, process, orphan, creator)
    }

    /// An `exit_group` grant takes the turns of the caller's process's other
    /// threads, as Linux's `zap_other_threads` kills the caller's own thread
    /// group: not a live thread of another process whose ID the tree still
    /// lists under the caller's process, and also a live thread of the
    /// process that the tree's walk misses because its creator's ID now leads
    /// another process.
    #[test]
    fn an_exit_group_grant_kills_only_its_own_processes_threads() {
        let (mut scheduler, process, reused, other) = reused_thread_family();
        scheduler.logically_kill_exit_group_siblings(process, process, MmId::initial(process));
        assert!(scheduler.next_turns.contains_key(&reused));
        assert!(scheduler.next_turns.contains_key(&other));

        let (mut scheduler, process, orphan, creator) = reused_creator_family();
        scheduler.logically_kill_exit_group_siblings(creator, creator, MmId::initial(creator));
        assert!(scheduler.next_turns.contains_key(&orphan));
        scheduler.logically_kill_exit_group_siblings(process, process, MmId::initial(process));
        assert!(!scheduler.next_turns.contains_key(&orphan));
        assert!(scheduler.next_turns.contains_key(&creator));

        // Process 38 was reaped and Linux gave 38 to a thread of process 50,
        // beside 50's thread 51. 38's exit_group kills 50's other threads:
        // its process is 50, whatever process its ID once led.
        let mut scheduler = Scheduler::new(&Config::default());
        let tid = DetTid::from_raw;
        let (parent, caller, other, sibling) = (tid(37), tid(38), tid(50), tid(51));
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, caller, true);
        scheduler.thread_tree.add_child(parent, other, true);
        scheduler.thread_tree.add_child(other, caller, false);
        scheduler.thread_tree.add_child(other, sibling, false);
        for thread in [parent, caller, other, sibling] {
            register_known_thread(&mut scheduler, thread);
        }
        scheduler.logically_kill_exit_group_siblings(caller, other, MmId::initial(other));
        assert!(!scheduler.next_turns.contains_key(&sibling));
        assert!(!scheduler.next_turns.contains_key(&other));
        assert!(scheduler.next_turns.contains_key(&caller));
        assert!(scheduler.next_turns.contains_key(&parent));
    }

    /// An `exit_group` grant holds turns until each thread of the process
    /// with a registered host thread is gone. A barrier on a live thread of
    /// another process, which the stale tree edge names, would hold every
    /// turn until a thread exits that has no reason to. A live thread of the
    /// process that the tree's walk misses is waited for.
    #[test]
    fn an_exit_group_holds_turns_only_for_its_own_processes_threads() {
        let host_pid = std::process::id() as i32;
        let host_tid = unsafe { libc::syscall(libc::SYS_gettid) as i32 };
        let register = |scheduler: &mut Scheduler, thread: DetTid| {
            let mm = scheduler.thread_mm(thread).unwrap();
            scheduler
                .register_physical_thread(thread, mm, host_pid, host_tid)
                .expect("PIDFD_THREAD must bind the current test thread");
        };
        let (mut scheduler, process, reused, _) = reused_thread_family();
        register(&mut scheduler, process);
        register(&mut scheduler, reused);
        scheduler.hold_turns_until_the_group_ends(process);
        assert!(scheduler.exited_thread_barriers.contains_key(&process));
        assert!(!scheduler.exited_thread_barriers.contains_key(&reused));

        let (mut scheduler, process, orphan, creator) = reused_creator_family();
        register(&mut scheduler, orphan);
        register(&mut scheduler, creator);
        scheduler.hold_turns_until_the_group_ends(creator);
        assert!(scheduler.exited_thread_barriers.contains_key(&creator));
        assert!(!scheduler.exited_thread_barriers.contains_key(&orphan));
        scheduler.exited_thread_barriers.clear();
        scheduler.hold_turns_until_the_group_ends(process);
        assert!(scheduler.exited_thread_barriers.contains_key(&orphan));
    }

    /// A leader whose exit was granted leaves the scheduler at its exit only
    /// while another thread of its process lives. A live thread of another
    /// process whose ID the tree lists under it is not one, so the last
    /// thread is left to its deregistration, as Linux's `exit_notify` reaps a
    /// leader whose group is empty (`thread_group_empty`) rather than
    /// delaying it as a zombie (`delay_group_leader`).
    #[test]
    fn a_reused_thread_of_another_process_does_not_keep_a_leader_as_a_zombie() {
        let (mut scheduler, process, reused, _) = reused_thread_family();
        assert!(!scheduler.retire_test_exited_leader(process, MmId::initial(process)));
        assert!(scheduler.next_turns.contains_key(&process));
        assert!(scheduler.next_turns.contains_key(&reused));
    }

    /// Under targeted chaos a process-directed signal goes to a random live
    /// thread of the process (Linux's `complete_signal` picks among the
    /// group's own threads): never to another process's thread whose ID the
    /// tree lists under it, and possibly to a live thread the tree's walk
    /// misses.
    #[test]
    fn targeted_chaos_steers_a_process_signal_only_to_its_own_threads() {
        let (mut scheduler, process, reused, _) = reused_thread_family();
        scheduler.chaos_target_races = true;
        for thread in [process, reused] {
            scheduler.runqueue_push_back(thread);
        }
        for draw in 0..32 {
            assert_eq!(
                scheduler.chaos_signal_target(process),
                Some(process),
                "draw {draw}"
            );
        }

        let (mut scheduler, process, orphan, creator) = reused_creator_family();
        scheduler.chaos_target_races = true;
        for thread in [process, orphan, creator] {
            scheduler.runqueue_push_back(thread);
        }
        let drawn: std::collections::BTreeSet<DetTid> = (0..32)
            .map(|_| scheduler.chaos_signal_target(process).unwrap())
            .collect();
        assert_eq!(drawn, [process, orphan].into_iter().collect());
        for draw in 0..32 {
            assert_eq!(
                scheduler.chaos_signal_target(creator),
                Some(creator),
                "draw {draw}"
            );
        }
    }

    /// The checks of whether another call of a process can take a signal
    /// waiting in its shared queue, or its SIGCHLD, read the process's own
    /// threads: a signalfd read or `rt_sigtimedwait` dequeues from the
    /// caller's own process, so a call of another process whose thread holds
    /// an ID the tree lists under it cannot take it. 50's own checks still
    /// see its thread 39.
    #[test]
    fn a_processs_signal_takers_are_its_own_threads() {
        let (mut scheduler, process, reused, other) = reused_thread_family();
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        scheduler.sigtimedwait_sets.insert(reused, usr1);
        assert!(!scheduler.another_call_may_take_waiting_signal(process, process, usr1));
        assert!(scheduler.another_call_may_take_waiting_signal(other, other, usr1));
        scheduler.sigtimedwait_sets.clear();

        let read = ExternalOpId::new(reused, 1);
        scheduler.signalfd_masks.insert(other, usr1);
        scheduler.background_signalfd_reads.insert(reused, read);
        scheduler.blocked.external_io_blockers.insert(reused, read);
        assert!(!scheduler.another_call_may_take_waiting_signal(process, process, usr1));
        assert!(scheduler.another_call_may_take_waiting_signal(other, other, usr1));

        scheduler
            .blocked
            .out_of_scheduler_masks
            .insert(reused, None);
        assert!(!scheduler.outside_call_may_take_sigchld(process));
        assert!(scheduler.outside_call_may_take_sigchld(other));
    }

    /// A disposition that ignores a signal flushes its pending copies from
    /// the threads of its own process (Linux's `do_sigaction` flushes the
    /// thread group's queues), not from another process's thread whose ID
    /// the tree lists under it.
    #[test]
    fn an_ignored_signal_forgets_only_its_own_processes_timer_copies() {
        let (mut scheduler, process, reused, other) = reused_thread_family();
        let signo = libc::SIGUSR1;
        for (thread, owner) in [(process, process), (reused, other)] {
            scheduler.thread_timer_copies.insert(
                (thread, signo),
                timed_waiters::SignalTimerId::Posix(owner, 0),
            );
        }
        scheduler.forget_thread_timer_copies(process, signo);
        assert!(
            !scheduler
                .thread_timer_copies
                .contains_key(&(process, signo))
        );
        assert!(scheduler.thread_timer_copies.contains_key(&(reused, signo)));
    }

    /// `signal_target_process` names a former leader that has no
    /// `thread_to_leader` entry as its own process. Its signal targets are
    /// then read by that process ID, without the member lookup that expects
    /// an entry. Production cannot build this state (`add_child` records a
    /// leader in both tables and nothing removes an entry); the test pins
    /// that the `expect` is gone, not a panic a run could reach.
    #[test]
    fn the_signal_targets_of_a_leader_without_a_leader_entry_are_read_by_its_id() {
        let mut scheduler = Scheduler::new(&Config::default());
        let (parent, leader) = (DetTid::from_raw(37), DetTid::from_raw(38));
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, leader, true);
        register_known_thread(&mut scheduler, parent);
        scheduler.thread_tree.remove_test_thread_leader(leader);
        assert_eq!(scheduler.signal_target_process(leader), Some(leader));
        assert_eq!(
            scheduler.process_signal_targets(leader),
            Vec::<DetTid>::new()
        );
    }

    /// The parent-death signals a process holds, and the thread that inherits
    /// an exiting thread's children (Linux's `find_alive_thread` walks the
    /// exiting thread's own group), are its own threads': not those of a
    /// thread of another process whose ID the tree lists under it.
    #[test]
    fn parent_death_reads_only_the_processs_own_threads() {
        let (mut scheduler, process, reused, _) = reused_thread_family();
        scheduler
            .thread_tree
            .parent_death_signals
            .insert(reused, libc::SIGTERM);
        assert_eq!(
            scheduler.held_parent_death_signals(process),
            Vec::<i32>::new()
        );
        // 38's leader is its last thread: no thread of 38 inherits.
        assert_ne!(scheduler.parent_death_heir(process, process), Some(reused));
    }

    /// A subreaper, or a PID namespace's init, whose leader has exited
    /// adopts an orphan by its own first live thread (Linux's
    /// `find_alive_thread`), not by a live thread of another process whose
    /// ID the tree lists under it, even one with a lower ID.
    #[test]
    fn a_reaper_adopts_by_its_own_live_thread() {
        let tid = DetTid::from_raw;
        let (parent, reaper, reused, own, other, orphan) =
            (tid(37), tid(38), tid(39), tid(41), tid(50), tid(60));
        let mut scheduler = Scheduler::new(&Config::default());
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, reaper, true);
        scheduler.thread_tree.add_child(reaper, reused, false);
        scheduler.thread_tree.add_child(reaper, own, false);
        scheduler.thread_tree.add_child(own, orphan, true);
        scheduler.thread_tree.add_child(parent, other, true);
        scheduler.thread_tree.add_child(other, reused, false);
        // 38's leader has exited; its thread 41 lives on.
        for thread in [parent, reused, own, other, orphan] {
            register_known_thread(&mut scheduler, thread);
        }
        assert_eq!(scheduler.thread_tree.parent_process(&orphan), Some(reaper));
        scheduler.thread_tree.set_child_subreaper(reaper, true);
        assert_eq!(scheduler.find_child_reaper(orphan), Some((reaper, own)));

        scheduler.thread_tree.set_child_subreaper(reaper, false);
        let namespaces = &mut scheduler.thread_tree.pid_namespaces;
        namespaces.record(reaper, &[reaper], &[38, 1]).unwrap();
        namespaces.record(orphan, &[reaper], &[60, 2]).unwrap();
        assert_eq!(scheduler.namespace_reaper(orphan), Some((reaper, own)));
    }

    /// A process's `/proc/<pid>/task` lists its own threads (Linux's
    /// `proc_task_readdir` walks the thread group), and an exact child wait
    /// sees the child running only while a thread of its own lives.
    #[test]
    fn a_processs_task_listing_and_wait_state_count_only_its_own_threads() {
        let (mut scheduler, process, _, _) = reused_thread_family();
        assert_eq!(
            scheduler.procfs_listing(Some(process)).threads,
            [process.as_raw()]
        );
        // 38's last thread exits; 50's thread 39 lives on.
        scheduler.next_turns.remove(&process);
        assert_ne!(
            scheduler.exact_child_wait_state(DetPid::from_raw(37), process),
            ExactChildWaitState::Running
        );
    }

    /// A successful exec retires the other threads of its own process
    /// (Linux's `de_thread` kills the caller's thread group), not a live
    /// thread of another process whose ID the tree lists under it.
    #[test]
    fn an_exec_retires_only_its_own_processes_threads() {
        let (mut scheduler, process, reused, _) = reused_thread_family();
        let pre_exec_mm = MmId::initial(process);
        let retired = scheduler.reconnect_after_exec(ExecReconnect {
            caller: process,
            new_leader: process,
            detpid: process,
            pre_exec_mm,
            post_exec_mm: pre_exec_mm.for_exec(process),
            child_tid_addr: 0,
            reconnect_priority: Some(DEFAULT_PRIORITY),
        });
        assert_eq!(retired, Vec::<DetTid>::new());
        assert!(scheduler.next_turns.contains_key(&reused));
    }

    /// A child process counts as stuck, for the deadlock check of its
    /// parent's wait, when its own live threads all wait with no way on: a
    /// live thread of another process whose ID the tree lists under it does
    /// not decide whether the child can run again.
    #[test]
    fn a_child_is_stuck_by_its_own_threads_alone() {
        let (mut scheduler, process, _, _) = reused_thread_family();
        scheduler
            .blocked
            .timed_waiters
            .insert(LogicalTime::INDEFINITE, process);
        assert!(scheduler.child_is_stuck(None, process, &BTreeSet::new()));
    }

    /// Without reused IDs `process_threads` is the tree's walk of the group,
    /// exited threads included and in the walk's order, which differs from
    /// DetTid order: targeted chaos draws an index into this list, so a seed
    /// picks the same thread as the walk did before.
    #[test]
    fn process_threads_are_the_tree_walk_without_reused_ids() {
        let tid = DetTid::from_raw;
        let mut scheduler = Scheduler::new(&Config::default());
        let (root, a, b) = (tid(1), tid(2), tid(9));
        scheduler.thread_tree.add_child(root, root, true);
        for (parent, child, leader) in [
            (root, tid(3), false),
            (root, a, true),
            (a, tid(4), false),
            (a, tid(5), false),
            (tid(4), tid(6), false),
            (root, tid(7), false),
            (a, b, true),
            (tid(5), tid(8), false),
            (b, tid(10), false),
        ] {
            scheduler.thread_tree.add_child(parent, child, leader);
        }
        for raw in 1..=10 {
            register_known_thread(&mut scheduler, tid(raw));
        }
        // An exited thread stays listed.
        scheduler.next_turns.remove(&tid(4));
        for process in [root, a, b] {
            assert_eq!(
                scheduler.process_threads(process),
                scheduler.thread_tree.my_thread_group(&process)
            );
        }
        let walk = scheduler.process_threads(a);
        let mut sorted = walk.clone();
        sorted.sort();
        assert_ne!(
            walk, sorted,
            "the walk's order must differ from DetTid order"
        );
    }

    /// A process-directed SIGKILL whose victim's leader has exited reaches
    /// the host through a registered thread of the victim's own process,
    /// also one the tree's walk misses because its creator's ID now leads
    /// another process; without it the kill could not be traced and the run
    /// would end in a deadlock report.
    #[test]
    fn a_sigkill_victim_is_known_by_a_thread_the_tree_walk_misses() {
        let (mut scheduler, process, orphan, _) = reused_creator_family();
        let mm = scheduler.thread_mm(orphan).unwrap();
        scheduler
            .register_physical_thread(orphan, mm, std::process::id() as i32, unsafe {
                libc::syscall(libc::SYS_gettid) as i32
            })
            .expect("PIDFD_THREAD must bind the current test thread");
        assert_eq!(
            scheduler.sigkill_victim_registered_thread(process, process, true),
            Some(orphan)
        );
    }

    /// Process 38 reuses an ID among its own threads: its thread 39 exited
    /// and Linux gave 39 to a new thread of 38. The tree lists 39 twice
    /// under 38; the process has it once, and `/proc/38/task` lists it once.
    #[test]
    fn a_thread_id_reused_within_its_process_is_listed_once() {
        let tid = DetTid::from_raw;
        let (parent, process, reused) = (tid(37), tid(38), tid(39));
        let mut scheduler = Scheduler::new(&Config::default());
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, process, true);
        scheduler.thread_tree.add_child(process, reused, false);
        scheduler.thread_tree.add_child(process, reused, false);
        for thread in [parent, process, reused] {
            register_known_thread(&mut scheduler, thread);
        }
        assert_eq!(scheduler.process_threads(process), [process, reused]);
        assert_eq!(
            scheduler.procfs_listing(Some(process)).threads,
            [process.as_raw(), reused.as_raw()]
        );
    }

    /// Process 38's thread 39 created thread 40 and exited, and Linux gave 39
    /// to a thread 40 created. The tree keeps both edges, 39 to 40 and 40 to
    /// 39, a cycle: the walk ends, and lists each thread once.
    #[test]
    fn a_cycle_of_reused_thread_ids_ends_the_walk() {
        let tid = DetTid::from_raw;
        let (parent, process, first, second) = (tid(37), tid(38), tid(39), tid(40));
        let mut scheduler = Scheduler::new(&Config::default());
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, process, true);
        scheduler.thread_tree.add_child(process, first, false);
        scheduler.thread_tree.add_child(first, second, false);
        scheduler.thread_tree.add_child(second, first, false);
        for thread in [parent, process, first, second] {
            register_known_thread(&mut scheduler, thread);
        }
        // A walk that never ends would keep its thread running, and growing,
        // after this test failed; under a single-process runner that thread
        // would outlive the test, so a timeout aborts the process instead.
        let (sender, receiver) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            let _ = sender.send((
                scheduler.process_threads(process),
                format!("{}", scheduler.thread_tree),
            ));
        });
        let (threads, printed) = receiver
            .recv_timeout(std::time::Duration::from_secs(10))
            .unwrap_or_else(|_| {
                eprintln!("the walk did not end on a cycle of reused IDs");
                std::process::abort()
            });
        assert_eq!(threads, [process, first, second]);
        // The run summary prints the tree: each thread once, and the edge
        // that closes the cycle as a repeat.
        assert_eq!(printed, "[37 [38 (39 (40 <again 39>))]]");
    }

    /// A thread of process 38 that the tree's walk misses, because its
    /// creator's ID 39 now leads another process, counts after it exits too:
    /// its exit was not committed, so 38 is going down and does not count as
    /// stuck (its parent's wait is real), although 38's leader waits with no
    /// deadline.
    #[test]
    fn an_exited_thread_the_walk_misses_still_counts_for_a_stuck_child() {
        let (mut scheduler, process, orphan, _) = reused_creator_family();
        scheduler.next_turns.remove(&orphan);
        scheduler
            .blocked
            .timed_waiters
            .insert(LogicalTime::INDEFINITE, process);
        assert_eq!(scheduler.process_threads(process), [process, orphan]);
        assert!(!scheduler.child_is_stuck(None, process, &BTreeSet::new()));
    }

    /// Process 38 was reaped and Linux gave 38 to a new process. The old
    /// process's thread 39, which left without a committed exit, still names
    /// 38 in `thread_to_leader`, and the tree still lists it under 38; it is
    /// no thread of the new process, so the new 38, whose only thread waits
    /// with no deadline, counts as stuck.
    #[test]
    fn a_reused_process_id_starts_with_none_of_the_old_processs_threads() {
        let tid = DetTid::from_raw;
        let (parent, process, old_thread) = (tid(37), tid(38), tid(39));
        let mut scheduler = Scheduler::new(&Config::default());
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, process, true);
        scheduler.thread_tree.add_child(process, old_thread, false);
        // The old 38 and its thread 39 are gone; a new process gets 38.
        scheduler.thread_tree.add_child(parent, process, true);
        for thread in [parent, process] {
            register_known_thread(&mut scheduler, thread);
        }
        assert!(
            scheduler
                .thread_tree
                .my_thread_group(&process)
                .contains(&old_thread),
            "the stale edge this test is about must exist"
        );
        scheduler
            .blocked
            .timed_waiters
            .insert(LogicalTime::INDEFINITE, process);
        assert_eq!(scheduler.process_threads(process), [process]);
        assert!(scheduler.child_is_stuck(None, process, &BTreeSet::new()));
    }

    /// The same reused pid, but the old process's thread 39 still has turn
    /// state: its deregistration has not reached Detcore. It is still no
    /// thread of the new process 38, for the paths that read live threads
    /// only: the new 38's leader is its last thread at its exit, and once it
    /// has gone a wait does not see the new 38 running.
    #[test]
    fn a_reused_process_id_does_not_count_an_old_thread_still_registered() {
        let tid = DetTid::from_raw;
        let (parent, process, old_thread) = (tid(37), tid(38), tid(39));
        let mut scheduler = Scheduler::new(&Config::default());
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, process, true);
        scheduler.thread_tree.add_child(process, old_thread, false);
        scheduler.thread_tree.add_child(parent, process, true);
        for thread in [parent, process, old_thread] {
            register_known_thread(&mut scheduler, thread);
        }
        assert_eq!(
            scheduler.live_process_threads(process).collect::<Vec<_>>(),
            [process]
        );
        assert!(!scheduler.retire_test_exited_leader(process, MmId::initial(process)));
        scheduler.next_turns.remove(&process);
        assert_ne!(
            scheduler.exact_child_wait_state(parent, process),
            ExactChildWaitState::Running
        );
    }

    /// Process 38's leader left at its own exit while its thread 39 lived on,
    /// which dropped 38's SIGALRM state; 39 then published a SIGALRM handler
    /// for 38. 39's exit_group ends the process, so nothing of 38's SIGALRM
    /// state may outlive it: a new process that Linux gives pid 38 must not
    /// have its SIGALRM diverted as if it handled it. The grant's kill of the
    /// exited leader is what drops it (the caller, 39, leaves by its own
    /// exit; the grant kills 40).
    #[test]
    fn an_exit_group_drops_its_processs_sigalrm_state_after_the_leader_left() {
        let tid = DetTid::from_raw;
        let (parent, leader, sibling, other) = (tid(37), tid(38), tid(39), tid(40));
        let mm = MmId::initial(leader);
        let mut scheduler = Scheduler::new(&Config::default());
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, leader, true);
        scheduler.thread_tree.add_child(leader, sibling, false);
        scheduler.thread_tree.add_child(leader, other, false);
        for thread in [parent, leader, sibling, other] {
            register_known_thread(&mut scheduler, thread);
        }
        scheduler.logically_kill_thread(&leader, &leader, mm);
        assert!(!scheduler.next_turns.contains_key(&leader));
        scheduler.set_sigalrm_handled(leader, true);
        scheduler.logically_kill_exit_group_siblings(sibling, leader, mm);
        assert!(!scheduler.next_turns.contains_key(&other));
        assert!(scheduler.next_turns.contains_key(&sibling));
        assert!(!scheduler.sigalrm_handled(leader));
    }

    /// `has_had_other_threads` is per process incarnation: an exec, which
    /// leaves its process one thread, keeps it, and a new process that Linux
    /// gives the pid starts without it, whatever the old one had.
    #[test]
    fn the_had_other_threads_flag_survives_exec_and_resets_at_a_new_process() {
        let tid = DetTid::from_raw;
        let (parent, process, sibling) = (tid(37), tid(38), tid(39));
        let mut scheduler = Scheduler::new(&Config::default());
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, process, true);
        assert!(!scheduler.thread_tree.has_had_other_threads(process));
        scheduler.thread_tree.add_child(process, sibling, false);
        for thread in [parent, process, sibling] {
            register_known_thread(&mut scheduler, thread);
        }
        assert!(scheduler.thread_tree.has_had_other_threads(process));

        let pre_exec_mm = MmId::initial(process);
        let retired = scheduler.reconnect_after_exec(ExecReconnect {
            caller: process,
            new_leader: process,
            detpid: process,
            pre_exec_mm,
            post_exec_mm: pre_exec_mm.for_exec(process),
            child_tid_addr: 0,
            reconnect_priority: Some(DEFAULT_PRIORITY),
        });
        assert_eq!(retired, [sibling]);
        scheduler.record_successful_exec(process);
        assert!(scheduler.thread_tree.has_had_other_threads(process));

        // The process has gone; Linux gives 38 to a new process.
        scheduler.logically_kill_thread(&process, &process, pre_exec_mm.for_exec(process));
        scheduler.thread_tree.add_child(parent, process, true);
        assert!(!scheduler.thread_tree.has_had_other_threads(process));
    }

    /// Threads of process 38 that the tree's walk misses come after the walk,
    /// in DetTid order, whatever order they were created in.
    #[test]
    fn threads_the_walk_misses_follow_it_in_tid_order() {
        let tid = DetTid::from_raw;
        let (parent, process, creator, late, early) = (tid(37), tid(38), tid(39), tid(42), tid(40));
        let mut scheduler = Scheduler::new(&Config::default());
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, process, true);
        scheduler.thread_tree.add_child(process, creator, false);
        scheduler.thread_tree.add_child(creator, late, false);
        scheduler.thread_tree.add_child(creator, early, false);
        scheduler.thread_tree.add_child(parent, creator, true);
        for thread in [parent, process, creator, late, early] {
            register_known_thread(&mut scheduler, thread);
        }
        assert_eq!(scheduler.process_threads(process), [process, early, late]);
    }

    /// Targeted chaos draws its index into the tree walk's order, not DetTid
    /// order, so a fuzz seed picks the same thread as it did before reused
    /// IDs were handled: the draws equal `chaos_pick` over the walk.
    #[test]
    fn targeted_chaos_draws_in_the_tree_walks_order() {
        let tid = DetTid::from_raw;
        let mut scheduler = Scheduler::new(&Config::default());
        let root = tid(1);
        scheduler.thread_tree.add_child(root, root, true);
        for child in 2..=6 {
            scheduler.thread_tree.add_child(root, tid(child), false);
        }
        for raw in 1..=6 {
            register_known_thread(&mut scheduler, tid(raw));
            scheduler.runqueue_push_back(tid(raw));
        }
        scheduler.chaos_target_races = true;
        let walk = scheduler.thread_tree.my_thread_group(&root);
        let mut sorted = walk.clone();
        sorted.sort();
        assert_ne!(
            walk, sorted,
            "the walk's order must differ from DetTid order"
        );
        let mut prng = scheduler.fuzz_prng.clone();
        let expected: Vec<DetTid> = (0..32)
            .map(|_| chaos_pick(&mut prng, &walk).unwrap())
            .collect();
        let drawn: Vec<DetTid> = (0..32)
            .map(|_| scheduler.chaos_signal_target(root).unwrap())
            .collect();
        assert_eq!(drawn, expected);
    }

    /// A cross-task signal must interrupt a precise-mode futex waiter, which sleeps
    /// outside the run queue (https://github.com/rrnewton/hermit/issues/3146).
    #[test]
    fn pending_signal_interrupts_a_parked_futex_waiter() {
        let mut scheduler = Scheduler::new(&Config::default());
        let target = DetTid::from_raw(100);
        register_known_thread(&mut scheduler, target);
        let futex = FutexID::private(MmId::initial(DetPid::from_raw(100)), 0x404110);
        scheduler.sleep_futex_waiter(
            &target,
            futex,
            None,
            u32::MAX,
            Some(signal_watch(usr_signals())),
        );
        scheduler
            .test_kernel_signal_states
            .insert(target, signal_state(usr_signals(), 0));
        assert!(scheduler.is_parked_futex_waiter(target));
        assert!(!scheduler.run_queue.contains_tid(target));

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR2));
        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        // Nothing moves until the deterministic step2 drain.
        assert!(scheduler.is_parked_futex_waiter(target));
        assert!(!scheduler.run_queue.contains_tid(target));
        scheduler.drain_pending_cross_task_signals();

        assert!(scheduler.pending_cross_task_signals.is_empty());
        assert!(!scheduler.is_parked_futex_waiter(target));
        assert!(scheduler.blocked.no_futex_waiters());
        assert!(scheduler.run_queue.contains_tid(target));
        assert_eq!(
            scheduler.inbound_signals(target),
            vec![
                SigWrapper::from(Signal::SIGUSR1),
                SigWrapper::from(Signal::SIGUSR2)
            ]
        );
        // A futex wake that arrives afterwards finds no waiter to take.
        assert_eq!(scheduler.wake_futex_waiters(target, futex, 1, u32::MAX), 0);
    }

    fn usr_signals() -> u64 {
        kernel_signal_bit(libc::SIGUSR1) | kernel_signal_bit(libc::SIGUSR2)
    }

    /// A precise-mode futex waiter's report in a unit test. The `/proc` identity
    /// names no live thread, so a test that installs no kernel signal state for
    /// the waiter exercises the read-error fallback.
    fn signal_watch(unblocked: u64) -> FutexSignalWatch {
        FutexSignalWatch {
            unblocked,
            defers_default_stops: false,
            pid: i32::MAX,
            tid: i32::MAX,
        }
    }

    /// Kernel dispositions with `caught` handled and `ignored` set to `SIG_IGN`;
    /// every other signal keeps its default action.
    fn signal_state(caught: u64, ignored: u64) -> KernelSignalState {
        KernelSignalState {
            caught,
            ignored,
            ..Default::default()
        }
    }

    fn parked_futex_target(scheduler: &mut Scheduler) -> (DetTid, FutexID) {
        let target = DetTid::from_raw(100);
        register_known_thread(scheduler, target);
        (
            target,
            FutexID::private(MmId::initial(DetPid::from_raw(100)), 0x404110),
        )
    }

    /// A cross-task signal the waiter blocks, ignores, or ignores by default leaves
    /// a precise-mode futex waiter parked with its original deadline, alongside one
    /// that does interrupt it (https://github.com/rrnewton/hermit/issues/3146).
    #[test]
    fn non_interrupting_signal_leaves_a_parked_futex_waiter_parked() {
        let mut scheduler = Scheduler::new(&Config::default());
        let (target, futex) = parked_futex_target(&mut scheduler);
        let deadline = LogicalTime::from_nanos(300_000_000);
        // SIGTERM is blocked. SIGUSR1 is caught, SIGUSR2 is ignored, and SIGWINCH
        // and SIGCHLD keep their default action, which ignores them.
        let unblocked =
            usr_signals() | kernel_signal_bit(libc::SIGWINCH) | kernel_signal_bit(libc::SIGCHLD);
        scheduler.sleep_futex_waiter(
            &target,
            futex,
            Some(deadline),
            u32::MAX,
            Some(signal_watch(unblocked)),
        );
        scheduler.test_kernel_signal_states.insert(
            target,
            signal_state(
                kernel_signal_bit(libc::SIGUSR1),
                kernel_signal_bit(libc::SIGUSR2),
            ),
        );

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR2));
        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGWINCH));
        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGTERM));
        scheduler.drain_pending_cross_task_signals();
        scheduler.wake_signaled_guest(target, Signal::SIGUSR2);
        scheduler.wake_signaled_guest(target, Signal::SIGCHLD);
        scheduler.wake_signaled_guest(target, Signal::SIGTERM);

        assert!(scheduler.pending_cross_task_signals.is_empty());
        assert!(scheduler.is_parked_futex_waiter(target));
        assert!(!scheduler.run_queue.contains_tid(target));
        assert!(scheduler.inbound_signals(target).is_empty());
        assert_eq!(
            scheduler.blocked.timed_waiters.iter().collect::<Vec<_>>(),
            vec![(deadline, TimedEvent::ThreadEvt(target))]
        );

        // The one signal that interrupts the wait still ends it.
        scheduler.wake_signaled_guest(target, Signal::SIGUSR1);
        assert!(!scheduler.is_parked_futex_waiter(target));
        assert!(scheduler.run_queue.contains_tid(target));
        assert!(scheduler.blocked.timed_waiters.is_empty());
        assert_eq!(
            scheduler.inbound_signals(target),
            vec![SigWrapper::from(Signal::SIGUSR1)]
        );
    }

    /// A timed `FUTEX_WAIT`, whose restart would start its relative timeout again,
    /// stays parked with its original deadline when a default `SIGTSTP` arrives:
    /// Linux discards that stop in an orphaned process group and the wait goes on.
    /// `SIGSTOP` and a caught `SIGTSTP` still end it, and a wait that does not
    /// defer default stops is ended by the default `SIGTSTP` too (review of
    /// https://github.com/rrnewton/hermit/pull/3361 at `cbb36408`, finding 4).
    #[test]
    fn a_default_job_control_stop_leaves_a_rearming_futex_wait_parked() {
        let stops = kernel_signal_bit(libc::SIGTSTP)
            | kernel_signal_bit(libc::SIGTTIN)
            | kernel_signal_bit(libc::SIGTTOU);
        let deadline = LogicalTime::from_nanos(300_000_000);
        let park = |scheduler: &mut Scheduler, defers_default_stops: bool, caught: u64| {
            let (target, futex) = parked_futex_target(scheduler);
            scheduler.sleep_futex_waiter(
                &target,
                futex,
                Some(deadline),
                u32::MAX,
                Some(FutexSignalWatch {
                    defers_default_stops,
                    ..signal_watch(stops | kernel_signal_bit(libc::SIGSTOP))
                }),
            );
            scheduler
                .test_kernel_signal_states
                .insert(target, signal_state(caught, 0));
            target
        };
        let assert_parked = |scheduler: &Scheduler, target: DetTid| {
            assert!(scheduler.is_parked_futex_waiter(target));
            assert!(!scheduler.run_queue.contains_tid(target));
            assert!(scheduler.inbound_signals(target).is_empty());
            assert_eq!(
                scheduler.blocked.timed_waiters.iter().collect::<Vec<_>>(),
                vec![(deadline, TimedEvent::ThreadEvt(target))]
            );
        };
        let assert_woken = |scheduler: &Scheduler, target: DetTid, signal: Signal| {
            assert!(!scheduler.is_parked_futex_waiter(target));
            assert!(scheduler.run_queue.contains_tid(target));
            assert!(scheduler.blocked.timed_waiters.is_empty());
            assert_eq!(
                scheduler.inbound_signals(target),
                vec![SigWrapper::from(signal)]
            );
        };

        // Through the drain of cross-task signals and through scheduler sends.
        let mut scheduler = Scheduler::new(&Config::default());
        let target = park(&mut scheduler, true, 0);
        for signal in [Signal::SIGTSTP, Signal::SIGTTIN, Signal::SIGTTOU] {
            scheduler.notify_signal_pending(target, SigWrapper::from(signal));
        }
        scheduler.drain_pending_cross_task_signals();
        scheduler.wake_signaled_guest(target, Signal::SIGTSTP);
        assert!(scheduler.pending_cross_task_signals.is_empty());
        assert_parked(&scheduler, target);
        // SIGSTOP always stops the process, so it still ends the wait.
        scheduler.wake_signaled_guest(target, Signal::SIGSTOP);
        assert_woken(&scheduler, target, Signal::SIGSTOP);

        // A handler makes SIGTSTP an ordinary caught signal.
        let mut scheduler = Scheduler::new(&Config::default());
        let target = park(&mut scheduler, true, kernel_signal_bit(libc::SIGTSTP));
        scheduler.wake_signaled_guest(target, Signal::SIGTSTP);
        assert_woken(&scheduler, target, Signal::SIGTSTP);

        // A wait whose restart keeps its deadline takes the default stop at once.
        let mut scheduler = Scheduler::new(&Config::default());
        let target = park(&mut scheduler, false, 0);
        scheduler.wake_signaled_guest(target, Signal::SIGTSTP);
        assert_woken(&scheduler, target, Signal::SIGTSTP);
    }

    /// A precise-mode futex waiter is admitted on its mask and on what Linux
    /// does with the signal as it is sent: a blocked one is not recorded
    /// (https://github.com/rrnewton/hermit/issues/3146), and neither is one that
    /// is ignored now, which Linux discards at generation, so a handler
    /// installed before the drain does not bring it back (the Claude review of
    /// https://github.com/rrnewton/hermit/pull/4290; before it, an ignored
    /// signal was recorded and the drain decided from the dispositions then).
    /// The drain still decides from the dispositions it reads for a signal it
    /// did record (`a_signal_caught_after_a_futex_wait_began_ends_it`).
    ///
    /// The sender records each send's fate in its turn, before it notifies
    /// (`discarded_at_send`, <https://github.com/rrnewton/hermit/issues/4293>),
    /// and the admission reads that record.
    #[test]
    fn a_parked_futex_waiter_is_admitted_on_its_mask_and_the_disposition_at_the_send() {
        let mut scheduler = gated_scheduler();
        let (target, futex) = parked_futex_target(&mut scheduler);
        scheduler.sleep_futex_waiter(
            &target,
            futex,
            None,
            u32::MAX,
            Some(signal_watch(
                kernel_signal_bit(libc::SIGUSR1) | kernel_signal_bit(libc::SIGTERM),
            )),
        );
        // SIGUSR1 ignored, SIGTERM caught; SIGUSR2 blocked by the wait's mask.
        scheduler.test_kernel_signal_states.insert(
            target,
            signal_state(
                kernel_signal_bit(libc::SIGTERM),
                kernel_signal_bit(libc::SIGUSR1),
            ),
        );

        for signal in [Signal::SIGUSR1, Signal::SIGUSR2, Signal::SIGTERM] {
            record_guest_send(&mut scheduler, target, signal as i32);
            scheduler.notify_signal_pending(target, SigWrapper::from(signal));
        }

        assert_eq!(
            scheduler.pending_cross_task_signals.get(&target),
            Some(&vec![SigWrapper::from(Signal::SIGTERM)])
        );
        assert!(scheduler.is_parked_futex_waiter(target));
    }

    /// C1 of the Claude approval of the design of
    /// https://github.com/rrnewton/hermit/issues/4293: a scheduler send Linux
    /// discards commits nothing to a parked futex waiter, whatever that
    /// branch's own filter says. SIGUSR1 at its default action to a PID
    /// namespace's init is discarded (`SIGNAL_UNKILLABLE`), which
    /// `parked_futex_interrupting_signals` does not model: it calls SIGUSR1
    /// interrupting.
    #[test]
    fn a_discarded_scheduler_send_to_a_namespace_init_commits_no_futex_wake() {
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        let mut scheduler = gated_scheduler();
        let (target, futex) = parked_futex_target(&mut scheduler);
        scheduler.sleep_futex_waiter(&target, futex, None, u32::MAX, Some(signal_watch(usr1)));
        scheduler
            .test_kernel_signal_states
            .insert(target, signal_state(0, 0));
        assert!(!scheduler.discarded_when_sent_to(target, libc::SIGUSR1, None));
        scheduler
            .thread_tree
            .mark_pid_namespace_init(DetPid::from_raw(target.as_raw()));
        assert!(scheduler.discarded_when_sent_to(target, libc::SIGUSR1, None));
        assert_eq!(
            scheduler
                .parked_futex_interrupting_signals(target, 0)
                .map(|signals| signals & usr1),
            Some(usr1),
            "the branch's own filter would wake it"
        );
        scheduler.wake_signaled_guest_as(target, Signal::SIGUSR1, true);
        assert!(scheduler.is_parked_futex_waiter(target));
        assert!(scheduler.inbound_signals(target).is_empty());
    }

    /// R5-1 of the design review of https://github.com/rrnewton/hermit/issues/4293:
    /// a discarded scheduler send skips only the branches that commit an
    /// `InboundSignal`. The physical copy still wakes a thread asleep in a real
    /// `rt_sigsuspend` whose mask admits it, so that thread is still armed for
    /// the release barrier, which fixes where its continuation rejoins.
    #[test]
    fn a_discarded_scheduler_send_still_arms_a_thread_asleep_outside_the_schedule() {
        let mut scheduler = gated_scheduler();
        let (target, _) = parked_futex_target(&mut scheduler);
        let op = ExternalOpId {
            tid: target,
            sequence: 1,
        };
        scheduler.blocked.rt_sigsuspend_blockers.insert(target, op);
        scheduler
            .blocked
            .out_of_scheduler_masks
            .insert(target, Some(0));
        scheduler.wake_signaled_guest_as(target, Signal::SIGUSR1, true);
        assert!(scheduler.blocked.signaled_background.contains(&target));
    }

    /// A discarded scheduler send commits no `InboundSignal` to a parked
    /// sleep (R4-1 of the design review of
    /// https://github.com/rrnewton/hermit/issues/4293): the sleep stays parked,
    /// where a kept send of the same signal wakes it.
    #[test]
    fn a_discarded_scheduler_send_leaves_a_parked_sleep_parked() {
        for discarded in [true, false] {
            let mut scheduler = gated_scheduler();
            let target = filed_sleep(&mut scheduler, LogicalTime::INDEFINITE, PAUSE_FYI, false);
            scheduler.wake_signaled_guest_as(target, Signal::SIGUSR1, discarded);
            if discarded {
                assert!(scheduler.inbound_signals(target).is_empty());
                assert!(!scheduler.run_queue.contains_tid(target));
            } else {
                assert_eq!(
                    scheduler.inbound_signals(target),
                    vec![SigWrapper::from(Signal::SIGUSR1)]
                );
            }
        }
    }

    /// The same for a sleep still queued, as under `when-chosen` registration
    /// or race search: a timed signal due before its deadline wakes it to
    /// answer the signal, and notes the due time, though committed time has
    /// passed the deadline; one due at the deadline leaves it to complete when
    /// admitted (https://github.com/rrnewton/hermit/issues/4931).
    #[test]
    fn a_timed_signal_due_before_a_queued_nanosleep_deadline_ends_it_whenever_it_pops() {
        let deadline = LogicalTime::from_nanos(5_000_000_000);
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        let early = LogicalTime::from_nanos(4_950_000_000);
        for (due, woken) in [(early, true), (deadline, false)] {
            let mut scheduler = gated_scheduler();
            let target = filed_sleep(&mut scheduler, deadline, NANOSLEEP_FYI, true);
            scheduler.committed_time = LogicalTime::from_nanos(5_001_000_000);
            set_sleeper_state(&mut scheduler, target, sleeper_state(usr1, 0, 0, 0));
            scheduler.signal_sent_at = Some(due);
            scheduler.wake_signaled_guest_as(target, Signal::SIGUSR1, false);
            let case = format!("due {due}");
            if woken {
                assert_eq!(
                    scheduler.inbound_signals(target),
                    vec![SigWrapper::from(Signal::SIGUSR1)],
                    "{case}"
                );
                assert!(scheduler.blocked.woken_sleeps.contains(&target), "{case}");
                assert_eq!(
                    scheduler.take_sleep_interruption(target),
                    Some(due),
                    "{case}"
                );
            } else {
                assert!(scheduler.inbound_signals(target).is_empty(), "{case}");
                assert!(!scheduler.blocked.woken_sleeps.contains(&target), "{case}");
                assert_eq!(scheduler.take_sleep_interruption(target), None, "{case}");
            }
        }
    }

    /// A timed signal sent to a `nanosleep` held at a happens-before gate is
    /// not delivered to it (`force_unblock_thread_at` leaves the thread held,
    /// its request in place), so no interruption is noted: the note is only
    /// for an interruption delivered to the sleep, and one left here would
    /// outlive it.
    #[test]
    fn a_timed_signal_to_a_sleep_held_at_a_gate_notes_no_interruption() {
        let deadline = LogicalTime::from_nanos(5_000_000_000);
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        for queued in [false, true] {
            let mut scheduler = gated_scheduler();
            let target = filed_sleep(&mut scheduler, deadline, NANOSLEEP_FYI, queued);
            scheduler.committed_time = LogicalTime::from_nanos(5_001_000_000);
            set_sleeper_state(&mut scheduler, target, sleeper_state(usr1, 0, 0, 0));
            let mut hb = hb_runtime(HB_GATE_SPEC);
            hb.parked.insert(target);
            scheduler.happens_before = Some(hb);
            scheduler.signal_sent_at = Some(LogicalTime::from_nanos(4_950_000_000));
            scheduler.wake_signaled_guest_as(target, Signal::SIGUSR1, false);
            assert!(
                scheduler.inbound_signals(target).is_empty(),
                "queued {queued}"
            );
            assert_eq!(
                scheduler.take_sleep_interruption(target),
                None,
                "queued {queued}"
            );
        }
    }

    /// A `nanosleep` filing its request starts with no interruption noted: a
    /// note an earlier sleep's wake left behind is dropped. Another request
    /// leaves the note alone.
    #[test]
    fn a_nanosleep_filing_its_request_drops_an_earlier_note() {
        let global_time = Arc::new(Mutex::new(GlobalTime::new(&Config::default())));
        let earlier = LogicalTime::from_nanos(1_000);
        for (fyi, kept) in [(NANOSLEEP_FYI, false), (PAUSE_FYI, true)] {
            let mut scheduler = Scheduler::new(&Config::default());
            let sleeper = DetTid::from_raw(100);
            register_known_thread(&mut scheduler, sleeper);
            scheduler
                .blocked
                .sleep_interruptions
                .insert(sleeper, earlier);
            let mut sleep = Resources::new(sleeper);
            sleep.insert(
                ResourceID::SleepUntil(LogicalTime::from_nanos(5_000)),
                Permission::W,
            );
            sleep.fyi(fyi);
            let req = scheduler.next_turns[&sleeper].req.clone();
            scheduler.request_put(&req, sleep, &global_time);
            assert_eq!(
                scheduler.take_sleep_interruption(sleeper),
                kept.then_some(earlier),
                "{fyi}"
            );
        }
    }

    /// The mask that decides a discard is the first source present: the
    /// guest's own mask while Detcore holds a private one, a parked futex
    /// waiter's watch, the mask recorded for a thread asleep outside the
    /// schedule (an unknown one decides nothing), then `SigBlk`. A task the
    /// scheduler does not know, such as an exited leader whose frozen mask
    /// Detcore never read, is not discarded
    /// (https://github.com/rrnewton/hermit/issues/4293).
    #[test]
    fn the_discard_mask_takes_the_first_source_present() {
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        let mut scheduler = gated_scheduler();
        let (target, futex) = parked_futex_target(&mut scheduler);
        let mut state = signal_state(0, usr1);
        state.blocked = usr1;
        scheduler.test_kernel_signal_states.insert(target, state);
        let discarded =
            |scheduler: &Scheduler| scheduler.discarded_when_sent_to(target, libc::SIGUSR1, None);
        assert!(!discarded(&scheduler), "SigBlk blocks it");
        // A filed rt_sigsuspend's temporary mask decides before SigBlk.
        let mut request = Resources::new(target);
        request.insert(
            ResourceID::BlockingRtSigsuspend(ExternalOpId::new(target, 1)),
            Permission::RW,
        );
        request.blocked_signal_mask = Some(0);
        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(request));
        assert!(
            discarded(&scheduler),
            "the filed rt_sigsuspend's mask before SigBlk"
        );
        scheduler
            .blocked
            .out_of_scheduler_masks
            .insert(target, Some(usr1));
        assert!(
            !discarded(&scheduler),
            "the sleeping mask before the filed rt_sigsuspend's"
        );
        scheduler
            .blocked
            .out_of_scheduler_masks
            .insert(target, Some(0));
        assert!(discarded(&scheduler), "the sleeping mask before SigBlk");
        scheduler
            .blocked
            .out_of_scheduler_masks
            .insert(target, None);
        assert!(!discarded(&scheduler), "an unknown sleeping mask");
        scheduler.blocked.out_of_scheduler_masks.remove(&target);
        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::new();
        scheduler.sleep_futex_waiter(&target, futex, None, u32::MAX, Some(signal_watch(usr1)));
        assert!(discarded(&scheduler), "the futex watch before SigBlk");
        assert!(scheduler.set_saved_guest_sigmask(target, Some(usr1)));
        assert!(!discarded(&scheduler), "the guest's own mask first");
        assert!(!scheduler.discarded_when_sent_to(DetTid::from_raw(999), libc::SIGUSR1, None));
    }

    /// A5 step 2b: a discard reads the dispositions the target's process
    /// published (`publish_signal_dispositions`) in place of the kernel's,
    /// for a signal Detcore's copy holds exactly. A withdrawn entry, a signal
    /// Linux force-delivers, and a noted unreported signal send it back to the
    /// kernel's view. The entry is the process's, read for any thread of it,
    /// and goes with the process's last thread and with a new process on its
    /// pid.
    #[test]
    fn a_discard_reads_the_dispositions_the_process_published() {
        use crate::syscalls::signal_shadow::CopiedDispositions;
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        let segv = kernel_signal_bit(libc::SIGSEGV);
        let mut scheduler = gated_scheduler();
        let (target, _) = parked_futex_target(&mut scheduler);
        let process = DetPid::from_raw(target.as_raw());
        let sibling = DetTid::from_raw(101);
        register_known_thread(&mut scheduler, sibling);
        scheduler.thread_tree.add_child(target, target, true);
        scheduler.thread_tree.add_child(target, sibling, false);
        // The kernel shows nothing ignored, the published copy SIGUSR1 and
        // SIGSEGV: only the source a discard reads can make it true.
        scheduler
            .test_kernel_signal_states
            .insert(target, signal_state(0, 0));
        let published = CopiedDispositions {
            ignored: usr1 | segv,
            caught: 0,
        };
        let discarded =
            |scheduler: &Scheduler, signal| scheduler.discarded_when_sent_to(target, signal, None);
        assert!(!discarded(&scheduler, libc::SIGUSR1), "the kernel's view");
        let mm = MmId::initial(process);
        let answer =
            |held, taken| Some(crate::syscalls::signal_shadow::PublicationAnswer { held, taken });
        assert_eq!(
            scheduler.publish_signal_dispositions(DetTid::from_raw(999), mm, 1, Some(published)),
            None,
            "a thread the scheduler does not know"
        );
        assert_eq!(
            scheduler.publish_signal_dispositions(sibling, mm, 2, Some(published)),
            answer(2, true)
        );
        assert!(
            discarded(&scheduler, libc::SIGUSR1),
            "a sibling's publication is the process's"
        );
        assert!(
            !discarded(&scheduler, libc::SIGSEGV),
            "a signal Linux force-delivers reads the kernel's"
        );
        // A note of a thread that no longer exists (pid_max is far below this
        // tid) counts until it is pruned.
        crate::syscalls::signal_shadow::note_unreported(1, i32::MAX - 1, libc::SIGUSR2);
        assert!(
            !discarded(&scheduler, libc::SIGUSR1),
            "a noted unreported signal"
        );
        assert!(!crate::syscalls::signal_shadow::unreported_pending());
        assert!(discarded(&scheduler, libc::SIGUSR1));
        // A publication older than the one taken changes nothing, in either
        // direction.
        assert_eq!(
            scheduler.publish_signal_dispositions(target, mm, 1, None),
            answer(2, false),
            "the generation held is the later one"
        );
        assert!(discarded(&scheduler, libc::SIGUSR1), "an older withdrawal");
        assert_eq!(
            scheduler.publish_signal_dispositions(target, mm, 3, None),
            answer(3, true)
        );
        assert!(!discarded(&scheduler, libc::SIGUSR1), "withdrawn");
        assert_eq!(
            scheduler.publish_signal_dispositions(target, mm, 2, Some(published)),
            answer(3, false)
        );
        assert!(
            !discarded(&scheduler, libc::SIGUSR1),
            "an older publication"
        );

        assert_eq!(
            scheduler.publish_signal_dispositions(target, mm, 4, Some(published)),
            answer(4, true)
        );
        scheduler.forget_previous_process_exit(process);
        assert!(
            !discarded(&scheduler, libc::SIGUSR1),
            "a new process on the pid"
        );
        assert_eq!(
            scheduler.publish_signal_dispositions(target, mm, 1, Some(published)),
            answer(1, true),
            "a new process's generations start again"
        );
        assert!(discarded(&scheduler, libc::SIGUSR1));
        scheduler.logically_kill_thread(&sibling, &process, MmId::initial(process));
        assert_eq!(
            scheduler.publish_signal_dispositions(sibling, mm, 9, None),
            None,
            "a thread logically killed publishes nothing"
        );
        assert!(
            discarded(&scheduler, libc::SIGUSR1),
            "a thread of the process remains"
        );
        // A retired exec incarnation of the tid publishes nothing.
        scheduler.install_test_exec_incarnation(target, MmId::initial(DetPid::from_raw(555)));
        assert_eq!(
            scheduler.publish_signal_dispositions(target, mm, 9, None),
            None,
            "a retired incarnation"
        );
        assert!(
            discarded(&scheduler, libc::SIGUSR1),
            "the entry is unchanged"
        );
        scheduler.logically_kill_thread(&target, &process, MmId::initial(process));
        assert_eq!(
            scheduler.published_dispositions[&process],
            crate::syscalls::signal_shadow::PublishedDispositions {
                generation: 1,
                dispositions: None,
                ..Default::default()
            },
            "the process's last thread took its dispositions with it, not the generation"
        );
    }

    /// A5 step 2b: where a decision reads a thread's kernel mask, it reads the
    /// mask the thread published in place of `SigBlk`, for a signal Detcore's
    /// copy holds exactly. A withdrawn mask, a signal Linux force-delivers, a
    /// noted unreported signal and a private mask Detcore installed read the
    /// kernel's; the mask goes with its thread.
    #[test]
    fn mask_readers_take_the_mask_the_thread_published() {
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        let segv = kernel_signal_bit(libc::SIGSEGV);
        let mut scheduler = gated_scheduler();
        let (target, _) = parked_futex_target(&mut scheduler);
        let process = DetPid::from_raw(target.as_raw());
        let mm = MmId::initial(process);
        scheduler.thread_tree.add_child(target, target, true);
        // The kernel shows SIGUSR1 and SIGSEGV blocked, the published copy
        // neither.
        let mut state = signal_state(0, 0);
        state.blocked = usr1 | segv;
        scheduler.test_kernel_signal_states.insert(target, state);
        let mask = |scheduler: &Scheduler, signal| scheduler.discard_mask(target, signal);
        assert_eq!(
            mask(&scheduler, libc::SIGUSR1),
            Some(usr1 | segv),
            "the kernel's"
        );
        assert!(
            !scheduler.publish_signal_mask(DetTid::from_raw(999), mm, Some(0)),
            "a thread the scheduler does not know"
        );
        assert!(scheduler.publish_signal_mask(target, mm, Some(0)));
        assert_eq!(mask(&scheduler, libc::SIGUSR1), Some(0), "published");
        assert!(scheduler.poll_mask_admits(target, SigWrapper(libc::SIGUSR1)));
        assert_eq!(
            scheduler.thread_signal_mask_for(target, libc::SIGUSR1),
            Some(0)
        );
        assert_eq!(
            scheduler.thread_signal_mask(target),
            Some(usr1 | segv),
            "a whole mask still reads the kernel's"
        );
        assert_eq!(
            mask(&scheduler, libc::SIGSEGV),
            Some(usr1 | segv),
            "a signal Linux force-delivers reads the kernel's"
        );
        crate::syscalls::signal_shadow::note_unreported(1, i32::MAX - 1, libc::SIGUSR2);
        assert_eq!(
            mask(&scheduler, libc::SIGUSR1),
            Some(usr1 | segv),
            "a noted unreported signal"
        );
        assert!(!crate::syscalls::signal_shadow::unreported_pending());
        assert!(scheduler.publish_signal_mask(target, mm, None));
        assert_eq!(
            mask(&scheduler, libc::SIGUSR1),
            Some(usr1 | segv),
            "withdrawn"
        );
        assert!(scheduler.publish_signal_mask(target, mm, Some(0)));
        // The process-directed target choice: the published mask unblocks
        // SIGUSR1, where SigBlk blocks it.
        assert_eq!(
            scheduler.kernel_signal_target(process, target, libc::SIGUSR1),
            Some(target)
        );
        // While Detcore holds the thread under a mask of its own, readers that
        // ask for the kernel's mask get SigBlk, as before.
        assert!(scheduler.set_saved_guest_sigmask(target, Some(0)));
        assert_eq!(
            scheduler.thread_signal_mask_for(target, libc::SIGUSR1),
            Some(usr1 | segv),
            "a private mask is installed"
        );
        assert_eq!(
            scheduler.kernel_signal_target(process, target, libc::SIGUSR1),
            None
        );
        assert!(scheduler.set_saved_guest_sigmask(target, None));
        scheduler.install_test_exec_incarnation(target, MmId::initial(DetPid::from_raw(555)));
        assert!(
            !scheduler.publish_signal_mask(target, mm, None),
            "a retired incarnation"
        );
        assert_eq!(mask(&scheduler, libc::SIGUSR1), Some(0), "unchanged");
        scheduler.logically_kill_thread(&target, &process, mm);
        assert!(
            !scheduler.published_masks.contains_key(&target),
            "the mask went with its thread"
        );
    }

    /// A send of SIGCONT flushes the stop signals from every queue of the
    /// process, as `prepare_signal` does, so a discarded stop signal's bit
    /// goes with it (https://github.com/rrnewton/hermit/issues/4293).
    #[test]
    fn a_sigcont_send_flushes_a_discarded_stop_signal() {
        let tstp = kernel_signal_bit(libc::SIGTSTP);
        let mut scheduler = gated_scheduler();
        let (target, _) = parked_futex_target(&mut scheduler);
        scheduler
            .test_kernel_signal_states
            .insert(target, signal_state(0, tstp));
        record_guest_send(&mut scheduler, target, libc::SIGTSTP);
        assert_eq!(scheduler.discarded_bits(target).0 & tstp, tstp);
        record_guest_send(&mut scheduler, target, libc::SIGCONT);
        assert_eq!(scheduler.discarded_bits(target).0 & tstp, 0);
    }

    /// Record a guest's thread-directed send of `signal` to `target` in the
    /// discarded-at-send record, as its sender does in its turn
    /// (`DiscardedSignalControl::PreSend`, then `Sent`).
    fn record_guest_send(scheduler: &mut Scheduler, target: DetTid, signal: i32) {
        let queue = discarded_at_send::QueueId::Thread(target);
        let token = scheduler.discard_pre_send(target, queue, signal, Some(target));
        scheduler.discard_note_send(token, None, None);
    }

    /// A signal ignored by default with no handler when it is sent (here a
    /// guest's recorded thread-directed SIGCHLD, and SIGURG) is discarded by
    /// Linux then. A handler installed before the drain, which `rt_sigaction`
    /// does without a turn, does not end the wait: it stays parked
    /// (the Claude review of https://github.com/rrnewton/hermit/pull/4290).
    #[test]
    fn a_signal_discarded_when_sent_does_not_end_a_futex_wait_a_later_handler_could() {
        use child_exit_sigchld::ChildExitSigchldControl;
        for signal in [Signal::SIGCHLD, Signal::SIGURG] {
            let bit = kernel_signal_bit(signal as libc::c_int);
            let mut scheduler = gated_scheduler();
            let (target, futex) = parked_futex_target(&mut scheduler);
            scheduler.sleep_futex_waiter(&target, futex, None, u32::MAX, Some(signal_watch(bit)));
            scheduler
                .test_kernel_signal_states
                .insert(target, signal_state(0, 0));
            if signal == Signal::SIGCHLD {
                scheduler.child_exit_sigchld_control(
                    target,
                    ChildExitSigchldControl::PrivateSent { target },
                );
            }
            // The sender records the send's fate in its turn.
            record_guest_send(&mut scheduler, target, signal as libc::c_int);
            scheduler.notify_signal_pending(target, SigWrapper::from(signal));
            // The handler arrives after the send, before the drain.
            scheduler
                .test_kernel_signal_states
                .insert(target, signal_state(bit, 0));
            scheduler.drain_pending_cross_task_signals();
            assert!(scheduler.is_parked_futex_waiter(target), "{signal}");
            assert!(scheduler.inbound_signals(target).is_empty(), "{signal}");
        }
    }

    /// A handler a sibling installs over `SIG_IGN` after the wait began ends the
    /// wait when the signal arrives, as on Linux. The earlier design read the
    /// dispositions when the wait began and left this waiter parked; an untimed
    /// wait then never ended (https://github.com/rrnewton/hermit/issues/3146).
    #[test]
    fn a_signal_caught_after_a_futex_wait_began_ends_it() {
        // Through the step2 drain of a cross-task signal.
        let mut scheduler = Scheduler::new(&Config::default());
        let (target, futex) = parked_futex_target(&mut scheduler);
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        scheduler
            .test_kernel_signal_states
            .insert(target, signal_state(0, usr1));
        scheduler.sleep_futex_waiter(&target, futex, None, u32::MAX, Some(signal_watch(usr1)));
        // The sibling's `rt_sigaction` runs in its turn, before it signals.
        scheduler
            .test_kernel_signal_states
            .insert(target, signal_state(usr1, 0));
        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        scheduler.drain_pending_cross_task_signals();

        assert!(!scheduler.is_parked_futex_waiter(target));
        assert!(scheduler.run_queue.contains_tid(target));
        assert_eq!(
            scheduler.inbound_signals(target),
            vec![SigWrapper::from(Signal::SIGUSR1)]
        );

        // Through a scheduler send (a timer), for SIGWINCH, which is ignored by
        // default until a handler is installed. A SIGCHLD ends the wait only
        // when the scheduler sends it
        // (`a_sigchld_ends_a_parked_futex_wait_only_when_the_scheduler_sends_it`).
        let mut scheduler = Scheduler::new(&Config::default());
        let (target, futex) = parked_futex_target(&mut scheduler);
        let winch = kernel_signal_bit(libc::SIGWINCH);
        scheduler
            .test_kernel_signal_states
            .insert(target, signal_state(0, 0));
        scheduler.sleep_futex_waiter(&target, futex, None, u32::MAX, Some(signal_watch(winch)));
        scheduler
            .test_kernel_signal_states
            .insert(target, signal_state(winch, 0));
        scheduler.wake_signaled_guest(target, Signal::SIGWINCH);

        assert!(!scheduler.is_parked_futex_waiter(target));
        assert!(scheduler.run_queue.contains_tid(target));
        assert_eq!(
            scheduler.inbound_signals(target),
            vec![SigWrapper::from(Signal::SIGWINCH)]
        );
    }

    /// A signal a sibling sets to `SIG_IGN` after the wait began leaves the waiter
    /// parked, registered with its original absolute deadline, because Linux
    /// discards an ignored signal without ending the wait. The earlier design woke
    /// the waiter, and the restarted `FUTEX_WAIT` began a fresh relative timeout
    /// (https://github.com/rrnewton/hermit/issues/3146).
    #[test]
    fn a_signal_ignored_after_a_futex_wait_began_keeps_its_deadline() {
        let mut scheduler = Scheduler::new(&Config::default());
        let (target, futex) = parked_futex_target(&mut scheduler);
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        let deadline = LogicalTime::from_nanos(300_000_000);
        scheduler
            .test_kernel_signal_states
            .insert(target, signal_state(usr1, 0));
        scheduler.sleep_futex_waiter(
            &target,
            futex,
            Some(deadline),
            u32::MAX,
            Some(signal_watch(usr1)),
        );
        scheduler
            .test_kernel_signal_states
            .insert(target, signal_state(0, usr1));

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        scheduler.drain_pending_cross_task_signals();
        scheduler.wake_signaled_guest(target, Signal::SIGUSR1);

        assert!(scheduler.pending_cross_task_signals.is_empty());
        assert!(scheduler.is_parked_futex_waiter(target));
        assert!(!scheduler.run_queue.contains_tid(target));
        assert!(scheduler.inbound_signals(target).is_empty());
        assert_eq!(
            scheduler.blocked.timed_waiters.iter().collect::<Vec<_>>(),
            vec![(deadline, TimedEvent::ThreadEvt(target))]
        );
        // A FUTEX_WAKE still finds the waiter.
        assert_eq!(
            scheduler.wake_futex_waiters(DetTid::from_raw(101), futex, 1, u32::MAX),
            1
        );
    }

    /// When the waiter's signal state cannot be read at the commit point, every
    /// signal its mask leaves unblocked ends the wait. A needless wake costs one
    /// turn: the waiter re-checks its signals in its own turn and parks again
    /// with its original absolute deadline. A missed wake can leave the waiter
    /// parked forever (https://github.com/rrnewton/hermit/issues/3146).
    #[test]
    fn an_unreadable_signal_state_ends_a_parked_futex_wait() {
        let mut scheduler = Scheduler::new(&Config::default());
        let (target, futex) = parked_futex_target(&mut scheduler);
        scheduler.sleep_futex_waiter(
            &target,
            futex,
            None,
            u32::MAX,
            Some(signal_watch(kernel_signal_bit(libc::SIGWINCH))),
        );
        assert!(!scheduler.test_kernel_signal_states.contains_key(&target));

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGWINCH));
        scheduler.drain_pending_cross_task_signals();

        assert!(!scheduler.is_parked_futex_waiter(target));
        assert!(scheduler.run_queue.contains_tid(target));
        assert_eq!(
            scheduler.inbound_signals(target),
            vec![SigWrapper::from(Signal::SIGWINCH)]
        );
    }

    /// A backend that does not report the guest's signal state keeps the base
    /// behavior: no cross-task wakeup for a parked futex waiter.
    #[test]
    fn unreported_signal_state_keeps_futex_waiter_parked_for_cross_task_signals() {
        let mut scheduler = Scheduler::new(&Config::default());
        let target = DetTid::from_raw(100);
        register_known_thread(&mut scheduler, target);
        let futex = FutexID::private(MmId::initial(DetPid::from_raw(100)), 0x404110);
        scheduler.sleep_futex_waiter(&target, futex, None, u32::MAX, None);

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        scheduler.drain_pending_cross_task_signals();

        assert!(scheduler.pending_cross_task_signals.is_empty());
        assert!(scheduler.is_parked_futex_waiter(target));
        assert!(!scheduler.run_queue.contains_tid(target));
    }

    /// A futex waiter that a wake already requeued completes as woken; the signal
    /// does not rewrite its request.
    #[test]
    fn pending_signal_does_not_rewrite_a_woken_futex_waiter() {
        let mut scheduler = Scheduler::new(&Config::default());
        let target = DetTid::from_raw(100);
        let waker = DetTid::from_raw(101);
        register_known_thread(&mut scheduler, target);
        let futex = FutexID::private(MmId::initial(DetPid::from_raw(100)), 0x404110);
        scheduler.sleep_futex_waiter(
            &target,
            futex,
            None,
            u32::MAX,
            Some(signal_watch(usr_signals())),
        );
        scheduler
            .test_kernel_signal_states
            .insert(target, signal_state(usr_signals(), 0));
        assert_eq!(scheduler.wake_futex_waiters(waker, futex, 1, u32::MAX), 1);
        assert!(!scheduler.is_parked_futex_waiter(target));

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        scheduler.drain_pending_cross_task_signals();

        assert!(scheduler.pending_cross_task_signals.is_empty());
        assert!(scheduler.run_queue.contains_tid(target));
        assert!(scheduler.inbound_signals(target).is_empty());
        assert!(is_futex_request(&scheduler.next_turns[&target]));
    }

    /// `--watch`: the threads alive when the watches become due are summarized
    /// even if one is killed parked, before it records an event: at the
    /// threshold, and when the event that crosses it is the exit_group
    /// whose teardown kills the peer.
    #[test]
    fn a_peer_alive_when_watches_become_due_is_summarized_if_killed_parked() {
        use detcore_model::access_trace::TraceRecord;
        use detcore_model::access_trace::WatchSummaryRecord;
        use detcore_model::access_trace::WatchUnarmed;

        use crate::watch::WatchStatus;
        let main = DetTid::from_raw(3);
        let peer = DetTid::from_raw(4);
        for crossing in [
            SchedEvent::branches(main, 1),
            SchedEvent::syscall(main, Sysno::exit_group, SyscallPhase::Prehook),
        ] {
            let mut scheduler = Scheduler::new(&Config::default());
            let (mut writer, bytes) = crate::access_trace::in_memory_writer();
            // Due once 2 events are recorded.
            writer.enable_watch(2);
            scheduler.access_trace = Some(writer);
            register_known_thread(&mut scheduler, main);
            register_known_thread(&mut scheduler, peer);
            for event in [SchedEvent::branches(main, 1), crossing.clone()] {
                scheduler.recorded_event_count += 1;
                scheduler.note_watch(&event, Some(WatchStatus::Pending));
            }
            // The exit_group's teardown: the parked peer is gone without
            // another event.
            scheduler.next_turns.remove(&peer);
            let writer = scheduler.access_trace.take().unwrap();
            writer.finish(2).unwrap();
            let trace =
                detcore_model::access_trace::read_access_trace(&bytes.lock().unwrap()[..]).unwrap();
            let summaries: Vec<&WatchSummaryRecord> = trace
                .records
                .iter()
                .filter_map(|record| match record {
                    TraceRecord::WatchSummary(summary) => Some(summary),
                    _ => None,
                })
                .collect();
            let unarmed = |tid| WatchSummaryRecord {
                tid,
                armed_before: None,
                unarmed: Some(WatchUnarmed::NoStop),
                hits: 0,
                recorded: 0,
            };
            assert_eq!(
                summaries,
                vec![&unarmed(main), &unarmed(peer)],
                "{crossing:?}"
            );
        }
    }

    /// The access trace's futex edges: each wake ends at the woken waiter's
    /// posthook and starts at the waker's FUTEX_WAKE prehook, whichever
    /// waiter the wake takes. With `--fuzz-futexes` the waiter is a random
    /// pick, and the edge follows the pick.
    #[test]
    fn a_futex_wake_edge_names_the_waiter_the_wake_took() {
        use detcore_model::access_trace::EdgeRecord;
        use detcore_model::access_trace::EventRef;

        use crate::access_trace::AccessPayload;
        use crate::access_trace::SyscallEntry;
        use crate::access_trace::SyscallOutcome;
        for (fuzz, seed) in [(false, 0), (true, 1), (true, 2), (true, 3)] {
            let config = Config {
                fuzz_futexes: fuzz,
                fuzz_seed: Some(seed),
                ..Config::default()
            };
            let mut scheduler = Scheduler::new(&config);
            let (writer, bytes) = crate::access_trace::in_memory_writer();
            scheduler.access_trace = Some(writer);
            let waiters = [100, 101, 102].map(DetTid::from_raw);
            let waker = DetTid::from_raw(103);
            let futex = FutexID::private(MmId::initial(DetPid::from_raw(100)), 0x404110);
            let entry = || {
                Some(AccessPayload::SyscallEntry(SyscallEntry {
                    pid: DetPid::from_raw(100),
                    nth: 1,
                    sysno: Sysno::futex,
                    args: [0; 6],
                    accesses: Vec::new(),
                }))
            };
            let observe = |scheduler: &mut Scheduler, index, tid, phase, payload| {
                let event = SchedEvent::syscall(tid, Sysno::futex, phase);
                let writer = scheduler.access_trace.as_mut().unwrap();
                writer.observe(index, &event, payload, &ThreadTree::default());
            };
            for (index, waiter) in waiters.into_iter().enumerate() {
                register_known_thread(&mut scheduler, waiter);
                observe(
                    &mut scheduler,
                    index as u64,
                    waiter,
                    SyscallPhase::Prehook,
                    entry(),
                );
                scheduler.sleep_futex_waiter(&waiter, futex, None, u32::MAX, None);
            }
            observe(&mut scheduler, 3, waker, SyscallPhase::Prehook, entry());
            assert_eq!(scheduler.wake_futex_waiters(waker, futex, 1, u32::MAX), 1);
            let woken: Vec<DetTid> = waiters
                .into_iter()
                .filter(|waiter| !scheduler.is_parked_futex_waiter(*waiter))
                .collect();
            assert_eq!(woken.len(), 1, "fuzz {fuzz}, seed {seed}");
            let outcome = || {
                Some(AccessPayload::SyscallExit(Box::new(SyscallOutcome {
                    result: 0,
                    accesses: Vec::new(),
                    returned: None,
                    out_bytes: None,
                })))
            };
            observe(&mut scheduler, 4, waker, SyscallPhase::Posthook, outcome());
            observe(
                &mut scheduler,
                5,
                woken[0],
                SyscallPhase::Posthook,
                outcome(),
            );
            scheduler.access_trace.take().unwrap().finish(6).unwrap();
            assert_eq!(
                crate::access_trace::edges_of(&bytes),
                vec![EdgeRecord {
                    kind: EdgeKind::FutexWake,
                    from: EventRef {
                        tid: waker,
                        event: 3
                    },
                    to: EventRef {
                        tid: woken[0],
                        event: 5
                    },
                    object: SyncObject::Futex(futex),
                }],
                "fuzz {fuzz}, seed {seed}"
            );
        }
    }

    /// A requeue's edges: the waiter it woke gets a wake edge, and the
    /// waiter it moved gets a requeue edge, then the later wake's edge,
    /// both ending at that waiter's own return.
    #[test]
    fn a_requeue_edge_waits_for_the_moved_waiters_return() {
        use detcore_model::access_trace::EventRef;

        let mut scheduler = Scheduler::new(&Config::default());
        let (mut writer, bytes) = crate::access_trace::in_memory_writer();
        let (first, second, requeuer, unlocker) = (
            DetTid::from_raw(100),
            DetTid::from_raw(101),
            DetTid::from_raw(102),
            DetTid::from_raw(103),
        );
        let mm = MmId::initial(DetPid::from_raw(100));
        let (cond, mutex) = (FutexID::private(mm, 0x1000), FutexID::private(mm, 0x2000));
        for (index, tid) in [first, second, requeuer, unlocker].into_iter().enumerate() {
            writer.observe(
                index as u64,
                &SchedEvent::branches(tid, 1),
                None,
                &ThreadTree::default(),
            );
        }
        scheduler.access_trace = Some(writer);
        for waiter in [first, second] {
            register_known_thread(&mut scheduler, waiter);
            scheduler.sleep_futex_waiter(&waiter, cond, None, u32::MAX, None);
        }
        assert_eq!(
            scheduler.requeue_futex_waiters(requeuer, cond, mutex, 1, 1),
            (1, 1, false)
        );
        assert_eq!(
            scheduler.wake_futex_waiters(unlocker, mutex, 1, u32::MAX),
            1
        );
        let outcome = || {
            Some(crate::access_trace::AccessPayload::SyscallExit(Box::new(
                crate::access_trace::SyscallOutcome {
                    result: 0,
                    accesses: Vec::new(),
                    returned: None,
                    out_bytes: None,
                },
            )))
        };
        // A posthook ends only the edges of a syscall the writer saw begin;
        // the waiters' waits began before this test's events, so the edges
        // end at their next posthooks after an entry.
        let writer = scheduler.access_trace.as_mut().unwrap();
        for (index, tid) in [(10, first), (11, second)] {
            writer.observe(
                index,
                &SchedEvent::syscall(tid, Sysno::futex, SyscallPhase::Prehook),
                Some(crate::access_trace::AccessPayload::SyscallEntry(
                    crate::access_trace::SyscallEntry {
                        pid: DetPid::from_raw(100),
                        nth: 1,
                        sysno: Sysno::futex,
                        args: [0; 6],
                        accesses: Vec::new(),
                    },
                )),
                &ThreadTree::default(),
            );
            writer.observe(
                index + 10,
                &SchedEvent::syscall(tid, Sysno::futex, SyscallPhase::Posthook),
                outcome(),
                &ThreadTree::default(),
            );
        }
        scheduler.access_trace.take().unwrap().finish(30).unwrap();
        let edges: Vec<(EdgeKind, DetTid, EventRef, SyncObject)> =
            crate::access_trace::edges_of(&bytes)
                .into_iter()
                .map(|edge| (edge.kind, edge.from.tid, edge.to, edge.object))
                .collect();
        assert_eq!(
            edges,
            vec![
                (
                    EdgeKind::FutexWake,
                    requeuer,
                    EventRef {
                        tid: first,
                        event: 20
                    },
                    SyncObject::Futex(cond)
                ),
                (
                    EdgeKind::FutexRequeue,
                    requeuer,
                    EventRef {
                        tid: second,
                        event: 21
                    },
                    SyncObject::Futex(mutex)
                ),
                (
                    EdgeKind::FutexWake,
                    unlocker,
                    EventRef {
                        tid: second,
                        event: 21
                    },
                    SyncObject::Futex(mutex)
                ),
            ]
        );
    }

    /// An exit's clear-child-tid wake is an exit-to-join edge from the
    /// exiting thread's last event, on both of its wake paths.
    #[test]
    fn a_clear_child_tid_wake_is_a_join_edge() {
        use detcore_model::access_trace::EventRef;

        let mut scheduler = Scheduler::new(&Config::default());
        let (mut writer, bytes) = crate::access_trace::in_memory_writer();
        let (joiner, exiting) = (DetTid::from_raw(100), DetTid::from_raw(101));
        writer.observe(
            0,
            &SchedEvent::branches(joiner, 1),
            None,
            &ThreadTree::default(),
        );
        writer.observe(
            1,
            &SchedEvent::branches(exiting, 1),
            None,
            &ThreadTree::default(),
        );
        scheduler.access_trace = Some(writer);
        register_known_thread(&mut scheduler, joiner);
        let futex = FutexID::private(MmId::initial(DetPid::from_raw(100)), 0x7000);
        scheduler.sleep_futex_waiter(&joiner, futex, None, u32::MAX, None);
        scheduler.wake_futex_child_cleartid(futex, exiting);
        let writer = scheduler.access_trace.as_mut().unwrap();
        writer.observe(
            2,
            &SchedEvent::syscall(joiner, Sysno::futex, SyscallPhase::Prehook),
            Some(crate::access_trace::AccessPayload::SyscallEntry(
                crate::access_trace::SyscallEntry {
                    pid: DetPid::from_raw(100),
                    nth: 1,
                    sysno: Sysno::futex,
                    args: [0; 6],
                    accesses: Vec::new(),
                },
            )),
            &ThreadTree::default(),
        );
        writer.observe(
            3,
            &SchedEvent::syscall(joiner, Sysno::futex, SyscallPhase::Posthook),
            Some(crate::access_trace::AccessPayload::SyscallExit(Box::new(
                crate::access_trace::SyscallOutcome {
                    result: 0,
                    accesses: Vec::new(),
                    returned: None,
                    out_bytes: None,
                },
            ))),
            &ThreadTree::default(),
        );
        scheduler.access_trace.take().unwrap().finish(4).unwrap();
        let edges = crate::access_trace::edges_of(&bytes);
        assert_eq!(edges.len(), 1, "{edges:?}");
        assert_eq!(edges[0].kind, EdgeKind::ExitJoin);
        assert_eq!(
            edges[0].from,
            EventRef {
                tid: exiting,
                event: 1
            }
        );
        assert_eq!(
            edges[0].to,
            EventRef {
                tid: joiner,
                event: 3
            }
        );
    }

    /// A non-leader exec keeps the caller's own pending signals under the
    /// leader's tid (Linux's `de_thread` keeps the exec caller, and
    /// `exchange_tids` gives it the leader's id), so the access trace's
    /// sends to the caller follow it through the scheduler's exec handoff.
    /// Thread 41 of process 40 queues SIGUSR1 to itself with a forged
    /// SI_USER naming process 50, and thread 50 tkills SIGUSR2 to thread 41.
    /// Thread 41 execs and goes on as 40, and process 50 kills process 40
    /// with SIGUSR1. Linux delivers 41's own SIGUSR1 first, and that
    /// delivery must not take 50's kill as its cause; the SIGUSR2 delivery
    /// to 40 keeps its edge from the tkill.
    #[test]
    fn a_nonleader_exec_keeps_the_callers_pending_sends_under_the_leader() {
        use detcore_model::access_trace::EventRef;
        use detcore_model::access_trace::ObservedSignalDisposition;
        use detcore_model::schedule::Op;

        use crate::access_trace::AccessPayload;
        use crate::access_trace::SyscallEntry;
        use crate::access_trace::SyscallOutcome;
        let (leader, caller, killer) = (
            DetTid::from_raw(40),
            DetTid::from_raw(41),
            DetTid::from_raw(50),
        );
        let (usr1, usr2) = (libc::SIGUSR1, libc::SIGUSR2);
        let mut sched = Scheduler::new(&Config::default());
        let (detpid, pre_exec_mm, _) = install_runnable_exec_group(&mut sched, leader, caller);
        let (writer, bytes) = crate::access_trace::in_memory_writer();
        sched.access_trace = Some(writer);
        let call = |sched: &mut Scheduler, pre: u64, tid: DetTid, sysno: Sysno, args: [u64; 6]| {
            let pid = DetPid::from_raw(if tid == killer { 50 } else { 40 });
            let writer = sched.access_trace.as_mut().unwrap();
            writer.observe(
                pre,
                &SchedEvent::syscall(tid, sysno, SyscallPhase::Prehook),
                Some(AccessPayload::SyscallEntry(SyscallEntry {
                    pid,
                    nth: 1,
                    sysno,
                    args,
                    accesses: Vec::new(),
                })),
                &ThreadTree::default(),
            );
            writer.observe(
                pre + 1,
                &SchedEvent::syscall(tid, sysno, SyscallPhase::Posthook),
                Some(AccessPayload::SyscallExit(Box::new(SyscallOutcome {
                    result: 0,
                    accesses: Vec::new(),
                    returned: None,
                    out_bytes: None,
                }))),
                &ThreadTree::default(),
            );
        };
        // A delivery to the leader whose siginfo names process 50.
        let deliver = |sched: &mut Scheduler, index: u64, signo: i32, code: i32| {
            let mut info = [0u8; 128];
            info[8..12].copy_from_slice(&code.to_ne_bytes());
            info[16..20].copy_from_slice(&50i32.to_ne_bytes());
            let note = crate::access_trace::signal_note(
                signo,
                Some(&info),
                ObservedSignalDisposition::Handler,
            );
            sched.access_trace.as_mut().unwrap().observe(
                index,
                &SchedEvent {
                    op: Op::SignalReceived(SigWrapper(signo)),
                    ..SchedEvent::branches(leader, 1)
                },
                Some(AccessPayload::Signal(note)),
                &ThreadTree::default(),
            );
        };
        let queue = [40, 41, usr1 as u64, 0, 0, 0];
        call(&mut sched, 1, caller, Sysno::rt_tgsigqueueinfo, queue);
        let tkill = [41, usr2 as u64, 0, 0, 0, 0];
        call(&mut sched, 3, killer, Sysno::tkill, tkill);
        assert_eq!(
            reconnect_nonleader_exec(&mut sched, leader, caller, detpid, pre_exec_mm),
            vec![leader, caller]
        );
        let kill = [40, usr1 as u64, 0, 0, 0, 0];
        call(&mut sched, 5, killer, Sysno::kill, kill);
        call(&mut sched, 7, leader, Sysno::getpid, [0; 6]);
        deliver(&mut sched, 9, usr1, libc::SI_USER);
        deliver(&mut sched, 10, usr2, libc::SI_TKILL);
        sched.access_trace.take().unwrap().finish(11).unwrap();
        let edges: Vec<(EventRef, EventRef, SyncObject)> = crate::access_trace::edges_of(&bytes)
            .into_iter()
            .filter(|edge| edge.kind == EdgeKind::Signal)
            .map(|edge| (edge.from, edge.to, edge.object))
            .collect();
        assert_eq!(
            edges,
            vec![(
                EventRef {
                    tid: killer,
                    event: 3
                },
                EventRef {
                    tid: leader,
                    event: 10
                },
                SyncObject::Signal(usr2)
            )]
        );
    }

    /// A `FUTEX_WAKE` of one waiter wakes the longest waiter, as Linux does for
    /// waiters of equal priority. Waking the newest one let a thread that re-waits
    /// after every wake take every wake, and an older waiter never ran
    /// (https://github.com/rrnewton/hermit/issues/3917).
    #[test]
    fn a_futex_wake_takes_the_longest_waiter_first() {
        let mut scheduler = Scheduler::new(&Config::default());
        let waiters = [100, 101, 102].map(DetTid::from_raw);
        let waker = DetTid::from_raw(103);
        let futex = FutexID::private(MmId::initial(DetPid::from_raw(100)), 0x404110);
        for waiter in waiters {
            register_known_thread(&mut scheduler, waiter);
            scheduler.sleep_futex_waiter(&waiter, futex, None, u32::MAX, None);
        }
        for (woken, waiter) in waiters.into_iter().enumerate() {
            assert_eq!(scheduler.wake_futex_waiters(waker, futex, 1, u32::MAX), 1);
            for (index, other) in waiters.into_iter().enumerate() {
                assert_eq!(
                    scheduler.is_parked_futex_waiter(other),
                    index > woken,
                    "after wake {woken}, waiter {other:?}"
                );
            }
            assert!(scheduler.run_queue.contains_tid(waiter));
        }
    }

    /// A `FUTEX_WAKE` count of 0, or a count that is negative as the kernel's
    /// `int nr_wake` (-1, which is `u32::MAX` as the guest passes it), wakes one
    /// waiter, the longest one, as Linux's `futex_wake` does: it counts a waiter
    /// before comparing, `if (++ret >= nr_wake) break;`
    /// (https://github.com/rrnewton/hermit/issues/3957). A count of 0 used to wake
    /// nobody, and a negative count panicked the scheduler.
    #[test]
    fn a_futex_wake_count_of_zero_or_below_wakes_one_waiter() {
        for count in [0, -1, u32::MAX as i32, i32::MIN] {
            let mut scheduler = Scheduler::new(&Config::default());
            let waiters = [100, 101].map(DetTid::from_raw);
            let futex = FutexID::private(MmId::initial(DetPid::from_raw(100)), 0x404110);
            for waiter in waiters {
                register_known_thread(&mut scheduler, waiter);
                scheduler.sleep_futex_waiter(&waiter, futex, None, u32::MAX, None);
            }
            assert_eq!(
                scheduler.wake_futex_waiters(DetTid::from_raw(102), futex, count, u32::MAX),
                1,
                "count {count}"
            );
            assert!(
                !scheduler.is_parked_futex_waiter(waiters[0]),
                "count {count}"
            );
            assert!(
                scheduler.is_parked_futex_waiter(waiters[1]),
                "count {count}"
            );
        }
        // With no waiter, such a wake still wakes nobody.
        let mut scheduler = Scheduler::new(&Config::default());
        let futex = FutexID::private(MmId::initial(DetPid::from_raw(100)), 0x404110);
        assert_eq!(
            scheduler.wake_futex_waiters(DetTid::from_raw(102), futex, 0, u32::MAX),
            0
        );
    }

    /// A count of 0 still skips waiters whose bitset does not match, and wakes
    /// the first one that does, as `futex_wake`'s `continue` before `++ret`.
    #[test]
    fn a_futex_wake_bitset_count_of_zero_wakes_the_first_matching_waiter() {
        let mut scheduler = Scheduler::new(&Config::default());
        let futex = FutexID::private(MmId::initial(DetPid::from_raw(100)), 0x404110);
        let waiters = [(100, 0b10), (101, 0b01), (102, 0b01)]
            .map(|(tid, bitset)| (DetTid::from_raw(tid), bitset));
        for (waiter, bitset) in waiters {
            register_known_thread(&mut scheduler, waiter);
            scheduler.sleep_futex_waiter(&waiter, futex, None, bitset, None);
        }
        assert_eq!(
            scheduler.wake_futex_waiters(DetTid::from_raw(103), futex, 0, 0b01),
            1
        );
        let parked = waiters.map(|(waiter, _)| scheduler.is_parked_futex_waiter(waiter));
        assert_eq!(parked, [true, false, true]);
    }

    /// Helper: `n` waiters (raw tids from `first`) parked on `futex` with `bitset`.
    fn park_futex_waiters(
        scheduler: &mut Scheduler,
        futex: FutexID,
        first: i32,
        n: i32,
        bitset: u32,
    ) -> Vec<DetTid> {
        (first..first + n)
            .map(|raw| {
                let waiter = DetTid::from_raw(raw);
                register_known_thread(scheduler, waiter);
                scheduler.sleep_futex_waiter(&waiter, futex, None, bitset, None);
                waiter
            })
            .collect()
    }

    fn futex_waiter_order(scheduler: &Scheduler, futex: FutexID) -> Vec<DetTid> {
        scheduler
            .blocked
            .futex_waiters
            .get(&futex)
            .map(|waiters| waiters.iter().map(|w| w.dettid).collect())
            .unwrap_or_default()
    }

    /// FUTEX_REQUEUE wakes the first `nr_wake` waiters in arrival order and moves
    /// the next `nr_requeue`, which join the end of the target's waiters in their
    /// arrival order, as Linux's `futex_requeue` (kernel/futex/requeue.c) with
    /// `requeue_futex` appending to the target chain
    /// (https://github.com/rrnewton/hermit/issues/3958).
    #[test]
    fn a_futex_requeue_wakes_the_oldest_and_moves_the_next_in_order() {
        let mut scheduler = Scheduler::new(&Config::default());
        let mm = MmId::initial(DetPid::from_raw(100));
        let from = FutexID::private(mm, 0x404110);
        let to = FutexID::private(mm, 0x404120);
        let on_to = park_futex_waiters(&mut scheduler, to, 100, 1, u32::MAX);
        let on_from = park_futex_waiters(&mut scheduler, from, 101, 4, u32::MAX);
        assert_eq!(
            scheduler.requeue_futex_waiters(DetTid::from_raw(98), from, to, 1, 2),
            (1, 2, false)
        );
        assert!(scheduler.run_queue.contains_tid(on_from[0]));
        assert_eq!(futex_waiter_order(&scheduler, from), vec![on_from[3]]);
        assert_eq!(
            futex_waiter_order(&scheduler, to),
            vec![on_to[0], on_from[1], on_from[2]]
        );
        // A later wake of the target takes its own earlier waiter first.
        assert_eq!(
            scheduler.wake_futex_waiters(DetTid::from_raw(99), to, 1, u32::MAX),
            1
        );
        assert!(scheduler.run_queue.contains_tid(on_to[0]));
    }

    /// `futex_requeue`'s loop: `if (task_count - nr_wake >= nr_requeue) break;`
    /// before counting, and `if (++task_count <= nr_wake)` to wake. So nothing is
    /// done for 0 and 0, a `nr_wake` of 0 wakes nobody (unlike `futex_wake`), and
    /// bitsets do not matter.
    #[test]
    fn futex_requeue_counts_follow_linux() {
        let mm = MmId::initial(DetPid::from_raw(100));
        let from = FutexID::private(mm, 0x404110);
        let to = FutexID::private(mm, 0x404120);
        for (nr_wake, nr_requeue, expected) in [
            (0, 0, (0, 0, false)),
            (0, 1, (0, 1, false)),
            (2, 0, (2, 0, false)),
            (5, 5, (3, 0, false)),
        ] {
            let mut scheduler = Scheduler::new(&Config::default());
            let waiters = park_futex_waiters(&mut scheduler, from, 100, 3, 0b01);
            assert_eq!(
                scheduler.requeue_futex_waiters(
                    DetTid::from_raw(98),
                    from,
                    to,
                    nr_wake,
                    nr_requeue
                ),
                expected,
                "nr_wake {nr_wake} nr_requeue {nr_requeue}"
            );
            let (woken, moved, _) = expected;
            let (woken, moved) = (woken as usize, moved as usize);
            for (index, &waiter) in waiters.iter().enumerate() {
                assert_eq!(
                    scheduler.run_queue.contains_tid(waiter),
                    index < woken,
                    "nr_wake {nr_wake} nr_requeue {nr_requeue} waiter {index}"
                );
            }
            assert_eq!(
                futex_waiter_order(&scheduler, to),
                waiters[woken..woken + moved].to_vec()
            );
        }
    }

    /// Requeueing a futex onto itself moves nobody (`requeue_futex` only rewrites
    /// the key): the counted waiters keep their places, and only the woken leave.
    #[test]
    fn a_futex_requeue_onto_itself_keeps_waiters_in_place() {
        let mut scheduler = Scheduler::new(&Config::default());
        let futex = FutexID::private(MmId::initial(DetPid::from_raw(100)), 0x404110);
        let waiters = park_futex_waiters(&mut scheduler, futex, 100, 3, u32::MAX);
        assert_eq!(
            scheduler.requeue_futex_waiters(
                DetTid::from_raw(98),
                futex,
                futex,
                0,
                i32::MAX as usize
            ),
            (0, 3, false)
        );
        assert_eq!(futex_waiter_order(&scheduler, futex), waiters);
        assert_eq!(
            scheduler.requeue_futex_waiters(DetTid::from_raw(98), futex, futex, 1, 1),
            (1, 1, false)
        );
        assert_eq!(futex_waiter_order(&scheduler, futex), waiters[1..].to_vec());
    }

    /// A `FUTEX_WAKE` of several wakes the longest waiters, and they join the
    /// run queue in the order they started waiting.
    #[test]
    fn a_futex_wake_of_several_takes_the_longest_waiters_in_order() {
        let mut scheduler = Scheduler::new(&Config::default());
        let waiters = [100, 101, 102, 103].map(DetTid::from_raw);
        let futex = FutexID::private(MmId::initial(DetPid::from_raw(100)), 0x404110);
        for waiter in waiters {
            register_known_thread(&mut scheduler, waiter);
            scheduler.sleep_futex_waiter(&waiter, futex, None, u32::MAX, None);
        }
        assert_eq!(
            scheduler.wake_futex_waiters(DetTid::from_raw(104), futex, 2, u32::MAX),
            2
        );
        assert_eq!(
            scheduler.run_queue.tids().copied().collect::<Vec<_>>(),
            waiters[..2]
        );
        assert!(
            waiters[2..]
                .iter()
                .all(|&waiter| scheduler.is_parked_futex_waiter(waiter))
        );
    }

    /// A `FUTEX_WAKE_BITSET` that matches only some waiters leaves the others
    /// in the order they arrived, so a later wake still takes the longest
    /// waiter (Linux `futex_wake` walks one list in arrival order and skips
    /// the waiters whose bitset does not match).
    #[test]
    fn a_partial_bitset_wake_keeps_the_other_waiters_in_arrival_order() {
        let mut scheduler = Scheduler::new(&Config::default());
        let waker = DetTid::from_raw(103);
        let futex = FutexID::private(MmId::initial(DetPid::from_raw(100)), 0x404110);
        let waiters = [(100, 0b01), (101, 0b01), (102, 0b10)]
            .map(|(tid, bitset)| (DetTid::from_raw(tid), bitset));
        for (waiter, bitset) in waiters {
            register_known_thread(&mut scheduler, waiter);
            scheduler.sleep_futex_waiter(&waiter, futex, None, bitset, None);
        }
        let parked = |scheduler: &Scheduler| {
            waiters
                .iter()
                .map(|&(waiter, _)| scheduler.is_parked_futex_waiter(waiter))
                .collect::<Vec<_>>()
        };
        assert_eq!(scheduler.wake_futex_waiters(waker, futex, 1, 0b01), 1);
        assert_eq!(parked(&scheduler), [false, true, true]);
        assert_eq!(scheduler.wake_futex_waiters(waker, futex, 1, u32::MAX), 1);
        assert_eq!(parked(&scheduler), [false, false, true]);
        assert_eq!(scheduler.wake_futex_waiters(waker, futex, 1, u32::MAX), 1);
        assert_eq!(parked(&scheduler), [false, false, false]);
    }

    /// The wakes Detcore issues for an exiting thread also take the longest
    /// waiter: the one-waiter wake of `CLONE_CHILD_CLEARTID` (several threads
    /// joining one) and the one-waiter wake of a robust-list futex.
    #[test]
    fn exit_wakes_take_the_longest_waiter_first() {
        let mut scheduler = Scheduler::new(&Config::default());
        let exiting = DetTid::from_raw(99);
        let waiters = [100, 101, 102].map(DetTid::from_raw);
        let futex = FutexID::private(MmId::initial(DetPid::from_raw(99)), 0x404110);
        for waiter in waiters {
            register_known_thread(&mut scheduler, waiter);
            scheduler.sleep_futex_waiter(&waiter, futex, None, u32::MAX, None);
        }
        scheduler.wake_futex_child_cleartid(futex, exiting);
        assert!(!scheduler.is_parked_futex_waiter(waiters[0]));
        assert!(scheduler.is_parked_futex_waiter(waiters[1]));
        assert_eq!(
            scheduler.wake_futex_waiters_after_exit(&[(exiting, futex)]),
            vec![1]
        );
        assert!(!scheduler.is_parked_futex_waiter(waiters[1]));
        assert!(scheduler.is_parked_futex_waiter(waiters[2]));
    }

    fn pi_futex(address: usize) -> FutexID {
        FutexID::private(MmId::initial(DetPid::from_raw(99)), address)
    }

    fn contended(owner: DetTid, next_owner: Option<DetTid>) -> PiFutexState {
        PiFutexState::Contended {
            owner,
            next_owner,
            queueing_deadlocks: false,
        }
    }

    fn unqueued(alive: bool) -> PiFutexState {
        PiFutexState::Unqueued {
            named_owner_alive: alive,
            queueing_deadlocks: false,
        }
    }

    /// FUTEX_LOCK_PI waiters queue behind the owner the first one found and are
    /// handed the lock first in, first out (`wake_futex_pi` takes the rt_mutex
    /// top waiter, and every guest thread has the same rt_mutex priority). A
    /// waiter handed the lock owns the state until it takes the lock, learning
    /// it came from an unlock, and the state goes when nobody is queued or
    /// about to take it.
    #[test]
    fn pi_futex_waiters_are_handed_the_lock_first_in_first_out() {
        let mut scheduler = Scheduler::new(&Config::default());
        let owner = DetTid::from_raw(99);
        let waiters = [100, 101, 102].map(DetTid::from_raw);
        let futex = pi_futex(0x404110);
        for tid in std::iter::once(owner).chain(waiters) {
            register_known_thread(&mut scheduler, tid);
        }
        assert_eq!(
            scheduler.pi_futex_state(futex, 99, waiters[0]),
            unqueued(true)
        );
        for waiter in waiters {
            scheduler.sleep_pi_futex_waiter(waiter, futex, None, None, owner);
        }
        assert_eq!(
            scheduler.pi_futex_state(futex, 99, waiters[2]),
            contended(owner, Some(waiters[0]))
        );
        // The owner itself would queue behind itself.
        assert_eq!(
            scheduler.pi_futex_state(futex, 99, owner),
            PiFutexState::Contended {
                owner,
                next_owner: Some(waiters[0]),
                queueing_deadlocks: true,
            }
        );
        for (i, &waiter) in waiters.iter().enumerate() {
            assert_eq!(scheduler.hand_off_pi_futex(futex), Some(waiter));
            assert!(!scheduler.is_parked_futex_waiter(waiter));
            assert!(scheduler.run_queue.contains_tid(waiter));
            assert_eq!(
                scheduler.pi_futex_state(futex, waiter.as_raw() as u32, owner),
                contended(waiter, waiters.get(i + 1).copied())
            );
            assert_eq!(
                scheduler.take_handed_pi_futex(futex, waiter),
                Some(PiHandOver::Unlock)
            );
            assert_eq!(scheduler.take_handed_pi_futex(futex, waiter), None);
        }
        assert_eq!(scheduler.hand_off_pi_futex(futex), None);
        assert_eq!(scheduler.pi_futex_state(futex, 102, owner), unqueued(true));
        assert!(scheduler.blocked.pi_futex_owners.is_empty());
    }

    /// A word whose first waiter is a plain FUTEX_WAIT waiter has no PI state
    /// (`attach_to_pi_state` [3]), and a word nobody waits on names a thread that
    /// is alive or not (`attach_to_pi_owner`).
    #[test]
    fn pi_futex_state_reports_plain_waiters_and_dead_owners() {
        let mut scheduler = Scheduler::new(&Config::default());
        let live = DetTid::from_raw(100);
        let plain = DetTid::from_raw(101);
        register_known_thread(&mut scheduler, live);
        register_known_thread(&mut scheduler, plain);
        let futex = pi_futex(0x404110);
        for (named, alive) in [(100, true), (0, false), (12345, false), (u32::MAX, false)] {
            assert_eq!(
                scheduler.pi_futex_state(futex, named, plain),
                unqueued(alive),
                "named {named}"
            );
        }
        scheduler.sleep_futex_waiter(&plain, futex, None, u32::MAX, None);
        assert_eq!(
            scheduler.pi_futex_state(futex, 100, live),
            PiFutexState::PlainWaiters
        );
    }

    /// A plain wake walks the queue in order and stops at the first PI waiter,
    /// as Linux's `futex_wake` does: the plain waiters before it are woken, and
    /// the wake reports that it met one unless it woke its count first. The
    /// wakes a thread's exit makes stop there too.
    #[test]
    fn a_plain_wake_stops_at_the_first_pi_waiter() {
        for fuzz in [false, true] {
            let mut scheduler = Scheduler::new(&Config::default());
            scheduler.fuzz_futexes = fuzz;
            let owner = DetTid::from_raw(99);
            let [plain, pi_waiter, late_plain] = [100, 101, 102].map(DetTid::from_raw);
            for tid in [owner, plain, pi_waiter, late_plain] {
                register_known_thread(&mut scheduler, tid);
            }
            let futex = pi_futex(0x404110);
            scheduler.sleep_futex_waiter(&plain, futex, None, u32::MAX, None);
            scheduler.sleep_pi_futex_waiter(pi_waiter, futex, None, None, owner);
            scheduler.sleep_futex_waiter(&late_plain, futex, None, u32::MAX, None);
            assert!(scheduler.has_pi_waiters(futex));
            // Its count reached at the plain waiter first: no EINVAL.
            assert_eq!(
                scheduler.wake_futex_waiters_until_pi(owner, futex, 1, u32::MAX),
                (1, false)
            );
            assert!(scheduler.run_queue.contains_tid(plain));
            // The PI waiter heads the queue now.
            assert_eq!(
                scheduler.wake_futex_waiters_until_pi(owner, futex, 2, u32::MAX),
                (0, true)
            );
            assert_eq!(
                scheduler.wake_futex_waiters_after_exit(&[(owner, futex)]),
                vec![0]
            );
            assert!(scheduler.is_parked_futex_waiter(pi_waiter));
            assert!(scheduler.is_parked_futex_waiter(late_plain));
        }
    }

    /// `futex_requeue` checks its counts before it looks at a waiter, and stops
    /// with EINVAL at a PI waiter, keeping what it did before.
    #[test]
    fn a_plain_requeue_stops_at_the_first_pi_waiter() {
        let mut scheduler = Scheduler::new(&Config::default());
        let owner = DetTid::from_raw(99);
        let [plain, pi_waiter] = [100, 101].map(DetTid::from_raw);
        for tid in [owner, plain, pi_waiter] {
            register_known_thread(&mut scheduler, tid);
        }
        let from = pi_futex(0x404110);
        let to = pi_futex(0x404120);
        scheduler.sleep_futex_waiter(&plain, from, None, u32::MAX, None);
        scheduler.sleep_pi_futex_waiter(pi_waiter, from, None, None, owner);
        assert_eq!(
            scheduler.requeue_futex_waiters(owner, from, to, 0, 0),
            (0, 0, false)
        );
        assert_eq!(
            scheduler.requeue_futex_waiters(owner, from, to, 0, 5),
            (0, 1, true)
        );
        assert_eq!(futex_waiter_order(&scheduler, to), vec![plain]);
        assert_eq!(futex_waiter_order(&scheduler, from), vec![pi_waiter]);
    }

    /// A waiter handed the lock and not yet running still heads the queue in
    /// Linux (after FUTEX_UNLOCK_PI, which hands over only when a PI waiter is
    /// first): a plain wake or requeue meets it first, and a later FUTEX_LOCK_PI
    /// finds the state even when only plain waiters are queued behind it.
    #[test]
    fn a_waiter_handed_the_lock_still_heads_the_queue() {
        let mut scheduler = Scheduler::new(&Config::default());
        let owner = DetTid::from_raw(99);
        let [heir, plain] = [100, 101].map(DetTid::from_raw);
        for tid in [owner, heir, plain] {
            register_known_thread(&mut scheduler, tid);
        }
        let futex = pi_futex(0x404110);
        scheduler.sleep_pi_futex_waiter(heir, futex, None, None, owner);
        assert_eq!(scheduler.hand_off_pi_futex(futex), Some(heir));
        scheduler.sleep_futex_waiter(&plain, futex, None, u32::MAX, None);
        assert_eq!(
            scheduler.pi_futex_state(futex, 100, owner),
            contended(heir, None)
        );
        assert_eq!(
            scheduler.wake_futex_waiters_until_pi(owner, futex, 1, u32::MAX),
            (0, true)
        );
        assert_eq!(
            scheduler.requeue_futex_waiters(owner, futex, pi_futex(0x404120), 1, 0),
            (0, 0, true)
        );
        assert_eq!(
            scheduler.requeue_futex_waiters(owner, futex, pi_futex(0x404120), 0, 0),
            (0, 0, false)
        );
        assert_eq!(
            scheduler.take_handed_pi_futex(futex, heir),
            Some(PiHandOver::Unlock)
        );
        assert_eq!(
            scheduler.pi_futex_state(futex, 100, owner),
            PiFutexState::PlainWaiters
        );
        assert_eq!(scheduler.wake_futex_waiters(owner, futex, 1, u32::MAX), 1);
    }

    /// A FUTEX_LOCK_PI waiter whose owner waits, through PI futexes, for a lock
    /// the waiter owns would deadlock (`rt_mutex_adjust_prio_chain`'s
    /// `EDEADLK`), as would one waiting behind itself; a chain that ends at a
    /// running thread does not. The state answers it for the caller.
    #[test]
    fn a_pi_futex_wait_that_closes_a_cycle_deadlocks() {
        let mut scheduler = Scheduler::new(&Config::default());
        let [a, b, c] = [100, 101, 102].map(DetTid::from_raw);
        for tid in [a, b, c] {
            register_known_thread(&mut scheduler, tid);
        }
        let held_by_a = pi_futex(0x404110);
        let held_by_b = pi_futex(0x404120);
        // B owns another word and waits behind A.
        scheduler.sleep_pi_futex_waiter(b, held_by_a, None, None, a);
        assert!(scheduler.pi_futex_wait_deadlocks(b, a));
        assert!(scheduler.pi_futex_wait_deadlocks(a, a));
        assert!(!scheduler.pi_futex_wait_deadlocks(b, c));
        assert!(!scheduler.pi_futex_wait_deadlocks(a, c));
        assert_eq!(
            scheduler.pi_futex_state(held_by_b, 101, a),
            PiFutexState::Unqueued {
                named_owner_alive: true,
                queueing_deadlocks: true,
            }
        );
        assert_eq!(
            scheduler.pi_futex_state(held_by_a, 100, c),
            contended(a, Some(b))
        );
    }

    /// The deadlock walk stops where Linux's `rt_mutex_adjust_prio_chain`
    /// does (kernel/locking/rtmutex.c:704 at v6.16). Linux checks the direct
    /// owner before the walk (`task_blocks_on_rt_mutex`), then the next owner
    /// at each of depths 1 to `max_lock_depth`, and answers `EDEADLK` when
    /// the owner it reached at depth 1024 is itself blocked. So a chain of
    /// 1025 owners whose last runs is no deadlock, and the same chain whose
    /// last owner waits on a 1026th is one, though nobody in it is the caller.
    #[test]
    fn the_pi_futex_deadlock_walk_stops_at_linuxs_lock_depth() {
        let mut scheduler = Scheduler::new(&Config::default());
        let caller = DetTid::from_raw(99);
        let owners: Vec<DetTid> = (1..=1026).map(|n| DetTid::from_raw(1000 + n)).collect();
        register_known_thread(&mut scheduler, caller);
        for &owner in &owners {
            register_known_thread(&mut scheduler, owner);
        }
        // Owner i waits on a word owner i + 1 holds, for owners 1 to 1024.
        for (i, pair) in owners.windows(2).take(1024).enumerate() {
            scheduler.sleep_pi_futex_waiter(
                pair[0],
                pi_futex(0x500000 + 4 * i),
                None,
                None,
                pair[1],
            );
        }
        assert!(!scheduler.pi_futex_wait_deadlocks(owners[0], caller));
        // Owner 1025 waits on a word owner 1026 holds.
        scheduler.sleep_pi_futex_waiter(owners[1024], pi_futex(0x600000), None, None, owners[1025]);
        assert!(scheduler.pi_futex_wait_deadlocks(owners[0], caller));
    }

    /// A thread whose own `Exit` was granted has not deregistered yet, which
    /// it does at a host-timed moment; a word naming it already names a dead
    /// owner, as Linux answers `ESRCH` once the exiting owner is gone
    /// (`handle_exit_race`).
    #[test]
    fn a_pi_futex_word_naming_a_thread_whose_exit_was_granted_names_a_dead_owner() {
        let mut scheduler = Scheduler::new(&Config::default());
        let [owner, caller] = [100, 101].map(DetTid::from_raw);
        for tid in [owner, caller] {
            register_known_thread(&mut scheduler, tid);
        }
        let futex = pi_futex(0x404110);
        assert_eq!(scheduler.pi_futex_state(futex, 100, caller), unqueued(true));
        scheduler.commit_own_exit(owner);
        assert!(scheduler.next_turns.contains_key(&owner));
        assert_eq!(
            scheduler.pi_futex_state(futex, 100, caller),
            unqueued(false)
        );
    }

    /// An owner's PI futexes go to their longest waiters at its own `Exit`
    /// grant, before it deregisters, and its later deregistration hands over
    /// nothing more.
    #[test]
    fn an_exit_grant_hands_the_exiting_owners_pi_futexes_to_their_waiters() {
        let mut scheduler = Scheduler::new(&Config::default());
        let owner = DetTid::from_raw(99);
        let detpid = DetPid::from_raw(99);
        let [first, second] = [100, 101].map(DetTid::from_raw);
        scheduler.thread_tree.add_child(owner, owner, true);
        for tid in [owner, first, second] {
            register_known_thread(&mut scheduler, tid);
        }
        let futex = pi_futex(0x404110);
        scheduler.sleep_pi_futex_waiter(first, futex, None, None, owner);
        scheduler.sleep_pi_futex_waiter(second, futex, None, None, owner);

        scheduler.commit_own_exit(owner);
        assert!(scheduler.admission_pending(first));
        assert!(scheduler.is_parked_futex_waiter(second));
        assert_eq!(
            scheduler.pi_futex_state(futex, 0, second),
            contended(first, Some(second))
        );

        scheduler.logically_kill_thread(&owner, &detpid, MmId::initial(detpid));
        assert!(scheduler.is_parked_futex_waiter(second));
        assert_eq!(
            scheduler.take_handed_pi_futex(futex, first),
            Some(PiHandOver::OwnerDeath)
        );
        assert_eq!(
            scheduler.pi_futex_state(futex, 100, second),
            contended(first, Some(second))
        );
    }

    /// Wake the parked `tid` for a signal, as the scheduler's signal paths do.
    fn wake_pi_waiter_for_a_signal(scheduler: &mut Scheduler, tid: DetTid) {
        let mut signal = Resources::new(tid);
        signal.insert(
            ResourceID::InboundSignal(SigWrapper(libc::SIGUSR1)),
            Permission::W,
        );
        assert!(scheduler.force_unblock_thread_at(tid, signal, true));
    }

    /// `tid`, woken, has run its turn and asks again.
    fn finish_woken_turn(scheduler: &mut Scheduler, tid: DetTid) {
        assert!(scheduler.run_queue.remove_tid(tid));
        let turn = scheduler.next_turns.get_mut(&tid).unwrap();
        turn.req = Ivar::new();
        turn.resp = Ivar::new();
    }

    /// A FUTEX_LOCK_PI waiter the scheduler woke for a signal stays queued in
    /// its place, as Linux's rt_mutex waiter does, and sleeps again there when
    /// it finds nothing pending. When its call ends (a restart after the
    /// signal), it leaves the queue, and the next call queues at the tail.
    #[test]
    fn a_pi_waiter_woken_for_a_signal_it_did_not_find_keeps_its_place() {
        let mut scheduler = Scheduler::new(&Config::default());
        let owner = DetTid::from_raw(99);
        let [a, b, c] = [100, 101, 102].map(DetTid::from_raw);
        for tid in [owner, a, b, c] {
            register_known_thread(&mut scheduler, tid);
        }
        let futex = pi_futex(0x404110);
        for tid in [a, b, c] {
            scheduler.sleep_pi_futex_waiter(tid, futex, None, None, owner);
        }

        wake_pi_waiter_for_a_signal(&mut scheduler, b);
        assert!(!scheduler.is_parked_futex_waiter(b));
        assert_eq!(scheduler.futex_waiters_for_test(futex), vec![a, b, c]);
        finish_woken_turn(&mut scheduler, b);
        scheduler.sleep_pi_futex_waiter(b, futex, None, None, owner);
        assert!(scheduler.is_parked_futex_waiter(b));
        assert_eq!(scheduler.futex_waiters_for_test(futex), vec![a, b, c]);

        wake_pi_waiter_for_a_signal(&mut scheduler, b);
        finish_woken_turn(&mut scheduler, b);
        scheduler.leave_pi_futex_queue(b);
        assert_eq!(scheduler.futex_waiters_for_test(futex), vec![a, c]);
        scheduler.sleep_pi_futex_waiter(b, futex, None, None, owner);
        assert_eq!(scheduler.futex_waiters_for_test(futex), vec![a, c, b]);
    }

    /// An unlock, or the owner's death, while the longest PI waiter is woken
    /// for a signal and has not yet run hands that waiter the lock, which it
    /// takes in its turn; it is already runnable, so nothing wakes it again.
    #[test]
    fn a_pi_waiter_woken_for_a_signal_is_still_handed_the_lock() {
        let mut scheduler = Scheduler::new(&Config::default());
        let owner = DetTid::from_raw(99);
        let detpid = DetPid::from_raw(99);
        let [a, b, c] = [100, 101, 102].map(DetTid::from_raw);
        scheduler.thread_tree.add_child(owner, owner, true);
        for tid in [owner, a, b, c] {
            register_known_thread(&mut scheduler, tid);
        }
        let [unlocked, abandoned] = [0x404110, 0x404120].map(pi_futex);
        scheduler.sleep_pi_futex_waiter(a, unlocked, None, None, owner);
        scheduler.sleep_pi_futex_waiter(b, unlocked, None, None, owner);
        scheduler.sleep_pi_futex_waiter(c, abandoned, None, None, owner);

        wake_pi_waiter_for_a_signal(&mut scheduler, a);
        assert_eq!(
            scheduler.pi_futex_state(unlocked, 99, owner),
            PiFutexState::Contended {
                owner,
                next_owner: Some(a),
                queueing_deadlocks: true,
            }
        );
        assert_eq!(scheduler.hand_off_pi_futex(unlocked), Some(a));
        assert_eq!(
            scheduler.take_handed_pi_futex(unlocked, a),
            Some(PiHandOver::Unlock)
        );
        assert_eq!(scheduler.futex_waiters_for_test(unlocked), vec![b]);
        assert!(scheduler.is_parked_futex_waiter(b));

        wake_pi_waiter_for_a_signal(&mut scheduler, c);
        scheduler.logically_kill_thread(&owner, &detpid, MmId::initial(detpid));
        assert!(!scheduler.admission_pending(c));
        assert_eq!(
            scheduler.take_handed_pi_futex(abandoned, c),
            Some(PiHandOver::OwnerDeath)
        );
    }

    /// A committed SIGKILL dooms its process's threads for PI futexes before
    /// they deregister, which comes at a host-timed moment: a word naming one
    /// names a dead owner, the futexes they own go to their waiters at the
    /// kill's commit, and a doomed waiter is passed over. A process-group
    /// kill's notice before its send dooms nothing.
    #[test]
    fn a_sigkilled_process_is_dead_to_pi_futexes_from_the_kill() {
        let mut scheduler = Scheduler::new(&Config::default());
        let [killed, doomed, live] = [90, 91, 92].map(DetTid::from_raw);
        let [waiter, other, caller] = [100, 101, 102].map(DetTid::from_raw);
        for process in [killed, doomed] {
            scheduler.thread_tree.add_child(process, process, true);
        }
        for tid in [killed, doomed, live, waiter, other, caller] {
            register_known_thread(&mut scheduler, tid);
        }
        let [held, unqueued_word, shared] = [0x404110, 0x404120, 0x404130].map(pi_futex);
        scheduler.sleep_pi_futex_waiter(waiter, held, None, None, killed);
        scheduler.sleep_pi_futex_waiter(doomed, shared, None, None, live);
        scheduler.sleep_pi_futex_waiter(other, shared, None, None, live);
        assert_eq!(
            scheduler.pi_futex_state(unqueued_word, 90, caller),
            unqueued(true)
        );

        // A process-group kill's notice comes before its send, while a victim
        // may still run and unlock: it dooms nothing for PI futexes.
        let group = DetPid::from_raw(77);
        assert!(
            scheduler
                .thread_tree
                .set_process_group(DetPid::from_raw(90), group)
        );
        scheduler.record_unresolved_sigkill(Some(group));
        assert!(scheduler.sigkill_recorded(DetPid::from_raw(90)).0);
        assert_eq!(
            scheduler.pi_futex_state(unqueued_word, 90, caller),
            unqueued(true)
        );
        assert!(!scheduler.admission_pending(waiter));

        scheduler.record_committed_sigkill(killed, Some(DetPid::from_raw(90)));
        assert!(scheduler.next_turns.contains_key(&killed));
        assert_eq!(
            scheduler.pi_futex_state(unqueued_word, 90, caller),
            unqueued(false)
        );
        assert!(scheduler.admission_pending(waiter));
        assert_eq!(
            scheduler.take_handed_pi_futex(held, waiter),
            Some(PiHandOver::OwnerDeath)
        );

        scheduler.record_committed_sigkill(doomed, Some(DetPid::from_raw(91)));
        assert_eq!(
            scheduler.pi_futex_state(shared, 92, caller),
            contended(live, Some(other))
        );
        assert_eq!(scheduler.hand_off_pi_futex(shared), Some(other));
    }

    /// A thread's retirement hands each PI futex it owns to that futex's longest
    /// waiter, admitted at the next drain and told the owner died, as Linux's
    /// `exit_pi_state_list` does; a futex whose waiters all left is dropped.
    #[test]
    fn a_retired_pi_futex_owner_hands_its_futexes_to_their_longest_waiters() {
        let mut scheduler = Scheduler::new(&Config::default());
        let owner = DetTid::from_raw(99);
        let detpid = DetPid::from_raw(99);
        let [first, second, other] = [100, 101, 102].map(DetTid::from_raw);
        scheduler.thread_tree.add_child(owner, owner, true);
        for tid in [owner, first, second, other] {
            register_known_thread(&mut scheduler, tid);
        }
        let [futex, other_futex, abandoned] = [0x404110, 0x404120, 0x404130].map(pi_futex);
        scheduler.sleep_pi_futex_waiter(first, futex, None, None, owner);
        scheduler.sleep_pi_futex_waiter(second, futex, None, None, owner);
        scheduler.sleep_pi_futex_waiter(other, other_futex, None, None, owner);
        // A record whose waiter has left (a timeout or a kill).
        scheduler.set_pi_futex_owner(abandoned, owner, None);

        scheduler.logically_kill_thread(&owner, &detpid, MmId::initial(detpid));

        for (tid, parked) in [(first, false), (second, true), (other, false)] {
            assert_eq!(scheduler.is_parked_futex_waiter(tid), parked, "{tid}");
            assert_eq!(scheduler.admission_pending(tid), !parked, "{tid}");
        }
        assert_eq!(
            scheduler.pi_futex_state(futex, 0, second),
            contended(first, Some(second))
        );
        assert_eq!(
            scheduler.pi_futex_state(other_futex, 99, second),
            contended(other, None)
        );
        assert!(!scheduler.blocked.pi_futex_owners.contains_key(&abandoned));
        assert_eq!(
            scheduler.take_handed_pi_futex(other_futex, other),
            Some(PiHandOver::OwnerDeath)
        );
        assert_eq!(
            scheduler.pi_futex_state(other_futex, 102, second),
            unqueued(true)
        );
    }

    /// A waiter handed the lock that dies before it takes it passes the lock on,
    /// as `exit_pi_state_list` releases a state the dying task owns.
    #[test]
    fn a_successor_killed_before_it_takes_the_lock_passes_it_on() {
        let mut scheduler = Scheduler::new(&Config::default());
        let owner = DetTid::from_raw(99);
        let [heir, next] = [100, 101].map(DetTid::from_raw);
        let detpid = DetPid::from_raw(100);
        scheduler.thread_tree.add_child(heir, heir, true);
        for tid in [owner, heir, next] {
            register_known_thread(&mut scheduler, tid);
        }
        let futex = pi_futex(0x404110);
        scheduler.sleep_pi_futex_waiter(heir, futex, None, None, owner);
        scheduler.sleep_pi_futex_waiter(next, futex, None, None, owner);
        assert_eq!(scheduler.hand_off_pi_futex(futex), Some(heir));

        scheduler.logically_kill_thread(&heir, &detpid, MmId::initial(detpid));

        assert!(!scheduler.is_parked_futex_waiter(next));
        assert!(scheduler.admission_pending(next));
        assert_eq!(
            scheduler.take_handed_pi_futex(futex, next),
            Some(PiHandOver::OwnerDeath)
        );
        assert_eq!(scheduler.take_handed_pi_futex(futex, heir), None);
    }

    /// Under `--futex-wake-yields` a waker that woke a waiter goes
    /// behind it, and behind every thread already queued, so its yield at the
    /// syscall's post-hook is granted only after their turns
    /// (https://github.com/rrnewton/hermit/issues/3874). By default the waker
    /// keeps its place ahead of the waiter it woke.
    #[test]
    fn a_futex_waker_is_requeued_behind_the_waiters_it_woke() {
        for requeue in [false, true] {
            let mut scheduler = Scheduler::new(&Config::default());
            let waiter = DetTid::from_raw(100);
            let waker = DetTid::from_raw(101);
            let runnable = DetTid::from_raw(102);
            for tid in [waiter, waker, runnable] {
                register_known_thread(&mut scheduler, tid);
            }
            scheduler.runqueue_push_back(waker);
            scheduler.runqueue_push_back(runnable);
            let futex = FutexID::private(MmId::initial(DetPid::from_raw(100)), 0x404110);
            scheduler.sleep_futex_waiter(&waiter, futex, None, u32::MAX, None);

            assert_eq!(scheduler.wake_futex_waiters(waker, futex, 1, u32::MAX), 1);
            if requeue {
                scheduler.requeue_futex_waker(waker);
            }
            let expected = if requeue {
                vec![runnable, waiter, waker]
            } else {
                vec![waker, runnable, waiter]
            };
            assert_eq!(
                scheduler.run_queue.tids().copied().collect::<Vec<_>>(),
                expected
            );
        }
    }

    /// A chaos scheduler with three threads in consecutive bands, the first
    /// two put into the yield epoch through real `SchedYield` turns.
    fn scheduler_with_two_yielders_in_the_epoch() -> (Scheduler, [DetTid; 3]) {
        let mut scheduler = Scheduler::new(&Config {
            chaos: true,
            ..Config::default()
        });
        let tids = [
            DetTid::from_raw(100),
            DetTid::from_raw(101),
            DetTid::from_raw(102),
        ];
        for (index, tid) in tids.into_iter().enumerate() {
            register_known_thread(&mut scheduler, tid);
            scheduler
                .priorities
                .insert(tid, runqueue::FIRST_PRIORITY + index as u64);
            scheduler.runqueue_push_back(tid);
        }
        for yielder in [tids[0], tids[1]] {
            for _ in 0..=runqueue::PLAIN_YIELDS_BEFORE_EPOCH {
                let mut request = Resources::new(yielder);
                request.insert(ResourceID::SchedYield, Permission::W);
                let next = scheduler.next_turns.get(&yielder).unwrap();
                next.req.put(Ok(request.clone()));
                let response = next.resp.clone();
                assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(yielder));
                assert!(
                    scheduler
                        .step4_resource_block(yielder, &request, &response)
                        .is_ok()
                );
                assert!(
                    scheduler
                        .step5_guest_unblock(yielder, &request, &response)
                        .is_ok()
                );
                assert!(matches!(response.try_read(), Some(SchedResponse::Go(_))));
                let requeue = scheduler.requeue_after(&request);
                assert_eq!(requeue, Requeue::YieldEpoch);
                scheduler.step6_reenquue(yielder, requeue);
            }
        }
        (scheduler, tids)
    }

    /// A poller's non-committing backoff grants no turn, so the yielders stay
    /// excluded and the poller, in a later band, is selected again. Written by
    /// the Codex reviewer of https://github.com/rrnewton/hermit/pull/4080
    /// (round 2), as are the next two tests.
    #[test]
    fn a_noncommitting_poll_backoff_keeps_the_yield_epoch() {
        let (mut scheduler, tids) = scheduler_with_two_yielders_in_the_epoch();
        let poller = tids[2];
        let mut request = Resources::new(poller);
        request.insert(ResourceID::InternalIOPolling, Permission::W);
        request.poll_attempt = 1;
        let next = scheduler.next_turns.get(&poller).unwrap();
        next.req.put(Ok(request.clone()));
        let response = next.resp.clone();
        let committed_time = scheduler.committed_time;
        assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(poller));
        assert!(
            scheduler
                .step4_resource_block(poller, &request, &response)
                .is_err()
        );
        assert!(
            response.try_read().is_none(),
            "NONCOMMIT cannot grant this retry"
        );
        assert_eq!(scheduler.committed_time, committed_time);
        assert_eq!(
            scheduler
                .next_turns
                .get(&poller)
                .unwrap()
                .req
                .try_read()
                .unwrap()
                .unwrap()
                .poll_attempt,
            0,
            "the real backoff path must remake its pending request as runnable"
        );
        assert_eq!(
            scheduler.run_queue.queued_priority(poller),
            Some(2 * (runqueue::FIRST_PRIORITY + 2))
        );
        assert_eq!(
            scheduler.run_queue.tentative_pop_next(),
            Some(poller),
            "poll bookkeeping grants no non-yield turn, so the earlier yielders must remain excluded"
        );
    }

    /// A completed guest turn of a thread that did not yield ends the epoch.
    #[test]
    fn a_completed_non_yield_turn_ends_the_yield_epoch() {
        let (mut scheduler, tids) = scheduler_with_two_yielders_in_the_epoch();
        let worker = tids[2];
        let request = Resources::new(worker);
        let next = scheduler.next_turns.get(&worker).unwrap();
        next.req.put(Ok(request.clone()));
        let response = next.resp.clone();
        assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(worker));
        assert!(
            scheduler
                .step4_resource_block(worker, &request, &response)
                .is_ok()
        );
        assert!(
            scheduler
                .step5_guest_unblock(worker, &request, &response)
                .is_ok()
        );
        assert!(matches!(response.try_read(), Some(SchedResponse::Go(_))));
        let requeue = scheduler.requeue_after(&request);
        assert_eq!(requeue, Requeue::Back);
        scheduler.step6_reenquue(worker, requeue);
        assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(tids[0]));
    }

    /// When the last thread outside the epoch yields too, the epoch covers the
    /// queue and ends, and the bands decide again.
    #[test]
    fn the_last_thread_outside_yielding_ends_the_yield_epoch() {
        let (mut scheduler, tids) = scheduler_with_two_yielders_in_the_epoch();
        let last = tids[2];
        // Its plain yield, then the one that joins the epoch and covers it.
        for _ in 0..=runqueue::PLAIN_YIELDS_BEFORE_EPOCH {
            let mut request = Resources::new(last);
            request.insert(ResourceID::SchedYield, Permission::W);
            let next = scheduler.next_turns.get(&last).unwrap();
            next.req.put(Ok(request.clone()));
            let response = next.resp.clone();
            assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(last));
            assert!(
                scheduler
                    .step4_resource_block(last, &request, &response)
                    .is_ok()
            );
            assert!(
                scheduler
                    .step5_guest_unblock(last, &request, &response)
                    .is_ok()
            );
            assert!(matches!(response.try_read(), Some(SchedResponse::Go(_))));
            let requeue = scheduler.requeue_after(&request);
            assert_eq!(requeue, Requeue::YieldEpoch);
            scheduler.step6_reenquue(last, requeue);
        }
        assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(tids[0]));
    }

    /// A replay that lets go of its schedule drops each thread's recorded
    /// callback checkpoints with it, at the reply that tells the thread so
    /// (`Scheduler::schedule_replay_reply`), when the thread drops its own
    /// copy: another thread's copy stays until its own reply. The run summary
    /// records the release and what it dropped.
    #[test]
    fn a_released_schedule_drops_its_callback_checkpoints() {
        use crate::preemptions::callback_history::Checkpoint;
        use crate::preemptions::callback_history::Origin;
        use crate::preemptions::callback_history::Site;
        use crate::slice_boundary::callbacks::Callback;
        let thread = DetTid::from_raw(3);
        let event = |rip: usize| SchedEvent {
            dettid: thread,
            op: detcore_model::schedule::Op::OtherInstructions,
            count: 1,
            start_rip: None,
            end_rip: std::num::NonZeroUsize::new(rip),
            end_time: Some(LogicalTime::from_nanos(0)),
            stopless: false,
        };
        let directory = tempfile::tempdir().unwrap();
        let schedule = directory.path().join("schedule.json");
        let recorded = vec![event(100), event(100)];
        std::fs::write(
            &schedule,
            serde_json::json!({ "per_thread": {}, "global": recorded }).to_string(),
        )
        .unwrap();
        let mut scheduler = Scheduler::new(&Config {
            replay_schedule_from: Some(schedule),
            ..Config::default()
        });
        let origin = Origin {
            callback: Callback::PmuTimer,
            site: Site::Prehook,
            progress: 1,
            last_op: None,
            time: LogicalTime::from_nanos(0),
            rcbs: 0,
        };
        let other = DetTid::from_raw(4);
        for tid in [thread, other] {
            scheduler.callback_checkpoints.insert(
                tid,
                [Checkpoint {
                    history_index: 0,
                    origin: origin.clone(),
                }]
                .into(),
            );
        }
        for _ in 1..replayer::UNMATCHED_EVENTS_BEFORE_RELEASE {
            assert!(scheduler.consume_schedevent(&event(200)).keep_running);
        }
        assert_eq!(scheduler.schedule_replay_reply(thread), (false, false));
        assert!(scheduler.callback_checkpoints[&thread].len() == 1);
        assert!(scheduler.consume_schedevent(&event(200)).keep_running);
        assert!(scheduler.schedule_released());
        assert!(scheduler.callback_checkpoints[&thread].len() == 1);
        assert_eq!(scheduler.schedule_replay_reply(thread), (true, true));
        assert!(scheduler.callback_checkpoints[&thread].is_empty());
        assert!(scheduler.callback_checkpoints[&other].len() == 1);
        let text = scheduler
            .generate_partial_run_summary(None)
            .unwrap()
            .desync_descrip
            .unwrap();
        assert!(
            text.contains(&format!(
                "RELEASED replayed schedule at event #{}: {} observed events in a row matched none \
                 of it (events are numbered, and unmatched ones counted, without polling \
                 retries); 2 recorded events left unreplayed; callback checkpoints dropped with \
                 it: dtid 3: 1\n",
                replayer::UNMATCHED_EVENTS_BEFORE_RELEASE - 1,
                replayer::UNMATCHED_EVENTS_BEFORE_RELEASE,
            )),
            "{text}"
        );
        // The thread that has not heard of the release still holds its
        // checkpoint, and the summary names it as unconsumed.
        assert!(
            text.contains("DESYNC incomplete callback history for 4: 1 unconsumed"),
            "{text}"
        );
    }

    /// A `SchedYield` turn opens or joins a yield epoch only under `--chaos`,
    /// and only when it is a `sched_yield`: the zero-timeout loopback poll's
    /// yield, whose count is host-timed, keeps the one-turn exclusion
    /// (https://github.com/rrnewton/hermit/issues/4068).
    #[test]
    fn only_a_chaos_sched_yield_opens_a_yield_epoch() {
        let tid = DetTid::from_raw(100);
        let mut sched_yield = Resources::new(tid);
        sched_yield.insert(ResourceID::SchedYield, Permission::W);
        let mut loopback = sched_yield.clone();
        loopback.fyi(LOOPBACK_POLL_YIELD_FYI);
        let other = Resources::new(tid);
        for chaos in [false, true] {
            let scheduler = Scheduler::new(&Config {
                chaos,
                ..Config::default()
            });
            let expected = if chaos {
                Requeue::YieldEpoch
            } else {
                Requeue::OneTurnYield
            };
            assert_eq!(scheduler.requeue_after(&sched_yield), expected);
            assert_eq!(scheduler.requeue_after(&loopback), Requeue::OneTurnYield);
            assert_eq!(scheduler.requeue_after(&other), Requeue::Back);
        }
    }

    /// Through `step6_reenquue`, two chaos `sched_yield` callers cannot take
    /// turns ahead of a thread in a later band, and both keep their persistent
    /// priorities. Without chaos the one-turn exclusion lets the first yielder
    /// run again after the second.
    #[test]
    fn two_chaos_yielders_cannot_shut_out_a_thread_in_a_later_band() {
        for chaos in [false, true] {
            let mut scheduler = Scheduler::new(&Config {
                chaos,
                ..Config::default()
            });
            let first = DetTid::from_raw(100);
            let second = DetTid::from_raw(101);
            let awaited = DetTid::from_raw(102);
            for tid in [first, second, awaited] {
                register_known_thread(&mut scheduler, tid);
            }
            scheduler.priorities.insert(first, runqueue::FIRST_PRIORITY);
            scheduler
                .priorities
                .insert(second, runqueue::FIRST_PRIORITY + 1);
            scheduler
                .priorities
                .insert(awaited, runqueue::LAST_PRIORITY);
            for tid in [first, second, awaited] {
                scheduler.runqueue_push_back(tid);
            }
            // Under chaos each yielder's first yield is a plain one; its second
            // joins the epoch.
            let yields_each = if chaos {
                runqueue::PLAIN_YIELDS_BEFORE_EPOCH + 1
            } else {
                1
            };
            for yielder in [first, second] {
                let mut request = Resources::new(yielder);
                request.insert(ResourceID::SchedYield, Permission::W);
                let requeue = scheduler.requeue_after(&request);
                for _ in 0..yields_each {
                    assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(yielder));
                    scheduler.step6_reenquue(yielder, requeue);
                }
            }
            let expected = if chaos { awaited } else { first };
            assert_eq!(
                scheduler.run_queue.tentative_pop_next(),
                Some(expected),
                "chaos={chaos}"
            );
            assert_eq!(scheduler.get_priority(first), runqueue::FIRST_PRIORITY);
            assert_eq!(scheduler.get_priority(second), runqueue::FIRST_PRIORITY + 1);
        }
    }

    /// Put `yielder` into a yield epoch through `step6_reenquue`, with the
    /// chaos `sched_yield` turns that take it there: its plain yields, then
    /// the one that joins.
    fn chaos_yield_turn(scheduler: &mut Scheduler, yielder: DetTid) {
        let mut request = Resources::new(yielder);
        request.insert(ResourceID::SchedYield, Permission::W);
        let requeue = scheduler.requeue_after(&request);
        assert_eq!(requeue, Requeue::YieldEpoch);
        for _ in 0..=runqueue::PLAIN_YIELDS_BEFORE_EPOCH {
            assert_eq!(
                scheduler.run_queue.tentative_pop_tid(yielder),
                Some(yielder)
            );
            scheduler.step6_reenquue(yielder, requeue);
        }
    }

    /// A panic in the scheduler task reaches `on_panic` (which ends the
    /// process in production, `exit_on_scheduler_panic`) instead of being
    /// left to the task harness; a scheduler that returns does not.
    #[tokio::test]
    async fn a_scheduler_task_panic_reaches_its_handler() {
        let called = std::cell::Cell::new(false);
        run_or_on_panic(async { panic!("scheduler control") }, |_| called.set(true)).await;
        assert!(called.get());

        let called = std::cell::Cell::new(false);
        run_or_on_panic(async {}, |_| called.set(true)).await;
        assert!(!called.get());
    }

    /// A scheduler panic exits, except while a backend failure is being
    /// cleaned up: then it carries on unwinding, so the task's `JoinError`
    /// reaches that cleanup and the backend's failure stays the primary one.
    #[test]
    fn a_scheduler_panic_during_backend_failure_cleanup_still_unwinds() {
        let exited = std::cell::Cell::new(false);
        on_scheduler_panic(Box::new("scheduler control"), false, || exited.set(true));
        assert!(exited.get());

        let exited = std::cell::Cell::new(false);
        let unwound = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            on_scheduler_panic(Box::new("scheduler control"), true, || exited.set(true))
        }));
        assert!(!exited.get());
        assert_eq!(
            unwound.unwrap_err().downcast_ref::<&str>(),
            Some(&"scheduler control")
        );
    }

    /// A priority change point is a turn of a thread that did not yield, so,
    /// through the scheduler's own change-point path, it ends the yield epoch:
    /// the yielder in the first band runs next, not the third thread.
    #[test]
    fn a_priority_change_point_ends_the_yield_epoch() {
        let mut scheduler = Scheduler::new(&Config {
            chaos: true,
            ..Config::default()
        });
        let yielder = DetTid::from_raw(100);
        let preempted = DetTid::from_raw(101);
        let third = DetTid::from_raw(102);
        for tid in [yielder, preempted, third] {
            register_known_thread(&mut scheduler, tid);
        }
        scheduler
            .priorities
            .insert(yielder, runqueue::FIRST_PRIORITY);
        scheduler.priorities.insert(third, runqueue::LAST_PRIORITY);
        for tid in [yielder, preempted, third] {
            scheduler.runqueue_push_back(tid);
        }
        chaos_yield_turn(&mut scheduler, yielder);

        assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(preempted));
        // A change point never commits the turn: it always reports a skip.
        assert!(
            scheduler
                .perform_priority_changepoint(
                    preempted,
                    DEFAULT_PRIORITY,
                    LogicalTime::from_nanos(1),
                    1,
                    &[]
                )
                .is_err()
        );
        assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(yielder));
    }

    /// A chaos change point never commits; the empty request it leaves in its
    /// place commits the thread's next turn, which is the one charged for
    /// the preemption. So that request keeps the change point's slice-expiry
    /// mark (`--cap-preemption-charge`), and a change point of an explicit
    /// `sched_yield`, which has none, leaves none.
    #[test]
    fn a_change_point_hands_its_slice_expiry_to_the_request_it_leaves() {
        for expired in [true, false] {
            let (mut scheduler, spinner, _) = chaos_spinner_and_waiter(
                Config {
                    chaos: true,
                    ..Config::default()
                },
                DEFAULT_PRIORITY,
                DEFAULT_PRIORITY,
            );
            let mut request = Resources::new(spinner);
            request.insert(
                ResourceID::PriorityChangePoint(
                    DEFAULT_PRIORITY,
                    LogicalTime::from_nanos(1),
                    1,
                    Vec::new(),
                ),
                Permission::W,
            );
            request.slice_expired = expired;
            scheduler.next_turns[&spinner].req.put(Ok(request));
            spinner_changepoint(&mut scheduler, spinner, DEFAULT_PRIORITY, 1);
            let left = scheduler.next_turns[&spinner]
                .req
                .try_read()
                .unwrap()
                .unwrap();
            assert!(left.resources.is_empty());
            assert_eq!(left.slice_expired, expired);
        }
    }

    /// Two change points of one thread at one instant, as a diverged
    /// preemption replay files them when a slice closes at the instant the
    /// last one did (https://github.com/rrnewton/hermit/issues/4830, and an Android replay whose
    /// timeout cleanup tripped `&time > last` on its stalled second one).
    /// The scheduler and the re-recording writer, on a run that replays a
    /// preemption record and records a new one.
    fn replaying_and_recording_spinner(replays: bool) -> (Scheduler, DetTid) {
        let cfg = Config {
            chaos: true,
            record_preemptions: true,
            replay_preemptions_from: replays.then(|| PathBuf::from("history.json")),
            ..Config::default()
        };
        let (mut scheduler, spinner, _waiter) =
            chaos_spinner_and_waiter(cfg, DEFAULT_PRIORITY, DEFAULT_PRIORITY);
        scheduler
            .preemption_writer
            .as_mut()
            .unwrap()
            .register_thread(spinner, DEFAULT_PRIORITY);
        (scheduler, spinner)
    }

    #[test]
    fn scheduler_departures_keep_the_first_coordinate_and_refuse_count_overflow() {
        use crate::tool_global::replay_departure::Refusal;
        let (mut scheduler, spinner) = replaying_and_recording_spinner(true);
        spinner_changepoint(&mut scheduler, spinner, DEFAULT_PRIORITY + 1, 500);
        assert_eq!(scheduler.replay_departure(), None);
        let event = scheduler.recorded_event_count;
        spinner_changepoint(&mut scheduler, spinner, DEFAULT_PRIORITY + 2, 500);
        let first = scheduler.replay_departure().cloned().unwrap();
        assert_eq!(first.count, 1);
        assert_eq!(
            first.first.source,
            detcore_model::replay_departure::Source::SchedulerChangePoint
        );
        assert_eq!(first.first.thread, spinner);
        assert_eq!(first.first.slice, None);
        assert_eq!(first.first.observed, LogicalTime::from_nanos(500));
        assert_eq!(first.first.previous, LogicalTime::from_nanos(500));
        assert_eq!(first.first.recorded_event_count, Some(event));
        spinner_changepoint(&mut scheduler, spinner, DEFAULT_PRIORITY + 3, 499);
        assert_eq!(scheduler.replay_departure().unwrap().count, 2);
        assert_eq!(scheduler.replay_departure().unwrap().first, first.first);
        // Only the count is staged at its finite bound; the actual admission
        // must refuse before changing the first finding, writer or scheduler.
        scheduler.replay_departure.as_mut().unwrap().count = u64::MAX;
        let before = format!("{scheduler:?}");
        assert_eq!(
            scheduler.note_replay_departure(
                detcore_model::replay_departure::Source::SchedulerChangePoint,
                spinner,
                LogicalTime::from_nanos(500),
                LogicalTime::from_nanos(499),
                None,
            ),
            Err(Refusal::CountOverflow)
        );
        assert_eq!(format!("{scheduler:?}"), before);
    }

    /// In a replay, the second is a replay divergence: reported as a skid
    /// overshoot (the run ends in that refusal, exit 122) and kept out of the
    /// new record, which stays strictly increasing, instead of the writer's
    /// assertion. The thread's priority still changes.
    #[test]
    fn a_replay_change_point_at_the_last_ones_instant_is_an_overshoot() {
        let (mut scheduler, spinner) = replaying_and_recording_spinner(true);

        spinner_changepoint(&mut scheduler, spinner, DEFAULT_PRIORITY + 1, 500);
        // Reported through `report_stale_replay_change_point`; the
        // process-wide overshoot count is not asserted here, since tests
        // running beside this one take it too.
        spinner_changepoint(&mut scheduler, spinner, DEFAULT_PRIORITY + 2, 500);

        let writer = scheduler.preemption_writer.as_ref().unwrap();
        assert_eq!(writer.reprioritization_count(spinner), 1);
        assert_eq!(
            writer.last_reprioritization_time(spinner),
            Some(LogicalTime::from_nanos(500))
        );
        assert_eq!(scheduler.priorities[&spinner], DEFAULT_PRIORITY + 2);
        // A later one is recorded after it as usual.
        spinner_changepoint(&mut scheduler, spinner, DEFAULT_PRIORITY + 3, 600);
        assert_eq!(
            scheduler
                .preemption_writer
                .as_ref()
                .unwrap()
                .reprioritization_count(spinner),
            2
        );
    }

    /// In a replay of an edited record (`--replay-edited-preemptions`),
    /// change points need not advance: the record keeps a slice whose RCB
    /// target is the thread's count and ends it at once. The second change
    /// point at one instant is no departure and is not reported, and it is
    /// still left out of the new record, whose writer asserts increasing
    /// rows. The thread's priority still changes.
    #[test]
    fn an_edited_replay_change_point_at_the_last_ones_instant_is_left_out() {
        let cfg = Config {
            chaos: true,
            record_preemptions: true,
            replay_preemptions_from: Some(PathBuf::from("history.json")),
            replay_edited_preemptions: true,
            ..Config::default()
        };
        let (mut scheduler, spinner, _waiter) =
            chaos_spinner_and_waiter(cfg, DEFAULT_PRIORITY, DEFAULT_PRIORITY);
        scheduler
            .preemption_writer
            .as_mut()
            .unwrap()
            .register_thread(spinner, DEFAULT_PRIORITY);
        assert!(scheduler.replays_edited_preemptions);
        let reports = || STALE_CHANGE_POINT_REPORTS.with(std::cell::Cell::get);
        let before = reports();

        spinner_changepoint(&mut scheduler, spinner, DEFAULT_PRIORITY + 1, 500);
        spinner_changepoint(&mut scheduler, spinner, DEFAULT_PRIORITY + 2, 500);

        assert_eq!(reports(), before);
        let writer = scheduler.preemption_writer.as_ref().unwrap();
        assert_eq!(writer.reprioritization_count(spinner), 1);
        assert_eq!(scheduler.priorities[&spinner], DEFAULT_PRIORITY + 2);
        // The record says it left a change point out (`replay_departed_at`):
        // it is not an exact record of the run.
        let event = scheduler.recorded_event_count;
        let written = scheduler.preemption_writer.take().unwrap().into_string();
        let record: crate::preemptions::PreemptionRecord = serde_json::from_str(&written).unwrap();
        assert_eq!(record.replay_departed_at(), Some(event));
        // The same in a faithful replay is reported, and marks its record too.
        let (mut faithful, spinner) = replaying_and_recording_spinner(true);
        spinner_changepoint(&mut faithful, spinner, DEFAULT_PRIORITY + 1, 500);
        spinner_changepoint(&mut faithful, spinner, DEFAULT_PRIORITY + 2, 500);
        assert_eq!(reports(), before + 1);
        let written = faithful.preemption_writer.take().unwrap().into_string();
        let record: crate::preemptions::PreemptionRecord = serde_json::from_str(&written).unwrap();
        assert!(record.replay_departed_at().is_some());
        // Only a replay's record can be edited.
        let (scheduler, _) = replaying_and_recording_spinner(false);
        assert!(!scheduler.replays_edited_preemptions);
    }

    /// A stale change point that carries a slowdown-epoch transition writes
    /// neither: the writer's epoch assertions (strictly later time and
    /// epoch) would otherwise fire on it first.
    #[test]
    fn a_replay_change_point_at_the_last_ones_instant_writes_no_epoch() {
        let (mut scheduler, spinner) = replaying_and_recording_spinner(true);
        let epoch = |epoch, at| crate::resources::ChaosEpochTransition {
            logical_time: LogicalTime::from_nanos(at),
            epoch,
            factor: crate::types::RcbTimeMultiplier::ONE,
        };
        assert_eq!(
            scheduler.run_queue.tentative_pop_tid(spinner),
            Some(spinner)
        );
        let _ = scheduler.perform_priority_changepoint(
            spinner,
            DEFAULT_PRIORITY + 1,
            LogicalTime::from_nanos(500),
            500,
            &[epoch(1, 500)],
        );
        assert_eq!(
            scheduler.run_queue.tentative_pop_tid(spinner),
            Some(spinner)
        );
        let _ = scheduler.perform_priority_changepoint(
            spinner,
            DEFAULT_PRIORITY + 2,
            LogicalTime::from_nanos(500),
            500,
            &[epoch(1, 500)],
        );
        let writer = scheduler.preemption_writer.as_ref().unwrap();
        assert_eq!(writer.reprioritization_count(spinner), 1);
    }

    /// A recording that is not a replay keeps the writer's assertion: there
    /// the scheduler itself would have filed the two.
    #[test]
    #[should_panic(expected = "&time > last")]
    fn a_recording_change_point_at_the_last_ones_instant_still_asserts() {
        let (mut scheduler, spinner) = replaying_and_recording_spinner(false);
        spinner_changepoint(&mut scheduler, spinner, DEFAULT_PRIORITY + 1, 500);
        spinner_changepoint(&mut scheduler, spinner, DEFAULT_PRIORITY + 2, 500);
    }

    /// Two threads, spinner and waiter, at the given priorities, both queued,
    /// on a chaos scheduler.
    fn chaos_spinner_and_waiter(
        cfg: Config,
        spinner_priority: Priority,
        waiter_priority: Priority,
    ) -> (Scheduler, DetTid, DetTid) {
        let mut scheduler = Scheduler::new(&cfg);
        let spinner = DetTid::from_raw(100);
        let waiter = DetTid::from_raw(101);
        for tid in [spinner, waiter] {
            register_known_thread(&mut scheduler, tid);
        }
        scheduler.priorities.insert(spinner, spinner_priority);
        scheduler.priorities.insert(waiter, waiter_priority);
        scheduler.runqueue_push_back(spinner);
        scheduler.runqueue_push_back(waiter);
        (scheduler, spinner, waiter)
    }

    /// The spinner's change point, through the scheduler's own path, with
    /// `drawn` as its new random priority.
    fn spinner_changepoint(scheduler: &mut Scheduler, spinner: DetTid, drawn: Priority, at: u64) {
        assert_eq!(
            scheduler.run_queue.tentative_pop_tid(spinner),
            Some(spinner)
        );
        assert!(
            scheduler
                .perform_priority_changepoint(spinner, drawn, LogicalTime::from_nanos(at), at, &[])
                .is_err()
        );
    }

    /// One committed turn of `tid`, through steps 4 to 6: it must be the next
    /// thread, and it is requeued at the back of its band.
    fn commit_a_turn(scheduler: &mut Scheduler, tid: DetTid) {
        let request = Resources::new(tid);
        let next = scheduler.next_turns.get(&tid).unwrap();
        next.req.put(Ok(request.clone()));
        let response = next.resp.clone();
        assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(tid));
        assert!(
            scheduler
                .step4_resource_block(tid, &request, &response)
                .is_ok()
        );
        assert!(
            scheduler
                .step5_guest_unblock(tid, &request, &response)
                .is_ok()
        );
        let requeue = scheduler.requeue_after(&request);
        scheduler.step6_reenquue(tid, requeue);
    }

    /// Under chaos, a thread that never blocks redraws its priority at each
    /// slice end, but a thread that never runs never redraws. A new thread
    /// with a poor draw (9820 here) waited behind a busy-wait until the spinner
    /// drew worse still (https://github.com/rrnewton/hermit/issues/4374). Now a
    /// thread passed over at `CHAOS_PASSOVER_BOUND` slice ends moves ahead:
    /// the spinner takes the priority one below it, so it keeps the lead for
    /// every turn it takes, not only the first.
    #[test]
    fn a_chaos_change_point_yields_to_a_thread_it_keeps_passing_over() {
        let (mut scheduler, spinner, waiter) = chaos_spinner_and_waiter(
            Config {
                chaos: true,
                ..Config::default()
            },
            500,
            9820,
        );
        assert_eq!(CHAOS_PASSOVER_BOUND, 2);
        let next = |scheduler: &mut Scheduler| {
            let next = scheduler.run_queue.tentative_pop_next();
            scheduler.run_queue.undo_tentative_pop();
            next
        };
        assert_eq!(next(&mut scheduler), Some(spinner));
        // The first pass: the spinner keeps its draw and runs again.
        spinner_changepoint(&mut scheduler, spinner, 136, 1);
        assert_eq!(scheduler.priorities[&spinner], 136);
        assert_eq!(scheduler.chaos_passed_over.get(&waiter), Some(&1));
        assert_eq!(next(&mut scheduler), Some(spinner));
        // The second: it takes the priority one below the waiter's, not 7043.
        spinner_changepoint(&mut scheduler, spinner, 7043, 2);
        assert_eq!(scheduler.priorities[&spinner], 9821);
        // The waiter runs, and keeps running ahead of the spinner turn after
        // turn; its count restarted at its first committed turn.
        for _ in 0..3 {
            commit_a_turn(&mut scheduler, waiter);
            assert!(!scheduler.chaos_passed_over.contains_key(&waiter));
        }
        assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(waiter));
        scheduler.run_queue.undo_tentative_pop();
        // A thread whose blocking entries are removed leaves no count behind.
        scheduler.chaos_passed_over.insert(waiter, 1);
        scheduler.remove_blocking_entries(&waiter);
        assert!(!scheduler.chaos_passed_over.contains_key(&waiter));
    }

    /// A waiter at the last priority has no band below it: the spinner shares
    /// it and is requeued behind it.
    #[test]
    fn a_chaos_change_point_behind_a_last_priority_thread_shares_its_band() {
        let (mut scheduler, spinner, waiter) = chaos_spinner_and_waiter(
            Config {
                chaos: true,
                ..Config::default()
            },
            500,
            runqueue::LAST_PRIORITY,
        );
        spinner_changepoint(&mut scheduler, spinner, 136, 1);
        spinner_changepoint(&mut scheduler, spinner, 7043, 2);
        assert_eq!(scheduler.priorities[&spinner], runqueue::LAST_PRIORITY);
        assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(waiter));
    }

    /// While a schedule replay dictates the turns, the chaos bounds are off;
    /// past the end of its schedule (`schedule_replay_dictates_turns`), where
    /// the run draws chaos priorities at its slice ends as a run without a
    /// schedule does, they apply as in that run: the bound on a new thread's
    /// first turn (`chaos_first_turn_overdue`), the turn count that ends a
    /// chaos slice (`chaos_slice_spent_in_turns`) and the starvation bound at
    /// change points (`bound_chaos_starvation`). Before, all three stayed off
    /// for the whole of a schedule replay, its unguided rest included.
    #[test]
    fn the_chaos_bounds_apply_past_the_end_of_a_replayed_schedule() {
        let chaos = Config {
            chaos: true,
            ..Config::default()
        };
        let schedule = vec![SchedEvent::syscall(
            DetTid::from_raw(100),
            Sysno::getpid,
            SyscallPhase::Prehook,
        )];
        for over in [false, true] {
            let replaying = |scheduler: &mut Scheduler| {
                scheduler.replayer = Some(Replayer::new(schedule.clone()));
                scheduler.replay_priorities_released = over;
                assert_eq!(scheduler.schedule_replay_dictates_turns(), !over);
            };

            // A new thread (the waiter, which has not run) loses 400 grants
            // to the spinner on priority.
            let (mut scheduler, spinner, waiter) =
                chaos_spinner_and_waiter(chaos.clone(), 500, 9820);
            replaying(&mut scheduler);
            scheduler.chaos_had_turn.insert(spinner);
            for _ in 0..400 {
                scheduler.note_chaos_first_turn_waits(spinner);
            }
            assert_eq!(
                scheduler.chaos_first_turn_overdue(),
                over,
                "schedule over: {over}; first-turn waits {:?}",
                scheduler.chaos_first_turn_waits
            );
            assert!(!scheduler.chaos_had_turn.contains(&waiter));

            // The spinner has taken a chaos slice's worth of turns.
            let turns = scheduler.chaos_turns_per_slice.unwrap();
            scheduler.chaos_turns_in_slice.insert(spinner, turns);
            assert_eq!(scheduler.chaos_slice_spent_in_turns(spinner), over);
            assert_eq!(
                scheduler.grant_deadline_hint(spinner) == Some(Duration::ZERO),
                over,
                "schedule over: {over}"
            );

            // Two change points pass the waiter over: past the end, the
            // second puts the spinner one band behind it.
            let (mut scheduler, spinner, _waiter) =
                chaos_spinner_and_waiter(chaos.clone(), 500, 9820);
            replaying(&mut scheduler);
            spinner_changepoint(&mut scheduler, spinner, 136, 1);
            spinner_changepoint(&mut scheduler, spinner, 7043, 2);
            assert_eq!(
                scheduler.priorities[&spinner],
                if over { 9821 } else { 7043 },
                "schedule over: {over}"
            );
        }
    }

    /// A poller whose normal priority is the last band is counted by the
    /// bound once a poll upgrade has reached it, like every upgraded poller,
    /// although the upgrade cannot move it: after two passes the spinner
    /// shares its band, behind it, so its retry runs next. While it is backed
    /// off, change points keep their draws. Before, such a poller was never
    /// counted, so threads at better priorities kept it from its retry
    /// forever; in `tests/c/chaos_poller_beside_sleepers.c` two sleepers did,
    /// and it never saw the pipe write it polled for.
    #[test]
    fn a_chaos_change_point_yields_to_an_upgraded_last_band_poller() {
        let (mut scheduler, spinner, waiter) = chaos_spinner_and_waiter(
            Config {
                chaos: true,
                ..Config::default()
            },
            500,
            runqueue::LAST_PRIORITY,
        );
        assert!(scheduler.run_queue.remove_tid(waiter));
        scheduler
            .run_queue
            .push_poller(waiter, runqueue::LAST_PRIORITY, 5);
        spinner_changepoint(&mut scheduler, spinner, 136, 1);
        spinner_changepoint(&mut scheduler, spinner, 7043, 2);
        assert_eq!(scheduler.priorities[&spinner], 7043, "backed off");
        assert!(scheduler.chaos_passed_over.is_empty());

        scheduler.run_queue.poll_upgrade_now();
        spinner_changepoint(&mut scheduler, spinner, 136, 3);
        assert_eq!(scheduler.priorities[&spinner], 136);
        assert_eq!(scheduler.chaos_passed_over.get(&waiter), Some(&1));
        spinner_changepoint(&mut scheduler, spinner, 4756, 4);
        assert_eq!(scheduler.priorities[&spinner], runqueue::LAST_PRIORITY);
        assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(waiter));
    }

    /// The bound counts only a thread the new priority still beats, and only
    /// where every change point is a random draw at a timer slice end: under
    /// chaos with timer preemption and the default heuristic. Without timer
    /// preemption (a chaos `sched_yield` is then a change point), under
    /// `connectbind` (which sets chosen priorities), a preemption replay, a raw
    /// schedule replay or a random heuristic, and for a polling waiter, every
    /// change point keeps its draw.
    #[test]
    fn a_chaos_change_point_bounds_only_timer_slices_on_the_default_queue() {
        let chaos = || Config {
            chaos: true,
            ..Config::default()
        };
        assert!(chaos().max_timeslice.is_some());
        // A waiter the spinner's draws never beat is never counted.
        let (mut scheduler, spinner, waiter) = chaos_spinner_and_waiter(chaos(), 500, 9820);
        for (at, drawn) in [(1, 9900), (2, 9950), (3, 9990)] {
            spinner_changepoint(&mut scheduler, spinner, drawn, at);
            assert_eq!(scheduler.priorities[&spinner], drawn);
            assert!(!scheduler.chaos_passed_over.contains_key(&waiter));
            scheduler.priorities.insert(spinner, 500);
            assert!(scheduler.run_queue.remove_tid(spinner));
            scheduler.runqueue_push_back(spinner);
        }

        let unbounded = |name: &str, cfg: Config, setup: &dyn Fn(&mut Scheduler)| {
            let (mut scheduler, spinner, _waiter) = chaos_spinner_and_waiter(cfg, 500, 9820);
            setup(&mut scheduler);
            for (at, drawn) in [(1, 136), (2, 7043), (3, 4756)] {
                spinner_changepoint(&mut scheduler, spinner, drawn, at);
                assert_eq!(scheduler.priorities[&spinner], drawn, "{name}");
            }
            assert!(scheduler.chaos_passed_over.is_empty(), "{name}");
        };
        unbounded(
            "no timer preemption",
            Config {
                max_timeslice: None,
                ..chaos()
            },
            &|_| {},
        );
        unbounded(
            "connectbind",
            Config {
                sched_heuristic: crate::config::SchedHeuristic::ConnectBind,
                ..chaos()
            },
            &|_| {},
        );
        unbounded(
            "random heuristic",
            Config {
                sched_heuristic: crate::config::SchedHeuristic::Random,
                ..chaos()
            },
            &|_| {},
        );
        unbounded(
            "preemption replay",
            Config {
                replay_preemptions_from: Some(PathBuf::from("/nonexistent/preemptions.json")),
                ..chaos()
            },
            &|_| {},
        );
        unbounded("schedule replay", chaos(), &|scheduler| {
            scheduler.replayer = Some(replayer::Replayer::new(Vec::new()));
        });
        unbounded("polling waiter", chaos(), &|scheduler| {
            let waiter = DetTid::from_raw(101);
            assert!(scheduler.run_queue.remove_tid(waiter));
            scheduler.run_queue.push_poller(waiter, 9820, u32::MAX);
        });
    }

    /// A background grant (here `BlockingExternalIO`) is a turn of a thread
    /// that did not yield, so it ends the yield epoch as well as the one-turn
    /// exclusion: the yielder in the first band runs next.
    #[test]
    fn a_background_grant_ends_the_yield_epoch() {
        let mut scheduler = Scheduler::new(&Config {
            chaos: true,
            ..Config::default()
        });
        let yielder = DetTid::from_raw(100);
        let background = DetTid::from_raw(101);
        let third = DetTid::from_raw(102);
        for tid in [yielder, background, third] {
            register_known_thread(&mut scheduler, tid);
        }
        scheduler
            .priorities
            .insert(yielder, runqueue::FIRST_PRIORITY);
        scheduler.priorities.insert(third, runqueue::LAST_PRIORITY);
        scheduler.runqueue_push_back(yielder);
        scheduler.runqueue_push_back(third);
        chaos_yield_turn(&mut scheduler, yielder);

        commit_out_of_scheduler_call(
            &mut scheduler,
            background,
            ResourceID::BlockingExternalIO(ExternalOpId::new(background, 1)),
            None,
        );
        assert!(!scheduler.run_queue.contains_tid(background));
        assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(yielder));
    }

    /// A chaos `sched_yield` keeps the yielder ordinary work: the
    /// deterministic-work-first gate stays closed to an external continuation
    /// whose readiness is host-timed while it is runnable. A first version of
    /// the hermit#4068 fix moved the yielder into the last band, where it
    /// counted as a poller (review of https://github.com/rrnewton/hermit/pull/4080,
    /// whose Codex reviewer wrote this test).
    #[test]
    fn a_chaos_yield_keeps_ordinary_work_ahead_of_host_ready_io() {
        for finished in [false, true] {
            let mut scheduler = Scheduler::new(&Config {
                chaos: true,
                ..Config::default()
            });
            let yielder = DetTid::from_raw(100);
            let poller = DetTid::from_raw(101);
            let background = DetTid::from_raw(102);
            for tid in [yielder, poller, background] {
                register_known_thread(&mut scheduler, tid);
            }
            scheduler
                .priorities
                .insert(yielder, runqueue::FIRST_PRIORITY);
            scheduler.runqueue_push_back(yielder);
            scheduler
                .run_queue
                .push_poller(poller, DEFAULT_PRIORITY, u32::MAX);
            let op = ExternalOpId::new(background, 7);
            scheduler
                .blocked
                .external_io_blockers
                .insert(background, op);
            if finished {
                let mut continuation = Resources::new(background);
                continuation.insert(ResourceID::BlockedExternalContinue(op), Permission::RW);
                scheduler
                    .next_turns
                    .get(&background)
                    .unwrap()
                    .req
                    .put(Ok(continuation));
            }
            assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(yielder));
            scheduler.step6_reenquue(yielder, Requeue::YieldEpoch);
            assert!(scheduler.step2c_process_io_blockers().is_ok());
            assert_eq!(
                scheduler.blocked.external_io_blockers.get(&background),
                Some(&op),
                "ordinary yielding work must defer host-ready admission; finished={finished}"
            );
            assert!(!scheduler.run_queue.contains_tid(background));

            // Adjacent positive: with the ordinary yielder gone, a real all-poller
            // queue admits exactly a posted continuation, preserving useful IO progress.
            assert!(scheduler.run_queue.remove_tid(yielder));
            assert!(scheduler.step2c_process_io_blockers().is_ok());
            assert_eq!(scheduler.run_queue.contains_tid(background), finished);
        }
    }

    /// The `InboundSignal` branch defers a host-asynchronous `SIGCHLD` behind
    /// ordinary work, and a chaos `sched_yield` must not turn that work into a
    /// poller and release the signal (same review and author as above).
    #[test]
    fn a_chaos_yield_keeps_ordinary_work_ahead_of_a_deferred_sigchld() {
        let mut scheduler = Scheduler::new(&Config {
            chaos: true,
            ..Config::default()
        });
        let yielder = DetTid::from_raw(100);
        let poller = DetTid::from_raw(101);
        let signaled = DetTid::from_raw(102);
        for tid in [yielder, poller, signaled] {
            register_known_thread(&mut scheduler, tid);
        }
        scheduler
            .priorities
            .insert(yielder, runqueue::FIRST_PRIORITY);
        scheduler.runqueue_push_back(yielder);
        scheduler
            .run_queue
            .push_poller(poller, DEFAULT_PRIORITY, u32::MAX);
        scheduler.runqueue_push_back(signaled);
        let inbound = ResourceID::InboundSignal(SigWrapper(libc::SIGCHLD));
        assert_eq!(
            scheduler.run_queue.tentative_pop_tid(signaled),
            Some(signaled)
        );
        assert!(
            scheduler
                .block_for_one_resource(
                    signaled,
                    &inbound,
                    &Permission::W,
                    None,
                    None,
                    &Ivar::new()
                )
                .is_err()
        );
        assert!(scheduler.blocked.sigchld_deferred.contains(&signaled));
        assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(yielder));
        scheduler.step6_reenquue(yielder, Requeue::YieldEpoch);
        scheduler.step2e_process_signal_deferred();
        assert!(
            scheduler.blocked.sigchld_deferred.contains(&signaled),
            "ordinary yielding work must defer host-async SIGCHLD admission"
        );
        assert!(!scheduler.run_queue.contains_tid(signaled));

        // Adjacent positive: removing the only ordinary thread leaves real
        // pollers and makes the same deferred signal eligible for readmission.
        assert!(scheduler.run_queue.remove_tid(yielder));
        scheduler.step2e_process_signal_deferred();
        assert!(!scheduler.blocked.sigchld_deferred.contains(&signaled));
        assert!(scheduler.run_queue.contains_tid(signaled));
    }

    /// Under a schedule replay whose next record, after the thread's
    /// `SignalReceived`, is the thread's own, a host-async `SIGCHLD` delivery is
    /// not parked behind a polling retry the replay holds in the deferred band:
    /// the recording did not run that retry first, or its polling attempt would
    /// be the next record. It is still parked behind genuine work, here a
    /// queued kernel-run blocking call, which records no event and so keeps its
    /// run-queue order, and step 2e readmits it past the poller once that call
    /// has left the queue; and behind the poller when the schedule runs the
    /// poller next.
    #[test]
    fn a_replayed_sigchld_waits_behind_genuine_work_but_not_a_replay_held_poller() {
        let poller = DetTid::from_raw(3);
        let blocker = DetTid::from_raw(5);
        let signaled = DetTid::from_raw(7);
        let inbound = ResourceID::InboundSignal(SigWrapper(libc::SIGCHLD));
        let polling = |tid: DetTid| {
            let mut request = Resources::new(tid);
            request.insert(ResourceID::InternalIOPolling, Permission::W);
            request
        };
        let deferred = |next: SchedEvent, with_blocker: bool| {
            let mut scheduler = Scheduler::new(&Config::default());
            let mut queued = vec![(poller, polling(poller))];
            if with_blocker {
                let mut request = Resources::new(blocker);
                request.insert(
                    ResourceID::BlockingExternalIO(ExternalOpId::new(blocker, 1)),
                    Permission::W,
                );
                queued.push((blocker, request));
            }
            for (tid, request) in &queued {
                register_known_thread(&mut scheduler, *tid);
                scheduler.next_turns.get_mut(tid).unwrap().req = Ivar::full(Ok(request.clone()));
                scheduler.priorities.insert(*tid, REPLAY_DEFERRED_PRIORITY);
                // A replay requeues a polling thread as an ordinary entry at
                // the priority it gives the threads it does not want to run.
                scheduler.runqueue_push_back(*tid);
            }
            register_known_thread(&mut scheduler, signaled);
            scheduler
                .priorities
                .insert(signaled, REPLAY_FOREGROUND_PRIORITY);
            let received = SchedEvent {
                op: detcore_model::schedule::Op::SignalReceived(SigWrapper(libc::SIGCHLD)),
                ..SchedEvent::branches(signaled, 1)
            }
            .with_time(LogicalTime::from_nanos(10_000));
            scheduler.replayer = Some(Replayer::new(vec![received.clone(), next]));
            let _ = scheduler.consume_schedevent(&received);
            assert!(scheduler.run_queue.has_runnable_besides(signaled));
            scheduler.runqueue_push_back(signaled);
            assert_eq!(
                scheduler.run_queue.tentative_pop_tid(signaled),
                Some(signaled)
            );
            let granted = scheduler
                .block_for_one_resource(
                    signaled,
                    &inbound,
                    &Permission::RW,
                    None,
                    None,
                    &Ivar::new(),
                )
                .is_ok();
            assert_eq!(
                granted,
                !scheduler.blocked.sigchld_deferred.contains(&signaled)
            );
            (scheduler, !granted)
        };
        // The schedule runs the signaled thread next: the poller does not
        // hold the delivery back.
        assert!(!deferred(SchedEvent::branches(signaled, 76), false).1);

        // A queued kernel-run blocking call still does. Once it has left the
        // queue, step 2e readmits the delivery past the poller, which counts
        // as work for `only_pollers`.
        let (mut behind_blocker, parked) = deferred(SchedEvent::branches(signaled, 76), true);
        assert!(parked);
        behind_blocker.step2e_process_signal_deferred();
        assert!(behind_blocker.blocked.sigchld_deferred.contains(&signaled));
        assert!(behind_blocker.run_queue.remove_tid(blocker));
        behind_blocker.step2e_process_signal_deferred();
        assert!(!behind_blocker.blocked.sigchld_deferred.contains(&signaled));
        assert!(behind_blocker.blocked.sigchld_ready.contains(&signaled));
        assert!(behind_blocker.run_queue.contains_tid(signaled));

        // The schedule runs the poller next: deferred as before, and step 2e
        // keeps it parked.
        let (mut poller_next, parked) = deferred(SchedEvent::branches(poller, 3), false);
        assert!(parked);
        poller_next.step2e_process_signal_deferred();
        assert!(poller_next.blocked.sigchld_deferred.contains(&signaled));

        // With another delivery parked too, the replay readmits only the one
        // the schedule runs next while the poller is queued, and the other
        // stays parked; once the queue is empty, step 2e's own gate admits
        // every parked delivery at once, as before.
        let other = DetTid::from_raw(9);
        let (mut two_parked, parked) = deferred(SchedEvent::branches(signaled, 76), true);
        assert!(parked);
        register_known_thread(&mut two_parked, other);
        two_parked.blocked.sigchld_deferred.insert(other);
        assert!(two_parked.run_queue.remove_tid(blocker));
        two_parked.step2e_process_signal_deferred();
        assert!(two_parked.run_queue.contains_tid(signaled));
        assert!(two_parked.blocked.sigchld_deferred.contains(&other));
        assert!(two_parked.run_queue.remove_tid(signaled));
        assert!(two_parked.run_queue.remove_tid(poller));
        two_parked.blocked.sigchld_deferred.insert(signaled);
        two_parked.step2e_process_signal_deferred();
        assert!(two_parked.blocked.sigchld_deferred.is_empty());
        assert!(two_parked.run_queue.contains_tid(signaled));
        assert!(two_parked.run_queue.contains_tid(other));
    }

    /// A polling request with `poll_attempt > 0` is a pending backoff: step 4
    /// requeues it without a grant and records nothing. So a replay counts it
    /// as work for a SIGCHLD delivery to the thread its schedule runs next,
    /// both when the delivery arrives and in step 2e's rescue. Once the backoff
    /// has run, the poller sits in the last band, and step 2e's own gate admits
    /// the delivery (Codex review of the readmission change).
    #[test]
    fn a_pending_poll_backoff_keeps_a_replayed_sigchld_parked() {
        let poller = DetTid::from_raw(3);
        let signaled = DetTid::from_raw(7);
        let inbound = ResourceID::InboundSignal(SigWrapper(libc::SIGCHLD));
        let mut scheduler = Scheduler::new(&Config::default());
        let mut backoff = Resources::new(poller);
        backoff.insert(ResourceID::InternalIOPolling, Permission::W);
        backoff.poll_attempt = 1;
        register_known_thread(&mut scheduler, poller);
        let next = scheduler.next_turns.get_mut(&poller).unwrap();
        next.req = Ivar::full(Ok(backoff.clone()));
        let response = next.resp.clone();
        scheduler
            .priorities
            .insert(poller, REPLAY_DEFERRED_PRIORITY);
        scheduler.runqueue_push_back(poller);
        register_known_thread(&mut scheduler, signaled);
        scheduler
            .priorities
            .insert(signaled, REPLAY_FOREGROUND_PRIORITY);
        let received = SchedEvent {
            op: detcore_model::schedule::Op::SignalReceived(SigWrapper(libc::SIGCHLD)),
            ..SchedEvent::branches(signaled, 1)
        }
        .with_time(LogicalTime::from_nanos(10_000));
        scheduler.replayer = Some(Replayer::new(vec![
            received.clone(),
            SchedEvent::branches(signaled, 76),
        ]));
        let _ = scheduler.consume_schedevent(&received);

        // The delivery waits behind the pending backoff.
        scheduler.runqueue_push_back(signaled);
        assert_eq!(
            scheduler.run_queue.tentative_pop_tid(signaled),
            Some(signaled)
        );
        assert!(
            scheduler
                .block_for_one_resource(
                    signaled,
                    &inbound,
                    &Permission::RW,
                    None,
                    None,
                    &Ivar::new(),
                )
                .is_err()
        );
        assert!(scheduler.blocked.sigchld_deferred.contains(&signaled));
        assert_eq!(scheduler.replay_readmits_parked_sigchld(), None);
        scheduler.step2e_process_signal_deferred();
        assert!(scheduler.blocked.sigchld_deferred.contains(&signaled));

        // The real backoff path grants nothing and moves the poller to the
        // last band; step 2e's own gate then admits the delivery.
        assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(poller));
        assert!(
            scheduler
                .step4_resource_block(poller, &backoff, &response)
                .is_err()
        );
        assert!(response.try_read().is_none());
        assert!(scheduler.run_queue.only_pollers());
        scheduler.step2e_process_signal_deferred();
        assert!(!scheduler.blocked.sigchld_deferred.contains(&signaled));
        assert!(scheduler.run_queue.contains_tid(signaled));
    }

    /// Step 2e's own gate still admits every parked SIGCHLD delivery at once
    /// where it is eligible, with an empty queue or one of real pollers, also
    /// under a schedule replay whose next record is one of their threads. The
    /// replay's rescue of the next-scheduled thread applies only where that
    /// gate keeps the deliveries parked (Codex review of the readmission
    /// change).
    #[test]
    fn a_replay_keeps_step2e_batch_admission_of_parked_sigchlds() {
        let first = DetTid::from_raw(7);
        let second = DetTid::from_raw(9);
        let poller = DetTid::from_raw(3);
        for real_pollers in [false, true] {
            let mut scheduler = Scheduler::new(&Config::default());
            scheduler.replayer = Some(Replayer::new(vec![SchedEvent::branches(first, 76)]));
            for tid in [first, second] {
                register_known_thread(&mut scheduler, tid);
                scheduler.priorities.insert(tid, REPLAY_DEFERRED_PRIORITY);
                scheduler.blocked.sigchld_deferred.insert(tid);
            }
            if real_pollers {
                register_known_thread(&mut scheduler, poller);
                scheduler
                    .run_queue
                    .push_poller(poller, DEFAULT_PRIORITY, u32::MAX);
                assert!(scheduler.run_queue.only_pollers());
            }
            scheduler.step2e_process_signal_deferred();
            assert!(
                scheduler.blocked.sigchld_deferred.is_empty(),
                "real pollers: {real_pollers}"
            );
            assert!(scheduler.run_queue.contains_tid(first));
            assert!(scheduler.run_queue.contains_tid(second));
        }
    }

    /// Defer `signaled`'s host-async `SIGCHLD` in a scheduler whose run queue
    /// holds `busy` as ordinary work besides it, with the kernel's copy raised
    /// at a point the schedule fixes (`fenced`, `BlockedPool::sigchld_fenced`)
    /// or not.
    fn defer_sigchld_beside_with(busy: &[DetTid], signaled: DetTid, fenced: bool) -> Scheduler {
        let mut scheduler = Scheduler::new(&Config::default());
        for tid in busy.iter().copied().chain([signaled]) {
            register_known_thread(&mut scheduler, tid);
            scheduler.runqueue_push_back(tid);
        }
        if fenced {
            let process = scheduler.sigchld_process(signaled);
            scheduler.blocked.sigchld_fenced.insert(
                process,
                SigchldFence {
                    at: scheduler.progress_epoch,
                    by: fence_marker(),
                    ran: BTreeSet::new(),
                },
            );
            // The delivery is filed after a commit of its thread since the
            // mark (`filed_after_sigchld_fence`).
            commit_for_fence(&mut scheduler, signaled);
        }
        assert_eq!(
            scheduler.run_queue.tentative_pop_tid(signaled),
            Some(signaled)
        );
        let inbound = ResourceID::InboundSignal(SigWrapper(libc::SIGCHLD));
        assert!(
            scheduler
                .block_for_one_resource(
                    signaled,
                    &inbound,
                    &Permission::W,
                    None,
                    None,
                    &Ivar::new()
                )
                .is_err()
        );
        assert!(scheduler.blocked.sigchld_deferred.contains(&signaled));
        assert!(
            scheduler.blocked.sigchld_fenced.is_empty(),
            "the mark is taken"
        );
        scheduler
    }

    /// The thread whose turn fences a copy in these tests: none of the
    /// parent's.
    fn fence_marker() -> DetTid {
        DetTid::from_raw(1)
    }

    /// `tid` commits a guest-executing turn, as `unblock_guest` records it:
    /// a new `progress_epoch` as its latest commits, then
    /// `sigchld_fence_commit`.
    fn commit_for_fence(scheduler: &mut Scheduler, tid: DetTid) {
        scheduler.progress_epoch += 1;
        scheduler
            .last_commit_at
            .insert(tid, scheduler.progress_epoch);
        scheduler
            .last_guest_commit_at
            .insert(tid, scheduler.progress_epoch);
        scheduler.sigchld_fence_commit(tid, true);
    }

    /// [`defer_sigchld_beside_with`] with a fenced copy, as a child killed by
    /// SIGKILL, or one whose SIGCHLD Linux discards, gives on ptrace.
    fn defer_sigchld_beside(busy: &[DetTid], signaled: DetTid) -> Scheduler {
        defer_sigchld_beside_with(busy, signaled, true)
    }

    /// A deferred `SIGCHLD` waits behind the work that was runnable when it
    /// was deferred, one turn of each, and then is re-admitted although that
    /// work is still runnable: a sibling that never blocks no longer starves
    /// it (https://github.com/rrnewton/hermit/issues/4132). Before, it waited
    /// for a queue with no ordinary work, which such a sibling never leaves.
    #[test]
    fn a_deferred_sigchld_is_readmitted_once_the_work_runnable_at_its_deferral_has_had_a_turn() {
        let (first, second, signaled) = (
            DetTid::from_raw(100),
            DetTid::from_raw(101),
            DetTid::from_raw(102),
        );
        let mut scheduler = defer_sigchld_beside(&[first, second], signaled);
        assert_eq!(
            scheduler.blocked.sigchld_deferred_behind.get(&signaled),
            Some(&BTreeSet::from([first, second]))
        );
        scheduler.step2e_process_signal_deferred();
        assert!(scheduler.blocked.sigchld_deferred.contains(&signaled));
        // One of them has had its turn and is runnable again: still behind
        // the other.
        scheduler.sigchld_deferrals_pass(first, true);
        scheduler.step2e_process_signal_deferred();
        assert!(scheduler.blocked.sigchld_deferred.contains(&signaled));
        assert!(!scheduler.run_queue.contains_tid(signaled));
        // Both have: the delivery is re-admitted beside them, and its
        // `InboundSignal` turn is granted rather than deferred again.
        scheduler.sigchld_deferrals_pass(second, true);
        scheduler.step2e_process_signal_deferred();
        assert!(scheduler.blocked.sigchld_deferred.is_empty());
        assert!(scheduler.blocked.sigchld_deferred_behind.is_empty());
        assert!(scheduler.blocked.sigchld_ready.contains(&signaled));
        assert!(scheduler.run_queue.contains_tid(signaled));
        assert!(scheduler.run_queue.contains_tid(first));
        assert!(scheduler.run_queue.contains_tid(second));
    }

    /// Work that becomes runnable after the deferral does not hold the
    /// delivery, and work that stops being runnable (it blocked, exited or
    /// was killed) without a turn stops holding it.
    #[test]
    fn a_deferred_sigchld_waits_only_for_work_still_runnable_from_its_deferral() {
        let (busy, gone, late, signaled) = (
            DetTid::from_raw(100),
            DetTid::from_raw(101),
            DetTid::from_raw(102),
            DetTid::from_raw(103),
        );
        let mut scheduler = defer_sigchld_beside(&[busy, gone], signaled);
        register_known_thread(&mut scheduler, late);
        scheduler.runqueue_push_back(late);
        assert!(scheduler.run_queue.remove_tid(gone));
        scheduler.step2e_process_signal_deferred();
        assert_eq!(
            scheduler.blocked.sigchld_deferred_behind.get(&signaled),
            Some(&BTreeSet::from([busy]))
        );
        scheduler.sigchld_deferrals_pass(busy, true);
        scheduler.step2e_process_signal_deferred();
        assert!(scheduler.blocked.sigchld_deferred.is_empty());
        assert!(scheduler.run_queue.contains_tid(signaled));
    }

    /// A copy raised at a point the schedule does not fix (a caught SIGCHLD
    /// that reached a running parent, or any copy on a backend that does not
    /// report child-exit publication) can be deferred at a turn that depends
    /// on host timing, so nothing is counted from it: the delivery waits for
    /// quiescence alone, as before, however many turns the busy thread takes.
    #[test]
    fn a_deferred_sigchld_whose_copy_was_not_fenced_waits_for_quiescence() {
        let (busy, signaled) = (DetTid::from_raw(100), DetTid::from_raw(101));
        let mut scheduler = defer_sigchld_beside_with(&[busy], signaled, false);
        assert!(scheduler.blocked.sigchld_deferred_behind.is_empty());
        for _ in 0..3 {
            scheduler.sigchld_deferrals_pass(busy, true);
            scheduler.step2e_process_signal_deferred();
            assert!(scheduler.blocked.sigchld_deferred.contains(&signaled));
        }
        assert!(scheduler.run_queue.remove_tid(busy));
        scheduler.step2e_process_signal_deferred();
        assert!(scheduler.blocked.sigchld_deferred.is_empty());
        assert!(scheduler.run_queue.contains_tid(signaled));
    }

    /// No mark is set for a copy Linux never sends, an explicit `SIG_IGN`
    /// (`do_notify_parent` sets the signal to 0), or for one the process may
    /// consume without a delivery (a signalfd covering `SIGCHLD`, or a thread
    /// in `rt_sigtimedwait` for it): nothing would take such a mark, and a
    /// later delivery whose turn depends on host timing would. A discarded
    /// copy, and one the parent catches or blocks, is fenced.
    #[test]
    fn a_sigchld_linux_never_sends_or_a_call_may_consume_is_not_fenced() {
        let (parent, sibling) = (DetTid::from_raw(100), DetTid::from_raw(101));
        let fresh = || {
            let mut scheduler = Scheduler::new(&Config::default());
            scheduler.thread_tree.add_child(parent, parent, true);
            scheduler.thread_tree.add_child(parent, sibling, false);
            for tid in [parent, sibling] {
                register_known_thread(&mut scheduler, tid);
            }
            scheduler
        };
        let process = fresh().sigchld_process(parent);
        let mut scheduler = fresh();
        scheduler.fence_child_exit_sigchld(
            process,
            Some(ChildExitNotification::None),
            fence_marker(),
        );
        assert!(scheduler.blocked.sigchld_fenced.is_empty());
        for notification in [
            Some(ChildExitNotification::Discard),
            Some(ChildExitNotification::Deliver),
            Some(ChildExitNotification::Undecided),
            None,
        ] {
            let mut scheduler = fresh();
            scheduler.fence_child_exit_sigchld(process, notification, fence_marker());
            assert!(
                scheduler.blocked.sigchld_fenced.contains_key(&process),
                "{notification:?}"
            );
        }
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let mut scheduler = fresh();
        scheduler.signalfd_masks.insert(process, chld);
        scheduler.fence_child_exit_sigchld(
            process,
            Some(ChildExitNotification::Discard),
            fence_marker(),
        );
        assert!(scheduler.blocked.sigchld_fenced.is_empty());
        // A signalfd recorded under another process: its open description
        // may be shared with this one.
        let mut scheduler = fresh();
        scheduler.signalfd_masks.insert(DetPid::from_raw(7), chld);
        scheduler.fence_child_exit_sigchld(
            process,
            Some(ChildExitNotification::Discard),
            fence_marker(),
        );
        assert!(scheduler.blocked.sigchld_fenced.is_empty());
        let mut scheduler = fresh();
        scheduler.sigtimedwait_sets.insert(sibling, chld);
        scheduler.fence_child_exit_sigchld(
            process,
            Some(ChildExitNotification::Discard),
            fence_marker(),
        );
        assert!(scheduler.blocked.sigchld_fenced.is_empty());
    }

    /// A fenced `SIGCHLD` mark does not outlive its copy. Turns of a thread
    /// that blocks `SIGCHLD` leave it alone, however many; the first turn of a
    /// thread that does not block it may be the one on whose return the copy
    /// is delivered, so it is kept; that thread's second turn shows it
    /// returned to user mode without taking the copy, and the mark expires. A
    /// turn of a thread in `rt_sigtimedwait` for `SIGCHLD` may consume the copy
    /// without a delivery, so it expires the mark at once. Before, the mark
    /// stayed until the process's next `SIGCHLD` delivery, however host-timed,
    /// which then counted its bound from a host-timed turn.
    #[test]
    fn a_fenced_sigchld_expires_once_a_thread_that_could_take_it_runs_on_without_it() {
        let (taker, blocker, waiter) = (
            DetTid::from_raw(100),
            DetTid::from_raw(101),
            DetTid::from_raw(102),
        );
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let fenced = || {
            let mut scheduler = Scheduler::new(&Config::default());
            scheduler.thread_tree.add_child(taker, taker, true);
            for tid in [blocker, waiter] {
                scheduler.thread_tree.add_child(taker, tid, false);
            }
            for tid in [taker, blocker, waiter] {
                register_known_thread(&mut scheduler, tid);
            }
            scheduler.blocked.continuation_masks.insert(taker, Some(0));
            scheduler
                .blocked
                .continuation_masks
                .insert(blocker, Some(chld));
            scheduler
                .blocked
                .continuation_masks
                .insert(waiter, Some(chld));
            let process = scheduler.sigchld_process(taker);
            scheduler.fence_child_exit_sigchld(
                process,
                Some(ChildExitNotification::Discard),
                fence_marker(),
            );
            assert!(scheduler.blocked.sigchld_fenced.contains_key(&process));
            (scheduler, process)
        };
        let (mut scheduler, process) = fenced();
        for _ in 0..3 {
            commit_for_fence(&mut scheduler, blocker);
            commit_for_fence(&mut scheduler, waiter);
        }
        assert!(scheduler.blocked.sigchld_fenced.contains_key(&process));
        commit_for_fence(&mut scheduler, taker);
        assert!(
            scheduler.blocked.sigchld_fenced.contains_key(&process),
            "its first turn may end where it takes the copy"
        );
        commit_for_fence(&mut scheduler, taker);
        assert!(!scheduler.blocked.sigchld_fenced.contains_key(&process));
        // A waiter that enters rt_sigtimedwait for SIGCHLD after the mark.
        let (mut scheduler, process) = fenced();
        scheduler.sigtimedwait_sets.insert(waiter, chld);
        commit_for_fence(&mut scheduler, waiter);
        assert!(!scheduler.blocked.sigchld_fenced.contains_key(&process));
    }

    /// The expiry above, through the production commit path
    /// (`unblock_guest`): the taker's InternalIOPolling retries - a parent
    /// in `read` whose internal probes run with signals privately blocked
    /// and restore the guest mask without executing the task - never
    /// expire the mark, however many commit, because in none did the
    /// thread return to user mode where the pending copy is delivered.
    /// Its ordinary turns then expire it on the second, as above, and so
    /// do first attempts of polling calls: a successful `epoll_wait`
    /// completes and returns to user mode on its first attempt and never
    /// takes a retry, so counting no polling grant at all would leave a
    /// delivery bounded by work that keeps completing such calls waiting
    /// forever (revastra2 F5). Dropping `unblock_guest`'s
    /// `sigchld_fence_commit` call, or counting retries as guest
    /// progress, fails this test (revclaude N1 and revastra2 F1/F5 on
    /// PR 4627).
    #[test]
    fn a_fenced_sigchld_survives_polling_grants_through_unblock_guest() {
        let taker = DetTid::from_raw(100);
        let fenced = || {
            let mut scheduler = Scheduler::new(&Config::default());
            scheduler.thread_tree.add_child(taker, taker, true);
            register_known_thread(&mut scheduler, taker);
            scheduler.blocked.continuation_masks.insert(taker, Some(0));
            let process = scheduler.sigchld_process(taker);
            scheduler.fence_child_exit_sigchld(
                process,
                Some(ChildExitNotification::Discard),
                fence_marker(),
            );
            assert!(scheduler.blocked.sigchld_fenced.contains_key(&process));
            (scheduler, process)
        };
        let (mut scheduler, process) = fenced();
        let grant = |scheduler: &mut Scheduler, request: Resources| {
            queue_request(scheduler, taker, request);
            // As step 3 selected it: the grant itself does not dequeue.
            assert!(scheduler.run_queue.remove_tid(taker));
            let response = scheduler.next_turns[&taker].resp.clone();
            assert!(scheduler.unblock_guest(taker, &response).is_ok());
        };
        for _ in 0..3 {
            let mut polling = Resources::new(taker);
            polling.insert(ResourceID::InternalIOPolling, Permission::W);
            polling.poll_attempt = 1;
            grant(&mut scheduler, polling);
            assert!(
                scheduler.blocked.sigchld_fenced.contains_key(&process),
                "a polling grant expired the mark"
            );
        }
        grant(&mut scheduler, Resources::new(taker));
        assert!(
            scheduler.blocked.sigchld_fenced.contains_key(&process),
            "its first guest turn may end where it takes the copy"
        );
        grant(&mut scheduler, Resources::new(taker));
        assert!(!scheduler.blocked.sigchld_fenced.contains_key(&process));
        // First attempts of polling calls count the same way: two of them
        // expire the mark, as two ordinary turns do.
        let (mut scheduler, process) = fenced();
        for _ in 0..2 {
            let mut first = Resources::new(taker);
            first.insert(ResourceID::InternalIOPolling, Permission::W);
            grant(&mut scheduler, first);
        }
        assert!(
            !scheduler.blocked.sigchld_fenced.contains_key(&process),
            "first polling attempts are guest progress"
        );
        // But first attempts that only continue a call already running in
        // parts (a multipart readv's later parts file fresh attempt-0
        // requests with the guest never resumed between parts) are not:
        // however many commit, the mark survives (revastra2 F6).
        let (mut scheduler, process) = fenced();
        for _ in 0..3 {
            let mut part = Resources::new(taker);
            part.insert(ResourceID::InternalIOPolling, Permission::W);
            part.upgraded_from_attempt = 1;
            part.previous_attempt_made_progress = true;
            grant(&mut scheduler, part);
            assert!(
                scheduler.blocked.sigchld_fenced.contains_key(&process),
                "a continuation part expired the mark"
            );
        }
        grant(&mut scheduler, Resources::new(taker));
        grant(&mut scheduler, Resources::new(taker));
        assert!(!scheduler.blocked.sigchld_fenced.contains_key(&process));
    }

    /// A turn committed under a mask blocking `SIGCHLD` is no delivery
    /// opportunity and does not prime the expiry counter: a wait4 grant
    /// runs with signals privately blocked, and its callback's posthook
    /// grant follows with the mask restored, still before the pending
    /// copy's delivery. Counting the blocked grant would expire the mark
    /// on the posthook and leave the delivery waiting for quiescence
    /// (revastra2 F8 on PR 4627).
    #[test]
    fn a_fenced_sigchld_is_not_primed_by_a_turn_blocking_it() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let taker = DetTid::from_raw(100);
        let mut scheduler = Scheduler::new(&Config::default());
        scheduler.thread_tree.add_child(taker, taker, true);
        register_known_thread(&mut scheduler, taker);
        scheduler.blocked.continuation_masks.insert(taker, Some(0));
        let process = scheduler.sigchld_process(taker);
        scheduler.fence_child_exit_sigchld(
            process,
            Some(ChildExitNotification::Discard),
            fence_marker(),
        );
        assert!(scheduler.blocked.sigchld_fenced.contains_key(&process));
        // The wait4 grant: privately blocked.
        scheduler
            .blocked
            .continuation_masks
            .insert(taker, Some(chld));
        commit_for_fence(&mut scheduler, taker);
        // The posthook grant: mask restored. This is the first turn on
        // which the copy could be delivered, so the mark stands.
        scheduler.blocked.continuation_masks.insert(taker, Some(0));
        commit_for_fence(&mut scheduler, taker);
        assert!(
            scheduler.blocked.sigchld_fenced.contains_key(&process),
            "the blocked grant primed expiry on the posthook"
        );
        commit_for_fence(&mut scheduler, taker);
        assert!(!scheduler.blocked.sigchld_fenced.contains_key(&process));
    }

    /// On a backend without child-exit publication this change adds no
    /// new deferral and no bound: a `SIGCHLD` delivery that waits behind
    /// other work keeps the pre-4627 quiescence wait, however many turns
    /// the work ahead of it commits (coordinator shape (B) for revastra2
    /// F3 on PR 4627), and the typed operation names the unsupported
    /// backend its deferral would have needed.
    #[test]
    fn a_sigchld_deferral_without_child_exit_publication_waits_for_quiescence() {
        let config = Config {
            backend: BackendCapabilities::DBT,
            ..Config::default()
        };
        let mut scheduler = Scheduler::new(&config);
        assert_eq!(
            scheduler.child_exit_publication().unwrap_err().to_string(),
            "the dbt backend does not report child-exit publication"
        );
        let (busy, signaled) = (DetTid::from_raw(100), DetTid::from_raw(101));
        for tid in [busy, signaled] {
            register_known_thread(&mut scheduler, tid);
            scheduler.runqueue_push_back(tid);
        }
        assert_eq!(
            scheduler.run_queue.tentative_pop_tid(signaled),
            Some(signaled)
        );
        let inbound = ResourceID::InboundSignal(SigWrapper(libc::SIGCHLD));
        assert!(
            scheduler
                .block_for_one_resource(
                    signaled,
                    &inbound,
                    &Permission::W,
                    None,
                    None,
                    &Ivar::new(),
                )
                .is_err()
        );
        assert!(scheduler.blocked.sigchld_deferred.contains(&signaled));
        assert!(
            !scheduler
                .blocked
                .sigchld_deferred_behind
                .contains_key(&signaled),
            "no bound is recorded without the contract"
        );
        // The busy thread's turn does not readmit it (no bound here), and
        // does not refuse the run either: the shared wait continues.
        scheduler.sigchld_deferrals_pass(busy, true);
        scheduler.step2e_process_signal_deferred();
        assert!(scheduler.blocked.sigchld_deferred.contains(&signaled));
        // Once the busy work leaves the queue the run is quiescent for
        // this purpose and the delivery is re-admitted, as before 4627.
        assert!(scheduler.run_queue.remove_tid(busy));
        scheduler.step2e_process_signal_deferred();
        assert!(!scheduler.blocked.sigchld_deferred.contains(&signaled));
        assert!(scheduler.blocked.sigchld_ready.contains(&signaled));
    }

    /// Two more routes by which a fenced copy goes without a delivery taking
    /// its mark. A signalfd covering `SIGCHLD` recorded under another process
    /// after the mark (its open description may be shared with the parent's
    /// process) removes the mark at the next commit of a thread of the
    /// parent's process. A disposition change that flushes the pending copy
    /// (`SIG_IGN` or `SIG_DFL`: `ChildExitSigchldControl::Flushed`) removes it
    /// at once. In both, a later delivery to the parent is deferred with no
    /// snapshot (`sigchld_deferred_behind`) and waits for quiescence alone.
    /// The controls: with neither, the blocking sibling's turns and the
    /// parent's first turn keep the mark, and the deferral is bounded.
    #[test]
    fn a_fenced_sigchld_that_a_shared_signalfd_or_a_flush_may_take_leaves_no_bound() {
        let (busy, parent) = (DetTid::from_raw(100), DetTid::from_raw(101));
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let fenced = || {
            let mut scheduler = Scheduler::new(&Config::default());
            scheduler.thread_tree.add_child(parent, parent, true);
            scheduler.thread_tree.add_child(parent, busy, false);
            for tid in [busy, parent] {
                register_known_thread(&mut scheduler, tid);
                scheduler.runqueue_push_back(tid);
            }
            scheduler.blocked.continuation_masks.insert(parent, Some(0));
            scheduler
                .blocked
                .continuation_masks
                .insert(busy, Some(chld));
            let process = scheduler.sigchld_process(parent);
            scheduler.fence_child_exit_sigchld(
                process,
                Some(ChildExitNotification::Discard),
                fence_marker(),
            );
            assert!(scheduler.blocked.sigchld_fenced.contains_key(&process));
            (scheduler, process)
        };
        let defer = |scheduler: &mut Scheduler| {
            assert_eq!(scheduler.run_queue.tentative_pop_tid(parent), Some(parent));
            let inbound = ResourceID::InboundSignal(SigWrapper(libc::SIGCHLD));
            assert!(
                scheduler
                    .block_for_one_resource(
                        parent,
                        &inbound,
                        &Permission::W,
                        None,
                        None,
                        &Ivar::new()
                    )
                    .is_err()
            );
            assert!(scheduler.blocked.sigchld_deferred.contains(&parent));
            assert!(scheduler.blocked.sigchld_fenced.is_empty());
        };
        // The control: the busy sibling blocks SIGCHLD, and the parent's
        // first turn may end where it takes the copy.
        let (mut scheduler, _) = fenced();
        commit_for_fence(&mut scheduler, busy);
        commit_for_fence(&mut scheduler, parent);
        defer(&mut scheduler);
        assert_eq!(
            scheduler.blocked.sigchld_deferred_behind.get(&parent),
            Some(&BTreeSet::from([busy]))
        );
        // A signalfd for SIGCHLD recorded under another process.
        let (mut scheduler, process) = fenced();
        scheduler.signalfd_masks.insert(DetPid::from_raw(7), chld);
        commit_for_fence(&mut scheduler, busy);
        assert!(!scheduler.blocked.sigchld_fenced.contains_key(&process));
        defer(&mut scheduler);
        assert!(scheduler.blocked.sigchld_deferred_behind.is_empty());
        // The parent blocks SIGCHLD, so its turns keep the mark, and sets its
        // action to SIG_IGN or SIG_DFL, which flushes the pending copy; it
        // later restores a handler and unblocks SIGCHLD.
        let (mut scheduler, process) = fenced();
        scheduler
            .blocked
            .continuation_masks
            .insert(parent, Some(chld));
        for _ in 0..3 {
            commit_for_fence(&mut scheduler, parent);
            commit_for_fence(&mut scheduler, busy);
        }
        assert!(scheduler.blocked.sigchld_fenced.contains_key(&process));
        scheduler.child_exit_sigchld_control(
            parent,
            crate::scheduler::child_exit_sigchld::ChildExitSigchldControl::Flushed,
        );
        assert!(!scheduler.blocked.sigchld_fenced.contains_key(&process));
        scheduler.blocked.continuation_masks.insert(parent, Some(0));
        defer(&mut scheduler);
        assert!(scheduler.blocked.sigchld_deferred_behind.is_empty());
    }

    /// Only a `SIGCHLD` delivery filed after the mark takes it. A delivery
    /// whose request was filed before the copy was fenced, by a thread whose
    /// latest commit precedes the mark (a caught copy that reached a running
    /// thread at a point the host chose, before a sibling's SIGKILL fenced
    /// the process), is deferred with no snapshot (`sigchld_deferred_behind`),
    /// waits for quiescence alone, and leaves the mark. The later delivery of
    /// the fenced copy takes it and is bounded: by the SIGKILL's sender,
    /// whose turn set the mark, or by a thread that committed since. Before,
    /// the first delivery took the mark and was bounded from a turn that
    /// existed only because of host timing.
    #[test]
    fn a_sigchld_delivery_filed_before_the_mark_leaves_it_for_the_fenced_copy() {
        let (busy, early, killer) = (
            DetTid::from_raw(100),
            DetTid::from_raw(101),
            DetTid::from_raw(102),
        );
        let chld = kernel_signal_bit(libc::SIGCHLD);
        // `early` and `killer` commit; `early` then files its delivery, and
        // `killer`'s SIGKILL fences the process in its turn.
        let fenced = || {
            let mut scheduler = Scheduler::new(&Config::default());
            scheduler.thread_tree.add_child(early, early, true);
            for tid in [busy, killer] {
                scheduler.thread_tree.add_child(early, tid, false);
            }
            for tid in [busy, early, killer] {
                register_known_thread(&mut scheduler, tid);
                scheduler.runqueue_push_back(tid);
            }
            scheduler
                .blocked
                .continuation_masks
                .insert(busy, Some(chld));
            for tid in [early, killer] {
                scheduler.blocked.continuation_masks.insert(tid, Some(0));
            }
            commit_for_fence(&mut scheduler, early);
            commit_for_fence(&mut scheduler, killer);
            let process = scheduler.sigchld_process(early);
            scheduler.fence_child_exit_sigchld(
                process,
                Some(ChildExitNotification::Deliver),
                killer,
            );
            assert!(scheduler.blocked.sigchld_fenced.contains_key(&process));
            (scheduler, process)
        };
        let deliver = |scheduler: &mut Scheduler, tid: DetTid| {
            assert_eq!(scheduler.run_queue.tentative_pop_tid(tid), Some(tid));
            let inbound = ResourceID::InboundSignal(SigWrapper(libc::SIGCHLD));
            assert!(
                scheduler
                    .block_for_one_resource(tid, &inbound, &Permission::W, None, None, &Ivar::new())
                    .is_err()
            );
            assert!(scheduler.blocked.sigchld_deferred.contains(&tid));
        };
        let (mut scheduler, process) = fenced();
        deliver(&mut scheduler, early);
        assert_eq!(scheduler.blocked.sigchld_deferred_behind.get(&early), None);
        assert!(
            scheduler.blocked.sigchld_fenced.contains_key(&process),
            "a delivery filed before the mark leaves it for the fenced copy"
        );
        deliver(&mut scheduler, killer);
        assert_eq!(
            scheduler.blocked.sigchld_deferred_behind.get(&killer),
            Some(&BTreeSet::from([busy]))
        );
        assert!(scheduler.blocked.sigchld_fenced.is_empty());
        // A thread that committed a turn since the mark files after it.
        let (mut scheduler, process) = fenced();
        commit_for_fence(&mut scheduler, early);
        assert!(scheduler.blocked.sigchld_fenced.contains_key(&process));
        deliver(&mut scheduler, early);
        assert_eq!(
            scheduler.blocked.sigchld_deferred_behind.get(&early),
            Some(&BTreeSet::from([busy, killer]))
        );
        assert!(scheduler.blocked.sigchld_fenced.is_empty());
    }

    /// The control for the two tests above: a queue of real pollers alone still
    /// admits ready IO and a deferred signal, as the progress policy needs.
    #[test]
    fn a_poller_only_queue_still_admits_ready_io_and_a_deferred_sigchld() {
        let mut scheduler = Scheduler::new(&Config {
            chaos: true,
            ..Config::default()
        });
        let poller = DetTid::from_raw(101);
        let background = DetTid::from_raw(102);
        let signaled = DetTid::from_raw(103);
        for tid in [poller, background, signaled] {
            register_known_thread(&mut scheduler, tid);
        }
        scheduler
            .run_queue
            .push_poller(poller, DEFAULT_PRIORITY, u32::MAX);
        assert!(scheduler.run_queue.only_pollers());
        scheduler.blocked.sigchld_deferred.insert(signaled);
        scheduler.step2e_process_signal_deferred();
        assert!(scheduler.blocked.sigchld_deferred.is_empty());
        assert!(scheduler.run_queue.contains_tid(signaled));
        assert!(scheduler.run_queue.remove_tid(signaled));
        let op = ExternalOpId::new(background, 7);
        scheduler
            .blocked
            .external_io_blockers
            .insert(background, op);
        let mut continuation = Resources::new(background);
        continuation.insert(ResourceID::BlockedExternalContinue(op), Permission::RW);
        scheduler
            .next_turns
            .get(&background)
            .unwrap()
            .req
            .put(Ok(continuation));
        assert!(scheduler.step2c_process_io_blockers().is_ok());
        assert!(scheduler.blocked.external_io_blockers.is_empty());
        assert!(scheduler.run_queue.contains_tid(background));
    }

    /// The scheduler under the condition that turns on its model of which thread
    /// a signal reaches (`models_signal_targets`): serialized threads and a
    /// backend that decides blocked-wait interruption from the kernel's signal
    /// state (https://github.com/rrnewton/hermit/issues/3146).
    fn gated_scheduler() -> Scheduler {
        let scheduler = Scheduler::new(
            &Config {
                sequentialize_threads: true,
                ..Config::default()
            }
            .with_backend(|backend| {
                detcore_model::config::set_kernel_signal_facts(backend, true);
                backend.delivers_preemption_timer_events = false;
                backend.runs_guest_code_between_injections = false;
            }),
        );
        assert!(scheduler.models_signal_targets);
        scheduler
    }

    /// A caught `SIGCHLD` ends a parked precise-mode futex wait only when the
    /// scheduler sends it to the waiter at a commit point (`wake_signaled_guest`,
    /// as a `ChildExit` timer does): the waiter is woken with the signal, as
    /// Linux ends the wait (https://github.com/rrnewton/hermit/issues/4005).
    /// Through the drain of a cross-task signal, which only says a `SIGCHLD` is
    /// pending, or when a host-timed source a guest armed can post `SIGCHLD`
    /// too, the waiter stays parked with its original deadline, and the signal
    /// stays pending in the kernel until the call returns for another reason:
    /// `/proc` cannot tell a `SIGCHLD` sent at a deterministic point from the
    /// one the kernel posts for a child event at a moment set by host timing
    /// (https://github.com/rrnewton/hermit/issues/3146). A caught `SIGUSR1`
    /// still ends the same wait.
    #[test]
    fn a_sigchld_ends_a_parked_futex_wait_only_when_the_scheduler_sends_it() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        let deadline = LogicalTime::from_nanos(300_000_000);
        for (scheduler_send, host_timed) in [(false, false), (true, false), (true, true)] {
            let mut scheduler = gated_scheduler();
            let (target, futex) = parked_futex_target(&mut scheduler);
            if host_timed {
                scheduler.record_host_timed_signals(target, HostTimedSignalScope::Caller, chld);
            }
            scheduler.sleep_futex_waiter(
                &target,
                futex,
                Some(deadline),
                u32::MAX,
                Some(signal_watch(chld | usr1)),
            );
            scheduler
                .test_kernel_signal_states
                .insert(target, signal_state(chld | usr1, 0));
            assert_eq!(
                scheduler.parked_futex_interrupting_signals(target, 0),
                Some(usr1),
                "a caught SIGCHLD is not among the signals that end the wait"
            );

            if scheduler_send {
                scheduler.wake_signaled_guest(target, Signal::SIGCHLD);
            } else {
                scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGCHLD));
                scheduler.drain_pending_cross_task_signals();
            }
            let case = format!("scheduler_send={scheduler_send} host_timed={host_timed}");
            if scheduler_send && !host_timed {
                assert!(!scheduler.is_parked_futex_waiter(target), "{case}");
                assert_eq!(
                    scheduler.inbound_signals(target),
                    vec![SigWrapper::from(Signal::SIGCHLD)],
                    "{case}"
                );
                continue;
            }
            assert!(scheduler.is_parked_futex_waiter(target), "{case}");
            assert!(!scheduler.run_queue.contains_tid(target), "{case}");
            assert!(scheduler.inbound_signals(target).is_empty(), "{case}");
            assert!(scheduler.pending_cross_task_signals.is_empty(), "{case}");
            assert_eq!(
                scheduler.blocked.timed_waiters.iter().collect::<Vec<_>>(),
                vec![(deadline, TimedEvent::ThreadEvt(target))],
                "{case}"
            );

            if scheduler_send {
                scheduler.wake_signaled_guest(target, Signal::SIGUSR1);
            } else {
                scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
                scheduler.drain_pending_cross_task_signals();
            }
            assert!(!scheduler.is_parked_futex_waiter(target), "{case}");
            assert_eq!(
                scheduler.inbound_signals(target),
                vec![SigWrapper::from(Signal::SIGUSR1)],
                "{case}"
            );
        }
    }

    /// A `SIGCHLD` the scheduler sends a parked precise-mode futex waiter at a
    /// commit point (a `ChildExit` timer) wakes it to the front of its band and
    /// marks the delivery as placed (`sigchld_ready`), so its turn is granted
    /// ahead of a runnable sibling rather than deferred behind it. Deferred,
    /// the sibling resumed first, and the kernel, which skips the
    /// ptrace-stopped waiter, gave the sibling the signal: the handler ran on
    /// the sibling and the wait did not end with EINTR, where Linux ends it
    /// (https://github.com/rrnewton/hermit/issues/4304). Without the mark the
    /// same turn is deferred, and a `SIGUSR1`, which is never deferred, sets
    /// no mark.
    #[test]
    fn a_scheduler_sigchld_wakes_a_parked_futex_waiter_ahead_of_a_runnable_sibling() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        for (signal, marked) in [
            (Signal::SIGCHLD, true),
            (Signal::SIGCHLD, false),
            (Signal::SIGUSR1, false),
        ] {
            let case = format!("{signal:?}, marked={marked}");
            let mut scheduler = gated_scheduler();
            let (target, futex) = parked_futex_target(&mut scheduler);
            scheduler.sleep_futex_waiter(
                &target,
                futex,
                None,
                u32::MAX,
                Some(signal_watch(chld | usr1)),
            );
            scheduler
                .test_kernel_signal_states
                .insert(target, signal_state(chld | usr1, 0));
            let sibling = DetTid::from_raw(101);
            register_known_thread(&mut scheduler, sibling);
            scheduler.runqueue_push_back(sibling);

            scheduler.wake_signaled_guest(target, signal);
            assert_eq!(
                scheduler.run_queue.tids().copied().collect::<Vec<_>>(),
                vec![target, sibling],
                "{case}"
            );
            assert_eq!(
                scheduler.blocked.sigchld_ready.contains(&target),
                signal == Signal::SIGCHLD,
                "{case}"
            );
            if signal == Signal::SIGCHLD && !marked {
                scheduler.blocked.sigchld_ready.remove(&target);
            }
            let resources = scheduler
                .next_turns
                .get(&target)
                .and_then(|next_turn| next_turn.req.try_read())
                .and_then(Result::ok)
                .expect("the waiter holds its signal request");
            let (selected, _, response) = scheduler.step3_peek().expect("a thread is runnable");
            assert_eq!(selected, target, "{case}");
            let granted = scheduler
                .step4_resource_block(target, &resources, &response)
                .is_ok();
            let deferred = signal == Signal::SIGCHLD && !marked;
            assert_eq!(granted, !deferred, "{case}");
            assert_eq!(
                scheduler.blocked.sigchld_deferred.contains(&target),
                deferred,
                "{case}"
            );
        }
    }

    /// A waiter the wake leaves held at a happens-before gate gets no
    /// `sigchld_ready` mark, which a later, host-timed `SIGCHLD` delivery could
    /// otherwise use to skip its deferral (the Codex and Claude reviews of
    /// https://github.com/rrnewton/hermit/issues/4304); nor
    /// is it made a thread step 3 resumes first. Where the wake does unblock it,
    /// both hold.
    #[test]
    fn a_held_futex_waiter_is_not_marked_for_a_scheduler_sigchld() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        for held in [false, true] {
            let mut scheduler = gated_scheduler();
            let (target, futex) = parked_futex_target(&mut scheduler);
            scheduler.sleep_futex_waiter(&target, futex, None, u32::MAX, Some(signal_watch(chld)));
            scheduler
                .test_kernel_signal_states
                .insert(target, signal_state(chld, 0));
            if held {
                let mut hb = hb_runtime(HB_GATE_SPEC);
                hb.parked.insert(target);
                scheduler.happens_before = Some(hb);
            }
            scheduler.wake_signaled_guest(target, Signal::SIGCHLD);
            assert_eq!(
                scheduler.blocked.sigchld_ready.contains(&target),
                !held,
                "held={held}"
            );
            assert_eq!(
                scheduler.blocked.sigchld_takers.contains(&target),
                !held,
                "held={held}"
            );
        }
    }

    /// A thread polling internal IO that the scheduler sends a `SIGCHLD` it
    /// does not block is woken to the front of its band and marked, so it is
    /// the next thread to resume and takes the signal. Before, it went to the
    /// back, its turn was deferred,
    /// and a spinning sibling took the signal: a `read` of an empty pipe
    /// returned the sibling's byte where Linux returns EINTR (the Claude
    /// review of https://github.com/rrnewton/hermit/issues/4304).
    #[test]
    fn a_scheduler_sigchld_wakes_an_internal_io_poller_ahead_of_a_runnable_sibling() {
        let mut scheduler = gated_scheduler();
        let poller = DetTid::from_raw(100);
        register_known_thread(&mut scheduler, poller);
        let sibling = DetTid::from_raw(101);
        register_known_thread(&mut scheduler, sibling);
        scheduler.runqueue_push_back(sibling);
        let mut polling = Resources::new(poller);
        polling.insert(ResourceID::InternalIOPolling, Permission::RW);
        scheduler.next_turns.get_mut(&poller).unwrap().req = Ivar::full(Ok(polling));
        scheduler.runqueue_push_back(poller);
        scheduler.wake_signaled_guest(poller, Signal::SIGCHLD);
        assert_eq!(
            scheduler.run_queue.tids().copied().collect::<Vec<_>>(),
            vec![poller, sibling]
        );
        assert!(scheduler.blocked.sigchld_ready.contains(&poller));
        assert!(scheduler.blocked.sigchld_takers.contains(&poller));
        assert_eq!(
            scheduler.inbound_signals(poller),
            vec![SigWrapper(libc::SIGCHLD)]
        );
    }

    /// A thread woken to take the scheduler's `SIGCHLD` is the next selected,
    /// whatever its priority or the selection heuristic, and before a runnable
    /// vfork child, so it is the thread that resumes first and takes the
    /// process-directed copy: chosen over a sibling in a higher band and over
    /// the vfork child (the Claude and Codex reviews of
    /// https://github.com/rrnewton/hermit/issues/4304). Not while its mask
    /// blocks `SIGCHLD`; and it leaves the set once its copy is gone from the
    /// shared queue and its request is not the delivery.
    #[test]
    fn a_sigchld_taker_is_selected_first_whatever_its_priority() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let mut scheduler = gated_scheduler();
        let (target, futex) = parked_futex_target(&mut scheduler);
        scheduler
            .priorities
            .insert(target, runqueue::LAST_PRIORITY - 1);
        scheduler.sleep_futex_waiter(&target, futex, None, u32::MAX, Some(signal_watch(chld)));
        scheduler
            .test_kernel_signal_states
            .insert(target, signal_state(chld, 0));
        let sibling = DetTid::from_raw(101);
        register_known_thread(&mut scheduler, sibling);
        scheduler
            .priorities
            .insert(sibling, runqueue::FIRST_PRIORITY);
        scheduler.runqueue_push_back(sibling);
        // A runnable vfork child, which step 3 otherwise selects first.
        let vfork_parent = DetTid::from_raw(102);
        let vfork_child = DetTid::from_raw(103);
        register_known_thread(&mut scheduler, vfork_child);
        scheduler
            .vfork_barriers
            .insert(vfork_parent, Some(vfork_child));
        scheduler.runqueue_push_back(vfork_child);
        scheduler.wake_signaled_guest(target, Signal::SIGCHLD);
        assert!(scheduler.blocked.sigchld_takers.contains(&target));
        let (selected, _, _) = scheduler.step3_peek().expect("a thread is runnable");
        assert_eq!(selected, target);
        scheduler.run_queue.undo_tentative_pop();

        // Not while its mask blocks SIGCHLD.
        scheduler
            .test_kernel_signal_states
            .insert(target, signal_state(chld, chld));
        scheduler
            .blocked
            .out_of_scheduler_masks
            .insert(target, Some(chld));
        let (selected, _, _) = scheduler.step3_peek().expect("a thread is runnable");
        assert_eq!(selected, vfork_child);
        scheduler.run_queue.undo_tentative_pop();
        scheduler.blocked.out_of_scheduler_masks.remove(&target);

        // Its copy gone (no send in the window) and its request something
        // else: it leaves the set.
        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(Resources::new(target)));
        let (selected, _, _) = scheduler.step3_peek().expect("a thread is runnable");
        assert_eq!(selected, vfork_child);
        scheduler.run_queue.undo_tentative_pop();
        assert!(!scheduler.blocked.sigchld_takers.contains(&target));
    }

    /// A process (`leader` first) of `members`, each with the signal state
    /// `state(blocked)`: SIGUSR1 caught, and `blocked` its mask.
    fn signal_process(
        scheduler: &mut Scheduler,
        leader: DetTid,
        members: &[(DetTid, u64)],
        caught: u64,
    ) {
        scheduler.thread_tree.add_child(leader, leader, true);
        for &(tid, blocked) in members {
            if tid != leader {
                scheduler.thread_tree.add_child(leader, tid, false);
            }
            register_known_thread(scheduler, tid);
            scheduler.test_kernel_signal_states.insert(
                tid,
                KernelSignalState {
                    caught,
                    blocked,
                    ..Default::default()
                },
            );
        }
    }

    /// The walk's choice becomes the process's `curr_target` only once the
    /// forwarded call has succeeded (`process_signal_sent`), as Linux moves it
    /// only for a send that reaches `complete_signal`: not when the kernel
    /// fails the call first (no success is reported, and the next choice
    /// discards the move), not when the choice is the named task's (no walk),
    /// and not when the send is refused because the sender would take it
    /// (`SenderTakesIt`).
    #[test]
    fn curr_target_moves_only_for_a_walk_choice_whose_send_succeeds() {
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        let mut scheduler = gated_scheduler();
        let leader = DetTid::from_raw(100);
        let first = DetTid::from_raw(101);
        let second = DetTid::from_raw(102);
        let process = DetPid::from_raw(100);
        signal_process(
            &mut scheduler,
            leader,
            &[(leader, usr1), (first, 0), (second, usr1)],
            usr1,
        );
        let walk = process_signal_receiver::ProcessSignalReceiver::Thread {
            thread: first,
            sole: true,
        };
        // A send whose forwarded call fails: nothing reports, nothing moves,
        // and the next choice walks from the leader again.
        assert_eq!(
            scheduler.process_signal_receiver(process, leader, leader, libc::SIGUSR1),
            walk
        );
        assert_eq!(scheduler.signal_curr_targets.get(&process), None);
        assert_eq!(
            scheduler.process_signal_receiver(process, leader, leader, libc::SIGUSR1),
            walk
        );
        // This one succeeds: the walk's choice becomes curr_target.
        scheduler.process_signal_sent(leader, process);
        assert_eq!(scheduler.signal_curr_targets.get(&process), Some(&first));
        // A success reported for no pending choice moves nothing.
        scheduler.signal_curr_targets.clear();
        scheduler.process_signal_sent(leader, process);
        assert_eq!(scheduler.signal_curr_targets.get(&process), None);
        // The named task takes it (no walk): its success moves nothing.
        assert_eq!(
            scheduler.process_signal_receiver(process, first, leader, libc::SIGUSR1),
            walk
        );
        scheduler.process_signal_sent(leader, process);
        assert_eq!(scheduler.signal_curr_targets.get(&process), None);

        // `second` sends with SIGUSR1 unblocked while the walk chooses
        // `first`: the sender would take the copy, so the send is refused,
        // and curr_target stays where it was.
        scheduler
            .test_kernel_signal_states
            .get_mut(&second)
            .unwrap()
            .blocked = 0;
        assert_eq!(
            scheduler.process_signal_receiver(process, leader, second, libc::SIGUSR1),
            process_signal_receiver::ProcessSignalReceiver::SenderTakesIt
        );
        assert_eq!(scheduler.signal_curr_targets.get(&process), None);
        scheduler.process_signal_sent(second, process);
        assert_eq!(scheduler.signal_curr_targets.get(&process), None);
    }

    /// A signal whose default action ends the process, sent to a process
    /// every thread of which blocks it, waits in the shared queue: no thread
    /// takes it, and none is named, least of all a thread of the sending
    /// process. With one thread leaving it unblocked, that thread is named.
    #[test]
    fn a_fatal_signal_every_thread_blocks_waits_in_the_shared_queue() {
        let term = kernel_signal_bit(libc::SIGTERM);
        let mut scheduler = gated_scheduler();
        let leader = DetTid::from_raw(100);
        let worker = DetTid::from_raw(101);
        let sender = DetTid::from_raw(200);
        let process = DetPid::from_raw(100);
        signal_process(&mut scheduler, leader, &[(leader, term), (worker, term)], 0);
        signal_process(&mut scheduler, sender, &[(sender, 0)], 0);
        assert_eq!(
            scheduler.process_signal_receiver(process, leader, sender, libc::SIGTERM),
            process_signal_receiver::ProcessSignalReceiver::SharedQueue
        );
        scheduler
            .test_kernel_signal_states
            .get_mut(&worker)
            .unwrap()
            .blocked = 0;
        assert_eq!(
            scheduler.process_signal_receiver(process, leader, sender, libc::SIGTERM),
            process_signal_receiver::ProcessSignalReceiver::Thread {
                thread: worker,
                sole: true
            }
        );
    }

    /// The sequence of the Codex review of #4625's second revision: a process
    /// with leader 10 (blocking SIGUSR1 and SIGUSR2), thread 11 (blocking
    /// SIGUSR1) and thread 12 (blocking neither). Thread 12's `kill(10,
    /// SIGUSR1)` is forwarded as it is, since every sibling blocks it, and
    /// Linux's walk from the leader reaches thread 12, which becomes
    /// `curr_target` once the call succeeds. A later SIGUSR2 from another
    /// process names the leader, which blocks it, and the walk starts at
    /// thread 12, which takes it, ahead of thread 11. Without a reported
    /// success, or for a send that names the sender (step 1, no walk),
    /// `curr_target` stays at the leader and thread 11 takes it.
    #[test]
    fn an_admitted_own_process_walk_moves_curr_target_for_a_later_foreign_send() {
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        let usr2 = kernel_signal_bit(libc::SIGUSR2);
        let leader = DetTid::from_raw(10);
        let eleven = DetTid::from_raw(11);
        let twelve = DetTid::from_raw(12);
        let foreign = DetTid::from_raw(20);
        let process = DetPid::from_raw(10);
        let setup = || {
            let mut scheduler = gated_scheduler();
            signal_process(
                &mut scheduler,
                leader,
                &[(leader, usr1 | usr2), (eleven, usr1), (twelve, 0)],
                usr1 | usr2,
            );
            signal_process(&mut scheduler, foreign, &[(foreign, 0)], usr1 | usr2);
            scheduler
        };
        let foreign_receiver = |scheduler: &mut Scheduler| match scheduler.process_signal_receiver(
            process,
            leader,
            foreign,
            libc::SIGUSR2,
        ) {
            process_signal_receiver::ProcessSignalReceiver::Thread { thread, .. } => thread,
            other => panic!("no receiver: {other:?}"),
        };

        let mut scheduler = setup();
        scheduler.own_process_signal_choice(twelve, leader, libc::SIGUSR1);
        scheduler.process_signal_sent(twelve, process);
        assert_eq!(scheduler.signal_curr_targets.get(&process), Some(&twelve));
        assert_eq!(foreign_receiver(&mut scheduler), twelve);

        // The own-process send failed: nothing reports, nothing moves.
        let mut scheduler = setup();
        scheduler.own_process_signal_choice(twelve, leader, libc::SIGUSR1);
        assert_eq!(foreign_receiver(&mut scheduler), eleven);

        // It named the sender itself: Linux's step 1 takes it, no walk.
        let mut scheduler = setup();
        scheduler.own_process_signal_choice(twelve, twelve, libc::SIGUSR1);
        scheduler.process_signal_sent(twelve, process);
        assert_eq!(scheduler.signal_curr_targets.get(&process), None);
        assert_eq!(foreign_receiver(&mut scheduler), eleven);
    }

    /// A reported success commits only the pending choice of the sender that
    /// reports it, for the process it chose in (`process_signal_sent`): a
    /// report from another thread, or for another process, moves nothing,
    /// and drops the pending choice.
    #[test]
    fn process_signal_sent_commits_only_the_reporting_senders_choice() {
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        let mut scheduler = gated_scheduler();
        let leader = DetTid::from_raw(100);
        let first = DetTid::from_raw(101);
        let other = DetTid::from_raw(102);
        let process = DetPid::from_raw(100);
        let elsewhere = DetPid::from_raw(200);
        signal_process(
            &mut scheduler,
            leader,
            &[(leader, usr1), (first, 0), (other, usr1)],
            usr1,
        );
        let choose = |scheduler: &mut Scheduler| {
            assert_eq!(
                scheduler.process_signal_receiver(process, leader, leader, libc::SIGUSR1),
                process_signal_receiver::ProcessSignalReceiver::Thread {
                    thread: first,
                    sole: true
                }
            );
        };
        choose(&mut scheduler);
        scheduler.process_signal_sent(other, process);
        assert_eq!(scheduler.signal_curr_targets.get(&process), None);
        scheduler.process_signal_sent(leader, process);
        assert_eq!(
            scheduler.signal_curr_targets.get(&process),
            None,
            "the mismatched report dropped the pending choice"
        );
        choose(&mut scheduler);
        scheduler.process_signal_sent(leader, elsewhere);
        assert_eq!(scheduler.signal_curr_targets.get(&process), None);
        assert_eq!(scheduler.signal_curr_targets.get(&elsewhere), None);
        choose(&mut scheduler);
        scheduler.process_signal_sent(leader, process);
        assert_eq!(scheduler.signal_curr_targets.get(&process), Some(&first));
    }

    /// The readmission that broke record/replay of make -jN (minibeads
    /// dh-ojrf): make (7), a SIGCHLD taker, is backgrounded in a `pselect6`
    /// and a child (173) in a `connect`. Both calls have finished by one
    /// step2c, which readmits them together as one rejoin entry, and step 3
    /// decides between them from make's mask. That mask must not come from
    /// the kernel, whose `SigBlk` there differs between record (0: the
    /// interrupted call's temporary mask, still installed) and replay
    /// (SIGCHLD blocked: the result was served). Whatever the kernel holds,
    /// in record and in replay alike:
    /// - a call a signal ended, with a known temporary mask that unblocks
    ///   SIGCHLD: make is the taker and runs first;
    /// - one whose temporary mask the scheduler does not know (a masked
    ///   record/replay wait, as in dh-ojrf): no taker, the child runs first;
    /// - a call that returned normally keeps no mask (Linux restored the
    ///   thread's own, which the kernel holds in both).
    ///
    /// The kept mask decides `discard_mask` too, and ends at the continuation.
    #[test]
    fn two_calls_readmitted_together_choose_the_sigchld_taker_by_its_recorded_mask() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let make = DetTid::from_raw(7);
        let child = DetTid::from_raw(173);
        let pselect = ExternalOpId::new(make, 1016);
        let connect = ExternalOpId::new(child, 199);
        let logged = Rejoin {
            turn: 12,
            wakes: 0,
            calls: vec![(make, 1016), (child, 199)],
            popped: None,
        };
        // (what make's continuation carries, the kept mask, who runs first)
        let interrupted_known = (Some(0), false, Some(Some(0)), Some(make));
        let interrupted_unknown = (None, true, Some(None), Some(child));
        let normal = (None, false, None, None);
        for (mask, unknown, kept, first) in [interrupted_known, interrupted_unknown, normal] {
            for replay in [false, true] {
                for kernel_blocked in [0, chld] {
                    let case = format!(
                        "continuation mask {mask:?} unknown {unknown}, replay {replay}, \
                         kernel SigBlk {kernel_blocked:#x}"
                    );
                    let dir = tempfile::tempdir().unwrap();
                    let mut scheduler = gated_scheduler();
                    scheduler.recordreplay_modes = true;
                    for (tid, op) in [(make, pselect), (child, connect)] {
                        scheduler.thread_tree.add_child(tid, tid, true);
                        register_known_thread(&mut scheduler, tid);
                        background(&mut scheduler, op, true);
                    }
                    let mut continuation = Resources::new(make);
                    continuation
                        .insert(ResourceID::BlockedExternalContinue(pselect), Permission::RW);
                    continuation.blocked_signal_mask = mask;
                    continuation.blocked_signal_mask_unknown = unknown;
                    scheduler.next_turns.get_mut(&make).unwrap().req = Ivar::full(Ok(continuation));
                    scheduler
                        .blocked
                        .out_of_scheduler_masks
                        .insert(make, if unknown { None } else { Some(0) });
                    // make catches SIGCHLD; the kernel's SigBlk is record's or
                    // replay's view.
                    let mut kernel = signal_state(chld, 0);
                    kernel.blocked = kernel_blocked;
                    scheduler.test_kernel_signal_states.insert(make, kernel);
                    assert!(scheduler.note_group_send(make, Signal::SIGCHLD, false));
                    scheduler.blocked.sigchld_takers.insert(make);
                    scheduler.turn = 12;
                    if replay {
                        replaying(&mut scheduler, std::slice::from_ref(&logged));
                    } else {
                        scheduler.rejoin_writer = Some(RejoinWriter::create(dir.path()).unwrap());
                    }

                    assert!(scheduler.step2c_process_io_blockers().is_ok(), "{case}");
                    for tid in [make, child] {
                        assert!(scheduler.run_queue.contains_tid(tid), "{case}");
                    }
                    if replay {
                        assert!(scheduler.rejoin_replay.as_ref().unwrap().is_empty());
                    } else {
                        assert_eq!(
                            rejoin_log::read(dir.path()).unwrap(),
                            std::collections::VecDeque::from([logged.clone()]),
                            "{case}"
                        );
                    }
                    assert!(!scheduler.blocked.out_of_scheduler_masks.contains_key(&make));
                    assert_eq!(
                        scheduler.blocked.continuation_masks.get(&make).copied(),
                        kept,
                        "{case}"
                    );
                    let Some(first) = first else {
                        // A normal return keeps nothing: the kernel's mask
                        // decides, which record and replay share.
                        continue;
                    };
                    assert_eq!(
                        scheduler.discard_mask(make, libc::SIGCHLD),
                        kept.flatten(),
                        "{case}"
                    );
                    let (selected, _, _) = scheduler.step3_peek().expect("a thread is runnable");
                    assert_eq!(selected, first, "{case}");
                    scheduler.run_queue.undo_tentative_pop();

                    assert!(
                        scheduler
                            .block_for_one_resource(
                                make,
                                &ResourceID::BlockedExternalContinue(pselect),
                                &Permission::RW,
                                None,
                                None,
                                &Ivar::new(),
                            )
                            .is_ok()
                    );
                    assert!(
                        !scheduler.blocked.continuation_masks.contains_key(&make),
                        "{case}"
                    );
                }
            }
        }
    }

    /// An `rt_sigsuspend` continuation is published with an unknown mask,
    /// whatever the call returned (`syscalls::helpers::continuation_mask`):
    /// whether the kernel installed its temporary mask is host-timed in record
    /// and hidden in replay. Readmitted together with another call, its thread
    /// is then no `SIGCHLD` taker and no discard decides from it, so record and
    /// replay pick the same next thread (queue order) whatever the kernel holds
    /// for it (the Codex review of da662bb2).
    #[test]
    fn an_rt_sigsuspend_continuation_is_unknown_and_picks_alike_in_record_and_replay() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let waiter = DetTid::from_raw(13);
        let child = DetTid::from_raw(173);
        let suspend = ExternalOpId::new(waiter, 40);
        let connect = ExternalOpId::new(child, 199);
        let logged = Rejoin {
            turn: 12,
            wakes: 0,
            calls: vec![(waiter, 40), (child, 199)],
            popped: None,
        };
        let mut picks = Vec::new();
        for replay in [false, true] {
            for kernel_blocked in [0, chld] {
                let case = format!("replay {replay}, kernel SigBlk {kernel_blocked:#x}");
                let dir = tempfile::tempdir().unwrap();
                let mut scheduler = gated_scheduler();
                scheduler.recordreplay_modes = true;
                for tid in [waiter, child] {
                    scheduler.thread_tree.add_child(tid, tid, true);
                    register_known_thread(&mut scheduler, tid);
                }
                background(&mut scheduler, connect, true);
                background(&mut scheduler, suspend, true);
                scheduler.blocked.external_io_blockers.remove(&waiter);
                scheduler
                    .blocked
                    .rt_sigsuspend_blockers
                    .insert(waiter, suspend);
                scheduler
                    .blocked
                    .out_of_scheduler_masks
                    .insert(waiter, Some(0));
                let mut continuation = Resources::new(waiter);
                continuation.insert(ResourceID::BlockedExternalContinue(suspend), Permission::RW);
                continuation.blocked_signal_mask_unknown = true;
                scheduler.next_turns.get_mut(&waiter).unwrap().req = Ivar::full(Ok(continuation));
                let mut kernel = signal_state(chld, 0);
                kernel.blocked = kernel_blocked;
                scheduler.test_kernel_signal_states.insert(waiter, kernel);
                assert!(scheduler.note_group_send(waiter, Signal::SIGCHLD, false));
                scheduler.blocked.sigchld_takers.insert(waiter);
                scheduler.turn = 12;
                if replay {
                    replaying(&mut scheduler, std::slice::from_ref(&logged));
                } else {
                    scheduler.rejoin_writer = Some(RejoinWriter::create(dir.path()).unwrap());
                }

                assert!(scheduler.step2c_process_io_blockers().is_ok(), "{case}");
                for tid in [waiter, child] {
                    assert!(scheduler.run_queue.contains_tid(tid), "{case}");
                }
                assert_eq!(
                    scheduler.blocked.continuation_masks.get(&waiter),
                    Some(&None),
                    "{case}"
                );
                assert_eq!(
                    scheduler.thread_signal_mask_for(waiter, libc::SIGCHLD),
                    None,
                    "{case}"
                );
                assert_eq!(
                    scheduler.discard_mask(waiter, libc::SIGUSR1),
                    None,
                    "{case}"
                );
                let (selected, _, _) = scheduler.step3_peek().expect("a thread is runnable");
                scheduler.run_queue.undo_tentative_pop();
                picks.push(selected);
            }
        }
        assert!(picks.iter().all(|pick| *pick == child), "{picks:?}");
    }

    /// A kept continuation mask also ends at a `VforkFailed` grant and when
    /// its thread retires.
    #[test]
    fn a_kept_continuation_mask_ends_at_vfork_failed_and_at_retirement() {
        let thread = DetTid::from_raw(7);
        let op = ExternalOpId::new(thread, 3);
        let mut scheduler = gated_scheduler();
        scheduler.thread_tree.add_child(thread, thread, true);
        register_known_thread(&mut scheduler, thread);
        scheduler.blocked.continuation_masks.insert(thread, Some(0));
        assert!(
            scheduler
                .block_for_one_resource(
                    thread,
                    &ResourceID::VforkFailed(op),
                    &Permission::RW,
                    None,
                    None,
                    &Ivar::new(),
                )
                .is_ok()
        );
        assert!(!scheduler.blocked.continuation_masks.contains_key(&thread));

        scheduler.blocked.continuation_masks.insert(thread, None);
        scheduler.logically_kill_thread(&thread, &thread, MmId::initial(thread));
        assert!(!scheduler.blocked.continuation_masks.contains_key(&thread));
    }

    /// A5 step 2b: the first SIGCHLD taker is chosen by the mask its thread
    /// published in place of `SigBlk`, and by the kernel's under a private
    /// mask or once the mask is withdrawn.
    #[test]
    fn the_first_sigchld_taker_reads_the_mask_its_thread_published() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let leader = DetTid::from_raw(100);
        let first = DetTid::from_raw(101);
        let mm = MmId::initial(DetPid::from_raw(100));
        let mut scheduler = gated_scheduler();
        let futex = FutexID::private(mm, 0x404110);
        scheduler.thread_tree.add_child(leader, leader, true);
        scheduler.thread_tree.add_child(leader, first, false);
        for thread in [leader, first] {
            register_known_thread(&mut scheduler, thread);
            scheduler.sleep_futex_waiter(&thread, futex, None, u32::MAX, Some(signal_watch(chld)));
            scheduler
                .test_kernel_signal_states
                .insert(thread, signal_state(chld, 0));
        }
        assert!(scheduler.note_group_send(first, Signal::SIGCHLD, false));
        scheduler.wake_signaled_guest(first, Signal::SIGCHLD);
        assert_eq!(
            scheduler.first_sigchld_taker(),
            Some(first),
            "SigBlk leaves it unblocked"
        );
        let mut blocking = signal_state(chld, 0);
        blocking.blocked = chld;
        scheduler.test_kernel_signal_states.insert(first, blocking);
        assert_eq!(scheduler.first_sigchld_taker(), None, "SigBlk blocks it");
        assert!(scheduler.publish_signal_mask(first, mm, Some(0)));
        assert_eq!(scheduler.first_sigchld_taker(), Some(first), "published");
        assert!(scheduler.set_saved_guest_sigmask(first, Some(0)));
        assert_eq!(
            scheduler.first_sigchld_taker(),
            None,
            "a private mask: SigBlk"
        );
        assert!(scheduler.set_saved_guest_sigmask(first, None));
        assert!(scheduler.publish_signal_mask(first, mm, None));
        assert_eq!(scheduler.first_sigchld_taker(), None, "withdrawn");
    }

    /// A second `SIGCHLD` sent while the first is still pending in the
    /// process's shared queue coalesces, as Linux does not queue a standard
    /// signal already pending (`legacy_queue`): it wakes no thread and makes
    /// none a taker, so the thread the first send woke takes the one copy.
    /// Before, the second send woke its own target and marked it too, and the
    /// lower-numbered target was resumed first and took the copy (the Codex
    /// review of https://github.com/rrnewton/hermit/issues/4304). Where the
    /// window and the queue disagree, one is stale and the thread is woken,
    /// as before.
    #[test]
    fn a_coalesced_sigchld_wakes_no_thread() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let leader = DetTid::from_raw(100);
        let first = DetTid::from_raw(101);
        for (pending_before, window_open, coalesces) in [
            (true, true, true),
            (false, true, false),
            (true, false, false),
        ] {
            let case = format!("pending_before={pending_before} window_open={window_open}");
            let mut scheduler = gated_scheduler();
            let futex = FutexID::private(MmId::initial(DetPid::from_raw(100)), 0x404110);
            scheduler.thread_tree.add_child(leader, leader, true);
            scheduler.thread_tree.add_child(leader, first, false);
            for thread in [leader, first] {
                register_known_thread(&mut scheduler, thread);
                scheduler.sleep_futex_waiter(
                    &thread,
                    futex,
                    None,
                    u32::MAX,
                    Some(signal_watch(chld)),
                );
                scheduler
                    .test_kernel_signal_states
                    .insert(thread, signal_state(chld, 0));
            }
            if window_open {
                // The first send, to `first`, as `send_guest_signal` makes it.
                assert!(
                    scheduler.note_group_send(first, Signal::SIGCHLD, false),
                    "{case}"
                );
                scheduler.wake_signaled_guest(first, Signal::SIGCHLD);
                assert!(scheduler.blocked.sigchld_takers.contains(&first), "{case}");
            }
            let wakes = scheduler.note_group_send(leader, Signal::SIGCHLD, pending_before);
            assert_eq!(wakes, !coalesces, "{case}");
            if wakes {
                scheduler.wake_signaled_guest(leader, Signal::SIGCHLD);
            }
            assert_eq!(
                scheduler.is_parked_futex_waiter(leader),
                coalesces,
                "{case}"
            );
            assert_eq!(
                scheduler.blocked.sigchld_takers.contains(&leader),
                !coalesces,
                "{case}"
            );
            if coalesces {
                let (selected, _, _) = scheduler.step3_peek().expect("a thread is runnable");
                assert_eq!(selected, first, "{case}");
                scheduler.run_queue.undo_tentative_pop();
            }
        }
    }

    /// The answer a woken thread's turn gets (`unblock_guest`).
    fn turn_answer(scheduler: &mut Scheduler, target: DetTid) -> Option<SchedResponse> {
        let response = scheduler.next_turns[&target].resp.clone();
        assert!(scheduler.unblock_guest(target, &response).is_ok());
        response.try_read()
    }

    /// A guest's thread-directed `SIGCHLD`, recorded in the sender's turn
    /// (`PrivateSent`), ends a parked precise-mode futex wait through the
    /// drain of the cross-task signal, as Linux ends the wait for a caught,
    /// unblocked signal pending for the thread. The waiter's turn says it was
    /// woken for a signal but commits no `SIGCHLD` to it, so its own check
    /// decides from the record (`PrivatePending`), which a flush clears. The
    /// wait stays parked for an unrecorded copy, a recorded one a host-timed
    /// source could also have posted, a recorded one that is default-ignored
    /// (under ptrace the kernel queues a copy Linux discards at generation,
    /// and the sender's turn records it), and one whose record a flush
    /// cleared (https://github.com/rrnewton/hermit/issues/4132).
    #[test]
    fn a_private_sigchld_ends_a_parked_futex_wait_through_the_drain() {
        use child_exit_sigchld::ChildExitSigchldControl;
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let deadline = LogicalTime::from_nanos(300_000_000);
        for case in ["recorded", "unrecorded", "host-timed", "default", "flushed"] {
            let mut scheduler = gated_scheduler();
            let (target, futex) = parked_futex_target(&mut scheduler);
            if case == "host-timed" {
                scheduler.record_host_timed_signals(target, HostTimedSignalScope::Caller, chld);
            }
            scheduler.sleep_futex_waiter(
                &target,
                futex,
                Some(deadline),
                u32::MAX,
                Some(signal_watch(chld)),
            );
            let caught = if case == "default" { 0 } else { chld };
            scheduler
                .test_kernel_signal_states
                .insert(target, signal_state(caught, 0));
            if case != "unrecorded" {
                scheduler.child_exit_sigchld_control(
                    target,
                    ChildExitSigchldControl::PrivateSent { target },
                );
            }
            if case == "flushed" {
                scheduler.child_exit_sigchld_control(target, ChildExitSigchldControl::Flushed);
            }
            scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGCHLD));
            scheduler.drain_pending_cross_task_signals();
            if case == "recorded" {
                assert!(!scheduler.is_parked_futex_waiter(target), "{case}");
                assert_eq!(
                    scheduler.inbound_signals(target),
                    vec![SigWrapper::from(Signal::SIGCHLD)],
                    "{case}"
                );
                assert!(
                    matches!(
                        turn_answer(&mut scheduler, target),
                        Some(SchedResponse::Signaled(Some(signals))) if signals.is_empty()
                    ),
                    "{case}: woken for a signal, with no SIGCHLD committed"
                );
                assert!(scheduler.blocked.drain_woken_waiters.is_empty());
                continue;
            }
            assert!(scheduler.is_parked_futex_waiter(target), "{case}");
            assert!(!scheduler.run_queue.contains_tid(target), "{case}");
            assert!(scheduler.inbound_signals(target).is_empty(), "{case}");
            assert_eq!(
                scheduler.blocked.timed_waiters.iter().collect::<Vec<_>>(),
                vec![(deadline, TimedEvent::ThreadEvt(target))],
                "{case}"
            );
        }
    }

    /// The drain marks a futex waiter only when it actually unblocked it: a
    /// thread held at a happens-before gate is left held
    /// (`force_unblock_thread_at`), and a mark left on it would outlive the
    /// wake it describes (the Claude re-check of
    /// https://github.com/rrnewton/hermit/issues/4132).
    #[test]
    fn a_futex_waiter_held_at_a_gate_is_not_marked_as_drain_woken() {
        use child_exit_sigchld::ChildExitSigchldControl;
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let mut scheduler = gated_scheduler();
        let (target, futex) = parked_futex_target(&mut scheduler);
        scheduler.sleep_futex_waiter(&target, futex, None, u32::MAX, Some(signal_watch(chld)));
        scheduler
            .test_kernel_signal_states
            .insert(target, signal_state(chld, 0));
        scheduler
            .child_exit_sigchld_control(target, ChildExitSigchldControl::PrivateSent { target });
        let mut hb = hb_runtime(HB_GATE_SPEC);
        hb.parked.insert(target);
        scheduler.happens_before = Some(hb);
        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGCHLD));
        scheduler.drain_pending_cross_task_signals();
        assert!(scheduler.blocked.drain_woken_waiters.is_empty());
    }

    /// A `SIGCHLD` the drain merges into the batch of a futex waiter it
    /// already woke (`WaitidSignalRequest::Pending`) is not committed either:
    /// the waiter's turn carries the `SIGUSR1` it was woken for and no
    /// `SIGCHLD`. A `SIGCHLD` the scheduler sends at a commit point
    /// (`wake_signaled_guest`, https://github.com/rrnewton/hermit/issues/4005)
    /// is committed, to a parked waiter and to one the drain already woke,
    /// for `SIGUSR1` or for a guest's recorded private `SIGCHLD`, that has not
    /// yet run its turn (the Claude re-check of
    /// https://github.com/rrnewton/hermit/issues/4132: that commit was lost).
    #[test]
    fn only_a_scheduler_sent_sigchld_is_committed_to_a_woken_futex_waiter() {
        use child_exit_sigchld::ChildExitSigchldControl;
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        let usr1_signal = SigWrapper::from(Signal::SIGUSR1);
        let chld_signal = SigWrapper::from(Signal::SIGCHLD);
        for case in [
            "merged",
            "parked",
            "woken for SIGUSR1",
            "woken for a private SIGCHLD",
        ] {
            let mut scheduler = gated_scheduler();
            let (target, futex) = parked_futex_target(&mut scheduler);
            scheduler.sleep_futex_waiter(
                &target,
                futex,
                None,
                u32::MAX,
                Some(signal_watch(chld | usr1)),
            );
            scheduler
                .test_kernel_signal_states
                .insert(target, signal_state(chld | usr1, 0));
            let expected = match case {
                "merged" => {
                    scheduler.notify_signal_pending(target, usr1_signal);
                    scheduler.drain_pending_cross_task_signals();
                    scheduler.notify_signal_pending(target, chld_signal);
                    scheduler.drain_pending_cross_task_signals();
                    assert_eq!(
                        scheduler.inbound_signals(target),
                        vec![usr1_signal, chld_signal],
                        "the merge put SIGCHLD in the batch"
                    );
                    vec![usr1_signal]
                }
                "parked" => {
                    scheduler.wake_signaled_guest(target, Signal::SIGCHLD);
                    vec![chld_signal]
                }
                "woken for SIGUSR1" => {
                    scheduler.notify_signal_pending(target, usr1_signal);
                    scheduler.drain_pending_cross_task_signals();
                    assert!(!scheduler.is_parked_futex_waiter(target));
                    scheduler.wake_signaled_guest(target, Signal::SIGCHLD);
                    vec![usr1_signal, chld_signal]
                }
                _ => {
                    scheduler.child_exit_sigchld_control(
                        target,
                        ChildExitSigchldControl::PrivateSent { target },
                    );
                    scheduler.notify_signal_pending(target, chld_signal);
                    scheduler.drain_pending_cross_task_signals();
                    assert!(!scheduler.is_parked_futex_waiter(target));
                    scheduler.wake_signaled_guest(target, Signal::SIGCHLD);
                    vec![chld_signal]
                }
            };
            let answer = turn_answer(&mut scheduler, target);
            assert!(
                matches!(&answer, Some(SchedResponse::Signaled(Some(signals))) if *signals == expected),
                "{case}: {answer:?}"
            );
        }
    }

    /// A recorded private `SIGCHLD` does not end a restartable internal IO
    /// poll: R2 exempts it only for precise futex waits, and
    /// `futex_wait_held_signals`, which the poll shares, still holds it
    /// (https://github.com/rrnewton/hermit/issues/4132).
    #[test]
    fn a_recorded_private_sigchld_does_not_end_a_restartable_internal_read_poll() {
        use child_exit_sigchld::ChildExitSigchldControl;
        let mut scheduler = gated_scheduler();
        let target = restartable_read_poller(&mut scheduler);
        assert!(scheduler.restartable_internal_io_signals(target).is_some());
        scheduler.test_kernel_signal_states.insert(
            target,
            KernelSignalState {
                caught: kernel_signal_bit(libc::SIGCHLD),
                ..Default::default()
            },
        );
        scheduler
            .child_exit_sigchld_control(target, ChildExitSigchldControl::PrivateSent { target });
        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGCHLD));
        scheduler.drain_pending_cross_task_signals();
        assert!(scheduler.inbound_signals(target).is_empty());
        let resources = scheduler.next_turns[&target]
            .req
            .try_read()
            .and_then(Result::ok)
            .expect("the poller keeps its request");
        assert!(
            resources
                .resources
                .contains_key(&ResourceID::InternalIOPolling)
        );
    }

    /// A signal recorded as host-timed for a process, as `PR_SET_PDEATHSIG`
    /// records its signal in the arming thread's turn, never ends a parked
    /// precise-mode futex wait of any thread of that process, although the
    /// waiter catches it, and a later disarm does not remove the record. A
    /// forked child's wait still ends for it; a container-wide record holds
    /// it in every process (https://github.com/rrnewton/hermit/issues/3146).
    #[test]
    fn a_host_timed_signal_never_ends_a_parked_futex_wait_of_its_process() {
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        let usr2 = kernel_signal_bit(libc::SIGUSR2);
        let term = kernel_signal_bit(libc::SIGTERM);
        let (mut scheduler, parent, creator, child) = sigchld_family(libc::SIGCHLD);
        for thread in [parent, creator, child] {
            assert_eq!(scheduler.host_timed_signals(thread), 0, "nothing armed yet");
        }

        // The creator, not its process's leader, arms SIGUSR1.
        assert_eq!(
            scheduler.record_host_timed_signals(creator, HostTimedSignalScope::Caller, usr1),
            usr1
        );
        assert_eq!(
            scheduler.host_timed_signals(parent),
            usr1,
            "the record covers every thread of the arming process"
        );
        assert_eq!(scheduler.host_timed_signals(creator), usr1);
        assert_eq!(
            scheduler.host_timed_signals(child),
            0,
            "a forked child starts without its parent's record"
        );
        // A disarm (signal 0) records nothing and removes nothing.
        assert_eq!(
            scheduler.record_host_timed_signals(parent, HostTimedSignalScope::Caller, 0),
            usr1
        );
        // A container-wide source holds its signal in every process.
        assert_eq!(
            scheduler.record_host_timed_signals(child, HostTimedSignalScope::Container, usr2),
            usr2
        );
        assert_eq!(scheduler.host_timed_signals(parent), usr1 | usr2);
        assert_eq!(scheduler.host_timed_signals(child), usr2);

        // Parked futex waiters that catch all three signals: only SIGTERM ends
        // the parent's wait, and SIGUSR1 and SIGTERM end the child's.
        for (thread, mm_pid) in [(parent, 100), (child, 200)] {
            scheduler.sleep_futex_waiter(
                &thread,
                FutexID::private(MmId::initial(DetPid::from_raw(mm_pid)), 0x404110),
                None,
                u32::MAX,
                Some(signal_watch(usr1 | usr2 | term)),
            );
            scheduler
                .test_kernel_signal_states
                .insert(thread, signal_state(usr1 | usr2 | term, 0));
        }
        assert_eq!(
            scheduler.parked_futex_interrupting_signals(parent, 0),
            Some(term)
        );
        assert_eq!(
            scheduler.parked_futex_interrupting_signals(child, 0),
            Some(usr1 | term)
        );
    }

    /// A launch that may pass the guest a terminal records every signal a
    /// terminal sends as host-timed for every process before the guest runs:
    /// SIGHUP and SIGCONT for a hangup, SIGINT, SIGQUIT and SIGTSTP for the
    /// interrupt, quit and suspend characters, SIGWINCH for a resize, and
    /// SIGTTIN and SIGTTOU for a background read or write. So a parked
    /// precise-mode futex wait that catches all of them ends for none, in the
    /// first process and in a forked child alike. Nothing is recorded without
    /// that terminal, or on a backend whose blocked waits do not read the
    /// kernel's signal state (https://github.com/rrnewton/hermit/issues/3146).
    /// Round-11 finding "Terminal resize remains an admitted host-timed
    /// interruption" on https://github.com/rrnewton/hermit/pull/3361: only
    /// SIGHUP and SIGCONT were recorded, so a resize ended such a wait at a
    /// turn the host chose.
    #[test]
    fn a_launch_that_may_pass_a_terminal_holds_the_terminal_signals_from_the_start() {
        let terminal = [
            libc::SIGHUP,
            libc::SIGCONT,
            libc::SIGINT,
            libc::SIGQUIT,
            libc::SIGTSTP,
            libc::SIGWINCH,
            libc::SIGTTIN,
            libc::SIGTTOU,
        ]
        .into_iter()
        .fold(0, |set, signal| set | kernel_signal_bit(signal));
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        let gated = |guest_may_inherit_a_terminal| {
            Config {
                sequentialize_threads: true,
                guest_may_inherit_a_terminal,
                ..Config::default()
            }
            .with_backend(|backend| {
                detcore_model::config::set_kernel_signal_facts(backend, true);
                backend.delivers_preemption_timer_events = false;
                backend.runs_guest_code_between_injections = false;
            })
        };
        assert_eq!(startup_host_timed_signals(&gated(true)), terminal);
        assert_eq!(startup_host_timed_signals(&gated(false)), 0);
        assert_eq!(
            startup_host_timed_signals(
                &Config {
                    guest_may_inherit_a_terminal: true,
                    ..Config::default()
                }
                .with_backend(|backend| {
                    detcore_model::config::set_kernel_signal_facts(backend, false)
                })
            ),
            0,
            "a backend whose waits do not read the kernel's signal state records nothing"
        );

        let mut scheduler = Scheduler::new(&gated(true));
        assert!(scheduler.models_signal_targets);
        let parent = DetTid::from_raw(100);
        let child = DetTid::from_raw(200);
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, child, true);
        for thread in [parent, child] {
            register_known_thread(&mut scheduler, thread);
        }
        for (thread, mm_pid) in [(parent, 100), (child, 200)] {
            assert_eq!(scheduler.host_timed_signals(thread), terminal);
            scheduler.sleep_futex_waiter(
                &thread,
                FutexID::private(MmId::initial(DetPid::from_raw(mm_pid)), 0x404110),
                None,
                u32::MAX,
                Some(signal_watch(terminal | usr1)),
            );
            scheduler
                .test_kernel_signal_states
                .insert(thread, signal_state(terminal | usr1, 0));
            assert_eq!(
                scheduler.parked_futex_interrupting_signals(thread, 0),
                Some(usr1),
                "only SIGUSR1 ends the wait of {thread:?}"
            );
        }

        let scheduler = Scheduler::new(&gated(false));
        assert_eq!(scheduler.host_timed_signals(parent), 0);
    }

    /// A parent process 100 whose second thread 101 created child process 200
    /// with `exit_signal`, on the gated scheduler.
    fn sigchld_family(exit_signal: libc::c_int) -> (Scheduler, DetTid, DetTid, DetTid) {
        let mut scheduler = gated_scheduler();
        let parent = DetTid::from_raw(100);
        let creator = DetTid::from_raw(101);
        let child = DetTid::from_raw(200);
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, creator, false);
        scheduler.thread_tree.add_child_with_wait_metadata(
            creator,
            child,
            true,
            false,
            exit_signal,
        );
        for thread in [parent, creator, child] {
            register_known_thread(&mut scheduler, thread);
        }
        (scheduler, parent, creator, child)
    }

    /// The inputs of a process-directed signal the leader sends to its own
    /// process read each sibling from the schedule
    /// (https://github.com/rrnewton/hermit/issues/4034): a stopped thread's
    /// `SigBlk`; the guest's own mask while Detcore holds the thread under a
    /// private one (`saved_guest_sigmasks`); `blocked & !set` for an
    /// `rt_sigtimedwait` poller; external I/O and a real `rt_sigsuspend` as
    /// outside the schedule; and a logically killed thread as exit-granted.
    #[test]
    fn own_process_signal_inputs_read_each_sibling_from_the_schedule() {
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        let usr2 = kernel_signal_bit(libc::SIGUSR2);
        let (mut scheduler, parent, creator, _child) = sigchld_family(libc::SIGCHLD);
        let state = |scheduler: &Scheduler| scheduler.own_process_signal_inputs(parent).siblings;
        scheduler.test_kernel_signal_states.insert(
            creator,
            KernelSignalState {
                blocked: usr1 | usr2,
                ..Default::default()
            },
        );
        assert_eq!(
            state(&scheduler),
            vec![(creator, SiblingSignalState::InSchedule(Some(usr1 | usr2)))]
        );
        assert!(scheduler.set_sigtimedwait_set(creator, Some(usr1)));
        assert_eq!(
            state(&scheduler),
            vec![(creator, SiblingSignalState::InSchedule(Some(usr2)))],
            "a poller takes a signal in its set whatever its mask"
        );
        assert!(scheduler.set_sigtimedwait_set(creator, None));
        assert!(scheduler.set_saved_guest_sigmask(creator, Some(usr2)));
        assert_eq!(
            state(&scheduler),
            vec![(creator, SiblingSignalState::InSchedule(Some(usr2)))],
            "the guest's own mask, not Detcore's private one"
        );
        assert!(scheduler.set_saved_guest_sigmask(creator, None));
        let op = ExternalOpId {
            tid: creator,
            sequence: 1,
        };
        scheduler.blocked.external_io_blockers.insert(creator, op);
        assert_eq!(
            state(&scheduler),
            vec![(creator, SiblingSignalState::OutOfSchedule)]
        );
        scheduler.blocked.external_io_blockers.remove(&creator);
        scheduler.blocked.rt_sigsuspend_blockers.insert(creator, op);
        assert_eq!(
            state(&scheduler),
            vec![(creator, SiblingSignalState::OutOfSchedule)]
        );
        scheduler.blocked.rt_sigsuspend_blockers.remove(&creator);
        scheduler.logically_killed_threads.insert(creator);
        assert_eq!(
            state(&scheduler),
            vec![(creator, SiblingSignalState::ExitGranted)]
        );
    }

    /// An unreaped child whose exit signal is neither 0 nor SIGCHLD names that
    /// signal in its parent's inputs, and a SIGCHLD child names nothing.
    #[test]
    fn own_process_signal_inputs_name_a_childs_foreign_exit_signal() {
        let (scheduler, parent, _creator, _child) = sigchld_family(libc::SIGUSR2);
        assert_eq!(
            scheduler
                .own_process_signal_inputs(parent)
                .foreign_exit_signals,
            kernel_signal_bit(libc::SIGUSR2)
        );
        let (scheduler, parent, _creator, _child) = sigchld_family(libc::SIGCHLD);
        assert_eq!(
            scheduler
                .own_process_signal_inputs(parent)
                .foreign_exit_signals,
            0
        );
    }

    /// A signal the scheduler sent to a process counts for its own-process
    /// admission only while it is in the process's shared queue, where its
    /// process-directed copy waits: a guest's copy of the same number taken
    /// from a thread's own queue does not settle it, and a copy merged into an
    /// earlier one (Hermit's `kill()` copy for a POSIX timer merges with a
    /// pending standard signal), taken by sigtimedwait or discarded by
    /// SIG_IGN, gone from the queue, refuses nothing. An unreadable queue keeps the record
    /// (https://github.com/rrnewton/hermit/issues/4122).
    #[test]
    fn a_scheduler_sent_signal_counts_while_it_is_in_the_shared_queue() {
        let hup = kernel_signal_bit(libc::SIGHUP);
        let (mut scheduler, parent, creator, _child) = sigchld_family(libc::SIGCHLD);
        let shared = |scheduler: &mut Scheduler, pending: u64| {
            scheduler.test_kernel_signal_states.insert(
                parent,
                KernelSignalState {
                    shared_pending: pending,
                    ..Default::default()
                },
            );
        };
        let undelivered = |scheduler: &Scheduler| {
            scheduler
                .own_process_signal_inputs(parent)
                .undelivered_scheduler_signals
        };
        shared(&mut scheduler, hup);
        assert_eq!(undelivered(&scheduler), 0, "nothing sent yet");
        scheduler.note_scheduler_signal_sent(creator, libc::SIGHUP);
        assert_eq!(undelivered(&scheduler), hup);
        shared(&mut scheduler, kernel_signal_bit(libc::SIGUSR1) | hup);
        assert_eq!(undelivered(&scheduler), hup, "only what the scheduler sent");
        shared(&mut scheduler, 0);
        assert_eq!(undelivered(&scheduler), 0, "gone from the shared queue");
        scheduler.test_kernel_signal_states.clear();
        assert_eq!(undelivered(&scheduler), hup, "an unreadable queue keeps it");
    }

    /// A guest's send of SIGSTKFLT, Reverie's timer marker, is recorded for
    /// every process and never forgotten.
    #[test]
    fn a_guest_marker_signal_send_is_recorded_for_every_process() {
        let (mut scheduler, parent, _creator, child) = sigchld_family(libc::SIGCHLD);
        assert!(
            !scheduler
                .own_process_signal_inputs(parent)
                .guest_marker_signal
        );
        scheduler.record_guest_marker_signal();
        assert!(
            scheduler
                .own_process_signal_inputs(parent)
                .guest_marker_signal
        );
        assert!(
            scheduler
                .own_process_signal_inputs(child)
                .guest_marker_signal
        );
    }

    fn park_for_sigchld(scheduler: &mut Scheduler, thread: DetTid, unblocked: u64) {
        let futex = FutexID::private(MmId::initial(DetPid::from_raw(100)), 0x404110);
        scheduler.sleep_futex_waiter(
            &thread,
            futex,
            None,
            u32::MAX,
            Some(signal_watch(unblocked)),
        );
        scheduler
            .test_kernel_signal_states
            .insert(thread, signal_state(kernel_signal_bit(libc::SIGCHLD), 0));
    }

    /// A child's death itself wakes no parked futex waiter of its parent,
    /// although the waiter catches `SIGCHLD`: a child killed by a signal, or
    /// leaving through `exit` in its last thread, has no `ChildExit` timer, and
    /// the kernel posts its own `SIGCHLD` at a moment set by host timing, so the
    /// signal stays pending until the waiter's call returns for another reason.
    /// Before, the death made the signal eligible and the drain woke that
    /// waiter (https://github.com/rrnewton/hermit/issues/3146). The scheduler
    /// still names the thread Linux would give it to (`kernel_sigchld_target`),
    /// the child's creator first, and the `SIGCHLD` a `ChildExit` timer sends to
    /// that thread wakes it, and only it
    /// (https://github.com/rrnewton/hermit/issues/4005).
    #[test]
    fn a_child_exit_wakes_only_the_parked_futex_waiter_its_timer_signals() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let (mut scheduler, parent, creator, child) = sigchld_family(libc::SIGCHLD);
        park_for_sigchld(&mut scheduler, parent, chld);
        park_for_sigchld(&mut scheduler, creator, chld);
        assert_eq!(
            scheduler.kernel_sigchld_target(parent, creator),
            Some(creator)
        );

        scheduler.logically_kill_thread(&child, &child, MmId::initial(child));
        scheduler.drain_pending_cross_task_signals();
        assert!(scheduler.is_parked_futex_waiter(parent));
        assert!(scheduler.is_parked_futex_waiter(creator));
        assert!(scheduler.pending_cross_task_signals.is_empty());
        assert!(scheduler.inbound_signals(parent).is_empty());
        assert!(scheduler.inbound_signals(creator).is_empty());

        // The SIGCHLD a `ChildExit` timer sends to the creator wakes it, and
        // leaves the leader parked.
        scheduler.wake_signaled_guest(creator, Signal::SIGCHLD);
        assert!(!scheduler.is_parked_futex_waiter(creator));
        assert_eq!(
            scheduler.inbound_signals(creator),
            vec![SigWrapper::from(Signal::SIGCHLD)]
        );
        assert!(scheduler.is_parked_futex_waiter(parent));
        assert!(scheduler.inbound_signals(parent).is_empty());
    }

    /// The kernel gives a shared-queue `SIGCHLD` to the first thread that does
    /// not block it, the child's creator first, whether that thread is parked or
    /// running, and `kernel_sigchld_target` names that thread: a `ChildExit`
    /// timer signals it. No parked waiter is woken for the child's death,
    /// whichever thread is the target (https://github.com/rrnewton/hermit/issues/3146).
    #[test]
    fn a_child_exit_sigchld_goes_to_the_first_thread_that_does_not_block_it() {
        let chld = kernel_signal_bit(libc::SIGCHLD);

        // The creator runs and does not block SIGCHLD: it takes the signal, and
        // the leader's wait is left alone.
        let (mut scheduler, parent, creator, child) = sigchld_family(libc::SIGCHLD);
        park_for_sigchld(&mut scheduler, parent, chld);
        scheduler
            .test_kernel_signal_states
            .insert(creator, signal_state(chld, 0));
        assert_eq!(
            scheduler.kernel_sigchld_target(parent, creator),
            Some(creator)
        );
        scheduler.logically_kill_thread(&child, &child, MmId::initial(child));
        scheduler.drain_pending_cross_task_signals();
        assert!(scheduler.is_parked_futex_waiter(parent));
        assert!(scheduler.inbound_signals(parent).is_empty());

        // The creator blocks SIGCHLD and the leader runs without blocking it: the
        // leader comes first in thread-ID order and takes it, so a waiter after
        // it is not woken.
        let (mut scheduler, parent, creator, child) = sigchld_family(libc::SIGCHLD);
        let waiter = DetTid::from_raw(102);
        scheduler.thread_tree.add_child(parent, waiter, false);
        register_known_thread(&mut scheduler, waiter);
        park_for_sigchld(&mut scheduler, waiter, chld);
        park_for_sigchld(&mut scheduler, creator, 0);
        scheduler
            .test_kernel_signal_states
            .insert(parent, signal_state(chld, 0));
        assert_eq!(
            scheduler.kernel_sigchld_target(parent, creator),
            Some(parent)
        );
        scheduler.logically_kill_thread(&child, &child, MmId::initial(child));
        scheduler.drain_pending_cross_task_signals();
        assert!(scheduler.is_parked_futex_waiter(waiter));
        assert!(scheduler.is_parked_futex_waiter(creator));

        // Every thread blocks it: nobody is chosen and nobody is woken.
        let (mut scheduler, parent, creator, child) = sigchld_family(libc::SIGCHLD);
        park_for_sigchld(&mut scheduler, creator, 0);
        scheduler.test_kernel_signal_states.insert(
            parent,
            KernelSignalState {
                blocked: chld,
                ..signal_state(chld, 0)
            },
        );
        assert_eq!(scheduler.kernel_sigchld_target(parent, creator), None);
        scheduler.logically_kill_thread(&child, &child, MmId::initial(child));
        scheduler.drain_pending_cross_task_signals();
        assert!(scheduler.is_parked_futex_waiter(creator));
    }

    /// A timer's process-directed signal is sent to a thread that does not
    /// block it, since Linux gives it to no other, and the scheduler wakes the
    /// thread it names. The thread `select_signal_target` drew keeps it if it
    /// does not block it; when every thread blocks it, the drawn thread is
    /// kept, and `kill` leaves it in the shared queue. Before, a SIGALRM drawn
    /// under `--chaos-target-races` for a worker that blocks it woke that
    /// worker, and the thread in `pause` slept forever
    /// (https://github.com/rrnewton/hermit/issues/4320).
    #[test]
    fn a_timer_signal_goes_to_a_thread_that_does_not_block_it() {
        let alrm = kernel_signal_bit(libc::SIGALRM);
        let state = |blocked: u64| KernelSignalState {
            blocked,
            ..signal_state(alrm, 0)
        };
        let (mut scheduler, leader, worker, _child) = sigchld_family(libc::SIGCHLD);
        assert!(scheduler.models_signal_targets);
        scheduler.test_kernel_signal_states.insert(leader, state(0));
        scheduler
            .test_kernel_signal_states
            .insert(worker, state(alrm));
        assert_eq!(
            scheduler.timer_signal_target(leader, worker, Signal::SIGALRM),
            leader,
            "the worker blocks SIGALRM, the leader does not"
        );
        assert_eq!(
            scheduler.timer_signal_target(leader, leader, Signal::SIGALRM),
            leader
        );

        scheduler.test_kernel_signal_states.insert(worker, state(0));
        assert_eq!(
            scheduler.timer_signal_target(leader, worker, Signal::SIGALRM),
            worker,
            "a drawn thread that does not block it keeps it"
        );

        scheduler
            .test_kernel_signal_states
            .insert(leader, state(alrm));
        scheduler
            .test_kernel_signal_states
            .insert(worker, state(alrm));
        assert_eq!(
            scheduler.timer_signal_target(leader, worker, Signal::SIGALRM),
            worker,
            "every thread blocks it: the drawn thread is kept"
        );

        // A second candidate: the fallback takes the lowest thread ID that
        // does not block it.
        let third = DetTid::from_raw(102);
        scheduler.thread_tree.add_child(leader, third, false);
        register_known_thread(&mut scheduler, third);
        scheduler.test_kernel_signal_states.insert(leader, state(0));
        scheduler.test_kernel_signal_states.insert(third, state(0));
        assert_eq!(
            scheduler.timer_signal_target(leader, worker, Signal::SIGALRM),
            leader,
            "the lowest thread that does not block it"
        );

        // A thread asleep in rt_sigsuspend whose mask admits the signal comes
        // first, ahead of a drawn thread that does not block it either: the
        // kernel wakes the sleeper while the drawn thread is held in a ptrace
        // stop (Claude review of https://github.com/rrnewton/hermit/pull/4331).
        let op = ExternalOpId::new(third, 1);
        commit_out_of_scheduler_call(
            &mut scheduler,
            third,
            ResourceID::BlockingRtSigsuspend(op),
            Some(0),
        );
        scheduler.test_kernel_signal_states.insert(worker, state(0));
        assert_eq!(
            scheduler.timer_signal_target(leader, worker, Signal::SIGALRM),
            third,
            "the rt_sigsuspend sleeper, not the drawn worker"
        );
        assert_eq!(
            scheduler.timer_signal_target(leader, leader, Signal::SIGALRM),
            third,
            "nor the drawn leader"
        );

        scheduler.models_signal_targets = false;
        let reads = scheduler
            .test_kernel_mask_reads
            .load(std::sync::atomic::Ordering::Relaxed);
        assert_eq!(
            scheduler.timer_signal_target(leader, worker, Signal::SIGALRM),
            worker,
            "without signal-target modelling the drawn thread is kept"
        );
        assert_eq!(
            scheduler
                .test_kernel_mask_reads
                .load(std::sync::atomic::Ordering::Relaxed),
            reads,
            "and no mask is read"
        );
    }

    /// A signal the scheduler sent while every thread blocked it waits in the
    /// process's shared queue, and a call that begins under a mask admitting
    /// it is ended by it at once. Such a call is armed for the release
    /// barrier, so it rejoins at a fixed point rather than as a completion
    /// only the host observes, which run mode held behind a thread spinning
    /// on `sched_yield` (https://github.com/rrnewton/hermit/issues/4234).
    ///
    /// Not armed:
    /// - when the call's mask blocks the signal;
    /// - when the process does not catch it (it does not end `sigsuspend`);
    /// - when a thread has taken it, or the shared queue no longer holds it,
    ///   as after SIG_IGN, `sigwaitinfo`, a signalfd read, an exec or a
    ///   sibling's dequeue; arming then held the barrier for a continuation
    ///   that never came (Claude review of
    ///   https://github.com/rrnewton/hermit/pull/4314);
    /// - when a sibling's `rt_sigtimedwait` set could take it first, or a
    ///   signalfd covers it and a sibling's background call reads a signalfd.
    ///   A signalfd that only exists, a background call that reads none, an
    ///   ended read, or another process's read does not count (Claude and
    ///   Codex re-checks of https://github.com/rrnewton/hermit/pull/4314);
    /// - for a later call once the armed call took it.
    ///
    /// Still armed after a thread took a copy from its own queue, which Linux
    /// dequeues first: the shared copy remains (Codex review of the same). And
    /// a later call is armed again while the signal is still pending, as when
    /// another signal ended the first (Claude re-check of the same).
    #[test]
    fn a_call_that_begins_with_a_scheduler_signal_waiting_is_armed() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let family = |caught: u64, pending: u64| {
            let (mut scheduler, parent, creator, _child) = sigchld_family(libc::SIGCHLD);
            scheduler
                .test_signal_masks
                .insert((parent, None, "SigCgt"), caught);
            for thread in [parent, creator] {
                scheduler.test_kernel_signal_states.insert(
                    thread,
                    KernelSignalState {
                        blocked: chld,
                        shared_pending: pending,
                        ..signal_state(caught, 0)
                    },
                );
            }
            scheduler.note_signal_left_in_shared_queue(parent, libc::SIGCHLD);
            (scheduler, parent, creator)
        };
        let begin = |scheduler: &mut Scheduler, thread: DetTid, mask: u64| {
            let op = ExternalOpId::new(thread, 1);
            commit_out_of_scheduler_call(
                scheduler,
                thread,
                ResourceID::BlockingRtSigsuspend(op),
                Some(mask),
            );
            assert_eq!(
                scheduler.blocked.rt_sigsuspend_blockers.get(&thread),
                Some(&op)
            );
            let armed = scheduler.blocked.signaled_background.contains(&thread);
            assert_eq!(armed, scheduler.blocked.sigchld_ready.contains(&thread));
            armed
        };

        let (mut scheduler, parent, creator) = family(chld, chld);
        assert!(
            begin(&mut scheduler, creator, 0),
            "caught, admitted, pending: armed"
        );
        for thread in [parent, creator] {
            if let Some(state) = scheduler.test_kernel_signal_states.get_mut(&thread) {
                state.shared_pending = 0;
            }
        }
        assert!(
            !begin(&mut scheduler, parent, 0),
            "the armed call took the signal: a later call is not armed"
        );
        assert_eq!(
            scheduler.shared_queue_scheduler_signals.get(&parent),
            Some(&0),
            "and the record forgets it"
        );

        let (mut scheduler, parent, creator) = family(chld, chld);
        assert!(begin(&mut scheduler, creator, 0), "armed");
        assert!(
            begin(&mut scheduler, parent, 0),
            "another signal ended the armed call and this one is still pending: \
             the later call it ends is armed too"
        );

        let (mut scheduler, _, creator) = family(chld, chld);
        assert!(
            !begin(&mut scheduler, creator, chld),
            "its mask blocks the signal"
        );

        let (mut scheduler, _, creator) = family(0, chld);
        assert!(
            !begin(&mut scheduler, creator, 0),
            "not caught: it does not end sigsuspend"
        );

        let (mut scheduler, parent, creator) = family(chld, chld);
        for thread in [parent, creator] {
            if let Some(state) = scheduler.test_kernel_signal_states.get_mut(&thread) {
                state.shared_pending = 0;
            }
        }
        scheduler.note_process_signal_taken(parent, libc::SIGCHLD);
        assert_eq!(
            scheduler.shared_queue_scheduler_signals.get(&parent),
            Some(&0),
            "a thread has taken it from the shared queue: the record forgets it"
        );
        assert!(!begin(&mut scheduler, creator, 0), "a thread has taken it");

        let (mut scheduler, parent, creator) = family(chld, chld);
        scheduler.note_process_signal_taken(parent, libc::SIGCHLD);
        assert_eq!(
            scheduler.shared_queue_scheduler_signals.get(&parent),
            Some(&chld),
            "a thread took its own copy: the shared one, and the record, remain"
        );
        assert!(
            begin(&mut scheduler, creator, 0),
            "after a private take the shared copy still ends the call: armed"
        );

        let (mut scheduler, parent, creator) = family(chld, 0);
        assert!(
            !begin(&mut scheduler, creator, 0),
            "the shared queue no longer holds it"
        );
        assert_eq!(
            scheduler.shared_queue_scheduler_signals.get(&parent),
            Some(&0),
            "and the record forgets it"
        );

        let (mut scheduler, parent, creator) = family(chld, chld);
        scheduler.sigtimedwait_sets.insert(parent, chld);
        assert!(
            !begin(&mut scheduler, creator, 0),
            "an rt_sigtimedwait set could take it first"
        );

        let (mut scheduler, parent, creator) = family(chld, chld);
        scheduler.signalfd_masks.insert(parent, chld);
        assert!(
            begin(&mut scheduler, creator, 0),
            "a signalfd covers it, but no other call runs outside the schedule: armed"
        );

        let reading = |tagged: bool, live: bool| {
            let (mut scheduler, parent, creator) = family(chld, chld);
            scheduler.signalfd_masks.insert(parent, chld);
            let op = ExternalOpId::new(parent, 7);
            scheduler.blocked.external_io_blockers.insert(parent, op);
            if tagged {
                let tag = if live {
                    op
                } else {
                    ExternalOpId::new(parent, 6)
                };
                scheduler.background_signalfd_reads.insert(parent, tag);
            }
            (scheduler, creator)
        };
        let (mut scheduler, creator) = reading(true, true);
        assert!(
            !begin(&mut scheduler, creator, 0),
            "a signalfd covers it and a sibling's background call reads a signalfd"
        );
        let (mut scheduler, creator) = reading(false, false);
        assert!(
            begin(&mut scheduler, creator, 0),
            "a sibling's background call that reads no signalfd (a select, a vfork): armed"
        );
        let (mut scheduler, creator) = reading(true, false);
        assert!(
            begin(&mut scheduler, creator, 0),
            "a signalfd read that has ended, the sibling now in another call: armed"
        );

        let (mut scheduler, parent, creator) = family(chld, chld);
        let other_process = DetTid::from_raw(parent.as_raw() + 100);
        let op = ExternalOpId::new(other_process, 7);
        scheduler.signalfd_masks.insert(other_process, chld);
        scheduler
            .blocked
            .external_io_blockers
            .insert(other_process, op);
        scheduler
            .background_signalfd_reads
            .insert(other_process, op);
        assert!(
            begin(&mut scheduler, creator, 0),
            "another process's signalfd read takes from its own queue: armed"
        );
    }

    /// Commit `thread`'s request to begin a blocking call outside the runnable
    /// set, as step3 does, with `mask` the call's own temporary mask.
    fn commit_out_of_scheduler_call(
        scheduler: &mut Scheduler,
        thread: DetTid,
        rid: ResourceID,
        mask: Option<u64>,
    ) {
        scheduler.runqueue_push_back(thread);
        assert_eq!(scheduler.run_queue.tentative_pop_tid(thread), Some(thread));
        assert!(
            scheduler
                .block_for_one_resource(thread, &rid, &Permission::RW, None, mask, &Ivar::new())
                .is_err()
        );
    }

    /// An in-guest scheduler (no signal-target modelling) with the in-guest
    /// delivery gate `gate` (A5 step 3c.1b): process 100 whose threads are
    /// 100 and 101, both stopped at a request. 101's kernel `SigBlk` is
    /// `kernel`, as the in-guest runtime's mask would make it.
    fn in_guest_publication_family(gate: bool, kernel: u64) -> (Scheduler, DetTid, DetTid) {
        let mut config = Config {
            sequentialize_threads: true,
            max_timeslice: None,
            in_guest_signal_delivery: gate,
            ..Config::default()
        };
        config.backend = reverie::BackendCapabilities::LITEINST_IN_GUEST;
        let mut scheduler = Scheduler::new(&config);
        assert!(!scheduler.models_signal_targets);
        assert_eq!(scheduler.in_guest_signal_delivery, gate);
        let parent = DetTid::from_raw(100);
        let thread = DetTid::from_raw(101);
        scheduler.thread_tree.add_child(parent, parent, true);
        scheduler.thread_tree.add_child(parent, thread, false);
        for known in [parent, thread] {
            register_known_thread(&mut scheduler, known);
        }
        scheduler.test_kernel_signal_states.insert(
            thread,
            KernelSignalState {
                blocked: kernel,
                ..Default::default()
            },
        );
        (scheduler, parent, thread)
    }

    /// A request of `thread` that publishes `mask`.
    fn publishing_request(thread: DetTid, mask: Option<u64>) -> Resources {
        let mut request = Resources::new(thread);
        request.guest_signal_mask = mask;
        request
    }

    /// Under the in-guest delivery gate, every reader of a thread's mask that
    /// would otherwise take the kernel's `SigBlk` takes the mask the thread
    /// published at its latest request (`read_thread_blocked_mask_result`,
    /// and through it `thread_signal_mask` and `thread_signal_mask_for`), as
    /// does a restartable poll's filter (`under_published_mask`). With nothing
    /// published, `SigBlk`, including after a later request that publishes
    /// nothing. With the gate off, `SigBlk` throughout, as before.
    /// Mutations: the gate test removed from `read_thread_blocked_mask_result`
    /// (the kernel's mask is read under the gate), or the record made
    /// unconditional (a published mask is read with the gate off).
    #[test]
    fn under_the_gate_a_threads_mask_is_the_one_its_latest_request_published() {
        let kernel = kernel_signal_bit(libc::SIGUSR1) | kernel_signal_bit(libc::SIGCHLD);
        let published = kernel_signal_bit(libc::SIGUSR2);
        for gate in [true, false] {
            let (mut scheduler, _parent, thread) = in_guest_publication_family(gate, kernel);
            assert_eq!(
                scheduler.thread_signal_mask(thread),
                Some(kernel),
                "gate {gate}"
            );
            assert_eq!(
                scheduler.record_request_guest_mask(
                    thread,
                    &publishing_request(thread, Some(published))
                ),
                gate
            );
            let want = if gate { published } else { kernel };
            assert_eq!(scheduler.read_thread_blocked_mask_result(thread), Ok(want));
            assert_eq!(scheduler.thread_signal_mask(thread), Some(want));
            assert_eq!(
                scheduler.thread_signal_mask_for(thread, libc::SIGUSR1),
                Some(want)
            );
            let state = KernelSignalState {
                blocked: kernel,
                ..Default::default()
            };
            assert_eq!(scheduler.under_published_mask(thread, state).blocked, want);
            // A later request that publishes nothing leaves nothing published
            // under the gate: `SigBlk` again.
            assert_eq!(
                scheduler.record_request_guest_mask(thread, &publishing_request(thread, None)),
                gate
            );
            assert_eq!(
                scheduler.thread_signal_mask(thread),
                Some(kernel),
                "gate {gate}"
            );
        }
    }

    /// Under the in-guest delivery gate, a rejoin (`BlockedExternalContinue`)
    /// is filed at a moment host timing chooses, while its thread is still
    /// outside the schedule: filing it changes nothing the scheduler holds,
    /// and the mask published at the call's request stays. When step 2c
    /// readmits the thread (`step2c_process_io_blockers`, through
    /// `keep_mask_for_continuation`), an ordered point, the rejoin's
    /// publication takes effect, so between readmission and the continuation
    /// turn the readers (`read_thread_blocked_mask_result`,
    /// `sibling_signal_state`) see:
    /// - a temporary-mask call that returned normally (`Restored`, a masked
    ///   `pselect6` with more than 64 descriptors): the own mask Linux
    ///   restored before it returned;
    /// - one a signal ended (`Temporary`): the temporary mask, kept until
    ///   `rt_sigreturn`;
    /// - `rt_sigsuspend` (`Unknown`, publishing nothing): the temporary mask
    ///   its call published, as design 18.16 holds for a readmitted thread,
    ///   while `thread_signal_mask` reads it as unknown (`continuation_masks`).
    ///
    /// With the gate off nothing is recorded at either point. Mutations:
    /// recording only at the continuation turn's grant (the readmitted window
    /// keeps the temporary mask for `Restored`), and recording at filing (the
    /// mask changes while the thread is out).
    #[test]
    fn under_the_gate_a_rejoin_publishes_at_its_readmission_not_at_its_filing() {
        let own = kernel_signal_bit(libc::SIGUSR2);
        let temporary = kernel_signal_bit(libc::SIGTERM);
        for gate in [true, false] {
            for (n, kind) in ["restored", "temporary", "unknown"].into_iter().enumerate() {
                let case = format!("{kind}, gate {gate}");
                let (mut scheduler, _parent, thread) = in_guest_publication_family(gate, !0);
                let op = ExternalOpId::new(thread, n as u64 + 1);
                let mut call = publishing_request(thread, Some(temporary));
                call.blocked_signal_mask = Some(temporary);
                call.insert(
                    if kind == "unknown" {
                        ResourceID::BlockingRtSigsuspend(op)
                    } else {
                        ResourceID::BlockingExternalIO(op)
                    },
                    Permission::RW,
                );
                scheduler.record_request_guest_mask(thread, &call);
                scheduler.runqueue_push_back(thread);
                assert_eq!(scheduler.run_queue.tentative_pop_tid(thread), Some(thread));
                assert!(
                    scheduler
                        .step4_resource_block(thread, &call, &Ivar::new())
                        .is_err(),
                    "{case}: the call runs outside the schedule"
                );
                let held = gate.then_some(temporary);
                assert_eq!(scheduler.published_guest_sigmask(thread), held, "{case}");
                // The call returns and the thread files its rejoin, as
                // `record_or_replay_blocking` builds it, while it is still out.
                let mut rejoin = Resources::new(thread);
                rejoin.insert(ResourceID::BlockedExternalContinue(op), Permission::RW);
                match kind {
                    "restored" => rejoin.guest_signal_mask = Some(own),
                    "temporary" => {
                        rejoin.blocked_signal_mask = Some(temporary);
                        rejoin.guest_signal_mask = Some(temporary);
                    }
                    _ => rejoin.blocked_signal_mask_unknown = true,
                }
                if !gate {
                    rejoin.guest_signal_mask = None;
                }
                assert!(rejoin.is_rejoin());
                assert!(
                    !scheduler.record_request_guest_mask(thread, &rejoin),
                    "{case}"
                );
                scheduler.next_turns[&thread].req.put(Ok(rejoin.clone()));
                assert_eq!(
                    scheduler.published_guest_sigmask(thread),
                    held,
                    "{case}: filing a rejoin changes nothing"
                );
                // Step 2c readmits it: an ordered point.
                assert!(scheduler.step2c_process_io_blockers().is_ok(), "{case}");
                assert!(
                    scheduler.run_queue.contains_tid(thread),
                    "{case}: readmitted"
                );
                let readmitted = match (gate, kind) {
                    (false, _) => None,
                    (true, "restored") => Some(own),
                    (true, _) => Some(temporary),
                };
                assert_eq!(
                    scheduler.published_guest_sigmask(thread),
                    readmitted,
                    "{case}: what readmission holds"
                );
                if gate {
                    let want = readmitted.unwrap();
                    assert_eq!(
                        scheduler.read_thread_blocked_mask_result(thread),
                        Ok(want),
                        "{case}"
                    );
                    assert_eq!(
                        scheduler.sibling_signal_state(thread),
                        SiblingSignalState::InSchedule(Some(want)),
                        "{case}"
                    );
                    if kind == "unknown" {
                        assert_eq!(scheduler.thread_signal_mask(thread), None, "{case}");
                    }
                }
                // The continuation turn's grant records nothing more.
                assert!(
                    scheduler
                        .step4_resource_block(thread, &rejoin, &Ivar::new())
                        .is_ok(),
                    "{case}"
                );
                assert_eq!(
                    scheduler.published_guest_sigmask(thread),
                    readmitted,
                    "{case}: after the continuation turn"
                );
            }
            // A failed vfork's rejoin is one too, and is not recorded at its
            // filing either.
            let (mut scheduler, _parent, thread) = in_guest_publication_family(gate, !0);
            let mut failed = publishing_request(thread, Some(own));
            failed.insert(
                ResourceID::VforkFailed(ExternalOpId::new(thread, 9)),
                Permission::RW,
            );
            assert!(failed.is_rejoin());
            assert!(!scheduler.record_request_guest_mask(thread, &failed));
            assert_eq!(scheduler.published_guest_sigmask(thread), None);
        }
    }

    /// Under the in-guest delivery gate, a call granted outside the schedule
    /// records the mask it sleeps under (`out_of_scheduler_masks`) from what
    /// its request published: its own mask, or its temporary one, and an
    /// unknown mask (`None`) when it published none. No `/proc` mask is read
    /// for it. Nothing is armed from it: with a caught `SIGCHLD` the scheduler
    /// left in the shared queue that the recorded mask admits, a scheduler
    /// that models signal targets arms the thread
    /// (`a_call_that_begins_with_a_scheduler_signal_waiting_is_armed`); under
    /// the gate it does not, since the arming paths stay under
    /// `models_signal_targets`. With the gate off nothing is recorded, as
    /// before. Mutations: the `/proc` read used under the gate (the read count
    /// moves and the kernel's mask is recorded); the arming moved to the gate
    /// (the thread is armed).
    #[test]
    fn under_the_gate_a_background_grant_records_the_published_mask_and_arms_nothing() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let own = kernel_signal_bit(libc::SIGUSR2);
        let temporary = kernel_signal_bit(libc::SIGTERM);
        // What `SigBlk` would show under the in-guest runtime's mask.
        let kernel = !0_u64;
        for gate in [true, false] {
            for (case, rid, blocked, published, want) in [
                (
                    "own mask",
                    ResourceID::BlockingExternalIO(ExternalOpId::new(DetTid::from_raw(101), 1)),
                    None,
                    Some(own),
                    Some(own),
                ),
                (
                    "temporary mask",
                    ResourceID::BlockingRtSigsuspend(ExternalOpId::new(DetTid::from_raw(101), 2)),
                    Some(temporary),
                    Some(temporary),
                    Some(temporary),
                ),
                (
                    "nothing published",
                    ResourceID::BlockingExternalIO(ExternalOpId::new(DetTid::from_raw(101), 3)),
                    None,
                    None,
                    None,
                ),
            ] {
                let (mut scheduler, parent, thread) = in_guest_publication_family(gate, kernel);
                scheduler
                    .test_signal_masks
                    .insert((parent, None, "SigCgt"), chld);
                if let Some(state) = scheduler.test_kernel_signal_states.get_mut(&thread) {
                    state.shared_pending = chld;
                }
                scheduler.note_signal_left_in_shared_queue(parent, libc::SIGCHLD);
                // The request was filed with its publication
                // (`record_request_guest_mask`).
                let mut filed = publishing_request(thread, published);
                filed.blocked_signal_mask = blocked;
                scheduler.record_request_guest_mask(thread, &filed);
                let reads = scheduler
                    .test_kernel_mask_reads
                    .load(std::sync::atomic::Ordering::Relaxed);
                scheduler.runqueue_push_back(thread);
                assert_eq!(scheduler.run_queue.tentative_pop_tid(thread), Some(thread));
                assert!(
                    scheduler
                        .block_for_one_resource(
                            thread,
                            &rid,
                            &Permission::RW,
                            None,
                            blocked,
                            &Ivar::new()
                        )
                        .is_err(),
                    "{case}"
                );
                assert_eq!(
                    scheduler
                        .blocked
                        .out_of_scheduler_masks
                        .get(&thread)
                        .copied(),
                    gate.then_some(want),
                    "{case}, gate {gate}"
                );
                assert_eq!(
                    scheduler
                        .test_kernel_mask_reads
                        .load(std::sync::atomic::Ordering::Relaxed),
                    reads,
                    "{case}: no /proc mask is read"
                );
                assert!(
                    !scheduler.blocked.signaled_background.contains(&thread),
                    "{case}, gate {gate}: nothing is armed"
                );
                assert!(scheduler.background_entry_barriers.is_empty(), "{case}");
                if gate {
                    assert_eq!(scheduler.thread_signal_mask(thread), want, "{case}");
                }
            }
        }
    }

    /// Every resource in the published list of kernel-run blocking calls
    /// (A5 design 16.11, `ResourceID::is_kernel_run_blocking`) is granted
    /// outside the schedule: the thread leaves the run queue and the
    /// scheduler records the call as running in the background. With the
    /// `debug_assert!` in `block_for_one_resource`'s background arm, this ties
    /// the list to that arm in both directions.
    #[test]
    fn every_kernel_run_blocking_resource_is_granted_outside_the_schedule() {
        let mut granted = 0;
        for rid in crate::resources::one_resource_of_each_variant(ExternalOpId::new(
            DetTid::from_raw(101),
            1,
        )) {
            if !rid.is_kernel_run_blocking() {
                continue;
            }
            let (mut scheduler, _parent, creator, _child) = sigchld_family(libc::SIGCHLD);
            commit_out_of_scheduler_call(&mut scheduler, creator, rid.clone(), None);
            assert!(
                !scheduler.run_queue.contains_tid(creator),
                "{rid:?} left the thread in the run queue"
            );
            let op = ExternalOpId::new(creator, 1);
            let background = if matches!(rid, ResourceID::BlockingRtSigsuspend(_)) {
                scheduler.blocked.rt_sigsuspend_blockers.get(&creator)
            } else {
                scheduler.blocked.external_io_blockers.get(&creator)
            };
            assert_eq!(background, Some(&op), "{rid:?}");
            granted += 1;
        }
        assert_eq!(granted, 3);
    }

    /// A thread sleeping in `rt_sigsuspend` or in other IO outside the runnable
    /// set is not stopped, so its live mask changes at host-timed moments:
    /// `rt_sigsuspend` installs its temporary mask only after the scheduler
    /// released the thread. The `SIGCHLD` target is chosen from the mask the
    /// scheduler recorded when it committed the call, the call's own mask or
    /// else the mask read while the thread was still stopped at its request.
    /// Before, the live mask was read when the child died, so whether the
    /// creator or a sibling parked in a precise futex wait took the signal
    /// depended on host timing; the target is also the thread a `ChildExit`
    /// timer signals (<https://github.com/rrnewton/hermit/issues/3146>).
    #[test]
    fn a_sigchld_target_sleeping_outside_the_scheduler_uses_the_mask_recorded_at_its_commit() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let blocking = |blocked: u64| KernelSignalState {
            blocked,
            ..signal_state(chld, 0)
        };
        let family_with_parked_sibling = || {
            let (mut scheduler, parent, creator, child) = sigchld_family(libc::SIGCHLD);
            let sibling = DetTid::from_raw(102);
            scheduler.thread_tree.add_child(parent, sibling, false);
            register_known_thread(&mut scheduler, sibling);
            park_for_sigchld(&mut scheduler, sibling, chld);
            // The leader runs with SIGCHLD blocked, and so does the creator
            // until its call installs a mask of its own.
            scheduler
                .test_kernel_signal_states
                .insert(parent, blocking(chld));
            scheduler
                .test_kernel_signal_states
                .insert(creator, blocking(chld));
            (scheduler, parent, creator, child, sibling)
        };

        // The creator suspends with an rt_sigsuspend mask that unblocks SIGCHLD.
        // Whether or not the host has installed that mask yet, the creator takes
        // the signal, so the sibling's precise futex wait is left alone.
        let (mut scheduler, parent, creator, child, sibling) = family_with_parked_sibling();
        let op = ExternalOpId::new(creator, 1);
        commit_out_of_scheduler_call(
            &mut scheduler,
            creator,
            ResourceID::BlockingRtSigsuspend(op),
            Some(0),
        );
        assert_eq!(
            scheduler.blocked.rt_sigsuspend_blockers.get(&creator),
            Some(&op)
        );
        assert_eq!(
            scheduler.blocked.out_of_scheduler_masks.get(&creator),
            Some(&Some(0))
        );
        for live in [chld, 0] {
            scheduler
                .test_kernel_signal_states
                .insert(creator, blocking(live));
            assert_eq!(
                scheduler.kernel_sigchld_target(parent, creator),
                Some(creator)
            );
        }
        scheduler.logically_kill_thread(&child, &child, MmId::initial(child));
        scheduler.drain_pending_cross_task_signals();
        assert!(scheduler.is_parked_futex_waiter(sibling));

        // Other external IO sleeps under the thread's own mask, read while it is
        // still stopped at its request: SIGCHLD blocked. A later change of its
        // live mask does not make it the target. The sibling is the target, but
        // its wait holds SIGCHLD, so it stays parked.
        let (mut scheduler, parent, creator, child, sibling) = family_with_parked_sibling();
        commit_out_of_scheduler_call(
            &mut scheduler,
            creator,
            ResourceID::BlockingExternalIO(ExternalOpId::new(creator, 2)),
            None,
        );
        assert_eq!(
            scheduler.blocked.out_of_scheduler_masks.get(&creator),
            Some(&Some(chld))
        );
        scheduler
            .test_kernel_signal_states
            .insert(creator, blocking(0));
        assert_eq!(
            scheduler.kernel_sigchld_target(parent, creator),
            Some(sibling)
        );
        scheduler.logically_kill_thread(&child, &child, MmId::initial(child));
        scheduler.drain_pending_cross_task_signals();
        assert!(scheduler.is_parked_futex_waiter(sibling));
        assert!(scheduler.inbound_signals(sibling).is_empty());

        // A mask that could not be recorded is not a target, whatever the live
        // one says, and the record goes when the thread leaves its pool.
        let (mut scheduler, parent, creator, _child, sibling) = family_with_parked_sibling();
        commit_out_of_scheduler_call(
            &mut scheduler,
            creator,
            ResourceID::BlockingExternalIO(ExternalOpId::new(creator, 3)),
            Some(0),
        );
        scheduler
            .blocked
            .out_of_scheduler_masks
            .insert(creator, None);
        scheduler
            .test_kernel_signal_states
            .insert(creator, blocking(0));
        assert_eq!(
            scheduler.kernel_sigchld_target(parent, creator),
            Some(sibling)
        );
        scheduler.remove_blocking_entries(&creator);
        assert!(scheduler.blocked.out_of_scheduler_masks.is_empty());
        assert_eq!(
            scheduler.kernel_sigchld_target(parent, creator),
            Some(creator)
        );
    }

    /// The creator is stopped at a request without blocking `SIGCHLD` while a
    /// sibling sleeps in an `rt_sigsuspend` whose mask lets it through. The
    /// kernel passes over a thread in a ptrace stop, so it gives the signal to
    /// the sibling and wakes it: the sibling is the target, and the signal the
    /// `ChildExit` timer sends it arms it for the release barrier. Before, the
    /// creator was named and the sibling not armed, so whether it took the
    /// signal before the creator resumed from a sleep virtual time ended was
    /// host-timed (<https://github.com/rrnewton/hermit/issues/4237>). The
    /// creator is named as before when the sibling's mask blocks `SIGCHLD`,
    /// and when the sibling is in other external IO: a `ppoll` that returned
    /// has restored its own mask, and a vfork parent's sleep is not woken.
    #[test]
    fn a_sigchld_goes_to_a_sibling_sleeping_outside_the_scheduler_before_a_stopped_creator() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        for (sigsuspend, sleeping_mask, sibling_takes) in
            [(true, 0, true), (true, chld, false), (false, 0, false)]
        {
            let (mut scheduler, parent, creator, _child) = sigchld_family(libc::SIGCHLD);
            scheduler
                .test_kernel_signal_states
                .insert(creator, signal_state(chld, 0));
            scheduler
                .test_kernel_signal_states
                .insert(parent, signal_state(chld, 0));
            let op = ExternalOpId::new(parent, 1);
            let rid = if sigsuspend {
                ResourceID::BlockingRtSigsuspend(op)
            } else {
                ResourceID::BlockingExternalIO(op)
            };
            commit_out_of_scheduler_call(&mut scheduler, parent, rid, Some(sleeping_mask));
            let expected = if sibling_takes { parent } else { creator };
            assert_eq!(
                scheduler.kernel_sigchld_target(parent, creator),
                Some(expected),
                "rt_sigsuspend {sigsuspend}, sleeping mask {sleeping_mask:#x}"
            );
            if sibling_takes {
                scheduler.wake_signaled_guest(parent, Signal::SIGCHLD);
                assert!(scheduler.blocked.signaled_background.contains(&parent));
                assert!(scheduler.blocked.sigchld_ready.contains(&parent));
            }
        }
    }

    /// Under targeted chaos, the random thread is only the one the kernel
    /// tries first: a `ChildExit` send still goes to the `rt_sigsuspend`
    /// sibling the kernel wakes, whichever thread chaos draws. Before, the
    /// draw replaced the kernel's choice, so it could name the stopped creator
    /// while the kernel woke the sibling, which nothing armed. With the
    /// sibling's mask blocking `SIGCHLD`, every draw ends at the creator (the
    /// Codex review of
    /// https://github.com/rrnewton/hermit/commit/2f046e41b49d4b24b1bec605f269e3c3afde5895).
    #[test]
    fn targeted_chaos_does_not_replace_the_kernels_child_exit_target() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        for (sleeping_mask, sibling_takes) in [(0, true), (chld, false)] {
            let (mut scheduler, parent, creator, _child) = sigchld_family(libc::SIGCHLD);
            scheduler.chaos_target_races = true;
            scheduler
                .test_kernel_signal_states
                .insert(creator, signal_state(chld, 0));
            scheduler
                .test_kernel_signal_states
                .insert(parent, signal_state(chld, 0));
            commit_out_of_scheduler_call(
                &mut scheduler,
                parent,
                ResourceID::BlockingRtSigsuspend(ExternalOpId::new(parent, 1)),
                Some(sleeping_mask),
            );
            let expected = if sibling_takes { parent } else { creator };
            for draw in 0..16 {
                assert_eq!(
                    scheduler.child_exit_sigchld_target(parent, creator),
                    expected,
                    "draw {draw}, sleeping mask {sleeping_mask:#x}"
                );
            }
        }
    }

    /// A guest's signal that the drain places on an `rt_sigsuspend` sleeper
    /// arms it, and the pass then ends before a due `ChildExit` timer pops:
    /// the timer chooses its target only after the release barrier has
    /// requeued that thread. Otherwise the timer could name the sleeper, which
    /// the kernel skips because a signal is already pending for it, while the
    /// kernel woke another sleeper that nothing armed (the Codex review of
    /// https://github.com/rrnewton/hermit/commit/2f046e41b49d4b24b1bec605f269e3c3afde5895).
    #[test]
    fn a_drain_that_arms_a_sleeper_ends_the_pass_before_a_child_exit_timer() {
        let global_time = Arc::new(Mutex::new(GlobalTime::new(&Config::default())));
        let (mut scheduler, parent, creator, child) = sigchld_family(libc::SIGCHLD);
        commit_out_of_scheduler_call(
            &mut scheduler,
            parent,
            ResourceID::BlockingRtSigsuspend(ExternalOpId::new(parent, 1)),
            Some(0),
        );
        let deadline = scheduler.committed_time;
        scheduler
            .blocked
            .timed_waiters
            .insert_child_exit(deadline, child, parent, creator);
        scheduler.committed_time = deadline + LogicalTime::from_nanos(10);
        scheduler.notify_signal_pending(parent, SigWrapper::from(Signal::SIGUSR1));

        assert!(scheduler.step2_process_blocked(&global_time).is_err());
        assert!(scheduler.blocked.signaled_background.contains(&parent));
        assert_eq!(
            scheduler.blocked.timed_waiters.iter().count(),
            1,
            "the ChildExit timer must not pop in the pass that armed the sleeper"
        );
    }

    /// A signal the scheduler sends while a thread is still stopped at its
    /// `rt_sigsuspend` request reaches the call: the thread may block it now,
    /// but the call's temporary mask does not, so the kernel delivers it as
    /// soon as the call starts. Committing the call arms the thread for the
    /// release barrier, which waits for its signal stop, as for a signal sent
    /// after the commit. Before, the thread entered the pool as a sleeper no
    /// signal could reach, and the next pass reported a deadlock. That is how
    /// dash's `wait` failed: a `ChildExit` timer fired between its
    /// `wait4(WNOHANG)` and its `rt_sigsuspend`, while it blocked every signal.
    /// A signal the temporary mask blocks arms nothing.
    #[test]
    fn a_signal_sent_at_an_rt_sigsuspend_request_arms_the_call_it_wakes() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        for (temporary_mask, armed) in [(0, true), (chld, false)] {
            let (mut scheduler, _parent, creator, _child) = sigchld_family(libc::SIGCHLD);
            let op = ExternalOpId::new(creator, 7);
            let mut request = Resources::new(creator);
            request.insert(ResourceID::BlockingRtSigsuspend(op), Permission::RW);
            request.blocked_signal_mask = Some(temporary_mask);
            scheduler.next_turns.get_mut(&creator).unwrap().req = Ivar::full(Ok(request));
            // Its request is posted, so it waits in the run queue for its turn.
            scheduler.runqueue_push_back(creator);

            scheduler.wake_signaled_guest(creator, Signal::SIGCHLD);
            assert!(scheduler.run_queue.remove_tid(creator));
            commit_out_of_scheduler_call(
                &mut scheduler,
                creator,
                ResourceID::BlockingRtSigsuspend(op),
                Some(temporary_mask),
            );
            assert_eq!(
                scheduler.blocked.rt_sigsuspend_blockers.get(&creator),
                Some(&op)
            );
            assert_eq!(
                scheduler.blocked.signaled_background.contains(&creator),
                armed,
                "temporary mask {temporary_mask:#x}"
            );
            assert_eq!(scheduler.blocked.sigchld_ready.contains(&creator), armed);
            assert!(scheduler.blocked.signaled_sigsuspend_requests.is_empty());
        }
    }

    /// A guest's signal to a thread asleep in a real `rt_sigsuspend`
    /// (`kill`, `tgkill` and `tkill` report it with `notify_signal_pending`)
    /// is placed at the next drain as a signal the scheduler sends is: the
    /// thread is armed for the release barrier when its sleeping mask lets the
    /// signal through, and not when it blocks it; a thread still stopped at
    /// its `rt_sigsuspend` request gets the record its grant arms. Before, such
    /// a signal was not recorded at all, the scheduler did not wait for the
    /// wake's signal stop, and on a slow host it reported a deadlock first.
    ///
    /// A realtime signal is placed the same way: `nix` cannot name it, and the
    /// drain used to drop it (https://github.com/rrnewton/hermit/issues/3941).
    /// SIGKILL arms too, although it has no delivery stop under ptrace: the
    /// arm is cleared when the thread's exit is processed
    /// (`a_sigkill_arm_on_an_rt_sigsuspend_sleeper_ends_with_its_exit`), and
    /// without it the killed sleeper would count as unwakeable until then.
    #[test]
    fn a_guest_signal_to_an_rt_sigsuspend_sleeper_arms_the_release_barrier() {
        let usr1 = SigWrapper::from(Signal::SIGUSR1);
        let realtime = SigWrapper(35);
        let kill = SigWrapper::from(Signal::SIGKILL);
        for (signal, sleeping_mask, armed) in [
            (usr1, 0, true),
            (usr1, kernel_signal_bit(libc::SIGUSR1), false),
            (realtime, 0, true),
            (realtime, kernel_signal_bit(35), false),
            (kill, 0, true),
        ] {
            let (mut scheduler, _parent, creator, _child) = sigchld_family(libc::SIGCHLD);
            commit_out_of_scheduler_call(
                &mut scheduler,
                creator,
                ResourceID::BlockingRtSigsuspend(ExternalOpId::new(creator, 5)),
                Some(sleeping_mask),
            );
            scheduler.notify_signal_pending(creator, signal);
            scheduler.drain_pending_cross_task_signals();
            assert_eq!(
                scheduler.blocked.signaled_background.contains(&creator),
                armed,
                "signal {signal}, sleeping mask {sleeping_mask:#x}"
            );
        }

        for signal in [usr1, realtime, kill] {
            let (mut scheduler, _parent, creator, _child) = sigchld_family(libc::SIGCHLD);
            let mut request = Resources::new(creator);
            request.insert(
                ResourceID::BlockingRtSigsuspend(ExternalOpId::new(creator, 6)),
                Permission::RW,
            );
            request.blocked_signal_mask = Some(0);
            scheduler.next_turns.get_mut(&creator).unwrap().req = Ivar::full(Ok(request));
            scheduler.runqueue_push_back(creator);
            scheduler.notify_signal_pending(creator, signal);
            scheduler.drain_pending_cross_task_signals();
            assert_eq!(
                scheduler.blocked.signaled_sigsuspend_requests.get(&creator),
                Some(&signal),
                "signal {signal}"
            );
        }
    }

    /// The SIGKILL policy of https://github.com/rrnewton/hermit/issues/3941: a
    /// guest's SIGKILL to a thread asleep in `rt_sigsuspend` arms it like any
    /// signal its mask admits (the installed mask can never block SIGKILL).
    /// There is no delivery stop to wait for; the thread exits, and processing
    /// that exit clears the arm (`remove_blocking_entries`), so the release
    /// barrier does not wait past it.
    #[test]
    fn a_sigkill_arm_on_an_rt_sigsuspend_sleeper_ends_with_its_exit() {
        let (mut scheduler, _parent, creator, _child) = sigchld_family(libc::SIGCHLD);
        commit_out_of_scheduler_call(
            &mut scheduler,
            creator,
            ResourceID::BlockingRtSigsuspend(ExternalOpId::new(creator, 5)),
            Some(0),
        );
        scheduler.notify_signal_pending(creator, SigWrapper::from(Signal::SIGKILL));
        scheduler.drain_pending_cross_task_signals();
        assert!(scheduler.blocked.signaled_background.contains(&creator));
        scheduler.remove_blocking_entries(&creator);
        assert!(!scheduler.blocked.signaled_background.contains(&creator));
        assert!(
            !scheduler
                .blocked
                .rt_sigsuspend_blockers
                .contains_key(&creator)
        );
    }

    /// A scheduler that does not model signal targets (`models_signal_targets`)
    /// neither reads a committed thread's sleeping mask from `/proc` nor records
    /// one. Nothing on such a scheduler consumes the record, and on a backend
    /// whose `DetTid` is not a host thread ID the read would name an unrelated
    /// host thread or none. The gated scheduler, for contrast, records the
    /// call's own mask, or else reads the thread's
    /// (https://github.com/rrnewton/hermit/issues/3146).
    /// A background call whose temporary mask its turn cannot vouch for
    /// (`Resources::blocked_signal_mask_unknown`: a pselect6 in record and
    /// replay) has no recorded sleeping mask, so a committed signal never arms
    /// it, whatever the thread's ordinary mask, and it is not a `SIGCHLD`
    /// target. Taking the ordinary mask for such a call armed it for a SIGALRM
    /// the call's own mask blocks, and the release barrier waited for a wake
    /// Linux never delivers (Codex review of
    /// https://github.com/rrnewton/hermit/pull/3989). The same call without the
    /// flag is armed, from the ordinary mask read while it was stopped.
    #[test]
    fn a_background_call_with_an_unknown_sleeping_mask_is_never_armed() {
        for unknown in [false, true] {
            let (mut scheduler, _parent, creator, _child) = sigchld_family(libc::SIGCHLD);
            // A send that this test reaches must not reach a real host thread.
            scheduler.backend.requires_thread_directed_process_signals = true;
            scheduler
                .test_kernel_signal_states
                .insert(creator, signal_state(0, 0));
            let op = ExternalOpId::new(creator, 1);
            let mut request = Resources::new(creator);
            request.insert(ResourceID::BlockingExternalIO(op), Permission::RW);
            request.blocked_signal_mask_unknown = unknown;
            scheduler.runqueue_push_back(creator);
            assert_eq!(
                scheduler.run_queue.tentative_pop_tid(creator),
                Some(creator)
            );
            assert!(
                scheduler
                    .step4_resource_block(creator, &request, &Ivar::new())
                    .is_err()
            );
            assert_eq!(
                scheduler.blocked.external_io_blockers.get(&creator),
                Some(&op)
            );
            scheduler.wake_signaled_guest(creator, Signal::SIGALRM);
            let recorded = scheduler.blocked.out_of_scheduler_masks.get(&creator);
            let armed = scheduler.blocked.signaled_background.contains(&creator);
            if unknown {
                assert_eq!(recorded, Some(&None));
                assert!(!armed);
                assert_eq!(scheduler.thread_signal_mask(creator), None);
            } else {
                assert_eq!(recorded, Some(&Some(0)));
                assert!(armed);
            }
        }
    }

    /// A thread released into a background `rt_sigsuspend` whose temporary
    /// mask differs from its own holds every later turn and timer pop until
    /// its kernel mask shows the temporary one, or its call has left the
    /// blocked pool. Before, the scheduler went on at once, and the
    /// process-directed `SIGALRM` of a timer wake, which the thread's own mask
    /// leaves unblocked, could reach it on its way into the kernel or not, as
    /// host timing decided (https://github.com/rrnewton/hermit/issues/3993).
    /// A call that sleeps under the thread's own mask needs no barrier.
    /// `--signal-at` sends its process-directed signal behind the same
    /// barrier: nothing while it holds, once it has settled.
    #[test]
    fn a_background_call_with_a_temporary_mask_holds_the_schedule_until_the_kernel_installs_it() {
        let alrm = kernel_signal_bit(libc::SIGALRM);
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        let masked = |blocked: u64| KernelSignalState {
            blocked,
            ..signal_state(0, 0)
        };
        for (own, installed_then_left) in [(alrm, None), (usr1, Some(true)), (usr1, Some(false))] {
            let (mut scheduler, _parent, creator, _child) = sigchld_family(libc::SIGCHLD);
            scheduler.models_signal_targets = true;
            scheduler
                .test_kernel_signal_states
                .insert(creator, masked(own));
            let op = ExternalOpId::new(creator, 1);
            commit_out_of_scheduler_call(
                &mut scheduler,
                creator,
                ResourceID::BlockingRtSigsuspend(op),
                Some(alrm),
            );
            let case = format!("own={own:#x} installed_then_left={installed_then_left:?}");
            // The root's `--signal-at` turn has been committed.
            scheduler.signal_at = Some(detcore_model::config::SignalAt {
                turn: 7,
                signal: libc::SIGALRM,
            });
            scheduler.last_committed_turn = Some(7);
            scheduler.test_sent_signals = Some(Vec::new());
            let sent = |scheduler: &Scheduler| scheduler.test_sent_signals.as_ref().unwrap().len();
            let Some(installed) = installed_then_left else {
                assert!(scheduler.background_entry_barriers.is_empty(), "{case}");
                assert!(scheduler.step2_drain_prefix().is_ok(), "{case}");
                assert_eq!(sent(&scheduler), 1, "{case}");
                continue;
            };
            // Still on its way into the kernel, under its own mask.
            assert!(scheduler.step2_drain_prefix().is_err(), "{case}");
            assert!(scheduler.step2_drain_prefix().is_err(), "{case}");
            assert_eq!(
                sent(&scheduler),
                0,
                "{case}: sent before the barrier settled"
            );
            assert!(scheduler.signal_at.is_some(), "{case}");
            if installed {
                scheduler
                    .test_kernel_signal_states
                    .insert(creator, masked(alrm));
            } else {
                // The call ended before the mask was seen, as when a pending
                // signal ended it at once and its continuation was granted.
                scheduler.blocked.rt_sigsuspend_blockers.remove(&creator);
            }
            assert!(scheduler.step2_drain_prefix().is_ok(), "{case}");
            assert!(scheduler.background_entry_barriers.is_empty(), "{case}");
            assert_eq!(sent(&scheduler), 1, "{case}");
            assert_eq!(scheduler.signal_at, None, "{case}");
        }
    }

    /// `--signal-at turn=N` is sent once a turn numbered N or later has been
    /// committed, and only then: not when `turn`, which names the next turn
    /// and also counts skipped ones, has passed N while the last commit is
    /// earlier. If turn N itself was skipped, the next commit sends it. It
    /// goes to the thread tree's root, here 100 rather than `ROOT_DETPID`
    /// (as under `--no-namespace`), and only once.
    #[test]
    fn signal_at_is_sent_after_the_first_commit_numbered_n_or_later() {
        for (commits, sent_after) in [(&[4u64, 5, 6][..], Some(5u64)), (&[3, 4, 6][..], Some(6))] {
            let (mut scheduler, root, _creator, _child) = sigchld_family(libc::SIGCHLD);
            scheduler.models_signal_targets = true;
            scheduler.signal_at = Some(detcore_model::config::SignalAt {
                turn: 5,
                signal: libc::SIGUSR1,
            });
            scheduler.test_sent_signals = Some(Vec::new());
            assert!(scheduler.step2_drain_prefix().is_ok());
            for commit in commits {
                // Skipped turns have moved `turn` past the commit.
                scheduler.turn = commit + 2;
                scheduler.last_committed_turn = Some(*commit);
                assert!(scheduler.step2_drain_prefix().is_ok());
                let sent = scheduler.test_sent_signals.clone().unwrap();
                if Some(*commit) < sent_after {
                    assert!(sent.is_empty(), "{commits:?}: sent after commit {commit}");
                } else {
                    assert_eq!(sent.len(), 1, "{commits:?}: after commit {commit}");
                    assert_eq!(sent[0].1, libc::SIGUSR1);
                    assert_eq!(
                        scheduler.thread_tree.thread_to_leader.get(&sent[0].0),
                        Some(&DetPid::from_raw(root.as_raw())),
                        "{commits:?}: not sent to the root process"
                    );
                }
            }
        }
    }

    /// A live thread released into a background call whose kernel mask cannot
    /// be read has not proved its entry, and holds its barrier: a read error
    /// is not evidence that the thread is gone (Codex review of
    /// https://github.com/rrnewton/hermit/pull/4053, whose regression this is).
    /// The test thread is a real, live identity; one read returns EIO through
    /// the read seam.
    #[test]
    fn a_live_thread_whose_mask_cannot_be_read_holds_its_background_entry() {
        use std::cell::Cell;
        use std::rc::Rc;

        use crate::syscalls::signal_state_read_seam;

        let (mut scheduler, thread, own, temporary) = live_background_entry_scheduler(None);
        assert_eq!(
            scheduler
                .background_entry_barriers
                .get(&thread)
                .map(|entry| entry.mask),
            Some(temporary)
        );
        let pid = reverie::Pid::from_raw(std::process::id() as i32);
        let tid = reverie::Pid::from_raw(thread.as_raw());
        let reads = Rc::new(Cell::new(0));
        let observed = reads.clone();
        let seam = signal_state_read_seam::install(move |_, _| {
            observed.set(observed.get() + 1);
            Some(Err(reverie::Errno::EIO))
        });
        let result = scheduler.step2_drain_prefix();
        drop(seam);
        assert_eq!(
            reads.get(),
            1,
            "the entry proof read takes the injected error"
        );
        assert!(!thread_is_gone(pid, tid));
        assert_eq!(read_kernel_signal_state(pid, tid).unwrap().blocked, own);
        assert!(
            result.is_err(),
            "a live thread with no observed temporary mask keeps the barrier"
        );
        assert!(scheduler.background_entry_barriers.contains_key(&thread));
        assert!(scheduler.terminal_deadlock.is_none());
    }

    /// An own mask that cannot be read when the scheduler grants the call is no
    /// proof that it equals the temporary mask, so the barrier is armed (Codex
    /// review of https://github.com/rrnewton/hermit/pull/4053).
    #[test]
    fn an_unreadable_own_mask_at_the_grant_still_arms_the_entry_barrier() {
        let (scheduler, thread, _own, temporary) =
            live_background_entry_scheduler(Some(reverie::Errno::EIO));
        assert_eq!(
            scheduler
                .background_entry_barriers
                .get(&thread)
                .map(|entry| entry.mask),
            Some(temporary)
        );
    }

    /// An entry that stays unproved, neither entered nor left, past
    /// `background_entry_valve` ends the run with a named refusal instead of
    /// holding every turn forever (Codex review of
    /// https://github.com/rrnewton/hermit/pull/4053).
    #[test]
    fn an_unproved_background_entry_ends_the_run_by_name_after_the_valve() {
        let alrm = kernel_signal_bit(libc::SIGALRM);
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        let (mut scheduler, _parent, creator, _child) = sigchld_family(libc::SIGCHLD);
        scheduler.models_signal_targets = true;
        scheduler.background_entry_valve = Duration::ZERO;
        scheduler.test_kernel_signal_states.insert(
            creator,
            KernelSignalState {
                blocked: usr1,
                ..signal_state(0, 0)
            },
        );
        commit_out_of_scheduler_call(
            &mut scheduler,
            creator,
            ResourceID::BlockingRtSigsuspend(ExternalOpId::new(creator, 1)),
            Some(alrm),
        );
        assert!(scheduler.step2_drain_prefix().is_err());
        let reason = scheduler
            .terminal_deadlock
            .clone()
            .expect("the unproved entry ends the run");
        assert!(reason.starts_with("HERMIT_DEADLOCK:"), "{reason}");
        assert!(reason.contains("neither entered it"), "{reason}");
    }

    /// A scheduler with the calling test thread, a real and live identity,
    /// granted a background `rt_sigsuspend` under a temporary mask that differs
    /// from its actual one. `own_read_error` makes the grant's own-mask read
    /// fail. Returns the scheduler, the thread, its actual mask and the
    /// temporary mask.
    fn live_background_entry_scheduler(
        own_read_error: Option<reverie::Errno>,
    ) -> (Scheduler, DetTid, u64, u64) {
        use crate::syscalls::signal_state_read_seam;

        let pid = reverie::Pid::from_raw(std::process::id() as i32);
        // SAFETY: gettid takes no arguments and changes nothing.
        let tid = reverie::Pid::from_raw(unsafe { libc::syscall(libc::SYS_gettid) as i32 });
        assert!(!thread_is_gone(pid, tid));
        let own = read_kernel_signal_state(pid, tid)
            .expect("the test thread's signal state is readable")
            .blocked;
        let temporary = own ^ kernel_signal_bit(libc::SIGALRM);
        let leader = DetTid::from_raw(pid.as_raw());
        let thread = DetTid::from_raw(tid.as_raw());
        let mut scheduler = gated_scheduler();
        scheduler.thread_tree.add_child(leader, leader, true);
        if thread != leader {
            scheduler.thread_tree.add_child(leader, thread, false);
        }
        register_known_thread(&mut scheduler, thread);
        let seam = own_read_error
            .map(|errno| signal_state_read_seam::install(move |_, _| Some(Err(errno))));
        commit_out_of_scheduler_call(
            &mut scheduler,
            thread,
            ResourceID::BlockingRtSigsuspend(ExternalOpId::new(thread, 1)),
            Some(temporary),
        );
        drop(seam);
        (scheduler, thread, own, temporary)
    }

    #[test]
    fn a_scheduler_that_does_not_model_signal_targets_reads_and_records_no_sleeping_mask() {
        use std::sync::atomic::Ordering;
        let chld = kernel_signal_bit(libc::SIGCHLD);
        for models in [false, true] {
            for (seq, rt_sigsuspend, call_mask) in [(1, false, None), (2, true, Some(0))] {
                let (mut scheduler, _parent, creator, _child) = sigchld_family(libc::SIGCHLD);
                scheduler.models_signal_targets = models;
                scheduler.test_kernel_signal_states.insert(
                    creator,
                    KernelSignalState {
                        blocked: chld,
                        ..signal_state(chld, 0)
                    },
                );
                let op = ExternalOpId::new(creator, seq);
                let rid = if rt_sigsuspend {
                    ResourceID::BlockingRtSigsuspend(op)
                } else {
                    ResourceID::BlockingExternalIO(op)
                };
                let before = scheduler.test_kernel_mask_reads.load(Ordering::Relaxed);
                commit_out_of_scheduler_call(&mut scheduler, creator, rid, call_mask);
                let reads = scheduler.test_kernel_mask_reads.load(Ordering::Relaxed) - before;
                let case = format!("models={models} rt_sigsuspend={rt_sigsuspend}");

                // Either way the thread sleeps in its pool.
                let pool = if rt_sigsuspend {
                    &scheduler.blocked.rt_sigsuspend_blockers
                } else {
                    &scheduler.blocked.external_io_blockers
                };
                assert_eq!(pool.get(&creator), Some(&op), "{case}");
                let recorded = scheduler.blocked.out_of_scheduler_masks.get(&creator);
                if models {
                    assert_eq!(recorded, Some(&Some(call_mask.unwrap_or(chld))), "{case}");
                    // The thread's own mask, read once: it is the sleeping mask
                    // of a call without one, and decides whether a call with
                    // one needs an entry barrier.
                    assert_eq!(reads, 1, "{case}");
                } else {
                    assert_eq!(recorded, None, "{case}");
                    assert!(
                        scheduler.blocked.out_of_scheduler_masks.is_empty(),
                        "{case}"
                    );
                    assert_eq!(reads, 0, "{case}");
                }
            }
        }
    }

    /// Post `signal`'s delivery stop for `thread`, as its backend does when the
    /// kernel wakes it for the signal.
    fn post_inbound_signal(
        scheduler: &mut Scheduler,
        thread: DetTid,
        signal: libc::c_int,
        global_time: &Arc<Mutex<GlobalTime>>,
    ) {
        let req = scheduler.next_turns.get(&thread).unwrap().req.clone();
        let mut delivered = Resources::new(thread);
        delivered.insert(ResourceID::InboundSignal(SigWrapper(signal)), Permission::W);
        scheduler.request_put(&req, delivered, global_time);
    }

    /// A committed signal to a thread asleep in a real blocking call outside
    /// the run queue, on a traced backend, counterfeits no request for it: its
    /// request was consumed when it was backgrounded. The thread is armed, and
    /// every scheduler pass is empty until the delivery stop the signal
    /// provokes is posted; the next pass then requeues it, before anything
    /// else, and its `SIGCHLD` delivery is granted rather than deferred behind
    /// a runnable sibling. Before, a debug build asserted here and a release
    /// build counterfeited a request for a thread still in its pool
    /// (https://github.com/rrnewton/hermit/issues/3146).
    #[test]
    fn a_signal_to_a_thread_sleeping_outside_the_scheduler_is_requeued_after_its_own_stop() {
        let global_time = Arc::new(Mutex::new(GlobalTime::new(&Config::default())));
        let (mut scheduler, parent, creator, _child) = sigchld_family(libc::SIGCHLD);
        let op = ExternalOpId::new(creator, 1);
        commit_out_of_scheduler_call(
            &mut scheduler,
            creator,
            ResourceID::BlockingRtSigsuspend(op),
            Some(0),
        );
        scheduler.runqueue_push_back(parent);

        scheduler.wake_signaled_guest(creator, Signal::SIGCHLD);
        assert!(scheduler.blocked.signaled_background.contains(&creator));
        assert!(scheduler.blocked.sigchld_ready.contains(&creator));
        assert!(
            scheduler
                .next_turns
                .get(&creator)
                .unwrap()
                .req
                .try_read()
                .is_none()
        );
        assert_eq!(
            scheduler.blocked.rt_sigsuspend_blockers.get(&creator),
            Some(&op)
        );
        assert!(!scheduler.run_queue.contains_tid(creator));

        // The kernel has not delivered yet: every pass is empty.
        for _ in 0..3 {
            assert!(scheduler.step2_release_signaled_background().is_err());
            assert!(!scheduler.run_queue.contains_tid(creator));
        }

        // The thread's own stop posts its continuation; the next pass requeues it.
        post_inbound_signal(&mut scheduler, creator, libc::SIGCHLD, &global_time);
        assert!(scheduler.step2_release_signaled_background().is_ok());
        assert!(scheduler.run_queue.contains_tid(creator));
        assert!(scheduler.blocked.rt_sigsuspend_blockers.is_empty());
        assert!(scheduler.blocked.out_of_scheduler_masks.is_empty());
        assert!(scheduler.blocked.signaled_background.is_empty());
        assert!(scheduler.signaled_background_since.is_none());

        // Its delivery commits although the leader is runnable.
        let inbound = ResourceID::InboundSignal(SigWrapper(libc::SIGCHLD));
        assert_eq!(
            scheduler.run_queue.tentative_pop_tid(creator),
            Some(creator)
        );
        assert!(
            scheduler
                .block_for_one_resource(creator, &inbound, &Permission::W, None, None, &Ivar::new())
                .is_ok()
        );
        assert!(scheduler.blocked.sigchld_deferred.is_empty());
    }

    /// On a scheduler that does not model signal targets (in-guest LiteInst,
    /// DBT, KVM), a committed signal to a thread asleep in a call outside the
    /// scheduler (a blocking external call, or a vfork parent waiting for its
    /// child) neither arms the thread nor counterfeits a request: the thread
    /// stays in its pool, awaiting its own continuation. Before, a debug build
    /// panicked here ("thread should be parked in the scheduler"). In-guest
    /// LiteInst hit it when a vfork child's exit signalled the parent it had
    /// just killed, and the panic poisoned the scheduler and hung the run.
    #[test]
    fn a_signal_to_a_backgrounded_thread_on_a_scheduler_without_signal_targets_waits_for_its_continuation()
     {
        for vfork in [false, true] {
            let (mut scheduler, parent, creator, _child) = sigchld_family(libc::SIGCHLD);
            scheduler.models_signal_targets = false;
            let op = ExternalOpId::new(creator, 1);
            let rid = if vfork {
                ResourceID::BlockingVfork(op)
            } else {
                ResourceID::BlockingExternalIO(op)
            };
            commit_out_of_scheduler_call(&mut scheduler, creator, rid, None);
            scheduler.runqueue_push_back(parent);

            scheduler.wake_signaled_guest(creator, Signal::SIGCHLD);
            let case = format!("vfork={vfork}");
            assert!(scheduler.blocked.signaled_background.is_empty(), "{case}");
            assert!(
                scheduler
                    .next_turns
                    .get(&creator)
                    .unwrap()
                    .req
                    .try_read()
                    .is_none(),
                "{case}: a request was counterfeited"
            );
            assert_eq!(
                scheduler.blocked.external_io_blockers.get(&creator),
                Some(&op),
                "{case}"
            );
            assert!(!scheduler.run_queue.contains_tid(creator), "{case}");
            assert!(scheduler.run_queue.contains_tid(parent), "{case}");
        }
    }

    /// When the release barrier's watchdog expires with an armed thread that
    /// has still not posted its continuation, the barrier must not drop the
    /// arm and resume scheduling: that would leave the thread for `step2c` to
    /// harvest behind runnable siblings, an admission order that host delivery
    /// time decides. The watchdog's start is backdated here (an injected clock),
    /// so the production bound needs no test knob.
    #[test]
    fn an_expired_release_barrier_keeps_the_arm_and_refuses_the_run() {
        let (mut scheduler, parent, creator, _child) = sigchld_family(libc::SIGCHLD);
        let op = ExternalOpId::new(creator, 1);
        commit_out_of_scheduler_call(
            &mut scheduler,
            creator,
            ResourceID::BlockingRtSigsuspend(op),
            Some(0),
        );
        scheduler.runqueue_push_back(parent);
        scheduler.wake_signaled_guest(creator, Signal::SIGCHLD);
        assert!(scheduler.blocked.signaled_background.contains(&creator));

        // The first empty pass starts the watchdog.
        assert!(scheduler.step2_release_signaled_background().is_err());
        assert!(scheduler.signaled_background_since.is_some());
        scheduler.signaled_background_since = Some(
            std::time::Instant::now()
                .checked_sub(Scheduler::SIGNALED_BACKGROUND_VALVE + Duration::from_secs(1))
                .expect("the monotonic clock has run longer than the watchdog bound"),
        );

        // Expired: the pass is still refused, the arm and the pool entry stay,
        // and nothing is requeued for a later harvest.
        for _ in 0..2 {
            assert!(scheduler.step2_release_signaled_background().is_err());
            assert!(scheduler.blocked.signaled_background.contains(&creator));
            assert_eq!(
                scheduler.blocked.rt_sigsuspend_blockers.get(&creator),
                Some(&op)
            );
            assert!(!scheduler.run_queue.contains_tid(creator));
        }
        // The typed refusal names the thread, and the scheduler loop ends the
        // run with it rather than scheduling on.
        let refusal = scheduler
            .signaled_background_refusal
            .take()
            .expect("an expired barrier records a typed refusal");
        assert_eq!(refusal.unposted, vec![creator]);
        assert!(refusal.waited >= Scheduler::SIGNALED_BACKGROUND_VALVE);
        assert!(
            refusal
                .to_string()
                .starts_with("hermit refused to continue the run")
        );
        // A whole pass is refused as well, so step2c cannot harvest the thread.
        let global_time = Arc::new(Mutex::new(GlobalTime::new(&Config::default())));
        assert!(scheduler.step2_process_blocked(&global_time).is_err());
        assert!(!scheduler.run_queue.contains_tid(creator));
        assert!(scheduler.signaled_background_refusal.is_some());
    }

    /// Armed threads are released together, only once every one has posted,
    /// in an order fixed by thread ID alone: the barrier pushes them in
    /// ascending DetTid order to the front of the run queue (as `step2e` admits
    /// deferred parents), so the highest DetTid runs first. Which stop the host
    /// reports first does not decide the order: both posting orders give the
    /// same run-queue order. A thread that leaves its pool another way (here it
    /// exits) is dropped rather than waited for.
    #[test]
    fn signaled_background_threads_are_released_together_in_thread_id_order() {
        for creator_posts_first in [false, true] {
            let global_time = Arc::new(Mutex::new(GlobalTime::new(&Config::default())));
            let (mut scheduler, parent, creator, child) = sigchld_family(libc::SIGCHLD);
            let sibling = DetTid::from_raw(102);
            scheduler.thread_tree.add_child(parent, sibling, false);
            register_known_thread(&mut scheduler, sibling);
            commit_out_of_scheduler_call(
                &mut scheduler,
                creator,
                ResourceID::BlockingRtSigsuspend(ExternalOpId::new(creator, 1)),
                Some(0),
            );
            commit_out_of_scheduler_call(
                &mut scheduler,
                sibling,
                ResourceID::BlockingExternalIO(ExternalOpId::new(sibling, 1)),
                Some(0),
            );
            commit_out_of_scheduler_call(
                &mut scheduler,
                child,
                ResourceID::BlockingExternalIO(ExternalOpId::new(child, 1)),
                Some(0),
            );
            for thread in [sibling, child, creator] {
                scheduler.wake_signaled_guest(thread, Signal::SIGUSR1);
            }
            assert_eq!(scheduler.blocked.signaled_background.len(), 3);
            assert!(scheduler.blocked.sigchld_ready.is_empty());

            let (first, last) = if creator_posts_first {
                (creator, sibling)
            } else {
                (sibling, creator)
            };
            post_inbound_signal(&mut scheduler, first, libc::SIGUSR1, &global_time);
            assert!(scheduler.step2_release_signaled_background().is_err());
            scheduler.logically_kill_thread(&child, &child, MmId::initial(child));
            assert!(scheduler.step2_release_signaled_background().is_err());
            assert!(!scheduler.run_queue.contains_tid(first));
            assert!(scheduler.signaled_background_since.is_some());

            post_inbound_signal(&mut scheduler, last, libc::SIGUSR1, &global_time);
            assert!(scheduler.step2_release_signaled_background().is_ok());
            assert!(scheduler.blocked.signaled_background.is_empty());
            assert!(scheduler.signaled_background_since.is_none());
            assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(sibling));
            assert_eq!(scheduler.run_queue.commit_tentative_pop(), sibling);
            assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(creator));
            assert_eq!(scheduler.run_queue.commit_tentative_pop(), creator);
            assert!(!scheduler.run_queue.contains_tid(child));
            assert!(scheduler.blocked.external_io_blockers.is_empty());
            assert!(scheduler.blocked.rt_sigsuspend_blockers.is_empty());
            assert!(scheduler.blocked.out_of_scheduler_masks.is_empty());
        }
    }

    /// A signal that does not wake a background call at a known point arms
    /// nothing and counterfeits nothing: the thread stays in its pool for
    /// `step2c` to harvest. That is a vfork parent, which sleeps killable, and
    /// a thread whose recorded sleeping mask blocks the signal or is unknown.
    #[test]
    fn a_signal_that_cannot_wake_a_background_call_leaves_it_in_its_pool() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let cases: [(&str, Option<u64>, bool); 3] = [
            ("vfork parent", Some(0), true),
            ("blocked", Some(chld), false),
            ("unknown mask", None, false),
        ];
        for (case, mask, vfork_parent) in cases {
            let (mut scheduler, _parent, creator, child) = sigchld_family(libc::SIGCHLD);
            let op = ExternalOpId::new(creator, 1);
            commit_out_of_scheduler_call(
                &mut scheduler,
                creator,
                ResourceID::BlockingExternalIO(op),
                Some(0),
            );
            scheduler
                .blocked
                .out_of_scheduler_masks
                .insert(creator, mask);
            if vfork_parent {
                scheduler.vfork_barriers.insert(creator, Some(child));
            }
            scheduler.wake_signaled_guest(creator, Signal::SIGCHLD);
            assert!(scheduler.blocked.signaled_background.is_empty(), "{case}");
            assert!(
                !scheduler.blocked.sigchld_ready.contains(&creator),
                "{case}"
            );
            assert_eq!(
                scheduler.blocked.external_io_blockers.get(&creator),
                Some(&op),
                "{case}"
            );
            assert!(!scheduler.run_queue.contains_tid(creator), "{case}");
            assert!(
                scheduler
                    .next_turns
                    .get(&creator)
                    .unwrap()
                    .req
                    .try_read()
                    .is_none(),
                "{case}"
            );
            assert!(
                scheduler.step2_release_signaled_background().is_ok(),
                "{case}"
            );
        }
    }

    /// A signal another guest sends in its own turn (`notify_signal_pending`)
    /// while a thread is still stopped at its posted `rt_sigsuspend` request
    /// reaches the call, as a timer's send at that point does
    /// (`a_signal_sent_at_an_rt_sigsuspend_request_arms_the_call_it_wakes`):
    /// the send is queued, the step2 drain notes it without arming anything,
    /// and committing the call arms the thread for the release barrier. A
    /// signal the temporary mask blocks is not noted, and nothing arms. Coverage
    /// of main: its drain notes the send
    /// (`BlockedPool::signaled_sigsuspend_requests`) and its grant arms the
    /// note.
    #[test]
    fn a_sibling_signal_sent_at_an_rt_sigsuspend_request_arms_the_call_it_wakes() {
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        // Realtime signals and SIGKILL follow the policy of
        // https://github.com/rrnewton/hermit/issues/3941: a realtime signal the
        // mask admits is noted and armed like a standard one; SIGKILL is too.
        for (case, signal, temporary_mask, armed) in [
            ("admitted", SigWrapper::from(Signal::SIGUSR1), 0, true),
            ("realtime admitted", SigWrapper(35), 0, true),
            (
                "realtime blocked",
                SigWrapper(35),
                kernel_signal_bit(35),
                false,
            ),
            ("blocked", SigWrapper::from(Signal::SIGUSR1), usr1, false),
            ("SIGKILL", SigWrapper::from(Signal::SIGKILL), 0, true),
        ] {
            let (mut scheduler, _parent, creator, _child) = sigchld_family(libc::SIGCHLD);
            let op = ExternalOpId::new(creator, 7);
            let mut request = Resources::new(creator);
            request.insert(ResourceID::BlockingRtSigsuspend(op), Permission::RW);
            request.blocked_signal_mask = Some(temporary_mask);
            scheduler.next_turns.get_mut(&creator).unwrap().req = Ivar::full(Ok(request));
            // Its request is posted, so it waits in the run queue for its turn.
            scheduler.runqueue_push_back(creator);

            scheduler.notify_signal_pending(creator, signal);
            assert_eq!(
                scheduler.pending_cross_task_signals.get(&creator),
                Some(&vec![signal]),
                "{case}"
            );
            assert!(
                scheduler.blocked.signaled_sigsuspend_requests.is_empty(),
                "{case}"
            );
            scheduler.drain_pending_cross_task_signals();
            assert!(scheduler.pending_cross_task_signals.is_empty(), "{case}");
            assert!(scheduler.blocked.signaled_background.is_empty(), "{case}");
            assert_eq!(
                scheduler
                    .blocked
                    .signaled_sigsuspend_requests
                    .get(&creator)
                    .copied(),
                armed.then_some(signal),
                "{case}"
            );
            assert!(scheduler.run_queue.remove_tid(creator), "{case}");
            commit_out_of_scheduler_call(
                &mut scheduler,
                creator,
                ResourceID::BlockingRtSigsuspend(op),
                Some(temporary_mask),
            );
            assert_eq!(
                scheduler.blocked.rt_sigsuspend_blockers.get(&creator),
                Some(&op),
                "{case}"
            );
            assert_eq!(
                scheduler.blocked.signaled_background.contains(&creator),
                armed,
                "{case}"
            );
            assert!(
                scheduler.blocked.signaled_sigsuspend_requests.is_empty(),
                "{case}"
            );
        }
    }

    /// A signal a sibling sends while the waiter's `rt_sigsuspend` request is
    /// posted but not yet granted is delivered by the kernel as soon as the
    /// granted call installs its temporary mask, and the waiter's delivery stop
    /// is its report. The step2 drain notes the send and granting the request
    /// arms the waiter, so every pass is empty until that stop is posted, and
    /// the release barrier then requeues the waiter ahead of the runnable
    /// sibling: no sibling runs between the grant and the waiter's return.
    /// Coverage of main: its drain notes the send
    /// (`BlockedPool::signaled_sigsuspend_requests`) and its grant arms the
    /// note. Adapted from https://github.com/rrnewton/hermit/pull/3224, where a
    /// hold on every other thread gave this order.
    #[tokio::test]
    async fn a_sibling_signal_sent_before_the_rt_sigsuspend_grant_requeues_the_waiter_first() {
        let global_time = Arc::new(Mutex::new(GlobalTime::new(&Config::default())));
        let (mut scheduler, parent, creator, _child) = sigchld_family(libc::SIGCHLD);
        let op = ExternalOpId::new(creator, 1);
        let rid = ResourceID::BlockingRtSigsuspend(op);
        let mut request = Resources::new(creator);
        request.insert(rid.clone(), Permission::RW);
        request.blocked_signal_mask = Some(0);
        let req = scheduler.next_turns[&creator].req.clone();
        scheduler.request_put(&req, request, &global_time);
        // Its request is posted, so it waits in the run queue for its turn.
        scheduler.runqueue_push_back(creator);

        scheduler.notify_signal_pending(creator, SigWrapper(libc::SIGUSR1));
        scheduler.drain_pending_cross_task_signals();
        assert!(scheduler.pending_cross_task_signals.is_empty());
        assert!(scheduler.blocked.signaled_background.is_empty());
        assert_eq!(
            scheduler.blocked.signaled_sigsuspend_requests.get(&creator),
            Some(&SigWrapper::from(Signal::SIGUSR1))
        );

        assert!(scheduler.run_queue.remove_tid(creator));
        commit_out_of_scheduler_call(&mut scheduler, creator, rid, Some(0));
        let req = scheduler.next_turns[&parent].req.clone();
        scheduler.request_put(&req, Resources::new(parent), &global_time);
        scheduler.runqueue_push_back(parent);
        let sched = Arc::new(Mutex::new(scheduler));
        let last: Result<Resources, SkipTurn> = Err(SkipTurn);

        for _ in 0..3 {
            let pass = do_a_turn_blocking(sched.clone(), global_time.clone(), &last).await;
            assert!(pass.is_err(), "the sibling ran before the waiter reported");
            let s = sched.lock().unwrap();
            assert!(s.next_turns[&parent].resp.try_read().is_none());
            assert!(s.run_queue.contains_tid(parent));
        }
        post_inbound_signal(
            &mut sched.lock().unwrap(),
            creator,
            libc::SIGUSR1,
            &global_time,
        );
        let turn = do_a_turn_blocking(sched.clone(), global_time.clone(), &last)
            .await
            .expect("the waiter's delivery turn");
        assert_eq!(turn.tid, creator);
        assert!(
            turn.resources
                .contains_key(&ResourceID::InboundSignal(SigWrapper(libc::SIGUSR1)))
        );
        let s = sched.lock().unwrap();
        assert!(s.next_turns[&parent].resp.try_read().is_none());
        assert!(s.blocked.rt_sigsuspend_blockers.is_empty());
        assert!(s.blocked.signaled_background.is_empty());
    }

    /// The invariant that guards the counterfeit request still holds for every
    /// thread outside the background pools: a signaled thread there must be
    /// parked at a posted request.
    #[test]
    #[should_panic(expected = "signal_guest: thread should be parked in the scheduler")]
    fn a_signal_to_an_unposted_thread_outside_the_background_pools_still_asserts() {
        let (mut scheduler, _parent, creator, _child) = sigchld_family(libc::SIGCHLD);
        scheduler.wake_signaled_guest(creator, Signal::SIGCHLD);
    }

    /// The resources of `thread`'s posted request, or `None` while it has
    /// posted nothing.
    fn request_resources(scheduler: &Scheduler, thread: DetTid) -> Option<Vec<ResourceID>> {
        scheduler.next_turns[&thread]
            .req
            .try_read()
            .map(|request| request.unwrap().resources.keys().cloned().collect())
    }

    /// A synthesized `SIGCHLD` that reaches a vfork parent still inside its real
    /// vfork (its request is empty) arms nothing and counterfeits nothing. A
    /// vfork parent sleeps killable, so the signal stays pending; a counterfeit
    /// request would put a thread that cannot answer on the run queue and lose
    /// the continuation that releases the vfork barrier. Once the child has
    /// exited, the parent's own continuation arrives and the ordinary barrier
    /// and blocker paths return it to the run queue.
    #[test]
    fn child_exit_signal_leaves_vfork_parent_waiting_for_its_continuation() {
        let (mut scheduler, _parent, creator, child) = sigchld_family(libc::SIGCHLD);
        let op = ExternalOpId::new(creator, 7);
        commit_out_of_scheduler_call(
            &mut scheduler,
            creator,
            ResourceID::BlockingExternalIO(op),
            Some(0),
        );
        scheduler.vfork_barriers.insert(creator, Some(child));

        scheduler.wake_signaled_guest(creator, Signal::SIGCHLD);

        assert!(scheduler.blocked.signaled_background.is_empty());
        assert_eq!(
            scheduler.blocked.external_io_blockers.get(&creator),
            Some(&op)
        );
        assert!(!scheduler.run_queue.contains_tid(creator));
        assert_eq!(request_resources(&scheduler, creator), None);

        let mut continuation = Resources::new(creator);
        continuation.insert(ResourceID::BlockedExternalContinue(op), Permission::RW);
        scheduler.next_turns.get_mut(&creator).unwrap().req = Ivar::full(Ok(continuation));
        assert!(scheduler.step2a_wait_for_vfork_barrier().is_ok());
        assert!(scheduler.vfork_barriers.is_empty());
        assert!(scheduler.step2c_process_io_blockers().is_ok());
        assert!(scheduler.blocked.external_io_blockers.is_empty());
        assert!(scheduler.run_queue.contains_tid(creator));
        assert_eq!(
            request_resources(&scheduler, creator),
            Some(vec![ResourceID::BlockedExternalContinue(op)])
        );
    }

    /// A `SIGCHLD` that reaches a vfork parent whose continuation is already
    /// posted neither replaces that continuation nor requeues the parent ahead
    /// of the barrier.
    #[test]
    fn child_exit_signal_does_not_replace_a_posted_vfork_continuation() {
        let (mut scheduler, _parent, creator, child) = sigchld_family(libc::SIGCHLD);
        let op = ExternalOpId::new(creator, 7);
        commit_out_of_scheduler_call(
            &mut scheduler,
            creator,
            ResourceID::BlockingExternalIO(op),
            Some(0),
        );
        scheduler.vfork_barriers.insert(creator, Some(child));
        let mut continuation = Resources::new(creator);
        continuation.insert(ResourceID::BlockedExternalContinue(op), Permission::RW);
        scheduler.next_turns.get_mut(&creator).unwrap().req = Ivar::full(Ok(continuation));

        scheduler.wake_signaled_guest(creator, Signal::SIGCHLD);

        assert!(scheduler.blocked.signaled_background.is_empty());
        assert_eq!(
            scheduler.blocked.external_io_blockers.get(&creator),
            Some(&op)
        );
        assert!(!scheduler.run_queue.contains_tid(creator));
        assert_eq!(
            request_resources(&scheduler, creator),
            Some(vec![ResourceID::BlockedExternalContinue(op)])
        );
    }

    /// A signal that the recorded mask of a thread blocked in external IO
    /// admits arms the thread and leaves it in its pool with its request empty:
    /// the scheduler waits for the thread's own report and every pass until
    /// then is empty.
    #[test]
    fn signal_leaves_blocking_external_io_waiting_for_its_own_report() {
        let (mut scheduler, _parent, creator, _child) = sigchld_family(libc::SIGCHLD);
        let op = ExternalOpId::new(creator, 291);
        commit_out_of_scheduler_call(
            &mut scheduler,
            creator,
            ResourceID::BlockingExternalIO(op),
            Some(0),
        );

        scheduler.wake_signaled_guest(creator, Signal::SIGALRM);

        assert!(scheduler.blocked.signaled_background.contains(&creator));
        assert!(!scheduler.blocked.sigchld_ready.contains(&creator));
        assert_eq!(
            scheduler.blocked.external_io_blockers.get(&creator),
            Some(&op)
        );
        assert!(!scheduler.run_queue.contains_tid(creator));
        assert_eq!(request_resources(&scheduler, creator), None);
        assert!(scheduler.step2_release_signaled_background().is_err());
        assert!(!scheduler.run_queue.contains_tid(creator));
    }

    /// `rt_sigsuspend` completes only through a signal. A signal its recorded
    /// mask admits arms the waiter without counterfeiting a request: the waiter
    /// rejoins the run queue only with the `InboundSignal` report it posts
    /// itself, and that report is what it runs with.
    #[test]
    fn signal_requeues_rt_sigsuspend_without_counterfeiting_its_report() {
        let global_time = Arc::new(Mutex::new(GlobalTime::new(&Config::default())));
        let (mut scheduler, _parent, creator, _child) = sigchld_family(libc::SIGCHLD);
        let op = ExternalOpId::new(creator, 291);
        commit_out_of_scheduler_call(
            &mut scheduler,
            creator,
            ResourceID::BlockingRtSigsuspend(op),
            Some(0),
        );

        scheduler.wake_signaled_guest(creator, Signal::SIGALRM);

        assert!(scheduler.blocked.signaled_background.contains(&creator));
        assert!(!scheduler.blocked.sigchld_ready.contains(&creator));
        assert_eq!(request_resources(&scheduler, creator), None);
        assert!(!scheduler.run_queue.contains_tid(creator));
        assert!(scheduler.step2_release_signaled_background().is_err());

        post_inbound_signal(&mut scheduler, creator, libc::SIGALRM, &global_time);
        assert!(scheduler.step2_release_signaled_background().is_ok());
        assert!(scheduler.blocked.rt_sigsuspend_blockers.is_empty());
        assert!(scheduler.run_queue.contains_tid(creator));
        assert_eq!(
            request_resources(&scheduler, creator),
            Some(vec![ResourceID::InboundSignal(SigWrapper(libc::SIGALRM))])
        );
    }

    /// Only a backend whose blocked waits are interrupted by the kernel's
    /// signal state (`supports_blocked_wait_signal_interruption`)
    /// arms an `rt_sigsuspend` waiter to await its report. On SaBRe, where
    /// the interrupted thread rejoins through its own continuation RPC, the
    /// waiter stays in its pool, unarmed, with its request empty.
    #[test]
    fn signal_leaves_rt_sigsuspend_in_its_pool_on_a_backend_without_a_guaranteed_report() {
        let config = Config::default().with_backend(|backend| {
            backend.reports_physical_process_exits = true;
        });
        let mut scheduler = Scheduler::new(&config);
        assert!(!scheduler.models_signal_targets);
        let waiter = DetTid::from_raw(11);
        let op = ExternalOpId::new(waiter, 291);
        register_known_thread(&mut scheduler, waiter);
        commit_out_of_scheduler_call(
            &mut scheduler,
            waiter,
            ResourceID::BlockingRtSigsuspend(op),
            Some(0),
        );

        scheduler.wake_signaled_guest(waiter, Signal::SIGALRM);

        assert!(scheduler.blocked.signaled_background.is_empty());
        assert_eq!(
            scheduler.blocked.rt_sigsuspend_blockers.get(&waiter),
            Some(&op)
        );
        assert!(!scheduler.run_queue.contains_tid(waiter));
        assert_eq!(request_resources(&scheduler, waiter), None);
    }

    /// A signal the waiter's temporary mask blocks cannot end its
    /// `rt_sigsuspend`, so it must not arm the waiter: the scheduler would then
    /// wait for a report that never comes. Left in its pool, a waiter that
    /// nothing else can wake gets the terminal deadlock verdict instead of a
    /// hang, and the verdict names the mask.
    #[test]
    fn signal_blocked_by_the_rt_sigsuspend_mask_leaves_the_wait_in_its_pool() {
        let mut scheduler = gated_scheduler();
        let global_time = Arc::new(Mutex::new(GlobalTime::new(&Config::default())));
        let waiter = DetTid::from_raw(11);
        let op = ExternalOpId::new(waiter, 291);
        register_known_thread(&mut scheduler, waiter);
        let alarm_bit = kernel_signal_bit(libc::SIGALRM);
        commit_out_of_scheduler_call(
            &mut scheduler,
            waiter,
            ResourceID::BlockingRtSigsuspend(op),
            Some(alarm_bit),
        );

        scheduler.wake_signaled_guest(waiter, Signal::SIGALRM);

        assert!(scheduler.blocked.signaled_background.is_empty());
        assert_eq!(
            scheduler.blocked.rt_sigsuspend_blockers.get(&waiter),
            Some(&op)
        );
        assert!(!scheduler.run_queue.contains_tid(waiter));
        assert_eq!(request_resources(&scheduler, waiter), None);
        assert!(scheduler.step2d_handle_empty_queue(&global_time).is_err());
        let report = scheduler
            .take_terminal_deadlock()
            .expect("a waiter whose mask blocks the only signal is a terminal deadlock");
        assert!(
            report.contains("thread(s) waiting in rt_sigsuspend with no possible signal"),
            "unexpected report:\n{report}"
        );
        assert!(
            report.contains(&format!("temporary mask {:#x}", alarm_bit)),
            "unexpected report:\n{report}"
        );
    }

    /// The scheduler's sigset bits are the kernel's: signal n is bit n - 1, so
    /// realtime signal 64 is bit 63, and a number outside 1..=64 has no bit.
    /// The mask recorded for an `rt_sigsuspend` waiter is the one the kernel
    /// installs, which never blocks SIGKILL or SIGSTOP (the syscall layer's
    /// `kernel_installed_signal_mask`, tested with it). A signal that mask
    /// admits arms the waiter; one it blocks does not.
    #[test]
    fn rt_sigsuspend_mask_uses_kernel_sigset_bits_and_cannot_block_kill_or_stop() {
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        assert_eq!(usr1, 1_u64 << (libc::SIGUSR1 - 1));
        assert_eq!(kernel_signal_bit(64), 1_u64 << 63);
        assert_eq!(kernel_signal_bit(63), 1_u64 << 62);
        for out_of_range in [0, 65, -1, i32::MIN] {
            assert_eq!(kernel_signal_bit(out_of_range), 0, "{out_of_range}");
        }
        // The widest mask the kernel installs.
        let everything = !(kernel_signal_bit(libc::SIGKILL) | kernel_signal_bit(libc::SIGSTOP));
        assert_ne!(everything & kernel_signal_bit(libc::SIGALRM), 0);
        assert_eq!(everything & kernel_signal_bit(libc::SIGKILL), 0);
        assert_eq!(everything & kernel_signal_bit(libc::SIGSTOP), 0);

        let cases = [
            (usr1, Signal::SIGUSR1, false),
            (usr1, Signal::SIGALRM, true),
            (0, Signal::SIGALRM, true),
            (everything, Signal::SIGALRM, false),
        ];
        for (mask, signal, armed) in cases {
            let mut scheduler = gated_scheduler();
            let waiter = DetTid::from_raw(11);
            register_known_thread(&mut scheduler, waiter);
            commit_out_of_scheduler_call(
                &mut scheduler,
                waiter,
                ResourceID::BlockingRtSigsuspend(ExternalOpId::new(waiter, 291)),
                Some(mask),
            );
            scheduler.wake_signaled_guest(waiter, signal);
            assert_eq!(
                scheduler.blocked.signaled_background.contains(&waiter),
                armed,
                "mask {mask:#x}, signal {signal}"
            );
        }
    }

    /// A child-exit timer whose creator already dequeued the kernel's own
    /// `SIGCHLD` for the process, and had that delivery deferred, commits that
    /// delivery instead of sending a second signal. Before, only the leader was
    /// looked up, so the timer sent again and found the deferred creator in no
    /// pool (https://github.com/rrnewton/hermit/issues/3146).
    #[test]
    fn a_child_exit_timer_commits_a_deferred_creator_delivery_without_sending() {
        let global_time = Arc::new(Mutex::new(GlobalTime::new(&Config::default())));
        let (mut scheduler, parent, creator, child) = sigchld_family(libc::SIGCHLD);
        // A send that this test reaches must not reach a real host thread.
        scheduler.backend.requires_thread_directed_process_signals = true;
        let inbound = ResourceID::InboundSignal(SigWrapper(libc::SIGCHLD));
        scheduler.runqueue_push_back(parent);
        scheduler.runqueue_push_back(creator);
        post_inbound_signal(&mut scheduler, creator, libc::SIGCHLD, &global_time);
        assert_eq!(
            scheduler.run_queue.tentative_pop_tid(creator),
            Some(creator)
        );
        assert!(
            scheduler
                .block_for_one_resource(creator, &inbound, &Permission::W, None, None, &Ivar::new())
                .is_err()
        );
        assert!(scheduler.blocked.sigchld_deferred.contains(&creator));
        assert!(!scheduler.run_queue.contains_tid(creator));

        let attempts = scheduler.host_signal_attempts;
        scheduler.dispatch_timed_signal(
            LogicalTime::from_nanos(1),
            timed_waiters::SignalTimerId::ChildExit { child, parent },
            SignalTarget::Process(creator),
            Signal::SIGCHLD.into(),
            true,
            scheduler.committed_time,
        );
        assert_eq!(scheduler.host_signal_attempts, attempts);
        assert!(scheduler.terminal_deadlock.is_none());
        assert!(scheduler.blocked.sigchld_deferred.is_empty());
        assert!(scheduler.blocked.sigchld_ready.contains(&creator));
        assert!(scheduler.run_queue.contains_tid(creator));
    }

    /// What happens to a real-time POSIX timer expiration
    /// (https://github.com/rrnewton/hermit/issues/4089): kept pending only
    /// when every live thread blocks it by a mask the schedule fixes and
    /// nothing can observe it, discarded where Linux discards it, and refused
    /// otherwise.
    fn real_time_family() -> (Scheduler, DetPid, DetTid, DetTid, u64) {
        let (mut scheduler, parent, creator, _child) = sigchld_family(libc::SIGCHLD);
        assert!(scheduler.models_signal_targets);
        let rt = kernel_signal_bit(35);
        for thread in [parent, creator] {
            scheduler.test_kernel_signal_states.insert(
                thread,
                KernelSignalState {
                    blocked: rt,
                    ..signal_state(0, 0)
                },
            );
        }
        (
            scheduler,
            DetPid::from_raw(parent.as_raw()),
            parent,
            creator,
            rt,
        )
    }

    #[test]
    fn a_real_time_expiration_every_thread_blocks_is_kept_pending() {
        let (mut scheduler, process, parent, _creator, rt) = real_time_family();
        assert_eq!(
            scheduler.real_time_expiration_fate(process, SignalTarget::Process(parent), 35),
            RealTimeFate::Queued
        );
        for at in [1, 2] {
            scheduler.dispatch_timed_signal(
                LogicalTime::from_nanos(at),
                timed_waiters::SignalTimerId::Posix(process, 0),
                SignalTarget::Process(parent),
                timed_waiters::TimerSignal::RefuseRealTime(35),
                true,
                scheduler.committed_time,
            );
        }
        // A second expiration of the same signal coalesces into the same bit.
        assert_eq!(scheduler.pending_real_time_expirations(process), rt);
        assert_eq!(
            scheduler.pending_real_time_expirations(DetPid::from_raw(200)),
            0
        );
        assert!(real_time_expiration_kept_pending());
    }

    #[test]
    fn a_real_time_expiration_one_thread_unblocks_is_deliverable() {
        let (mut scheduler, process, parent, creator, _rt) = real_time_family();
        scheduler
            .test_kernel_signal_states
            .insert(creator, signal_state(0, 0));
        assert_eq!(
            scheduler.real_time_expiration_fate(process, SignalTarget::Process(parent), 35),
            RealTimeFate::Deliverable
        );
    }

    /// A5 step 2b: a real-time expiration's fate reads the mask a thread
    /// published in place of `SigBlk`, after the guest's own mask under a
    /// private one, and the kernel's again once the mask is withdrawn.
    #[test]
    fn a_real_time_expiration_reads_the_mask_a_thread_published() {
        let (mut scheduler, process, parent, creator, rt) = real_time_family();
        let mm = MmId::initial(process);
        let fate = |scheduler: &Scheduler| {
            scheduler.real_time_expiration_fate(process, SignalTarget::Process(parent), 35)
        };
        assert_eq!(
            fate(&scheduler),
            RealTimeFate::Queued,
            "SigBlk blocks it everywhere"
        );
        assert!(scheduler.publish_signal_mask(creator, mm, Some(0)));
        assert_eq!(
            fate(&scheduler),
            RealTimeFate::Deliverable,
            "the published mask unblocks it"
        );
        assert!(scheduler.set_saved_guest_sigmask(creator, Some(rt)));
        assert_eq!(
            fate(&scheduler),
            RealTimeFate::Queued,
            "the guest's own mask first"
        );
        assert!(scheduler.set_saved_guest_sigmask(creator, None));
        assert!(scheduler.publish_signal_mask(creator, mm, None));
        assert_eq!(fate(&scheduler), RealTimeFate::Queued, "withdrawn");
    }

    /// A thread-directed real-time expiration
    /// (https://github.com/rrnewton/hermit/issues/4164) is judged by its named
    /// thread alone: kept pending while that thread blocks it, whatever its
    /// siblings do; deliverable when it does not; discarded once it is gone.
    #[test]
    fn a_thread_directed_real_time_expiration_is_judged_by_its_thread_alone() {
        let (mut scheduler, process, parent, creator, _rt) = real_time_family();
        scheduler
            .test_kernel_signal_states
            .insert(parent, signal_state(0, 0));
        let fate = |scheduler: &Scheduler, target| {
            scheduler.real_time_expiration_fate(process, target, 35)
        };
        assert_eq!(
            fate(&scheduler, SignalTarget::Process(creator)),
            RealTimeFate::Deliverable
        );
        assert_eq!(
            fate(&scheduler, SignalTarget::Thread(creator)),
            RealTimeFate::Queued
        );
        assert_eq!(
            fate(&scheduler, SignalTarget::Thread(parent)),
            RealTimeFate::Deliverable
        );
        scheduler.next_turns.remove(&creator);
        assert_eq!(
            fate(&scheduler, SignalTarget::Thread(creator)),
            RealTimeFate::Discarded
        );
    }

    /// `timer_create`'s `sigev_notify_thread_id` must name a live thread of the
    /// caller's process, as Linux's `good_sigevent` requires; a caller in a
    /// nested PID namespace is answered apart, since its ids are not DetTids
    /// (https://github.com/rrnewton/hermit/issues/4164).
    #[test]
    fn a_sigev_thread_id_timer_names_only_a_live_thread_of_its_process() {
        let (mut scheduler, parent, creator, child) = sigchld_family(libc::SIGCHLD);
        let process = DetPid::from_raw(parent.as_raw());
        assert_eq!(
            scheduler.posix_timer_thread(process, creator.as_raw()),
            PosixTimerThread::Thread(creator)
        );
        assert_eq!(
            scheduler.posix_timer_thread(process, parent.as_raw()),
            PosixTimerThread::Thread(parent)
        );
        for named in [child.as_raw(), 0, -1, 999] {
            assert_eq!(
                scheduler.posix_timer_thread(process, named),
                PosixTimerThread::NotInGroup,
                "{named}"
            );
        }
        scheduler.next_turns.remove(&creator);
        assert_eq!(
            scheduler.posix_timer_thread(process, creator.as_raw()),
            PosixTimerThread::NotInGroup
        );
        scheduler.thread_tree.enter_new_pid_namespace(process);
        assert_eq!(
            scheduler.posix_timer_thread(process, parent.as_raw()),
            PosixTimerThread::NestedNamespace
        );
    }

    /// A `SIGEV_THREAD_ID` expiration of a standard signal pending on its
    /// thread: an overrun when the pending copy is this timer's own and not
    /// consumed since, a refusal when it is another source's (another timer,
    /// no record) or a poll of the signal may have consumed it unobserved
    /// (an `rt_sigtimedwait` set, which also clears the record), and a send
    /// once the copy has been taken
    /// (https://github.com/rrnewton/hermit/issues/4164).
    #[test]
    fn a_thread_timer_expiration_beside_a_pending_copy_is_an_overrun_or_a_refusal() {
        let (mut scheduler, parent, creator, _child) = sigchld_family(libc::SIGCHLD);
        let process = DetPid::from_raw(parent.as_raw());
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        let timer = timed_waiters::SignalTimerId::Posix(process, 0);
        let other = timed_waiters::SignalTimerId::Posix(process, 1);
        let pending = |scheduler: &mut Scheduler, bits: u64| {
            scheduler.test_kernel_signal_states.insert(
                creator,
                KernelSignalState {
                    thread_pending: bits,
                    ..signal_state(0, 0)
                },
            );
        };
        pending(&mut scheduler, 0);
        assert_eq!(
            scheduler.thread_timer_send(timer, creator, Signal::SIGUSR1),
            ThreadTimerSend::Send
        );
        scheduler
            .thread_timer_copies
            .insert((creator, libc::SIGUSR1), timer);
        pending(&mut scheduler, usr1);
        assert_eq!(
            scheduler.thread_timer_send(timer, creator, Signal::SIGUSR1),
            ThreadTimerSend::Overrun
        );
        assert!(matches!(
            scheduler.thread_timer_send(other, creator, Signal::SIGUSR1),
            ThreadTimerSend::Refuse(reason) if reason.contains("another timer")
        ));
        scheduler.set_sigtimedwait_set(creator, Some(usr1));
        assert!(matches!(
            scheduler.thread_timer_send(timer, creator, Signal::SIGUSR1),
            ThreadTimerSend::Refuse(reason) if reason.contains("rt_sigtimedwait")
        ));
        scheduler.set_sigtimedwait_set(creator, None);
        assert!(matches!(
            scheduler.thread_timer_send(timer, creator, Signal::SIGUSR1),
            ThreadTimerSend::Refuse(reason) if reason.contains("not sent by this timer")
        ));
        scheduler
            .thread_timer_copies
            .insert((creator, libc::SIGUSR1), timer);
        pending(&mut scheduler, 0);
        assert_eq!(
            scheduler.thread_timer_send(timer, creator, Signal::SIGUSR1),
            ThreadTimerSend::Send
        );
        assert!(scheduler.thread_timer_copies.is_empty());
    }

    /// A thread's timer-copy records go with it, so a later thread given
    /// its tid starts with none (Claude review of
    /// https://github.com/rrnewton/hermit/pull/4203).
    #[test]
    fn a_dead_threads_timer_copy_records_go_with_it() {
        let (mut scheduler, parent, creator, _child) = sigchld_family(libc::SIGCHLD);
        let process = DetPid::from_raw(parent.as_raw());
        let timer = timed_waiters::SignalTimerId::Posix(process, 0);
        scheduler
            .thread_timer_copies
            .insert((creator, libc::SIGUSR1), timer);
        scheduler
            .thread_timer_copies
            .insert((parent, libc::SIGUSR1), timer);
        scheduler.logically_kill_thread(&creator, &process, MmId::initial(process));
        assert_eq!(
            scheduler.thread_timer_copies.keys().collect::<Vec<_>>(),
            vec![&(parent, libc::SIGUSR1)]
        );
    }

    /// An expiration of a `SIGEV_THREAD_ID` timer whose thread has exited is
    /// dropped, with no signal sent to any other thread and nothing recorded
    /// as left in the shared queue, and the periodic timer stays armed, as on
    /// Linux (https://github.com/rrnewton/hermit/issues/4164).
    #[test]
    fn a_sigev_thread_id_expiration_after_its_thread_exited_is_dropped() {
        let (mut scheduler, parent, creator, _child) = sigchld_family(libc::SIGCHLD);
        let process = DetPid::from_raw(parent.as_raw());
        scheduler.next_turns.remove(&creator);
        let period = LogicalTime::from_nanos(10);
        scheduler.register_posix_timer(
            process,
            SignalTarget::Thread(creator),
            0,
            Some(period),
            period,
            Signal::SIGUSR1.into(),
        );
        let (at, event) = scheduler
            .blocked
            .timed_waiters
            .pop_if_before(period)
            .expect("the timer is due");
        let TimedEvent::SignalEvt(id, target, signal) = event else {
            panic!("a timer event, not {event}");
        };
        assert_eq!(target, SignalTarget::Thread(creator));
        scheduler.dispatch_timed_signal(at, id, target, signal, true, at);
        assert_eq!(scheduler.host_signal_attempts, 0);
        assert!(scheduler.undelivered_scheduler_signals.is_empty());
        assert_eq!(
            scheduler.blocked.timed_waiters.iter().collect::<Vec<_>>(),
            vec![(
                LogicalTime::from_nanos(20),
                TimedEvent::SignalEvt(id, SignalTarget::Thread(creator), signal)
            )]
        );
    }

    #[test]
    fn a_real_time_expiration_is_judged_by_a_held_threads_own_mask() {
        // Detcore holds the creator under a private mask that blocks every
        // signal; its own mask does not block the timer's signal.
        let (mut scheduler, process, parent, creator, _rt) = real_time_family();
        scheduler.saved_guest_sigmasks.insert(creator, 0);
        assert_eq!(
            scheduler.real_time_expiration_fate(process, SignalTarget::Process(parent), 35),
            RealTimeFate::Deliverable
        );
        // And one whose own mask blocks it, while the kernel shows nothing blocked.
        let (mut scheduler, process, parent, creator, rt) = real_time_family();
        scheduler
            .test_kernel_signal_states
            .insert(creator, signal_state(0, 0));
        scheduler.saved_guest_sigmasks.insert(creator, rt);
        assert_eq!(
            scheduler.real_time_expiration_fate(process, SignalTarget::Process(parent), 35),
            RealTimeFate::Queued
        );
    }

    #[test]
    fn a_real_time_expiration_with_a_thread_outside_the_schedule_is_deliverable() {
        // Its recorded mask is its call's temporary one, which blocks the
        // signal; the mask restored as the call returns may not.
        let (mut scheduler, process, parent, creator, rt) = real_time_family();
        scheduler
            .blocked
            .out_of_scheduler_masks
            .insert(creator, Some(rt));
        assert_eq!(
            scheduler.real_time_expiration_fate(process, SignalTarget::Process(parent), 35),
            RealTimeFate::Deliverable
        );
    }

    #[test]
    fn a_real_time_expiration_with_an_unreadable_thread_is_deliverable() {
        let (mut scheduler, process, parent, creator, _rt) = real_time_family();
        scheduler.test_kernel_signal_states.remove(&creator);
        scheduler.test_sleeper_read_failures.insert(
            creator,
            sleep_signal::SleeperStateUnreadable::Unreadable(reverie::Errno::EIO),
        );
        assert_eq!(
            scheduler.real_time_expiration_fate(process, SignalTarget::Process(parent), 35),
            RealTimeFate::Deliverable
        );
    }

    #[test]
    fn an_ignored_real_time_expiration_is_discarded_where_a_thread_takes_it() {
        let (mut scheduler, process, parent, creator, rt) = real_time_family();
        for thread in [parent, creator] {
            scheduler.test_kernel_signal_states.insert(
                thread,
                KernelSignalState {
                    blocked: rt,
                    ..signal_state(0, rt)
                },
            );
        }
        // Every thread blocks it: Linux queues it, ignored or not.
        assert_eq!(
            scheduler.real_time_expiration_fate(process, SignalTarget::Process(parent), 35),
            RealTimeFate::Queued
        );
        // A thread that does not block it takes it, and discards it.
        scheduler
            .test_kernel_signal_states
            .insert(creator, signal_state(0, rt));
        assert_eq!(
            scheduler.real_time_expiration_fate(process, SignalTarget::Process(parent), 35),
            RealTimeFate::Discarded
        );
    }

    #[test]
    fn a_real_time_expiration_a_signalfd_or_a_handler_return_could_see_is_deliverable() {
        let (mut scheduler, process, parent, _creator, rt) = real_time_family();
        scheduler.register_signalfd(process, rt);
        assert_eq!(
            scheduler.real_time_expiration_fate(process, SignalTarget::Process(parent), 35),
            RealTimeFate::Deliverable
        );
        let (mut scheduler, process, parent, _creator, rt) = real_time_family();
        scheduler.record_handler_restore_unblocked(process, rt);
        assert_eq!(
            scheduler.real_time_expiration_fate(process, SignalTarget::Process(parent), 35),
            RealTimeFate::Deliverable
        );
        // Another signal's records change nothing.
        let (mut scheduler, process, parent, _creator, _rt) = real_time_family();
        scheduler.register_signalfd(process, kernel_signal_bit(40));
        scheduler.record_handler_restore_unblocked(process, kernel_signal_bit(41));
        assert_eq!(
            scheduler.real_time_expiration_fate(process, SignalTarget::Process(parent), 35),
            RealTimeFate::Queued
        );
        // A child process inherits its creator's records at creation, so a
        // later re-parenting changes nothing.
        let (mut scheduler, _parent_process, _parent, _creator, rt) = real_time_family();
        let child = DetTid::from_raw(200);
        let child_process = DetPid::from_raw(200);
        scheduler.test_kernel_signal_states.insert(
            child,
            KernelSignalState {
                blocked: rt,
                ..signal_state(0, 0)
            },
        );
        assert_eq!(
            scheduler.real_time_expiration_fate(child_process, SignalTarget::Process(child), 35),
            RealTimeFate::Queued
        );
        scheduler.register_signalfd(DetPid::from_raw(100), rt);
        // Recorded after the child was created: not the child's.
        assert_eq!(
            scheduler.real_time_expiration_fate(child_process, SignalTarget::Process(child), 35),
            RealTimeFate::Queued
        );
        scheduler.inherit_real_time_records(DetPid::from_raw(100), child_process);
        assert_eq!(
            scheduler.real_time_expiration_fate(child_process, SignalTarget::Process(child), 35),
            RealTimeFate::Deliverable
        );
    }

    #[test]
    fn a_real_time_expiration_after_a_call_outside_the_schedule_is_deliverable() {
        // The call's thread has rejoined, at a host-timed moment; the process
        // keeps the record.
        let (mut scheduler, process, parent, _creator, _rt) = real_time_family();
        scheduler.background_call_processes.insert(process);
        assert_eq!(
            scheduler.real_time_expiration_fate(process, SignalTarget::Process(parent), 35),
            RealTimeFate::Deliverable
        );
    }

    #[test]
    fn a_real_time_expiration_of_a_process_without_live_threads_is_discarded() {
        let (mut scheduler, process, parent, creator, _rt) = real_time_family();
        scheduler.next_turns.remove(&parent);
        scheduler.next_turns.remove(&creator);
        assert_eq!(
            scheduler.real_time_expiration_fate(process, SignalTarget::Process(parent), 35),
            RealTimeFate::Discarded
        );
    }

    #[test]
    fn without_signal_target_modelling_the_arming_thread_decides_as_before() {
        let (mut scheduler, process, parent, creator, rt) = real_time_family();
        scheduler.models_signal_targets = false;
        // Every thread blocks it, but nothing is kept pending.
        assert_eq!(
            scheduler.real_time_expiration_fate(process, SignalTarget::Process(parent), 35),
            RealTimeFate::Deliverable
        );
        scheduler
            .test_kernel_signal_states
            .insert(creator, signal_state(0, rt));
        assert_eq!(
            scheduler.real_time_expiration_fate(process, SignalTarget::Process(creator), 35),
            RealTimeFate::Discarded
        );
    }

    #[test]
    fn a_pending_real_time_expiration_is_discarded_by_ignore_and_by_exit() {
        let (mut scheduler, process, parent, creator, rt) = real_time_family();
        let other = kernel_signal_bit(40);
        scheduler
            .pending_real_time_expirations
            .insert(process, rt | other);
        scheduler.discard_pending_real_time_expirations(process, rt);
        assert_eq!(scheduler.pending_real_time_expirations(process), other);
        scheduler.discard_pending_real_time_expirations(process, other);
        assert!(
            !scheduler
                .pending_real_time_expirations
                .contains_key(&process)
        );
        // The process's exit discards what is left, once its last thread goes.
        scheduler.pending_real_time_expirations.insert(process, rt);
        scheduler.logically_kill_thread(&creator, &process, MmId::initial(process));
        assert_eq!(scheduler.pending_real_time_expirations(process), rt);
        scheduler.logically_kill_thread(&parent, &process, MmId::initial(process));
        assert_eq!(scheduler.pending_real_time_expirations(process), 0);
    }

    /// The barrier runs before anything else in a pass: while an armed thread
    /// has posted nothing, a due timer is not popped and the pass is empty;
    /// once it has posted, the pass requeues it first and then goes on.
    #[test]
    fn the_signaled_background_barrier_runs_before_any_timer_pop() {
        let global_time = Arc::new(Mutex::new(GlobalTime::new(&Config::default())));
        let (mut scheduler, parent, creator, child) = sigchld_family(libc::SIGCHLD);
        // A send that this test reaches must not reach a real host thread.
        scheduler.backend.requires_thread_directed_process_signals = true;
        commit_out_of_scheduler_call(
            &mut scheduler,
            creator,
            ResourceID::BlockingRtSigsuspend(ExternalOpId::new(creator, 1)),
            Some(0),
        );
        scheduler.wake_signaled_guest(creator, Signal::SIGUSR1);
        scheduler.blocked.timed_waiters.insert_child_exit(
            LogicalTime::from_nanos(0),
            child,
            parent,
            creator,
        );
        assert!(scheduler.step2_process_blocked(&global_time).is_err());
        assert_eq!(scheduler.blocked.timed_waiters.iter().count(), 1);
        assert!(!scheduler.run_queue.contains_tid(creator));

        post_inbound_signal(&mut scheduler, creator, libc::SIGUSR1, &global_time);
        let _ = scheduler.step2_process_blocked(&global_time);
        assert!(scheduler.run_queue.contains_tid(creator));
        assert!(scheduler.blocked.signaled_background.is_empty());
        assert!(scheduler.blocked.rt_sigsuspend_blockers.is_empty());
        assert_eq!(scheduler.blocked.timed_waiters.iter().count(), 0);
    }

    /// A `SIGCHLD` delivery that no scheduler decision placed is deferred behind
    /// a runnable sibling, as a host-async signal is, so the sibling's work runs
    /// first. A committed futex wake no longer places one: no `SIGCHLD` ends a
    /// gated wait (https://github.com/rrnewton/hermit/issues/3146).
    #[test]
    fn an_unplaced_sigchld_delivery_is_deferred_behind_a_runnable_sibling() {
        let inbound = ResourceID::InboundSignal(SigWrapper(libc::SIGCHLD));
        let (mut scheduler, parent, creator, _child) = sigchld_family(libc::SIGCHLD);
        scheduler.runqueue_push_back(creator);
        scheduler.runqueue_push_back(parent);
        assert!(!scheduler.blocked.sigchld_ready.contains(&parent));
        assert_eq!(scheduler.run_queue.tentative_pop_tid(parent), Some(parent));
        assert!(
            scheduler
                .block_for_one_resource(parent, &inbound, &Permission::W, None, None, &Ivar::new())
                .is_err()
        );
        assert!(scheduler.blocked.sigchld_deferred.contains(&parent));
        assert!(!scheduler.run_queue.contains_tid(parent));
        assert!(!scheduler.blocked.sigchld_ready.contains(&parent));
    }

    /// A precise futex waiter woken for a signal is queued ahead of a thread that
    /// was already runnable, so it is the thread that resumes and dequeues the
    /// signal (https://github.com/rrnewton/hermit/issues/3146).
    #[test]
    fn a_signal_woken_futex_waiter_runs_before_an_already_runnable_thread() {
        let usr1 = kernel_signal_bit(libc::SIGUSR1);
        for scheduler_send in [false, true] {
            let mut scheduler = gated_scheduler();
            let (target, futex) = parked_futex_target(&mut scheduler);
            let runnable = DetTid::from_raw(101);
            register_known_thread(&mut scheduler, runnable);
            scheduler.runqueue_push_back(runnable);
            scheduler.sleep_futex_waiter(&target, futex, None, u32::MAX, Some(signal_watch(usr1)));
            scheduler
                .test_kernel_signal_states
                .insert(target, signal_state(usr1, 0));
            if scheduler_send {
                scheduler.wake_signaled_guest(target, Signal::SIGUSR1);
            } else {
                scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
                scheduler.drain_pending_cross_task_signals();
            }
            assert_eq!(
                scheduler.run_queue.tids().copied().collect::<Vec<_>>(),
                vec![target, runnable]
            );
        }
    }

    /// A child whose `exit_group` was granted has a `ChildExit` timer that sends
    /// the parent's `SIGCHLD` at a fixed logical time. Its logical death leaves
    /// the timer armed and sends nothing itself, and the timer names the thread
    /// that created the child, the one Linux prefers
    /// (https://github.com/rrnewton/hermit/issues/3146).
    #[test]
    fn a_child_exit_timer_names_the_thread_that_created_the_child() {
        let (mut scheduler, parent, creator, child) = sigchld_family(libc::SIGCHLD);
        park_for_sigchld(&mut scheduler, creator, kernel_signal_bit(libc::SIGCHLD));
        let child_process = DetPid::from_raw(200);
        let deadline = scheduler.committed_time + LogicalTime::from_nanos(1);
        assert!(
            scheduler
                .block_for_one_resource(
                    child,
                    &ResourceID::Exit {
                        group: true,
                        process: child_process,
                        mm: MmId::initial(child),
                    },
                    &Permission::RW,
                    None,
                    None,
                    &Ivar::new(),
                )
                .is_ok()
        );

        scheduler.logically_kill_thread(&child, &child, MmId::initial(child));

        assert!(scheduler.pending_cross_task_signals.is_empty());
        assert_eq!(
            scheduler.blocked.timed_waiters.iter().collect::<Vec<_>>(),
            vec![(
                deadline,
                TimedEvent::SignalEvt(
                    timed_waiters::SignalTimerId::ChildExit {
                        child: child_process,
                        parent,
                    },
                    SignalTarget::Process(creator),
                    Signal::SIGCHLD.into(),
                ),
            )]
        );
    }

    /// The first `SIGCHLD` delivered for an owned child's exit stands for it
    /// (`child_exit_sigchld`): once the kernel's copy was delivered, the
    /// child's `ChildExit` timer sends none, which before was a second
    /// `SIGCHLD` for that exit. Without that delivery the timer sends its own.
    #[test]
    fn a_child_exit_timer_sends_nothing_after_the_kernels_copy() {
        use child_exit_sigchld::ChildExitSigchldAnswer;
        use child_exit_sigchld::ChildExitSigchldControl;
        for kernel_copy_first in [false, true] {
            let mut scheduler = Scheduler::new(&Config::default());
            let parent = DetPid::from_raw(100);
            let child = DetPid::from_raw(200);
            register_known_thread(&mut scheduler, parent);
            assert_eq!(
                scheduler.child_exit_sigchld_control(
                    child,
                    ChildExitSigchldControl::ExitStatus {
                        code: libc::CLD_EXITED,
                        status: 7,
                        uid: 0,
                    },
                ),
                ChildExitSigchldAnswer::Recorded
            );
            assert!(scheduler.child_exit_sigchld.own(parent, child));
            if kernel_copy_first {
                assert_eq!(
                    scheduler.child_exit_sigchld_control(
                        parent,
                        ChildExitSigchldControl::ClaimKernelCopy { child },
                    ),
                    ChildExitSigchldAnswer::Claimed(false),
                    "the kernel's copy is the first, and is delivered"
                );
            }
            let attempts = scheduler.host_signal_attempts;
            scheduler.dispatch_timed_signal(
                scheduler.committed_time,
                timed_waiters::SignalTimerId::ChildExit { child, parent },
                SignalTarget::Process(parent),
                Signal::SIGCHLD.into(),
                true,
                scheduler.committed_time,
            );
            assert_eq!(
                scheduler.host_signal_attempts - attempts,
                u64::from(!kernel_copy_first),
                "kernel copy first: {kernel_copy_first}"
            );
        }
    }

    /// A nested parent names its children by its own namespace's pids
    /// (https://github.com/rrnewton/hermit/issues/4155). The kernel's copy of
    /// a child's exit `SIGCHLD` carries the child's nested pid, which claims
    /// that child's exit, so its `ChildExit` timer then sends nothing. The
    /// scheduler's own copy is delivered with the nested pid, not the DetPid.
    /// A dequeue of a kernel copy whose pid names no task there is taken as
    /// another copy.
    #[test]
    fn a_nested_parents_child_exit_sigchld_is_answered_in_its_namespace() {
        use child_exit_sigchld::ChildExitSigchldAnswer;
        use child_exit_sigchld::ChildExitSigchldControl;
        use child_exit_sigchld::DequeuedCopy;
        use child_exit_sigchld::OwnCopy;
        use child_exit_sigchld::TimerSend;
        for kernel_copy_first in [false, true] {
            let mut scheduler = Scheduler::new(&Config::default());
            let parent = DetPid::from_raw(100);
            let child = DetPid::from_raw(200);
            register_known_thread(&mut scheduler, parent);
            let namespaces = &mut scheduler.thread_tree.pid_namespaces;
            namespaces.record(parent, &[parent], &[100, 1]).unwrap();
            namespaces.record(child, &[parent], &[200, 2]).unwrap();
            assert_eq!(
                scheduler.child_exit_sigchld_control(
                    child,
                    ChildExitSigchldControl::ExitStatus {
                        code: libc::CLD_EXITED,
                        status: 7,
                        uid: 0,
                    },
                ),
                ChildExitSigchldAnswer::Recorded
            );
            assert!(scheduler.child_exit_sigchld.own(parent, child));
            if kernel_copy_first {
                assert_eq!(
                    scheduler.child_exit_sigchld_control_for_receiver(
                        parent,
                        ChildExitSigchldControl::Dequeue {
                            copy: DequeuedCopy::Kernel {
                                child: DetPid::from_raw(99),
                            },
                            admits: true,
                        },
                    ),
                    ChildExitSigchldAnswer::Recorded,
                    "a pid that names no task in the namespace"
                );
                assert_eq!(
                    scheduler.child_exit_sigchld_control_for_receiver(
                        parent,
                        ChildExitSigchldControl::Dequeue {
                            copy: DequeuedCopy::Kernel {
                                child: DetPid::from_raw(2),
                            },
                            admits: true,
                        },
                    ),
                    ChildExitSigchldAnswer::Claimed(false)
                );
                assert_eq!(
                    scheduler.child_exit_sigchld.timer(parent, child),
                    Some(TimerSend::Nothing),
                    "the nested pid claimed the child's exit"
                );
            } else {
                assert_eq!(
                    scheduler.child_exit_sigchld.timer(parent, child),
                    Some(TimerSend::Send)
                );
                match scheduler.child_exit_sigchld_control_for_receiver(
                    parent,
                    ChildExitSigchldControl::Dequeue {
                        copy: DequeuedCopy::Scheduler,
                        admits: true,
                    },
                ) {
                    ChildExitSigchldAnswer::OwnCopy(OwnCopy::Deliver(info)) => {
                        assert_eq!(info.pid, 2, "the own copy names the child's nested pid")
                    }
                    other => panic!("the own copy is delivered, not {other:?}"),
                }
            }
        }
    }

    #[test]
    fn pending_signal_does_not_rewrite_other_internal_pollers() {
        let mut scheduler = Scheduler::new(&Config::default());
        let target = DetTid::from_raw(100);
        register_known_thread(&mut scheduler, target);
        let mut polling = Resources::new(target);
        polling.insert(ResourceID::InternalIOPolling, Permission::W);
        polling.set_signal_interrupt_errno(Errno::EINTR);
        polling.fyi("poll");
        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(polling));
        scheduler.runqueue_push_back(target);

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));

        assert!(scheduler.pending_cross_task_signals.is_empty());
        assert!(scheduler.run_queue.contains_tid(target));
        assert!(scheduler.inbound_signals(target).is_empty());

        scheduler.drain_pending_cross_task_signals();

        assert!(scheduler.run_queue.contains_tid(target));
        assert!(scheduler.inbound_signals(target).is_empty());
        let resources = scheduler
            .next_turns
            .get(&target)
            .and_then(|next_turn| next_turn.req.try_read())
            .and_then(Result::ok)
            .expect("the target should hold its signal interruption request");
        assert_eq!(resources.resources.len(), 1);
        assert!(
            resources
                .resources
                .contains_key(&ResourceID::InternalIOPolling)
        );
    }

    #[test]
    fn pending_signal_does_not_rewrite_an_unmarked_internal_poller() {
        let mut scheduler = Scheduler::new(&Config::default());
        let target = DetTid::from_raw(100);
        register_known_thread(&mut scheduler, target);
        let mut polling = Resources::new(target);
        polling.insert(ResourceID::InternalIOPolling, Permission::W);
        polling.fyi("write");
        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(polling));
        scheduler.runqueue_push_back(target);

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        scheduler.drain_pending_cross_task_signals();

        assert!(scheduler.pending_cross_task_signals.is_empty());
        assert!(scheduler.run_queue.contains_tid(target));
        assert!(scheduler.inbound_signals(target).is_empty());
        let resources = scheduler
            .next_turns
            .get(&target)
            .and_then(|next_turn| next_turn.req.try_read())
            .and_then(Result::ok)
            .expect("the target should retain its polling request");
        assert_eq!(resources.resources.len(), 1);
        assert!(
            resources
                .resources
                .contains_key(&ResourceID::InternalIOPolling)
        );
        assert_eq!(resources.signal_interrupt_errno(), None);
    }

    #[test]
    fn unsupported_backend_does_not_rewrite_a_marked_internal_poller() {
        let config = Config::default().with_backend(|backend| {
            backend.supports_parked_write_signal_interruption = false;
        });
        let mut scheduler = Scheduler::new(&config);
        let target = DetTid::from_raw(100);
        register_known_thread(&mut scheduler, target);
        let mut polling = Resources::new(target);
        polling.insert(ResourceID::InternalIOPolling, Permission::W);
        polling.set_signal_interrupt_errno(Errno::ERESTARTSYS);
        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(polling));
        scheduler.runqueue_push_back(target);

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        scheduler.drain_pending_cross_task_signals();

        assert!(scheduler.pending_cross_task_signals.is_empty());
        assert!(scheduler.run_queue.contains_tid(target));
        assert!(scheduler.inbound_signals(target).is_empty());
        assert!(scheduler.take_terminal_deadlock().is_none());
        let resources = scheduler
            .next_turns
            .get(&target)
            .and_then(|next_turn| next_turn.req.try_read())
            .and_then(Result::ok)
            .expect("the target should retain its polling request");
        assert!(
            resources
                .resources
                .contains_key(&ResourceID::InternalIOPolling)
        );
        assert_eq!(
            resources.signal_interrupt_errno(),
            Some(Errno::ERESTARTSYS.into_raw())
        );
    }

    /// A restartable internal read poller, as `retry_nonblocking_syscall_helper`
    /// marks one, with SIGUSR1 blocked and SIGUSR2 caught.
    /// A restartable internal IO poll is admitted, in the sender's turn, only
    /// for a signal its mask leaves unblocked: the kernel's mask, or the
    /// guest's own while Detcore holds the thread under a private one, as a
    /// pipe `writev` does (`saved_guest_sigmasks`; R2b-1 rule 1, the Claude
    /// implementation review, F5).
    #[test]
    fn a_poll_is_admitted_only_for_a_signal_its_mask_leaves_unblocked() {
        let usr1 = SigWrapper::from(Signal::SIGUSR1);
        let usr2 = SigWrapper::from(Signal::SIGUSR2);
        let admitted = |scheduler: &Scheduler, target| {
            scheduler
                .pending_cross_task_signals
                .get(&target)
                .cloned()
                .unwrap_or_default()
        };
        let mut scheduler = gated_scheduler();
        let target = restartable_read_poller(&mut scheduler);
        scheduler.notify_signal_pending(target, usr1);
        scheduler.notify_signal_pending(target, usr2);
        assert_eq!(
            admitted(&scheduler, target),
            vec![usr2],
            "the kernel's mask blocks SIGUSR1"
        );

        let mut scheduler = gated_scheduler();
        let target = restartable_read_poller(&mut scheduler);
        assert!(scheduler.set_saved_guest_sigmask(target, Some(kernel_signal_bit(libc::SIGUSR2))));
        scheduler.notify_signal_pending(target, usr1);
        scheduler.notify_signal_pending(target, usr2);
        assert_eq!(
            admitted(&scheduler, target),
            vec![usr1],
            "the guest's saved mask decides while a private one is installed"
        );
    }

    /// A poll the drain woke is marked (`DrainWokenWaiter::Poll`): a
    /// `SIGCHLD` the drain merges into its batch is not committed to it, and
    /// its turn decides from what is still pending then. A `SIGCHLD` the
    /// scheduler sends at a commit point (`wake_signaled_guest`, such as a
    /// child-exit timer's) is committed, to a drain-woken poll and to a queued
    /// one, and the answer names it (R2b-1 rule 7; the Claude implementation
    /// review, F4).
    #[test]
    fn only_a_scheduler_sent_sigchld_is_committed_to_a_woken_poll() {
        let chld = kernel_signal_bit(libc::SIGCHLD);
        let usr2 = kernel_signal_bit(libc::SIGUSR2);
        let usr2_signal = SigWrapper::from(Signal::SIGUSR2);
        let chld_signal = SigWrapper::from(Signal::SIGCHLD);
        for case in ["merged", "woken for SIGUSR2", "queued"] {
            let mut scheduler = gated_scheduler();
            let target = restartable_read_poller(&mut scheduler);
            scheduler.test_kernel_signal_states.insert(
                target,
                KernelSignalState {
                    caught: chld | usr2,
                    ..Default::default()
                },
            );
            let expected = match case {
                "merged" => {
                    scheduler.notify_signal_pending(target, usr2_signal);
                    scheduler.drain_pending_cross_task_signals();
                    assert_eq!(
                        scheduler
                            .blocked
                            .drain_woken_waiters
                            .get(&target)
                            .map(|woken| woken.waiter),
                        Some(DrainWokenWaiter::Poll),
                        "the drain marks the poll it woke"
                    );
                    scheduler.notify_signal_pending(target, chld_signal);
                    scheduler.drain_pending_cross_task_signals();
                    vec![usr2_signal]
                }
                "woken for SIGUSR2" => {
                    scheduler.notify_signal_pending(target, usr2_signal);
                    scheduler.drain_pending_cross_task_signals();
                    scheduler.wake_signaled_guest(target, Signal::SIGCHLD);
                    vec![usr2_signal, chld_signal]
                }
                _ => {
                    scheduler.wake_signaled_guest(target, Signal::SIGCHLD);
                    vec![chld_signal]
                }
            };
            let answer = turn_answer(&mut scheduler, target);
            assert!(
                matches!(&answer, Some(SchedResponse::Signaled(Some(signals))) if *signals == expected),
                "{case}: {answer:?}"
            );
        }
    }

    fn restartable_read_poller(scheduler: &mut Scheduler) -> DetTid {
        let target = DetTid::from_raw(100);
        register_known_thread(scheduler, target);
        let mut polling = Resources::new(target);
        polling.insert(ResourceID::InternalIOPolling, Permission::W);
        polling.set_signal_interrupt_errno(Errno::ERESTARTSYS);
        polling.fyi("read");
        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(polling));
        scheduler.runqueue_push_back(target);
        scheduler.test_kernel_signal_states.insert(
            target,
            KernelSignalState {
                caught: kernel_signal_bit(libc::SIGUSR1) | kernel_signal_bit(libc::SIGUSR2),
                blocked: kernel_signal_bit(libc::SIGUSR1),
                ..Default::default()
            },
        );
        target
    }

    /// Only a signal the kernel would deliver ends a restartable internal
    /// read poll: the blocked SIGUSR1 is dropped, and the caught SIGUSR2
    /// rewrites the request to its `ERESTARTSYS` wake
    /// (https://github.com/rrnewton/hermit/issues/4187).
    #[test]
    fn a_blocked_signal_does_not_end_a_restartable_internal_read_poll() {
        let mut scheduler = Scheduler::new(&Config::default());
        let target = restartable_read_poller(&mut scheduler);

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR2));
        scheduler.drain_pending_cross_task_signals();

        assert!(scheduler.run_queue.contains_tid(target));
        assert_eq!(
            scheduler.inbound_signals(target),
            vec![SigWrapper::from(Signal::SIGUSR2)]
        );
        let resources = scheduler
            .next_turns
            .get(&target)
            .and_then(|next_turn| next_turn.req.try_read())
            .and_then(Result::ok)
            .expect("the target should hold its signal interruption request");
        assert!(
            resources
                .resources
                .contains_key(&ResourceID::WaitidSignals(vec![SigWrapper::from(
                    Signal::SIGUSR2
                )]))
        );
        assert_eq!(
            resources.signal_interrupt_errno(),
            Some(Errno::ERESTARTSYS.into_raw())
        );
    }

    /// A poll that blocks every blockable signal in place (R2b-2 stage 2,
    /// `KernelSignalWait::block_in_place`) publishes the guest's own mask, and
    /// the drain filters by that mask, as admission does: the caught SIGUSR1
    /// the guest's mask leaves unblocked wakes the poll although the kernel's
    /// mask, scripted here as every blockable signal, blocks it. Without the
    /// published mask the drain dropped it, and the poll ended for the signal
    /// only at its backed-off turn (Claude review of R2b-2 stage 2, F1;
    /// https://github.com/rrnewton/hermit/issues/4273).
    #[test]
    fn the_drain_filters_a_poll_blocked_in_place_by_its_published_guest_mask() {
        let mut scheduler = Scheduler::new(&Config::default());
        let target = restartable_read_poller(&mut scheduler);
        let state = scheduler.test_kernel_signal_states[&target];
        scheduler.test_kernel_signal_states.insert(
            target,
            KernelSignalState {
                blocked: !0,
                ..state
            },
        );
        scheduler.set_saved_guest_sigmask(target, Some(0));

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        scheduler.drain_pending_cross_task_signals();

        assert!(scheduler.run_queue.contains_tid(target));
        assert_eq!(
            scheduler.inbound_signals(target),
            vec![SigWrapper::from(Signal::SIGUSR1)]
        );

        // The control: with nothing published, the kernel's full mask decides,
        // and the poll keeps polling.
        let mut unpublished = Scheduler::new(&Config::default());
        let target = restartable_read_poller(&mut unpublished);
        let state = unpublished.test_kernel_signal_states[&target];
        unpublished.test_kernel_signal_states.insert(
            target,
            KernelSignalState {
                blocked: !0,
                ..state
            },
        );
        unpublished.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        unpublished.drain_pending_cross_task_signals();
        assert!(unpublished.inbound_signals(target).is_empty());
    }

    /// With only a blocked signal pending, the poller keeps its polling
    /// request and its place in the run queue: the guest would otherwise see
    /// `ERESTARTSYS` with no signal to deliver, or never run again.
    #[test]
    fn a_restartable_internal_read_poll_with_only_a_blocked_signal_keeps_polling() {
        let mut scheduler = Scheduler::new(&Config::default());
        let target = restartable_read_poller(&mut scheduler);

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        scheduler.drain_pending_cross_task_signals();

        assert!(scheduler.run_queue.contains_tid(target));
        assert!(scheduler.inbound_signals(target).is_empty());
        let resources = scheduler
            .next_turns
            .get(&target)
            .and_then(|next_turn| next_turn.req.try_read())
            .and_then(Result::ok)
            .expect("the target should retain its polling request");
        assert_eq!(resources.resources.len(), 1);
        assert!(
            resources
                .resources
                .contains_key(&ResourceID::InternalIOPolling)
        );
    }

    /// On a backend that owns process signal control (KVM) a guest thread ID
    /// is not a host task, so the drain never reads kernel signal state for
    /// it: `/proc/<pid>/task/<tid>` would describe an unrelated host task,
    /// chosen by host thread-ID allocation. The backend reports the state
    /// instead, through the run-scoped control (SIGSHARE S2; its matrix is
    /// `scheduler::signal_state_reader_tests`). With no control installed,
    /// as here, nothing answers, and every signal the wait does not hold
    /// wakes the poll: here the SIGUSR1 that the (never consulted) scripted
    /// `/proc` state blocks still wakes it. On ptrace the same poll is
    /// filtered by that state.
    #[test]
    fn the_drain_never_reads_kernel_signal_state_under_process_signal_control() {
        use std::sync::atomic::Ordering;
        let config = Config::default().with_backend(|backend| {
            backend.provides_process_signal_control = true;
            backend.supports_parked_write_signal_interruption = true;
        });
        let mut scheduler = Scheduler::new(&config);
        let target = restartable_read_poller(&mut scheduler);

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        scheduler.drain_pending_cross_task_signals();

        assert_eq!(
            scheduler
                .test_internal_io_signal_state_reads
                .load(Ordering::Relaxed),
            0,
            "the drain read a guest thread's kernel signal state"
        );
        assert_eq!(
            scheduler.inbound_signals(target),
            vec![SigWrapper::from(Signal::SIGUSR1)]
        );

        let mut ptrace = Scheduler::new(&Config::default());
        let target = restartable_read_poller(&mut ptrace);
        ptrace.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        ptrace.drain_pending_cross_task_signals();
        assert_eq!(
            ptrace
                .test_internal_io_signal_state_reads
                .load(Ordering::Relaxed),
            1
        );
        assert!(ptrace.inbound_signals(target).is_empty());
    }

    /// A poll that decides for itself whether a signal interrupts it (a
    /// parked pipe `writev`, which polls with every ordinary signal blocked)
    /// is not filtered by the drain: with its scripted kernel state blocking
    /// SIGUSR1, the caught SIGUSR1 still wakes it, and the rewritten request
    /// keeps the marker for a later batch
    /// (https://github.com/rrnewton/hermit/issues/4187).
    #[test]
    fn the_drain_does_not_filter_a_poll_that_decides_signal_interruption_itself() {
        let mut scheduler = Scheduler::new(&Config::default());
        let target = DetTid::from_raw(100);
        register_known_thread(&mut scheduler, target);
        let mut polling = Resources::new(target);
        polling.insert(ResourceID::InternalIOPolling, Permission::W);
        polling.set_signal_interrupt_errno(Errno::ERESTARTSYS);
        polling.decides_signal_interruption_itself = true;
        polling.fyi("writev");
        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(polling));
        scheduler.runqueue_push_back(target);
        scheduler.test_kernel_signal_states.insert(
            target,
            KernelSignalState {
                caught: kernel_signal_bit(libc::SIGUSR1),
                blocked: kernel_signal_bit(libc::SIGUSR1),
                ..Default::default()
            },
        );

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        scheduler.drain_pending_cross_task_signals();

        assert!(scheduler.run_queue.contains_tid(target));
        assert_eq!(
            scheduler.inbound_signals(target),
            vec![SigWrapper::from(Signal::SIGUSR1)]
        );
        let resources = scheduler
            .next_turns
            .get(&target)
            .and_then(|next_turn| next_turn.req.try_read())
            .and_then(Result::ok)
            .expect("the target should hold its signal interruption request");
        assert!(resources.decides_signal_interruption_itself);
        assert_eq!(
            resources.signal_interrupt_errno(),
            Some(Errno::ERESTARTSYS.into_raw())
        );
    }

    #[test]
    fn pending_signals_preserve_a_restartable_internal_write_pollers_signal_set() {
        let mut scheduler = Scheduler::new(&Config::default());
        let target = DetTid::from_raw(100);
        register_known_thread(&mut scheduler, target);
        let mut polling = Resources::new(target);
        polling.insert(ResourceID::InternalIOPolling, Permission::W);
        polling.set_signal_interrupt_errno(Errno::ERESTARTSYS);
        polling.fyi("writev");
        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(polling));
        scheduler.runqueue_push_back(target);

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR2));
        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        scheduler.drain_pending_cross_task_signals();

        assert!(scheduler.run_queue.contains_tid(target));
        assert_eq!(
            scheduler.inbound_signals(target),
            vec![
                SigWrapper::from(Signal::SIGUSR1),
                SigWrapper::from(Signal::SIGUSR2)
            ]
        );
        let resources = scheduler
            .next_turns
            .get(&target)
            .and_then(|next_turn| next_turn.req.try_read())
            .and_then(Result::ok)
            .expect("the target should hold its signal interruption request");
        assert_eq!(resources.resources.len(), 1);
        assert!(
            resources
                .resources
                .contains_key(&ResourceID::WaitidSignals(vec![
                    SigWrapper::from(Signal::SIGUSR1),
                    SigWrapper::from(Signal::SIGUSR2)
                ]))
        );
        assert_eq!(
            resources.signal_interrupt_errno(),
            Some(Errno::ERESTARTSYS.into_raw())
        );

        // A signal arriving after the request was rewritten must remain part
        // of the same one-resource response rather than being dropped.
        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGTERM));
        scheduler.drain_pending_cross_task_signals();
        assert_eq!(
            scheduler.inbound_signals(target),
            vec![
                SigWrapper::from(Signal::SIGUSR1),
                SigWrapper::from(Signal::SIGUSR2),
                SigWrapper::from(Signal::SIGTERM),
            ]
        );

        let response = scheduler.next_turns[&target].resp.clone();
        let (selected, _, selected_response) = scheduler.step3_peek().unwrap();
        assert_eq!(selected, target);
        assert!(
            scheduler
                .step4_resource_block(target, &resources, &selected_response)
                .is_ok()
        );
        assert!(
            scheduler
                .step5_guest_unblock(target, &resources, &selected_response)
                .is_ok()
        );
        assert!(matches!(
            response.try_read(),
            Some(SchedResponse::Signaled(Some(signals)))
                if signals == vec![
                    SigWrapper::from(Signal::SIGUSR1),
                    SigWrapper::from(Signal::SIGUSR2),
                    SigWrapper::from(Signal::SIGTERM),
                ]
        ));
    }

    /// A signal to a restartable internal IO poll that an earlier signal
    /// already woke merges into that wake and leaves the poll where it is in
    /// the run queue. Moving it to the back on every batch starved it behind
    /// a sibling that signaled it once per turn: the sibling's requeued turn
    /// always came first (https://github.com/rrnewton/hermit/issues/4504).
    /// The merged wake keeps the poll's signal-state task and whether it
    /// decides interruption itself, and the first wake's
    /// `drain_woken_waiters` entry stays as it is: a `SIGCHLD` the scheduler
    /// committed to the poll in between (`scheduler_sent`) is kept, where the
    /// old re-wake's unblock dropped it.
    #[test]
    fn a_signal_to_an_already_woken_poll_keeps_its_place_in_the_run_queue() {
        for decides_itself in [false, true] {
            let mut scheduler = Scheduler::new(&Config::default());
            let target = DetTid::from_raw(100);
            let sender = DetTid::from_raw(101);
            register_known_thread(&mut scheduler, target);
            register_known_thread(&mut scheduler, sender);
            let mut polling = Resources::new(target);
            polling.insert(ResourceID::InternalIOPolling, Permission::W);
            polling.set_signal_interrupt_errno(Errno::ERESTARTSYS);
            polling.signal_state_task = Some((3, 100));
            polling.decides_signal_interruption_itself = decides_itself;
            polling.fyi("read");
            scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(polling));
            scheduler.runqueue_push_back(target);
            scheduler.runqueue_push_back(sender);

            // The first signal wakes the poll, which goes to the back.
            scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
            scheduler.drain_pending_cross_task_signals();
            assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(sender));
            scheduler.run_queue.undo_tentative_pop();
            // A poll that decides interruption itself is not marked.
            assert_eq!(
                scheduler.blocked.drain_woken_waiters.contains_key(&target),
                !decides_itself
            );
            // The scheduler commits a `SIGCHLD` to the woken poll.
            if let Some(woken) = scheduler.blocked.drain_woken_waiters.get_mut(&target) {
                woken.scheduler_sent = true;
            }

            // The sender has its turn and is queued again behind the poll.
            assert!(scheduler.run_queue.remove_tid(sender));
            scheduler.runqueue_push_back(sender);

            // Its next signal must not put the poll behind it again.
            scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR2));
            scheduler.drain_pending_cross_task_signals();
            assert_eq!(scheduler.run_queue.len(), 2);
            assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(target));
            scheduler.run_queue.undo_tentative_pop();
            let resources = scheduler
                .next_turns
                .get(&target)
                .and_then(|next_turn| next_turn.req.try_read())
                .and_then(Result::ok)
                .expect("the target should hold its signal interruption request");
            assert_eq!(resources.resources.len(), 1);
            assert!(
                resources
                    .resources
                    .contains_key(&ResourceID::WaitidSignals(vec![
                        SigWrapper::from(Signal::SIGUSR1),
                        SigWrapper::from(Signal::SIGUSR2)
                    ]))
            );
            assert_eq!(
                resources.signal_interrupt_errno(),
                Some(Errno::ERESTARTSYS.into_raw())
            );
            assert_eq!(resources.signal_state_task, Some((3, 100)));
            assert_eq!(resources.decides_signal_interruption_itself, decides_itself);
            assert_eq!(
                scheduler.blocked.drain_woken_waiters.get(&target).copied(),
                (!decides_itself).then_some(DrainWoken {
                    waiter: DrainWokenWaiter::Poll,
                    scheduler_sent: true,
                }),
                "decides_itself {decides_itself}"
            );
        }
    }

    /// A signal delivery that continues the thread's previous one
    /// (`Resources::continues_sigreturn`), filed through `request_put`, is
    /// selected before a thread queued ahead of it; the same request without
    /// the mark waits its turn (https://github.com/rrnewton/hermit/issues/4505).
    #[test]
    fn a_delivery_that_continues_its_threads_sigreturn_runs_first() {
        for continues in [false, true] {
            let global_time = Arc::new(Mutex::new(GlobalTime::new(&Config::default())));
            let mut scheduler = Scheduler::new(&Config::default());
            let sender = DetTid::from_raw(100);
            let target = DetTid::from_raw(101);
            register_known_thread(&mut scheduler, sender);
            register_known_thread(&mut scheduler, target);
            let mut other = Resources::new(sender);
            other.insert(
                ResourceID::InboundSignal(SigWrapper::from(Signal::SIGUSR2)),
                Permission::RW,
            );
            let mut delivery = Resources::new(target);
            delivery.insert(
                ResourceID::InboundSignal(SigWrapper::from(Signal::SIGUSR1)),
                Permission::RW,
            );
            delivery.continues_sigreturn = continues;
            let req = scheduler.next_turns[&sender].req.clone();
            scheduler.request_put(&req, other, &global_time);
            let req = scheduler.next_turns[&target].req.clone();
            scheduler.request_put(&req, delivery, &global_time);
            scheduler.runqueue_push_back(sender);
            scheduler.runqueue_push_back(target);

            assert_eq!(
                scheduler.first_sigreturn_continuation(),
                continues.then_some(target)
            );
            let (selected, _, _) = scheduler.step3_peek().unwrap();
            assert_eq!(
                selected,
                if continues { target } else { sender },
                "continues {continues}"
            );
            scheduler.run_queue.undo_tentative_pop();
        }
    }

    /// The mark is honoured only on a delivery (`InboundSignal`) that a
    /// thread queued to run its turn filed: not on a request of another kind,
    /// and not while the thread is queued as a poller.
    #[test]
    fn a_sigreturn_continuation_needs_a_queued_delivery() {
        let global_time = Arc::new(Mutex::new(GlobalTime::new(&Config::default())));
        let mut scheduler = Scheduler::new(&Config::default());
        let sleeper = DetTid::from_raw(100);
        let poller = DetTid::from_raw(101);
        register_known_thread(&mut scheduler, sleeper);
        register_known_thread(&mut scheduler, poller);
        let mut sleep = Resources::new(sleeper);
        sleep.insert(
            ResourceID::SleepUntil(LogicalTime::from_nanos(1)),
            Permission::W,
        );
        sleep.continues_sigreturn = true;
        let req = scheduler.next_turns[&sleeper].req.clone();
        scheduler.request_put(&req, sleep, &global_time);
        let mut delivery = Resources::new(poller);
        delivery.insert(
            ResourceID::InboundSignal(SigWrapper::from(Signal::SIGUSR1)),
            Permission::RW,
        );
        delivery.continues_sigreturn = true;
        let req = scheduler.next_turns[&poller].req.clone();
        scheduler.request_put(&req, delivery, &global_time);
        scheduler.runqueue_push_back(sleeper);
        scheduler.run_queue.push_poller(poller, DEFAULT_PRIORITY, 0);

        assert_eq!(scheduler.first_sigreturn_continuation(), None);
        assert!(
            !scheduler.sigreturn_continuations.contains(&sleeper),
            "a request that is not a delivery is never recorded"
        );
    }

    /// A turn with no marked request costs the rule nothing: with 64 queued
    /// threads whose requests are unmarked, step 3 reads none of them for it
    /// (Codex review of https://github.com/rrnewton/hermit/pull/4509).
    #[test]
    fn the_sigreturn_continuation_rule_reads_no_request_when_none_is_marked() {
        let global_time = Arc::new(Mutex::new(GlobalTime::new(&Config::default())));
        let mut scheduler = Scheduler::new(&Config::default());
        for raw in 100..164 {
            let thread = DetTid::from_raw(raw);
            register_known_thread(&mut scheduler, thread);
            let mut delivery = Resources::new(thread);
            delivery.insert(
                ResourceID::InboundSignal(SigWrapper::from(Signal::SIGUSR1)),
                Permission::RW,
            );
            let req = scheduler.next_turns[&thread].req.clone();
            scheduler.request_put(&req, delivery, &global_time);
            scheduler.runqueue_push_back(thread);
        }
        assert_eq!(scheduler.first_sigreturn_continuation(), None);
        assert!(scheduler.step3_peek().is_some());
        scheduler.run_queue.undo_tentative_pop();
        assert_eq!(
            scheduler
                .test_continuation_request_reads
                .load(std::sync::atomic::Ordering::Relaxed),
            0
        );
    }

    #[test]
    fn restartable_io_sigchld_bypasses_host_async_signal_deferral() {
        let mut scheduler = Scheduler::new(&Config::default());
        let target = DetTid::from_raw(100);
        let sibling = DetTid::from_raw(101);
        register_known_thread(&mut scheduler, target);
        register_known_thread(&mut scheduler, sibling);
        let mut polling = Resources::new(target);
        polling.insert(ResourceID::InternalIOPolling, Permission::W);
        polling.set_signal_interrupt_errno(Errno::ERESTARTSYS);
        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(polling));
        scheduler.runqueue_push_back(target);
        scheduler.runqueue_push_back(sibling);

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGCHLD));
        scheduler.drain_pending_cross_task_signals();

        let resources = scheduler.next_turns[&target]
            .req
            .try_read()
            .and_then(Result::ok)
            .expect("the target should hold its signal interruption request");
        assert_eq!(
            resources.signal_interrupt_errno(),
            Some(Errno::ERESTARTSYS.into_raw())
        );
        assert_eq!(scheduler.run_queue.tentative_pop_tid(target), Some(target));
        assert!(
            scheduler
                .block_for_one_resource(
                    target,
                    resources.resources.keys().next().unwrap(),
                    &Permission::W,
                    resources.signal_interrupt_errno(),
                    None,
                    &Ivar::new(),
                )
                .is_ok()
        );
        assert!(scheduler.blocked.sigchld_deferred.is_empty());
    }

    /// `step4_resource_block` and `blocking_request_is_ready` both assert that a
    /// request carries exactly one resource. The drain must never violate that.
    ///
    /// An earlier revision merged a pending signal into a request that already
    /// held an `InboundSignal`, producing a two-resource request. The scheduler
    /// daemon then panicked and the container hung — on a guest containing no
    /// `waitid` at all, because `{InboundSignal}` is exactly what `signal_guest`
    /// installs for an ordinary cross-thread signal.
    #[test]
    fn drain_never_builds_a_multi_resource_request() {
        let mut scheduler = Scheduler::new(&Config::default());
        let target = DetTid::from_raw(100);
        register_known_thread(&mut scheduler, target);
        // The shape that crashed: an ordinary delivered signal, nothing to do
        // with waitid.
        let mut inbound = Resources::new(target);
        inbound.insert(
            ResourceID::InboundSignal(SigWrapper::from(Signal::SIGUSR1)),
            Permission::W,
        );
        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(inbound));
        scheduler.runqueue_push_back(target);

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR2));
        scheduler.drain_pending_cross_task_signals();

        let resources = scheduler
            .next_turns
            .get(&target)
            .and_then(|next_turn| next_turn.req.try_read())
            .and_then(Result::ok)
            .expect("the target should still hold a request");
        assert!(
            resources.resources.len() <= 1,
            "the drain produced a {}-resource request, which step4 asserts against: {:?}",
            resources.resources.len(),
            resources.resources,
        );
    }

    /// A thread can hold a `WaitChild` request while ALREADY in the run queue:
    /// `wake_child_waiters` re-admits a waiter without clearing its request, and
    /// `step6_reenqueue` pushes a completed turn back before the guest issues
    /// its next request. An earlier revision inferred "blocked" from the
    /// resource and skipped the run-queue removal, so the drain pushed a
    /// second copy of the thread.
    ///
    /// That failure is worse than it looks: `RunQueue`'s duplicate check is
    /// `cfg!(debug_assertions)`, so debug builds panic with "Invariant
    /// violation! Tried to add ... already present" while RELEASE builds
    /// silently enqueue the thread twice and select it twice.
    #[test]
    fn pending_signal_does_not_double_queue_a_runnable_child_waiter() {
        let mut scheduler = Scheduler::new(&Config::default());
        let target = DetTid::from_raw(100);
        let parent = DetPid::from_raw(100);
        register_known_thread(&mut scheduler, target);
        let spec = ChildWaitSpec {
            selector: ChildWaitSelector::Any,
            owner: None,
            exit_class: ChildWaitExitClass::Sigchld,
        };
        let mut waiting = Resources::new(target);
        waiting.insert(ResourceID::WaitChild { parent, spec }, Permission::R);
        waiting.fyi("wait-child-lifecycle");
        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(waiting));
        // The distinguishing state: holds WaitChild AND is runnable, with no
        // `child_waiters` entry -- exactly what a just-woken waiter looks like.
        scheduler.runqueue_push_back(target);
        assert!(scheduler.run_queue.contains_tid(target));
        assert!(!scheduler.blocked.child_waiters.contains_key(&target));

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        scheduler.drain_pending_cross_task_signals();

        let occurrences = scheduler
            .run_queue
            .tids()
            .filter(|tid| **tid == target)
            .count();
        assert_eq!(
            occurrences, 1,
            "the signalled child waiter must appear in the run queue exactly once"
        );
    }

    /// A thread parked on a scheduler-managed child wait is blocked in
    /// `child_waiters`, never in the run queue, so the run-queue removal the
    /// polling disposition performs does not apply to it. Before this case was
    /// handled, a signal aimed at such a thread was recorded nowhere and a wait
    /// on a child that never exits could not be interrupted at all.
    #[test]
    fn pending_signal_unblocks_a_managed_child_waiter() {
        let mut scheduler = Scheduler::new(&Config::default());
        let target = DetTid::from_raw(100);
        let parent = DetPid::from_raw(100);
        register_known_thread(&mut scheduler, target);
        let spec = ChildWaitSpec {
            selector: ChildWaitSelector::Any,
            owner: None,
            exit_class: ChildWaitExitClass::Sigchld,
        };
        let mut waiting = Resources::new(target);
        waiting.insert(ResourceID::WaitChild { parent, spec }, Permission::R);
        waiting.fyi("wait-child-lifecycle");
        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(waiting));
        // Parked, not runnable: exactly how `WaitChild` leaves a thread.
        scheduler
            .blocked
            .child_waiters
            .insert(target, (parent, spec));
        assert!(!scheduler.run_queue.contains_tid(target));

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        assert_eq!(scheduler.pending_cross_task_signals[&target].len(), 1);

        scheduler.drain_pending_cross_task_signals();

        assert!(
            scheduler.run_queue.contains_tid(target),
            "the signalled child waiter must be requeued"
        );
        assert!(
            !scheduler.blocked.child_waiters.contains_key(&target),
            "its child-wait blocking entry must be cleared"
        );
        assert_eq!(
            scheduler.inbound_signals(target),
            vec![SigWrapper::from(Signal::SIGUSR1)],
            "the resume must name the signal that woke it"
        );
    }

    #[test]
    fn pending_signal_replaces_an_internal_poller_request() {
        let mut scheduler = Scheduler::new(&Config::default());
        let target = DetTid::from_raw(100);
        register_known_thread(&mut scheduler, target);
        let mut polling = Resources::new(target);
        polling.insert(ResourceID::InternalIOPolling, Permission::W);
        polling.fyi("waitid");
        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(polling));
        scheduler.runqueue_push_back(target);

        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR2));

        assert_eq!(scheduler.pending_cross_task_signals[&target].len(), 1);
        scheduler.drain_pending_cross_task_signals();
        assert!(scheduler.run_queue.contains_tid(target));
        assert_eq!(
            scheduler.inbound_signals(target),
            vec![SigWrapper::from(Signal::SIGUSR2)]
        );

        // A later signal must merge into the already-materialized waitid wakeup.
        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
        assert_eq!(scheduler.pending_cross_task_signals[&target].len(), 1);
        scheduler.drain_pending_cross_task_signals();
        assert_eq!(
            scheduler.inbound_signals(target),
            vec![
                SigWrapper::from(Signal::SIGUSR1),
                SigWrapper::from(Signal::SIGUSR2)
            ]
        );
    }

    /// A scheduler for a backend whose process exits complete asynchronously
    /// (in-guest LiteInst), with killed-thread RPC cancellation as that backend
    /// has it.
    fn async_exit_scheduler() -> Scheduler {
        let config = Config::default().with_backend(|backend| {
            backend.process_exits_complete_asynchronously = true;
            backend.needs_killed_thread_rpc_cancellation = true;
        });
        Scheduler::new(&config)
    }

    /// Registers single-threaded process `tid` with an empty pending request.
    fn register_process(scheduler: &mut Scheduler, tid: DetTid) {
        scheduler.thread_tree.add_child(tid, tid, true);
        scheduler.next_turns.insert(
            tid,
            ThreadNextTurn {
                dettid: tid,
                child_tid_addr: 0,
                req: Ivar::new(),
                resp: Ivar::new(),
                protocol: Default::default(),
            },
        );
    }

    #[test]
    fn async_exit_holds_selection_from_the_grant_until_completion() {
        let mut scheduler = async_exit_scheduler();
        let process = DetPid::from_raw(100);
        assert!(scheduler.step2_drain_prefix().is_ok());
        scheduler.begin_exit_at_grant(process);
        assert_eq!(
            scheduler.pending_physical_process_exits,
            BTreeSet::from([process])
        );
        // What the backend's watchdog reads.
        assert_eq!(scheduler.pending_async_process_exits(), [process]);
        // Every pass skips while the exit is pending, however many there are.
        for _ in 0..3 {
            assert!(scheduler.step2_drain_prefix().is_err());
        }
        assert!(scheduler.complete_physical_process_exit(process));
        assert!(scheduler.step2_drain_prefix().is_ok());
        assert!(scheduler.process_physically_gone(process));
        assert!(scheduler.pending_async_process_exits().is_empty());
    }

    #[test]
    fn without_async_exit_completion_the_grant_holds_nothing() {
        let config = Config::default();
        let mut scheduler = Scheduler::new(&config);
        let process = DetPid::from_raw(100);
        assert!(!scheduler.begin_physical_process_exit(process));
        assert!(scheduler.pending_physical_process_exits.is_empty());
        assert!(scheduler.step2_drain_prefix().is_ok());
        assert!(!scheduler.complete_physical_process_exit(process));
        assert!(!scheduler.process_physically_gone(process));
    }

    #[test]
    fn async_exit_lifetime_is_monotone() {
        // A completion that arrives first is kept, and a later begin, from the
        // grant or from a late deregistration, is a no-op.
        let mut scheduler = async_exit_scheduler();
        let process = DetPid::from_raw(100);
        assert!(!scheduler.complete_physical_process_exit(process));
        assert!(scheduler.process_physically_gone(process));
        scheduler.begin_exit_at_grant(process);
        assert!(!scheduler.begin_physical_process_exit(process));
        assert!(scheduler.pending_physical_process_exits.is_empty());
        assert!(scheduler.step2_drain_prefix().is_ok());

        // After a grant and its completion, a late begin is a no-op too.
        let other = DetPid::from_raw(200);
        scheduler.begin_exit_at_grant(other);
        assert!(scheduler.complete_physical_process_exit(other));
        assert!(!scheduler.begin_physical_process_exit(other));
        assert!(scheduler.pending_physical_process_exits.is_empty());
    }

    #[test]
    #[should_panic(expected = "the hold must allow at most one")]
    fn a_second_exit_grant_while_one_is_pending_is_an_invariant_violation() {
        let mut scheduler = async_exit_scheduler();
        scheduler.begin_exit_at_grant(DetPid::from_raw(100));
        scheduler.begin_exit_at_grant(DetPid::from_raw(200));
    }

    #[test]
    fn completion_consumes_only_registrations_the_process_did_not_deregister() {
        let mut scheduler = async_exit_scheduler();
        let dead = DetTid::from_raw(100);
        let deregistered = DetTid::from_raw(200);
        register_process(&mut scheduler, dead);
        register_process(&mut scheduler, deregistered);
        // `deregistered` finished its exit hook before exiting.
        assert!(scheduler.note_deregistration_accounted(deregistered));
        scheduler.logically_kill_thread(&deregistered, &deregistered, MmId::initial(deregistered));

        assert!(!scheduler.consume_unreported_exit(deregistered));
        assert!(scheduler.consume_unreported_exit(dead));
        assert!(!scheduler.next_turns.contains_key(&dead));
        // A late DeregisterThread for the consumed thread is already accounted.
        assert!(!scheduler.note_deregistration_accounted(dead));
        // Consuming twice is a no-op.
        assert!(!scheduler.consume_unreported_exit(dead));
    }

    /// A joiner woken by a thread's CLONE_CHILD_CLEARTID is admitted at the
    /// next drain, in DetTid order with the other admissions of that drain,
    /// whichever arrived first; it is not pushed at once. On the base code it
    /// was pushed at the wake, so it ran ahead of a lower DetTid
    /// (https://github.com/rrnewton/hermit/issues/4362, part 2 step 0b). The
    /// joiner here has the higher DetTid: with a lower one, both orders agree
    /// and the case could not tell them apart (Claude review of
    /// https://github.com/rrnewton/hermit/pull/4453, F2).
    #[test]
    fn a_cleartid_joiner_is_admitted_in_dettid_order_with_pending_admissions() {
        for wake_first in [false, true] {
            let mut scheduler = Scheduler::new(&Config::default());
            let lower = DetTid::from_raw(5);
            let dead = DetTid::from_raw(9);
            let joiner = DetTid::from_raw(11);
            let mm = MmId::initial(dead);
            let address = 0x404100;
            let futex = FutexID::private(mm, address);
            for tid in [lower, dead, joiner] {
                scheduler.thread_tree.add_child(tid, tid, true);
                register_known_thread(&mut scheduler, tid);
                scheduler.record_thread_mm(tid, mm);
            }
            scheduler.next_turns.get_mut(&dead).unwrap().child_tid_addr = address;
            scheduler.sleep_futex_waiter(&joiner, futex, None, u32::MAX, None);
            if wake_first {
                scheduler.wake_futex_child_cleartid(futex, dead);
                scheduler.admit_to_run_queue(lower, AdmitIntent::Fixed(AdmitSide::Back));
            } else {
                scheduler.admit_to_run_queue(lower, AdmitIntent::Fixed(AdmitSide::Back));
                scheduler.wake_futex_child_cleartid(futex, dead);
            }
            assert!(
                scheduler.admission_pending(joiner),
                "wake_first={wake_first}"
            );
            scheduler.drain_pending_run_queue_admissions();

            assert_eq!(
                scheduler.run_queue.tids().copied().collect::<Vec<_>>(),
                vec![lower, joiner],
                "wake_first={wake_first}"
            );
        }
    }

    /// A thread retired while a tentative selection is open wakes its
    /// clear-TID joiner by admission, which is legal there, instead of a run
    /// queue push, which panics (2ee7190125's test).
    #[test]
    fn unreported_exit_defers_clear_tid_wake_during_tentative_selection() {
        let mut scheduler = Scheduler::new(&Config::default());
        let anchor = DetTid::from_raw(5);
        let dead = DetTid::from_raw(9);
        let waiters = [11, 12].map(DetTid::from_raw);
        let mm = MmId::initial(dead);
        let address = 0x404100;
        let futex = FutexID::private(mm, address);
        for process in [anchor, dead, waiters[0]] {
            scheduler.thread_tree.add_child(process, process, true);
        }
        scheduler
            .thread_tree
            .add_child(waiters[0], waiters[1], false);
        for tid in [anchor, dead, waiters[0], waiters[1]] {
            register_known_thread(&mut scheduler, tid);
            scheduler.record_thread_mm(tid, mm);
        }
        // A CLONE_VM process can leave a clear-TID waiter in a different,
        // surviving thread group that shares its address space.
        scheduler.next_turns.get_mut(&dead).unwrap().child_tid_addr = address;
        scheduler.runqueue_push_back(anchor);
        scheduler.runqueue_push_back(dead);
        for waiter in waiters {
            scheduler.sleep_futex_waiter(&waiter, futex, None, u32::MAX, None);
        }
        assert_eq!(scheduler.run_queue.tentative_pop_next(), Some(anchor));
        assert!(scheduler.consume_unreported_exit(dead));
        assert!(scheduler.run_queue.tentative_pop_in_progress());
        assert!(scheduler.child_tid_was_cleared(futex, dead.as_raw()));
        assert!(scheduler.admission_pending(waiters[0]));
        assert!(!scheduler.admission_pending(waiters[1]));
        assert!(!scheduler.is_parked_futex_waiter(waiters[0]));
        assert!(scheduler.is_parked_futex_waiter(waiters[1]));
        scheduler.run_queue.undo_tentative_pop();
        scheduler.drain_pending_run_queue_removals();
        scheduler.drain_pending_run_queue_admissions();
        assert_eq!(
            scheduler.run_queue.tids().copied().collect::<Vec<_>>(),
            vec![anchor, waiters[0]]
        );
    }

    #[test]
    fn a_dead_vfork_parent_cancels_its_barrier_and_settles_a_late_child() {
        let mut scheduler = async_exit_scheduler();
        let parent = DetTid::from_raw(100);
        let child = DetTid::from_raw(101);
        register_process(&mut scheduler, parent);
        // The parent is in vfork; its child has not registered yet.
        scheduler.vfork_barriers.insert(parent, None);
        assert!(scheduler.consume_unreported_exit(parent));
        assert!(!scheduler.vfork_barriers.contains_key(&parent));
        // The child's outstanding registration settles without a barrier,
        // without panicking.
        scheduler.complete_vfork_registration(parent, child);
        assert!(!scheduler.vfork_barriers.contains_key(&parent));
        assert!(!scheduler.dead_vfork_parents.contains(&parent));
    }

    #[test]
    fn a_dead_vfork_parent_with_an_admitted_child_only_cancels_its_barrier() {
        let mut scheduler = async_exit_scheduler();
        let parent = DetTid::from_raw(100);
        let child = DetTid::from_raw(101);
        register_process(&mut scheduler, parent);
        scheduler.vfork_barriers.insert(parent, Some(child));
        assert!(scheduler.consume_unreported_exit(parent));
        assert!(!scheduler.vfork_barriers.contains_key(&parent));
        assert!(!scheduler.dead_vfork_parents.contains(&parent));
    }

    #[test]
    #[should_panic(expected = "vfork child registered without a pending parent")]
    fn a_vfork_registration_without_barrier_or_tombstone_is_still_an_invariant_violation() {
        let mut scheduler = async_exit_scheduler();
        scheduler.complete_vfork_registration(DetTid::from_raw(100), DetTid::from_raw(101));
    }

